-- GENERATED by `wfi generate` from data/quest/quest-0000.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [5] = { "Lo stomaco brontolante di Jitters", "Parla con Chef Grual.", "Sono settimane che sto nascosto in questa città fantasma, e non ho mangiato altro che larve ed erbacce! Mi serve del cibo decente, e sono disposto a pagarlo bene.\n\nPortami un banchetto e ti pagherò profumatamente.\n\nHo sentito che Chef Grual, alla Scarlet Raven Tavern di Darkshire, fa delle ottime Dusky Crab Cakes...", nil, "Ti servono delle Crab Cakes, eh? Be', forse posso cucinartene qualcuna...", 0x13753190, 0x3c550677, 0xb656ff77, nil, 0x9ca7596b, "...m." },
  [6] = { "Una taglia su Garrick Padfoot", "Uccidi Garrick Padfoot e porta la sua testa a Deputy Willem, alla Northshire Abbey.", "Garrick Padfoot, un tagliagole che da settimane tormenta i nostri contadini e mercanti, è stato visto in una baracca vicino ai vigneti, a est dell'abbazia, oltre il ponte. Portami la testa di quel furfante e guadagnati la taglia!\n\nMa stai in guardia, {name}. Garrick ha radunato intorno a sé una banda di delinquenti. Non sarà facile arrivare fino a lui.", "Hai trovato la baracca di Garrick? Siamo finalmente liberi da quel furfante?", "Ah! L'hai preso! Hai reso un grande servizio a Elwynn, e ora una bella taglia è tutta tua!", 0xd9a1ea2f, 0xb35875a3, 0x674275ec, 0xe205dce0, 0x8edda1cf, "....." },
  [7] = { "Ripulire il campo dei kobold", "Uccidi 10 Kobold Vermin, poi torna da Marshal McBride.", "Il tuo primo compito sarà fare pulizia, {name}. Un clan di kobold ha infestato i boschi a nord. Vai là e combatti i Kobold Vermin che trovi. Riducine il numero, così che un giorno potremo cacciarli da Northshire.", "Come va la caccia, {name}? Hai trovato e sconfitto quei parassiti?", "Ben fatto, <cittadino/cittadina>. Quei kobold sono ladri e codardi, ma in gran numero sono una minaccia per noi. E agli umani di Stormwind non serve un'altra minaccia.\n\nPer averli sconfitti, hai la mia gratitudine.", 0x5d10a531, 0xc0a62578, 0x54635c79, 0x4eb51373, 0xb52dae46, "....." },
  [9] = { "I campi della morte", "Farmer Saldean vuole che tu uccida 20 Harvest Watchers.", "Guarda cos'è successo a questo posto! Un tempo queste terre erano abitate da brava gente di campagna. Ma quei maledetti ladri li hanno cacciati tutti. Non me, però! Solo che a quanto pare alcuni Harvest Watchers si sono presi i campi.\n\nSe te la senti di lavorare, vorrei che andassi a ucciderne 20. Torna quando hai finito, per la paga. Se hai finito con quelli del mio campo, ripulisci anche i campi vicini.", "Ah, vedo che sei <tornato/tornata>! Spero che tu abbia lavorato sodo per ripulire quei campi dagli Harvest Watchers. Ne hai già uccisi 20?", "Bel lavoro, amico. Ti sei <guadagnato/guadagnata> la paga. Chissà, forse Westfall tornerà a prosperare.", 0xe8dc51f9, 0xb1fcb3e9, 0xc49a0580, 0x0e0d21d8, 0x9ce4bf4e, "....." },
  [11] = { "Taglia sugli gnoll Riverpaw", "Porta 8 Painted Gnoll Armbands a Deputy Rainer, alle Barracks.", "Gli gnoll, creature brutali che non hanno nulla da fare in queste terre, sono stati avvistati lungo i confini della Elwynn Forest. Un grosso branco, molto più numeroso di quanto possiamo affrontare da soli, ha infestato i boschi a sud della torre di guardia laggiù. Un altro gruppo ha infestato le zone vicino allo Stone Cairn Lake, a est.\n\nLa Stormwind Army ricompenserà chiunque aiuti a ucciderli. Portami i loro Painted Gnoll Armbands come prova dell'impresa.", "Salute, {name}. Hai ucciso degli gnoll...?", "Vedo che ti sei <dato/data> da fare! Hai la nostra gratitudine, {name}.", 0x9b53bb87, 0x8f6713f0, 0x9259d68e, 0x11769f64, 0xc6ac4114, "....." },
  [12] = { "La People's Militia", "Gryan Stoutmantle vuole che tu uccida 15 Defias Trappers e 15 Defias Smugglers, poi torni da lui a Sentinel Hill.", "La People's Militia ha un solo scopo: difendere le terre di Westfall e riportare la pace nei dintorni. Purtroppo, il prezzo della pace è spesso il sangue.\n\nUno dei miei esploratori mi ha avvertito che una banda di Defias Trappers sta seminando il caos qui vicino. Ho notizie di avvistamenti di Defias Trapper vicino alla Jangolode Mine, a nord-ovest, alla Molsen Farm e alla Furlbrow's Pumpkin Farm. Se vuoi unirti alle nostre file, uccidi 15 Defias Trappers e 15 Defias Smugglers, poi torna da me.", "Forse non sono stato chiaro, recluta. Per dimostrare il tuo valore come servitore della People's Militia e della Luce devi uccidere 15 Defias Trappers e 15 Defias Smugglers, poi tornare da me a cose fatte.", "Ben fatto, {name}. Il mio esploratore ha visto le tue gesta valorose. Finora stai dando ottima prova di te.", 0xe151209f, 0x16896ec7, 0x8596ea3e, 0xecfd7c3c, 0x84930ba2, "....." },
  [13] = { "La People's Militia", "Gryan Stoutmantle vuole che tu uccida 15 Defias Pillagers e 15 Defias Looters e torni da lui a Sentinel Hill.", "Una banda di feroci Defias Pillagers è stata vista saccheggiare la Gold Coast Quarry, Moonbrook e l'Alexston Farmstead. La People's Militia non tollererà un simile comportamento. Parti subito, {name}, e fai sentire la presenza della Luce a Westfall.\n\nLa Gold Coast Quarry è vicino alla riva, a ovest della torre. Come prossimo passo del tuo addestramento, voglio che tu uccida 15 di quei luridi Defias Pillagers e 15 Defias Looters.", "Non abbiamo tempo per parlare, {name}. I Defias Pillagers negano alla gente di Westfall la pace e la prosperità che merita. Assicurati che almeno 15 Defias Pillagers e 15 Defias Looters siano stati uccisi. Sarà un messaggio chiaro: la corruzione qui non è gradita.", "Il tuo valore per la People's Militia è stato confermato dalle tue azioni coraggiose.", 0xe151209f, 0x6d788fcc, 0x1eea16a0, 0x687557dd, 0xb859c405, "....." },
  [14] = { "La People's Militia", "Gryan Stoutmantle vuole che tu uccida 15 Defias Highwaymen, 5 Defias Pathstalkers e 5 Defias Knuckledusters, poi torni da lui a Sentinel Hill.", "Alcuni Defias ci sono sfuggiti. Il mio esploratore più fidato riferisce che questi Defias hanno razziato e saccheggiato le campagne, fino alla parte meridionale di Westfall. Crediamo che si nascondano nelle Dagger Hills, a tramare la loro prossima mossa. Uccidi quei miserabili in nome della People's Militia.", "{name}, non è il momento per le chiacchiere. Se vuoi ancora dimostrare il tuo valore alla People's Militia devi uccidere i Defias di cui ti ho parlato prima. Torna da me quando avrai compiuto il tuo dovere.", "Quando lasciai le terre corrotte di Lordaeron, tornai in patria e trovai una situazione cupa. Ma c'è ancora speranza per Westfall. Come dimostra il tuo valore in battaglia, è evidente che servi la nostra causa con onore. È con grande orgoglio che ti accolgo nella People's Militia. Che la Luce risplenda su di te.", 0xe151209f, 0x78ad5d7f, 0xab47f493, 0xa480f62a, 0xf947b26e, "....." },
  [15] = { "Indagini a Echo Ridge", "Uccidi 10 Kobold Workers, poi torna a fare rapporto a Marshal McBride.", "{name}, i miei esploratori dicono che l'infestazione di kobold è più estesa di quanto pensassimo. Un gruppo di Kobold Workers si è accampato vicino alla Echo Ridge Mine, a nord.\n\nVai alla miniera e toglili di mezzo. Sappiamo che sono almeno 10. Uccidili, controlla se ce ne sono altri, poi torna a farmi rapporto.", "Sei <andato/andata> alle miniere? Sei <pronto/pronta> a fare rapporto?", "Non mi piace sentire di tutti questi kobold nella nostra miniera. Non ne verrà niente di buono. Ecco, prendi questo come compenso, e quando sei <pronto/pronta> parlami di nuovo. Vorrei che tornassi alle miniere ancora una volta...", 0xb43a6289, 0xa368f704, 0x2cb816b5, 0x063df25d, 0xf0b6a1c7, "....." },
  [16] = { "Da bere per Gerard", nil, nil, "Lavorare nei campi mette sete, e cerco sempre acqua fresca di sorgente.\n\nSe ne hai un po', sono disposto a fare uno scambio.", "Grazie, {name}! E torna se vuoi fare un altro scambio.", 0x8a697a25, nil, nil, 0x6a289e06, 0x46e9e47e, ".mm.." },
  [17] = { "Reagenti da Uldaman", "Porta 12 Magenta Fungus Caps a Ghak Healtouch, a Thelsamar.", "Ho sentito parlare di una pianta scoperta da poco, le Magenta Fungus Caps. Crescono a grappoli, in fondo al sito di scavo di Uldaman; forse ci sono anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.\n\nTrova i grappoli di funghi magenta e portamene una dozzina. Attenzione: se scossi, i grappoli possono sputare spore velenose.\n\nFallo per me e ti preparerò una partita di uno dei miei famosi elisir ricostituenti!", "Hai ottenuto le Magenta Fungus Caps che mi servono per il mio lavoro alchemico? Niente funghi, niente ricompensa!", "Ben fatto {name}, hai dimostrato ancora una volta il tuo valore! I funghi saranno uno studio interessante, davvero!\n\nE ora, come promesso, goditi un assaggio di uno dei miei intrugli ricostituenti più potenti, dalla mia scorta personale...\n\nSe sei un alchimista esperto, forse potremmo fare altri affari. In ogni caso, ti ringrazio per l'aiuto!", 0xec9c87f2, 0xf9b7baaa, 0xf40372d4, 0x3dc33ca7, 0x6da9f6fe, "....." },
  [18] = { "La confraternita dei ladri", "Porta 12 Red Burlap Bandanas a Deputy Willem, fuori dalla Northshire Abbey.", "Da poco un nuovo gruppo di ladri si aggira intorno a Northshire. Si fanno chiamare Defias Brotherhood e sono stati visti oltre il fiume, a est.\n\nNon so cosa stiano tramando, ma di sicuro niente di buono! Portami le bandane che indossano e ti ricompenserò con un'arma.", "Hai già raccolto quelle bandane per me?", "Vedo che hai portato qualche bandana. La Stormwind Army ti è grata per il tuo aiuto.", 0x2f1eb64e, 0x0376329b, 0x0ff5818f, 0x59c5a6d0, 0x9eec7aad, "....." },
  [19] = { nil, "Porta la Tharil'zun's Head a Marshal Marris, a Redridge.", "I Blackrock Outrunners e i Renegades tendono imboscate tra qui e la Stonewatch Keep. Il capo degli Outrunners è un orco di nome Tharil'zun: è lui che vogliamo. Portami la testa di Tharil'zun!", "La pressione degli orchi Blackrock è ancora forte. Ma almeno ci hai liberati di Tharil'zun?", "Tharil'zun era un orco feroce e astuto. Ben fatto: di sicuro non è caduto facilmente. Ecco la tua ricompensa, {name}.", nil, 0x7c13c137, 0x8b3cf21c, 0x55e47621, 0x3c4e5d23, "m...." },
  [20] = { "La minaccia dei Blackrock", "Porta 10 Battleworn Axes a Marshal Marris, a Lakeshire.", "Gli orchi Blackrock sono arrivati dalle Burning Steppes e si sono presi la Stonewatch Keep, a nord. Da lì razziano le zone a nord di Lakeshire e tengono i suoi abitanti chiusi in paese, rinchiusi come bestiame.\n\nAiuta a liberare Lakeshire da questa minaccia. Uccidi questi orchi Blackrock e portami 10 delle loro Battleworn Axes come prova.\n\nE anche se i Blackrock ci minacciano da nord, abbiamo notizie di altri nell'angolo sud-orientale di Redridge. Se ne trovi anche lì, dai la caccia pure a loro.", "Hai ucciso degli orchi, {name}? Se è così, fammi vedere...", "Così abbiamo molti meno orchi di cui preoccuparci, grazie.", 0xeb0d5482, 0x427516c3, 0xdcc24f55, 0x9b1e452c, 0x1c8fce29, "....." },
  [21] = { "Scaramuccia a Echo Ridge", "Uccidi 12 Kobold Laborers, poi torna da Marshal McBride alla Northshire Abbey.", "Le tue indagini hanno dimostrato che la Echo Ridge Mine va ripulita. Torna alla miniera e aiuta a liberarla dai kobold.\n\nNon perdere tempo, {name}. Più a lungo i kobold restano indisturbati nella miniera, più saldamente mettono radici a Northshire.", "So che è un lavoro sanguinoso, {name}, ma è vitale per la sicurezza di Northshire. Sei <pronto/pronta> a fare rapporto?", "Ancora una volta hai conquistato il mio rispetto e la gratitudine della Stormwind Army. Forse nella miniera ci sono ancora dei kobold, ma radunerò altri soldati contro di loro. Abbiamo altri compiti per te.", 0xa7a12dbe, 0x26b99d1f, 0xeb16bc2b, 0xf565255c, 0x019e5401, "....." },
  [22] = { nil, "A Salma Saldean servono 8 Goretusk livers per preparare una Goretusk Liver Pie.", "Le cipolle sono sbucciate. L'aglio è tritato. Il rosmarino è pestato. La crosta è cotta. L'aneto è sminuzzato. Il sugo sobbolle. Ora per il mio famoso pasticcio di carne mi servono solo 8 Goretusk Livers!", "Per il mio famoso pasticcio di carne mi servono solo 8 Goretusk Livers!", "Sono perfetti, {name}! Grazie mille. Stasera io e Farmer Saldean faremo un banchetto. Ed ecco qualcosina per te, per il duro lavoro. Pensavi davvero che ti avrei lasciato a pancia vuota, {class}?", nil, 0x0a34a00f, 0xa7490995, 0xe421b346, 0x2f880112, "m...." },
  [26] = { "Una lezione da imparare", "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", "{name}, seguo i tuoi progressi con grande piacere. Stai diventando senza dubbio <un/una> <protettore/protettrice> della natura di grande valore.\n\nÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci: uno che ti dà il comando e la padronanza dell'acqua. Per questo devi andare nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Ti guiderà lui.", nil, "Salute, giovane druido; è giunto il momento che tu conosca la nostra forma acquatica. È una forma che ti permette di muoverti liberamente e senza limiti nell'acqua. Troverai questo aspetto uno strumento utile e una benedizione... ma va guadagnato prima di essere padroneggiato.\n\nDovrai superare due prove. La prima metterà alla prova la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.\n\nTieniti <pronto/pronta>, perché il momento della prova è arrivato.", 0xab90ac10, 0x127a78ca, 0x21ea754f, nil, 0x058b67b8, "...m." },
  [27] = { "Una lezione da imparare", "Parla con Dendrite Starblaze nel villaggio di Nighthaven, a Moonglade.", "{name}, seguo i tuoi progressi con grande piacere. Stai diventando senza dubbio <un/una> <protettore/protettrice> della natura di grande valore.\n\nÈ giunto il momento che tu impari di più su uno dei vari aspetti animali in cui Cenarius ci ha concesso di trasformarci: uno che ti dà il comando e la padronanza dell'acqua. Per questo devi andare nel villaggio di Nighthaven, a Moonglade, e parlare con Dendrite Starblaze del Cenarion Circle. Ti guiderà lui.", nil, "Salute, giovane druido; è giunto il momento che tu conosca la nostra forma acquatica. È una forma che ti permette di muoverti liberamente e senza limiti nell'acqua. Troverai questo aspetto uno strumento utile e una benedizione... ma va guadagnato prima di essere padroneggiato.\n\nDovrai superare due prove. La prima metterà alla prova la tua capacità di agire in acqua sotto pressione. La seconda metterà alla prova la tua determinazione a comprendere gli aspetti della forma stessa.\n\nTieniti <pronto/pronta>, perché il momento della prova è arrivato.", 0xab90ac10, 0x127a78ca, 0x21ea754f, nil, 0x058b67b8, "...m." },
  [28] = { "La prova del lago", "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nel nord-ovest di Moonglade. Una volta lì, usa lo Shrine Bauble.\n\nDopo devi parlare con Tajarri al santuario per completare la prova.", "Per la tua prima prova, cerca nelle profondità del Lake Elune'ara uno Shrine Bauble. Si deteriora rapidamente, quindi portalo subito allo Shrine of Remulos. Usa il gingillo al santuario, poi parla con Tajarri, che si trova lì: è una delle guardiane più fidate di Moonglade.\n\nHai a disposizione un tempo limitato per completare il compito, e potresti essere in competizione con altri druidi che cercano anch'essi i gingilli. L'agilità mentale e fisica sarà fondamentale per il tuo successo.\n\nBuona fortuna, {name}.", "Per completare la Trial of the Lake, devi usare lo Shrine Bauble entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.", "Ebbene, sembra che un altro druido abbia superato con successo la Trial of the Lake! Ben fatto, <mio/mia> giovane <amico/amica>, ben fatto.\n\nCome ti ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio servire come guardiana di Moonglade, e in particolare di questo santuario. Il Keeper Remulos guida il Cenarion Circle nella tutela della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare qui il gingillo è un omaggio all'importanza di questo luogo per il Circle.", 0xee209044, 0x40c0c195, 0x38927bd5, 0x95bbb916, 0x88cadd95, "....." },
  [29] = { "La prova del lago", "Trova uno Shrine Bauble nel Lake Elune'ara e portalo allo Shrine of Remulos, nel nord-ovest di Moonglade. Una volta lì, usa lo Shrine Bauble.\n\nDopo devi parlare con Tajarri al santuario per completare la prova.", "Per la tua prima prova, cerca nelle profondità del Lake Elune'ara uno Shrine Bauble. Si deteriora rapidamente, quindi portalo subito allo Shrine of Remulos. Usa il gingillo al santuario, poi parla con Tajarri, che si trova lì: è una delle guardiane più fidate di Moonglade.\n\nHai a disposizione un tempo limitato per completare il compito, e potresti essere in competizione con altri druidi che cercano anch'essi i gingilli. L'agilità mentale e fisica sarà fondamentale per il tuo successo.\n\nBuona fortuna, {name}.", "Per completare la Trial of the Lake, devi usare lo Shrine Bauble entro i confini di questo santuario. Finché non lo farai, la tua prova resterà incompiuta e rischierà di fallire.", "Ebbene, sembra che un altro druido abbia superato con successo la Trial of the Lake! Ben fatto, <mio/mia> giovane <amico/amica>, ben fatto.\n\nCome ti ho detto, mi chiamo Tajarri. È mio dovere e mio privilegio servire come guardiana di Moonglade, e in particolare di questo santuario. Il Keeper Remulos guida il Cenarion Circle nella tutela della natura e dell'equilibrio, e il suo santuario ne è un tributo duraturo. Usare qui il gingillo è un omaggio all'importanza di questo luogo per il Circle.", 0xee209044, 0x40c0c195, 0x38927bd5, 0x95bbb916, 0x88cadd95, "....." },
  [30] = { "La prova del leone marino", "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi.\n\nForma il Pendant of the Sea Lion unendo le due metà. Per farlo devi trovarti nei pressi dello Shrine of Remulos.\n\nPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.", "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro forma acquatica.\n\nParla con gli abitanti di Moonglade per scoprire dove possano trovarsi le parti, e portale entrambe qui per unirle. Una volta formato, porta il pendente a Dendrite Starblaze.", "Hai formato il pendente da farmi esaminare, {name}? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni agli abitanti. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.", "Hai completato la Trial of the Sea Lion, {name}: congratulazioni.\n\nOgni compito per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua volontà di abbracciare l'aspetto del leone marino.\n\nRicorda bene queste lezioni e contaci una volta ottenuta la tua forma acquatica.", 0x5cc8ed68, 0xdf177053, 0x23c219a5, 0x3520b13e, 0xb90d61f2, "....." },
  [31] = { "Forma acquatica", nil, nil, nil, nil, 0xb41f2b6a, nil, nil, nil, nil, ".mmmm" },
  [33] = { "Lupi oltre il confine", "Porta 8 pezzi di Tough Wolf Meat a Eagan Peltskinner, fuori dalla Northshire Abbey.", "Odio quei maledetti lupi dei boschi! Però le bistecche di lupo mi piacciono proprio... Portami della Tough Wolf Meat e te la scambierò con qualcosa che ti tornerà utile.\n\nLa Tough Wolf Meat si ricava cacciando i lupi dei boschi e i lupi giovani che vagano per le campagne di Northshire.", "Ehi, {name}. Comincio ad avere fame... hai preso quella Tough Wolf Meat?", "Hai lavorato sodo! Non vedo l'ora di cucinare quella carne di lupo...\n\nHo qui alcune cose che potrebbero interessarti: scegli pure!", 0xf2272f07, 0xdf199ead, 0x5ce8cfac, 0xf5cb8e2e, 0x63c80a97, "....." },
  [34] = { "Un ospite sgradito", "Martie Jainrose di Lakeshire vuole che tu uccida Bellygrub. Portale la sua zanna come prova.", "Ancora una volta il mio orto è stato calpestato e saccheggiato. E so chi è il bruto che lo fa. È quel maledetto cinghiale, quello che Marshal Marris ha preso a chiamare Bellygrub.\n\nOra non potrò ripiantare i narcisi fino alla prossima stagione. Rovinati! Tutto rovinato da quel cinghiale molesto. Metti fine a quella peste! Mostrami la sua zanna e sarò felice di ricompensarti. Sembra che passi il tempo a cercare cibo nel campo a sud-ovest di Lakeshire, ma ogni tanto si spinge fin qui, nel mio orto.", "Bellygrub continua a fare danni, o sei <riuscito/riuscita> a liberare Lakeshire da quella peste una volta per tutte?", "Finalmente la minaccia è sistemata! Grazie, {name}, mi hai reso un grande servizio. Quest'anno l'orto sarà in piena fioritura!", 0x5c809bb5, 0xabb3c5cc, 0xd5dec96a, 0x26e466ea, 0x3fd295c2, "....." },
  [35] = { "Altre preoccupazioni", "Marshal Dughan vuole che tu parli con Guard Thomas.", "Se temi che le voci sui murloc siano vere, allora fai così: vai al ponte orientale di Elwynn e parla con Guard Thomas. È di stanza al ponte da una settimana e saprà com'è la situazione nella zona.\n\nPortami il suo rapporto.", nil, "Sì, i murloc si sono stabiliti lungo i torrenti della parte orientale di Elwynn e nei dintorni. Non sappiamo perché siano qui, ma sono aggressivi e almeno in parte intelligenti.", 0xbf37aefc, 0xd1c199f2, 0x0d41f7ae, nil, 0xfbe5b854, "...m." },
  [36] = { nil, "Verna Furlbrow vuole che tu consegni la sua ricetta della Westfall Stew a Salma Saldean.", "Non avrei mai pensato che sarebbe arrivato il giorno in cui avrei lasciato la fattoria. Ma i campi sono invasi dai ladri, ed è troppo pericoloso restare qui. Appena Farmer Furlbrow avrà aggiustato il carro, ce ne andremo.\n\nMi faresti un favore? Lascia che ti scarabocchi la mia ricetta della Westfall Stew. Ti prego, portala a Salma Saldean, nella fattoria laggiù. La fattoria dei Saldean è appena oltre il bivio.", "Mi mancherà tanto quella Verna Furlbrow. Per caso l'hai vista venendo qui?", "Quella Verna è sempre stata una ragazza così dolce. Ci mancherà qui a Westfall ma, detto tra noi, in fondo è una ragazza di città, e Stormwind le starà a pennello. Ma basta pettegolezzi! Ora possiamo preparare la Westfall Stew!", nil, 0xd3f82a15, 0xce62c0a2, 0xdfbf0990, 0xd01407d2, "m...." },
  [37] = { "Trovare le guardie scomparse", "Guard Thomas vuole che tu risalga il fiume verso nord e cerchi le due guardie scomparse, Rolf e Malakai.", "Qualche giorno fa abbiamo mandato due guardie, Rolf e Malakai, a indagare lungo il fiume, e non sono ancora tornate. Per completare il mio rapporto devo sapere che fine hanno fatto.\n\nRisali il fiume verso nord e trova le guardie... o quello che ne resta.", nil, "Anche se il cadavere è stato in gran parte spogliato, lì vicino c'è un medaglione con incise le parole: \"Footman Malakai Stone\".", 0xbd0b84c3, 0xc79cfdb3, 0x96ec21d0, nil, 0xf410e026, "...m." },
  [38] = { nil, "Salma Saldean vuole 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes e 3 Okra.", "Aiutami a preparare la Westfall Stew! Torna con questi ingredienti:\n\n3 Stringy Vulture Meat\n\n3 Goretusk Snouts\n\n3 Murloc Eyes\n\n3 Okra", "Torna con questi ingredienti:\n\n3 Stringy Vulture Meat\n\n3 Goretusk Snouts\n\n3 Murloc Eyes\n\n3 Okra", "Questa Okra renderà il brodo bello denso! Ora aggiungiamo la Stringy Vulture Meat, qualche Murloc Eyes e quei deliziosi Goretusk Snouts. Ed è fatta! Per tutto il tuo aiuto, {name}, voglio che prenda tu la prima porzione di oggi di Westfall Stew!", nil, 0x1fd3a0f2, 0xe339c1dc, 0xbc377ac8, 0xe18bc596, "m...." },
  [39] = { "Consegnare il rapporto di Thomas", "Fai rapporto a Marshal Dughan, a Goldshire.", "Riferisci a Marshal Dughan della morte di Malakai e Rolf, e digli che con le truppe che abbiamo ora non possiamo contenere i murloc nella parte orientale di Elwynn.\n\nSo che non abbiamo molti uomini da mandare, ma speriamo che Dughan trovi qualcuno.", nil, "Mmm, queste notizie sono preoccupanti. Le nostre difese sono già allo stremo, e perdere Rolf e Malakai per colpa di quei murloc ci mette in una posizione ancora peggiore.\n\nSe le cose non migliorano, entro la fine della settimana si combatterà a Goldshire!", 0x25228270, 0x3f1aa863, 0x2d7986ad, nil, 0xae2657cb, "...m." },
  [40] = { "Un pericolo che sa di pesce", "Remy \"Two Times\" vuole che tu parli con Marshal Dughan, a Goldshire.", "{name}, c'è una nuova minaccia nella Elwynn Forest! I murloc risalgono i torrenti della parte orientale di Elwynn, fanno scappare i pesci e aggrediscono la brava gente!\n\nHo avvertito Marshal Dughan, ma lui si preoccupa di più degli gnoll e dei banditi. Non è convinto che i murloc siano un pericolo.\n\nTi prego, {name}, parla con Dughan e convincilo a mandare altre truppe a est!", nil, "Sì, ho parlato con Remy. Lo rispetto come mercante, ma le voci sui murloc a est sono state a dir poco vaghe.\n\nPrendo nota delle tue preoccupazioni, ma a meno che non riceva un rapporto militare su una minaccia dei murloc, non possiamo permetterci di mandare altre truppe a est.", 0x02cfe285, 0x67e1f5a8, 0xb8d781bd, nil, 0xf6272f28, "...m." },
  [45] = { "Scoprire la sorte di Rolf", "Cerca Rolf nel villaggio dei murloc, o segni della sua morte.", "Cercando ancora nella zona, trovi impronte palmate che vanno verso est lungo la riva dello Stone Cairn Lake. In lontananza, a est, riesci a malapena a scorgere un villaggio di murloc.\n\nForse è lì che Rolf ha trovato la sua fine...", nil, "Al collo del cadavere trovi un medaglione di metallo con incise le parole \"Footman Rolf Hartford.\"", 0x119e499d, 0x93412d0c, 0xbf0a2396, nil, 0x0692a2fa, "...m." },
  [46] = { "Taglia sui murloc", "Porta 8 Torn Murloc Fins a Guard Thomas, al ponte orientale di Elwynn.", "La Stormwind Army ha messo una taglia sui murloc lurker e forager di Elwynn. Fanne strage e portami le loro Torn Murloc Fins: la Stormwind Army ti ricompenserà bene.\n\nI murloc hanno costruito un villaggio allo Stone Cairn Lake, a nord di qui, e un altro a sud, dove il torrente si divide.", "Come va la caccia, {name}?", "Hai le pinne? Ottimo! Marshal Dughan è in ansia per la situazione dei murloc nella parte orientale di Elwynn, e mi piacerebbe dirgli che la stiamo mettendo sotto controllo.\n\nLe tue azioni hanno contribuito a renderlo possibile.", 0xd7ee6932, 0x320c64a3, 0x05a40606, 0xd84cca78, 0xff08c2c6, "....." },
  [47] = { "Scambio di Gold Dust", "Porta 10 Gold Dust a Remy \"Two Times\", a Goldshire. La Gold Dust si raccoglie dai kobold della Elwynn Forest.", "I kobold da queste parti a volte si portano dietro della Gold Dust. Mi farebbe proprio comodo: portamene un bel po' e ti farò il miglior prezzo in città... il miglior prezzo in città!\n\nTrovi i kobold nella Fargodeep Mine, a sud, e intorno alla Jasperlode Mine, a nord-est.", "Psst! Hai quella Gold Dust per me... per me?", "Grazie per la polvere, {name}. Ecco i tuoi soldi, e... ecco un pegno da parte di alcuni miei soci. Potrebbe tornarti utile... utile.", 0x6fc1c811, 0x54bcff94, 0xcbdc7c22, 0xfc397987, 0x26e50fd4, "....." },
  [48] = { "Ambra dolce", "Porta la Holy Spring Water a Grimbooze Thunderbrew.", "A sud, dove i tralci serpeggiano intrecciati\n\nC'è un pozzo nascosto, dagli abissi più celati\n\nPuro come la sacra figlia della Luce\n\nPortami la Holy Spring Water che lì riluce.", "Hic! Oh oh! Vuoi il bis?\n\nA sud, dove i tralci serpeggiano intrecciati\n\nC'è un pozzo nascosto, dagli abissi più celati\n\nPuro come la sacra figlia della Luce\n\nPortami la Holy Spring Water che lì riluce.", "Hic! Oh oh!", 0xcfa75457, 0x4e77cd9b, 0x13610a88, 0xb098103f, 0x677f464a, "....." },
  [49] = { "Ambra dolce", "Grimbooze Thunderbrew vuole un Sack of Barley, un Sack of Rye e un Sack of Corn.", "D'ambra è il colore del mio amore più antico\n\nCome l'ultima brace del tramonto, ti dico\n\nPerché il mio amore possa infine sbocciare\n\nOrzo, segale e mais, un sacco di ciascuno mi devi portare.", "Il bis? Ma certo!\n\nD'ambra è il colore del mio amore più antico\n\nCome l'ultima brace del tramonto, ti dico\n\nPerché il mio amore possa infine sbocciare\n\nOrzo, segale e mais, un sacco di ciascuno mi devi portare.", "Hic! Oh oh!", 0xcfa75457, 0x95311fad, 0x952da726, 0x2aecfde8, 0x6787a76a, "....." },
  [50] = { "Ambra dolce", "Grimbooze Thunderbrew vuole del Truesilver.", "Mescolerò e rimescolerò finché il mosto sarà pronto\n\nSarà la nostra scorta segreta, senza alcun sconto\n\nUn alambicco di metallo forte va forgiato\n\nPortami del Truesilver e il canto sarà terminato.", "Il bis per te? Ma certo, amico!\n\nMescolerò e rimescolerò finché il mosto sarà pronto\n\nSarà la nostra scorta segreta, senza alcun sconto\n\nUn alambicco di metallo forte va forgiato\n\nPortami del Truesilver e il canto sarà terminato.", "Hic! Oh oh!", 0xcfa75457, 0x4e472b5f, 0x915c986b, 0x5199c398, 0x6787a76a, "....." },
  [51] = { "Ambra dolce", "Porta un Sycamore Branch a Grimbooze Thunderbrew.", "Non ancora filtrato ma appena distillato\n\nCome un campo senza semi, già arato e preparato.\n\nPoi preparerò il nostro mucchio di carbone\n\nPortami un ramo di sicomoro: è la tua prossima missione.", "Il bis? Per te, questo e altro!\n\nNon ancora filtrato ma appena distillato\n\nCome un campo senza semi, già arato e preparato.\n\nPoi preparerò il nostro mucchio di carbone\n\nPortami un ramo di sicomoro: è la tua prossima missione.", "Hic! Oh oh!", 0xcfa75457, 0x4d5230ce, 0x29bc75b2, 0x5a875dd3, 0x6787a76a, "....." },
  [52] = { "Proteggere la frontiera", "Uccidi 8 Prowlers e 5 Young Forest Bears, poi torna da Guard Thomas al ponte orientale di Elwynn.", "Salute, {name}. Più ci si allontana da Goldshire, più gli animali selvatici diventano aggressivi, e l'Eastvale Logging Camp subisce attacchi quasi continui da lupi e orsi!\n\nCi farebbe comodo il tuo aiuto qui.", "Hai ucciso quei lupi e quegli orsi?", "Grazie mille per l'aiuto, {name}. Qualcosa nella foresta deve rendere questi animali così audaci.\n\nQualunque cosa sia, spero che resti lì.", 0x2e116184, 0x03f5e0ac, 0x866a4bcd, 0xfcb3bc90, 0xe7a250d3, "....." },
  [53] = { "Ambra dolce", "Porta a Grimbooze Thunderbrew un fascio di Charred Oak.", "Liquore mellifluo, limpido come il pianto di un bambino\n\nCon gli anni si fa d'ambra, d'un colore sopraffino\n\nMa prima di sbronzarci da capo a piedi, a volontà\n\nUn barile di quercia carbonizzata si costruirà.", "Certo, te la ricanto, amico!\n\nLiquore mellifluo, limpido come il pianto di un bambino\n\nCon gli anni si fa d'ambra, d'un colore sopraffino\n\nMa prima di sbronzarci da capo a piedi, a volontà\n\nUn barile di quercia carbonizzata si costruirà.", "Invecchiato in botte, filtrato nel carbone\n\nTi scende in gola e ti scalda il cuore e la ragione.\n\nBeviamo dunque, un brindisi a te\n\nE a me già che ci siamo, Grimbooze Thunderbrew!", 0xcfa75457, 0x2911d99e, 0x90b69e3d, 0xe5239d0c, 0x5368c39a, "....." },
  [54] = { "Rapporto a Goldshire", "Porta i Marshal McBride's Documents a Marshal Dughan, a Goldshire.", "{name}, come {class} hai dimostrato di avere a cuore la sicurezza di Northshire. Ora ti viene affidata la protezione della Elwynn Forest che la circonda.\n\nSe accetti questo incarico, ho preparato dei documenti da consegnare a Marshal Dughan, a Goldshire. Goldshire si trova lungo la strada a sud, oltre i cancelli di confine.", "Hai notizie da McBride? Northshire è un giardino in confronto alla Elwynn Forest, ma chissà cosa ha da riferire Marshal McBride.\n\nForza, dammi i suoi documenti...", "Bene, qui dice che ti è stato conferito il grado di Acting Deputy presso gli Stormwind Marshals. Congratulazioni.\n\nE buona fortuna: tenere al sicuro Elwynn non è una passeggiata... con quasi tutto l'esercito impegnato a fare chissà cosa per chissà quale nobile!\n\nÈ difficile stare dietro alla politica in questi tempi bui...", 0xccb7dcaf, 0xc0ef425f, 0xd8bc24db, 0xf6530924, 0xb56df9b4, "....." },
  [55] = { nil, "Usa il Morbent's Bane su Morbent Fel, uccidi Morbent Fel, poi riporta il Morbent's Bane a Sven nel suo accampamento.", "Morbent Fel si nasconde nel suo covo, la casa arroccata in cima alla collina a est, che domina il cimitero di Raven Hill. Il suo tempo in questa terra sta per finire...\n\nUsa contro di lui il Morbent's Bane. Renderà inutili le sue magie protettive.\n\nUccidilo. Uccidilo, e salvaci dalla sua malvagità. Sii lo strumento della mia vendetta, e un eroe di Duskwood!", "Morbent Fel è stato sconfitto?!", "Morbent Fel è stato sconfitto. I dark riders sono ancora in libertà, ma una piccola parte di ciò in cui speravo contro ogni speranza si è avverata.\n\nHai fatto l'impossibile, e le tue gesta vivranno per sempre nelle leggende di Duskwood.\n\nVai, {name}. E forse, un giorno, il destino ti riporterà da me...", nil, 0xee859640, 0xa0025f54, 0x7f970e9e, 0x80e0a20a, "m...." },
  [56] = { "La Night Watch", "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 8 Skeletal Warriors e 6 Skeletal Mages.", "Come comandante della Night Watch, ho giurato di proteggere i cittadini di Darkshire. Stormwind ha ritirato da qui le guardie che ci aveva assegnato, lasciandoci a cavarcela da soli.\n\nSe ti senti all'altezza del compito, abbiamo bisogno del tuo aiuto! Aiuta la Night Watch addentrandoti nei Tranquil Gardens, appena a sud di Darkshire, e uccidendo 8 Skeletal Warriors e 6 Skeletal Mages. La minaccia dei non morti va sventata!", "Vedo che sei <tornato/tornata>, {name}. Se vuoi dimostrare di poter servire la Night Watch, torna da me quando avrai ucciso 8 Skeletal Warriors e 6 Skeletal Mages.", "Splendido, {name}. Sarai <ricompensato/ricompensata> per il servizio reso alla gente di Darkshire.", 0x50990c24, 0x988ea067, 0xb762390c, 0x426a38c5, 0x00bdfe75, "....." },
  [57] = { "La Night Watch", "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 15 Skeletal Fiends e 15 Skeletal Horrors.", "{name}, mi arrivano notizie di un'infestazione di non morti nella foresta! Se te la senti, vai al cimitero di Raven Hill e uccidi 15 di quei luridi Skeletal Fiends e 15 Skeletal Horrors. Ci sono anche notizie di scheletri appena a sud di Darkshire, dentro e intorno al Tranquil Gardens Cemetery. I non morti vanno cacciati da Duskwood!", "Torna da me quando avrai ucciso 15 Skeletal Fiends e 15 Skeletal Horrors, {name}.", "La gente di Darkshire ti ringrazia, {name}. Hai dimostrato di essere un grande alleato della Night Watch.", 0x50990c24, 0xb2d050a2, 0xc3805ea3, 0x159417dc, 0xfa65ff23, "....." },
  [58] = { "La Night Watch", "Commander Althea Ebonlocke di Darkshire vuole che tu uccida 20 Plague Spreaders nel mausoleo orientale di Raven Hill.", "La situazione a Raven Hill è ancora cupa. La sicurezza di Darkshire è nelle tue mani, {name}. Non ho abbastanza Watchers per tenere al sicuro il paese. Ci serve che tu parta ancora una volta per Raven Hill e liberi il mausoleo orientale da 20 Plague Spreaders!", "Ho bisogno del tuo aiuto, {name}. Vai al cimitero a nord-ovest e libera il mausoleo orientale da 20 Plague Spreaders.\n\nTorna da me quando avrai portato a termine il compito.", "A nome della gente di Darkshire e come capo della Night Watch, ti ringrazio, {name}, per il tuo coraggio e la tua dedizione. Che la Luce illumini il tuo cammino.", 0x50990c24, 0x1fb37e1e, 0xf156af7a, 0x20d0eab3, 0xe664400d, "....." },
  [59] = { "Armature di stoffa e di cuoio", "Consegna lo Stormwind Armor Marker a Sara Timberlain.", "Per la tua astuzia e il tuo valore ho qui un buono che vale un pezzo d'armatura. Portalo a Sara Timberlain, all'Eastvale Logging Camp. Dalle il buono e lei ti forgerà l'armatura. E quando l'avrai, {name}, usala per difendere Elwynn.\n\nL'Eastvale Logging Camp si trova oltre il posto di guardia di Guard Thomas, a est.", "La Stormwind Army mi ha incaricata di fornire alla sua gente armature di stoffa e di cuoio.\n\nSe hai un buono per me, sarò felice di prepararti qualcosa.", "Ah, grazie per il buono. Scegli pure l'armatura che preferisci.\n\nBuona fortuna, prode {class}. E che questa armatura ti serva bene.", 0x751bcd47, 0x88cbb6e2, 0xec149fa7, 0xa0219e98, 0xff5c34aa, "....." },
  [60] = { "Candele dei kobold", "Porta 8 Large Candles a William Pestle, a Goldshire.", "Salve, <messere/madama>! Hai un momento?\n\nIo e mio fratello gestiamo una bottega di speziale a Stormwind, e sono qui a raccogliere Large Candles per la loro cera. Puoi aiutarmi?\n\nLe Large Candles si ottengono dai kobold, e si dice che i kobold stiano infestando le miniere di Elwynn... la Fargodeep Mine a sud e la Jasperlode Mine a est. Ti consiglio di cercare le candele in uno di quei posti.", "Hai già raccolto quelle candele?", "Ti sei <dato/data> da fare a cacciare kobold, eh? Grazie per le candele, {name}: ecco la tua ricompensa...", 0x514933bf, 0xd8ce4567, 0x6cce32c4, 0x77e7ca88, 0x98618684, ".....", nil, nil, 0x1993cf97, nil, nil },
  [61] = { "Una spedizione per Stormwind", "Porta la William's Shipment a Morgan Pestle, nello Stormwind Trade District.", "Mio fratello Morgan aspetta a Stormwind la mia spedizione di candele. Non ho tempo di fare il viaggio di persona, ma se vuoi portargli tu la spedizione, ti pagherà bene.\n\nHo impacchettato le candele: troverai Morgan nella nostra bottega, la Pestle's Apothecary, nello Stormwind Trade District.", "Oh, una spedizione da mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", "Ecco il tuo compenso... e già che sei qui, dai un'occhiata in giro! Di sicuro abbiamo una pozione o un altro gingillo che ti tornerà utile.", 0x6a825135, 0xdeec4138, 0xd71ae934, 0x89b01d8f, 0xdf7db746, "....." },
  [62] = { "La Fargodeep Mine", "Esplora la Fargodeep Mine, poi torna da Marshal Dughan a Goldshire.", "La miniera di Northshire non è l'unica ad avere problemi! Mi riferiscono che anche la Fargodeep Mine, a Elwynn, è diventata un rifugio per i kobold.\n\nEsplora la miniera e conferma queste voci, poi torna da me. La miniera si trova quasi esattamente a sud di Goldshire, tra le fattorie degli Stonefield e dei Maclure.", "Cosa hai da riferire, {name}? Sei <stato/stata> alla Fargodeep Mine?", "Brutte notizie. Cosa ci aspetta ora, i draghi?!? Dovremo aumentare le pattuglie vicino a quella miniera. Grazie per i tuoi sforzi, {name}. E aspetta un momento... forse ho un altro compito per te.", 0x3a373e5c, 0x068c7c5b, 0x196f6d77, 0x620f4981, 0x902000cc, "....." },
  [63] = { "Il richiamo dell'acqua", "Sconfiggi la Corrupt Manifestation of Water e poni i Corrupted Manifestation's Bracers insieme ai Remaining Drops of Purest Water sul Brazier of Everfount, nella Silverpine Forest.", "Lungo la costa di Silverpine, a ovest del Sepulcher, troverai un santuario contaminato dalla piaga. Gli spiriti di quel luogo non parlano più alla nostra gente, e toccherà a te sconfiggere la manifestazione e purificare la pozza.\n\nPrendi i bracciali dell'elementale, insieme alle ultime gocce della pozione di Brine, e ponili sul braciere. Il rituale dovrebbe bastare a evocare uno spirito puro con cui comunicare.\n\nPortami la prova che il compito è svolto e ti ricompenserò con il tuo totem.", "Il braciere riflette ancora la luce dell'ambiente circostante, e la fiamma tremola appena mentre ti avvicini.\n\nLa corruzione lungo le colline sembra essersi tenuta a distanza e, a parte i componenti mancanti, il braciere sembra pronto per il rituale che evoca una manifestazione purificata dell'acqua.", "Poni i bracciali sopra il braciere e versi le ultime gocce della pozione di Brine nella fiamma. Le gocce crepitano a contatto con la fiamma e cominci a recitare le semplici parole che Islen ti ha insegnato....", 0x1f0e11aa, 0xaa58c2a7, 0xf6931e98, 0x94ae3991, 0x8260098f, "....." },
  [64] = { "Il cimelio dimenticato", "Farmer Furlbrow vuole che tu recuperi il suo orologio da taschino dall'armadio della sua casa, alla fattoria delle zucche a ovest.", "È stato orribile! Verna mi ha svegliato quando ha sentito un baccano nei campi. I campi erano pieni di teppisti. Siamo scappati di corsa e ho dimenticato di prendere il mio orologio da taschino. Il padre di Verna me lo regalò il giorno del nostro matrimonio, e mi sento male al pensiero che ce l'abbiano quei ladri. L'ho lasciato nell'armadio, in casa. Cerca il campo di zucche a ovest: non puoi sbagliare. Se me lo riporti, te ne sarò davvero grato!", "Non è che sei <riuscito/riuscita> a prendere il mio orologio?", "Il mio orologio! Grazie mille, gentile <signore/signora>!\n\nSiamo solo poveri contadini e abbiamo perso la nostra terra, ma ti prego, accetta questa ricompensa come segno della nostra gratitudine.", 0xf0e121ad, 0xdbaefd0c, 0xf295ad64, 0xc78af9a9, 0x1ca851f8, ".....", nil, nil, nil, nil, 0xd9a3b24b },
  [65] = { "La Defias Brotherhood", "Gryan Stoutmantle vuole che tu parli con Wiley, a Lakeshire.", "La banda di miserabili che ha cacciato la brava gente di Westfall dalle sue terre si fa chiamare The Defias Brotherhood. Ho bisogno che tu ti infiltri in questa combriccola di delinquenti. Dobbiamo sapere chi guida l'organizzazione e dove si nascondono. A Lakeshire, alla locanda, c'è un ladro di nome Wiley che mi deve un favore.\n\nVai a Lakeshire, nelle Redridge Mountains, a est di Elwynn, e scopri quello che puoi.", nil, "Così ti manda Stoutmantle? Be', gli devo un favore.", 0x2a2224c0, 0x5c71d76f, 0x567bbd13, nil, 0xd8800e68, "...m." },
  [66] = { "La leggenda di Stalvan", "Cerca il Clerk Daltry nella Town Hall di Darkshire.", "La notte scorsa un orribile turbamento mi ha attraversato le vene. Ho percepito che mia nipote, Alyssa, era in grave pericolo. Ho consultato le carte e la morte mi ha fissato dal tavolo.\n\nDopo un lungo viaggio in una trance oscura, sono riuscita a scoprire un indizio di questo terrificante mistero. Mi è giunto un nome, il nome di Stalvan.\n\nCerca il Clerk nella Town Hall e vedi se riesci a scoprire di più su questo personaggio. Temo per tutti noi.", nil, "Ah, quindi ti ha mandato Madame Eva. . . .", 0xeb6571fb, 0xef91d1ff, 0x44b56c82, nil, 0x4de8a455, "...m." },
  [67] = { "La leggenda di Stalvan", "Recati alla Moonbrook Schoolhouse e riporta al Clerk Daltry qualsiasi nuova informazione su Stalvan.", "Stalvan, eh? Fammi controllare il registro cittadino.\n\nStalvan. . .Stalvan. . .vediamo. Ah, eccolo! Ho una registrazione di un certo signor Stalvan Mistmantle. L'ultimo indirizzo registrato è la Moonbrook Schoolhouse. Accidenti, altro che informazioni datate!\n\nFammi un favore, amico, va bene? Se capiti a Moonbrook, fammi sapere se hai notizie aggiornate su questo tizio. Mi piace tenere i registri in ordine.", nil, "Il vecchio baule si apre cigolando. . . .", 0xeb6571fb, 0x660c738d, 0x277b14bd, nil, 0x45ee8251, "...m." },
  [68] = { "La leggenda di Stalvan", "Porta la Dusty Unsent Letter al Clerk Daltry.", "Nel vecchio baule trovi una Dusty Unsent Letter.", "Ah, mi ricordo di te. Sei tu che chiedevi di quel tale Stalvan. Hai poi trovato ciò che cercavi?", "Interessante. Quindi il tizio ha davvero passato un po' di tempo a Moonbrook. È piuttosto strano che la lettera non sia mai stata consegnata. Comunque aggiornerò il registro.", 0xeb6571fb, 0x4e15fabb, 0x5b2de8d4, 0x78055707, 0x9c5b8cbb, "....." },
  [69] = { "La leggenda di Stalvan", "Va' alla Lion's Pride Inn per vedere se qualcuno ha sentito parlare di Stalvan.", "Oh, cielo! Devo essermelo perso la prima volta. Nel registro, proprio sotto il primo indirizzo di Stalvan, ce n'è un altro, cancellato solo in parte. Sembra che fosse diretto alla Lion's Pride Inn, a Goldshire. Forse vuoi controllare lì, {name}.", nil, "Stalvan? Di sicuro mi suona familiare.", 0xeb6571fb, 0x4acc049c, 0xa5734139, nil, 0xe0613a9e, "...m." },
  [70] = { "La leggenda di Stalvan", "Prendi la Stalvan's Undelivered Letter dal baule e consegnala nel Canal District di Stormwind.", "Il nome Stalvan mi dice qualcosa. Ora ricordo.\n\nMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di riparo per la notte. Verso la mezzanotte, l'uomo si precipitò giù per le scale urlando, pallido di paura. Ancora in camicia da notte, sparì sotto l'acquazzone.\n\nNella fretta dimenticò le sue lettere nel baule al piano di sopra, e non tornò mai a riprenderle. Ne è rimasta una di quel tale Stalvan, destinata al Canal District di Stormwind. Prendila pure.", "Cos'hai lì? Fammi dare un'occhiata. . .", "Hai una bella faccia tosta a portare questa roba qui.", 0xeb6571fb, 0xec87b2a9, 0xcf8206e0, 0xad2d2675, 0xf3e822c5, "....." },
  [71] = { "Rapporto a Thomas", "Consegna i Rolf and Malakai's Medallions a Guard Thomas, al ponte orientale di Elwynn.", "Ora che hai entrambi i medaglioni, consegnali a Guard Thomas al ponte, perché sappia che fine hanno fatto le sue guardie assassinate.", "Salve, {name}. Hai scoperto che fine hanno fatto Rolf e Malakai?", "Hai confermato i miei timori, {name}. I murloc sono una minaccia che non possiamo ignorare.", 0xcad5f606, 0xdfec0126, 0xfecbb9ef, 0x8c9b780e, 0xab891fb8, "....." },
  [72] = { "La leggenda di Stalvan", "Fruga tra gli effetti imballati in cerca di un indizio.", "Mio padre era il custode della tenuta molto prima di me. Dovette pulire il sangue dopo il massacro. Ma questo non c'entra.\n\nGli ultimi fondi del lascito Flintridge si sono esauriti. Ora gli ultimi beni della famiglia finiranno all'asta. Prenditela con gli avvoltoi delle tasse. Immagino che, se proprio muori dalla voglia di saperne di più, puoi frugare tra questa robaccia. Chissà cosa potresti trovare.", nil, "Fai scivolare lentamente il coperchio della cassa. . . .", 0xeb6571fb, 0x119baf0f, 0xf129a3f9, nil, 0xe56b8406, "...m." },
  [74] = { "La leggenda di Stalvan", "La Torn Journal page che hai scoperto ti fornisce il prossimo indizio.", "Nella cassa trovi vari oggetti: cimeli ammuffiti, un ritratto di famiglia, qualche trofeo di caccia e alcuni vecchi libri. Vicino al fondo, sotto un vaso di ceramica, scopri A Torn Journal Page.", "Cos'hai lì? Non ci vedo. La mia vista è pessima. Mettimelo in mano.", "Riesco a malapena a distinguere quelle lettere. Ma quello stile di scrittura mi ricorda qualcosa che vidi una volta, prima che la mia vista peggiorasse così.", 0xeb6571fb, 0x0bc0d882, 0xe3b43f83, 0x20b24ea6, 0x3a5de944, "....." },
  [75] = { "La leggenda di Stalvan", "Marshal Haggard vuole che tu cerchi la Faded Journal Page nel baule al piano di sopra.", "Quando mi trasferii qui, nel baule al piano di sopra c'era un fascio di pergamene. Le guardai una volta appena arrivato, ma ci rinunciai quando la nebbia mi annebbiò gli occhi.\n\nFai un favore a un vecchio quasi cieco e guarda nel baule di sopra se c'è qualcosa che possa aiutarti a scoprire di più su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.", "Hai trovato la pagina di cui ti parlavo, {name}?", "L'hai trovata!", 0xeb6571fb, 0x74cb8926, 0x33923181, 0x856913a4, 0x3715d975, "....." },
  [76] = { "La Jasperlode Mine", "Esplora la Jasperlode Mine, poi torna a fare rapporto a Marshal Dughan a Goldshire.", "Grazie a te sappiamo che la Fargodeep Mine è infestata dai kobold. Ora ci serve un esploratore che indaghi sulla Jasperlode Mine, più lontana.\n\nEsplora la Jasperlode e verifica se ci sono kobold. Per raggiungere la miniera, segui la strada verso est fino alla Tower of Azora. Dalla torre vai a nord e troverai la miniera ai piedi delle colline.", "Salute, {name}. Cosa hai da riferire? Hai esplorato la Jasperlode Mine?", "Kobold alla Jasperlode Mine, dici? Maledizione! La situazione peggiora di minuto in minuto!\n\nGrazie per il rapporto, {name}. Ma vorrei che le notizie che mi porti fossero buone.", 0x0323d68b, 0xb489dc45, 0xd63cfe6e, 0x3d82a623, 0xf3bd38e1, "....." },
  [78] = { "La leggenda di Stalvan", "Porta la Faded Journal Page a Tavernkeep Smitts.", "Conosco qualcuno che potrebbe aiutarti. Quando comandavo la Stormwind Guard, andavamo a bere alla Scarlet Raven Tavern, a Darkshire. Il locandiere, Smitts, era un vero esperto delle storie del posto. Mostragli questa pagina e senti cosa ne pensa.", "Ti manda Marshal Haggard? Perché non l'hai detto subito?\n\nAh, il buon vecchio Haggard. Poveretto, tra non molto sarà completamente cieco. Comunque, fammi vedere cos'hai lì.", "Per la Luce! Puoi scommetterci che riconosco questa calligrafia.", 0xeb6571fb, 0x9665adb8, 0xd11badb8, 0x01f28add, 0x017fe17b, "....." },
  [79] = { "La leggenda di Stalvan", "Porta la pagina infangata al Commander Ebonlocke.", "Ho seguito la leggenda di quel tale Stalvan per anni. Quando quei nobili in visita furono massacrati qualche anno fa, andai a indagare con Haggard. Trovai queste pagine infangate, ma non riuscimmo mai a collegare la calligrafia a quel pazzo nei boschi. Le prove che hai raccolto dimostrano la sua colpevolezza. Porta subito questo al Commander Ebonlocke e mettila al corrente di ciò che hai scoperto!", "Che sia qualcosa di buono, {class}. Fammi vedere cos'hai e raccontami la tua storia. Ma per la Luce, sbrigati. La difesa di Darkshire è la mia priorità assoluta. Non ho tempo da sprecare con piste senza sbocco.", "Accidenti, hai dimostrato di essere <un/una> <bravo/brava> detective, {class}.", 0xeb6571fb, 0xa2f0228c, 0x74cec9b0, 0xac774803, 0x7a5abbbe, "....." },
  [80] = { "La leggenda di Stalvan", "Mostra al Clerk Daltry la Bloodstained Journal Page.", "Tengo d'occhio quel mostro, Stalvan, da parecchio tempo. Ma se questa pagina è stata scritta dalla stessa mano, prova la sua colpevolezza al di là di ogni dubbio.\n\nIn tutti i suoi anni alla tenuta del Town Registry, il Clerk Daltry è diventato un esperto nel riconoscere le calligrafie. Mostragli questa pagina e vedi se la scrittura corrisponde alla firma del registro.", "Di nuovo qui, {name}? Cos'hai questa volta?", "Ma sì! La scrittura su questa pagina corrisponde davvero a quella delle firme del registro.", 0xeb6571fb, 0xde53f421, 0x3946b54a, 0x851ef05a, 0xedad08fb, "....." },
  [83] = { "Merce di lino rosso", "Porta 6 Red Linen Bandanas a Sara Timberlain, all'Eastvale Logging Camp.", "La banda dei Defias a Northshire porta maschere di tela di sacco, ma i Defias di Elwynn indossano il lino, che posso usare per confezionare ottimi capi.\n\nPortami delle Red Linen Bandanas e le userò per farti qualcosa.\n\nI membri della banda dei Defias hanno accampamenti sparsi in tutta Elwynn.", "Sto finendo il lino, {name}. Ne hai per me?", "Ah, sono belle bandane, anche se un po' ruvide...\n\nEcco qua!", 0xab13ee46, 0x6ab947a0, 0x2f31ce58, 0x13c355f0, 0xb808f80e, "....." },
  [84] = { "Ritorno da Billy", "Porta la Pork Belly Pie a Billy Maclure, ai Maclure Vineyards.", "Ecco qua. E quando dai questa torta a quel Billy, digli che spero gli vada di traverso!", "Uff... sto morendo di fame! Hai quella torta per me, {name}?", "Mmm, che buona! Questa torta è la migliore!\n\nMi sa che mi sta tornando la memoria...", 0x77e92707, 0xb3802d9c, 0x8c11f6b5, 0xa7950cc8, 0x90374641, "....." },
  [85] = { "La collana perduta", "Parla con Billy Maclure.", "Ho perso la mia collana, e credo che l'abbia presa quel monello di Billy Maclure! Di solito zampetta come un ratto intorno ai Maclure Vineyards, a est di qui.\n\nRiportami la collana e scalderai il cuore di una vecchia vedova.", nil, "Hai perso cosa? Be', io nessuna collana ho preso, perché non sono mica un ladro!\n\nForse so chi è stato, ma... <sogghigna>... ho troppa fame per ricordarmelo.", 0x1a691c23, 0x3c0d0519, 0xc37d5922, nil, 0xc488cf29, "...m." },
  [86] = { "Una torta per Billy", "Porta 4 Chunks of Boar Meat ad Auntie Bernice Stonefield, alla Stonefield's Farm.", "Forse, se avessi una torta, potrei dirti chi ha quella collana. E sai, credo che quella vecchia Bernice dell'altra fattoria faccia delle ottime Pork Belly Pie...\n\nMagari, se le dai un po' di carne dei cinghiali che girano intorno alle nostre fattorie e le dici a cosa serve, ti cuocerà una torta.", "Non mi sembra giusto sfamare proprio il ragazzo che mi ha rubato la collana, ma se è questo che serve per riavere ciò che è mio, e sia!\n\nHai quella carne di cinghiale?", "Questa carne di cinghiale selvatico è dura, ma se la fai sobbollire abbastanza viene fuori proprio una torta squisita!", 0xe258953a, 0x3d1f7b01, 0xb9e0bfdc, 0xd53bb684, 0x6b1f64bc, "....." },
  [87] = { nil, "Porta la Bernice's Necklace ad \"Auntie\" Bernice Stonefield, alla Stonefield Farm.", "Stavo giocando vicino alla Fargodeep Mine, e credo di aver perso, ehm... cioè, di aver visto la collana della vecchia. Non chiedermi come ci sia finita... non sono stato io!\n\nBe', comunque, ho visto un kobold grosso, con un dente d'oro, raccogliere la collana e scappare nella miniera. Trova quel kobold e troverai la collana, lo giuro!", "Salve, {name}. Hai trovato la mia collana?", "Oh, l'hai trovata! Grazie, grazie, tesoro!\n\nTieni, prendi questo. Era di mio marito, e diceva sempre che portava fortuna. Se solo non l'avesse dimenticato durante la sua ultima campagna! *snif*", nil, 0xec235807, 0x329228f9, 0x511d94a7, 0x9137e39e, "m...." },
  [88] = { "Princess deve morire!", "Uccidi Princess, prendi il suo collare e portalo a Ma Stonefield, alla Stonefield Farm.", "I Brackwell hanno una maiala che ha vinto dei premi, Princess. La scrofa è enorme, ed è diventata così venendo di nascosto qui a mangiarsi le mie verdure!\n\nQuindi, prima che arrivi ai nostri campi... Princess deve morire! Portami il suo collare come prova e ti darò qualcosa per il disturbo!\n\nDi solito Princess sta nella Brackwell Pumpkin Patch, a est, oltre la fattoria dei Maclure. Prendila prima che le venga fame e torni qui!", "L'hai vista? L'hai presa?", "Meno male! Quella maiala stava diventando così grossa che si sarebbe mangiata tutto il raccolto! Grazie, {name}.\n\nAllora, ti va bene una di queste cose?", 0xd0c3b757, 0x87ee4e48, 0xb6b583eb, 0x6ce3847c, 0x8ee1d213, "....." },
  [89] = { "L'Everstill Bridge", "Porta 5 Iron Pikes e 5 Iron Rivets a Foreman Oslow, a Lakeshire.", "Durante l'ultima invasione degli orchi siamo stati costretti a fondere il nostro ferro per farne proiettili, spade e armature. Abbiamo chiesto a Stormwind una nuova spedizione di materiali, ma una banda di gnoll di Redridge ha assaltato la carovana ed è fuggita sulle colline dietro Lakeshire.\n\nOra ci mancano le scorte per ricostruire questo ponte. Se mi porti 5 Iron Pikes e 5 Iron Rivets, {name}, farò in modo che tu venga ricompensato.\n\nOra mettiamoci al lavoro!", "Questo ponte non si costruisce da solo! Allora, dove sono quelle Iron Pikes e quei Iron Rivets?", "Ottimo lavoro, {name}. Questi materiali aiuteranno moltissimo a ricostruire il ponte. Rimetteremo in piedi questa bellezza in un attimo.", 0xfbe560d1, 0x5c73aae5, 0xcb575d10, 0xf3038219, 0xf1b96a47, "....." },
  [90] = { nil, "Raccogli 10 Lean Wolf Flanks e torna da Chef Grual, a Darkshire.", "I Seasoned Wolf Kabobs sono una specialità della casa! Certo, posso fartene qualcuno. Ma prima mi servono gli ingredienti. Portami 10 Lean Wolf Flanks. Con tutti i lupi che ci sono nella foresta, sono sicuro che trovare i Flanks non sarà un problema. Per tua fortuna mi è appena arrivata la spedizione di Stormwind Seasoning Herbs, quindi per cominciare mi servono solo i fianchi.", "Sei <riuscito/riuscita> a trovare 10 Lean Wolf Flanks? E le erbe di Felicia, a Stormwind?", "Ottimo lavoro, {name}! Goditi la prelibatezza nota come Seasoned Wolf Kabob!", nil, 0xb8f7846f, 0x7f6f2eef, 0x00eddfcd, 0x6c901c98, "m...." },
  [91] = { "La legge di Solomon", "Porta 10 Shadowhide Pendants a Bailiff Conacher, nella Lakeshire Town Hall.", "Un nemico di Stormwind si è stabilito sulle colline orientali di Redridge. Questo malvagio usa l'Arcane per seminare terrore e sofferenza nel nostro paese e tra la nostra gente. Porta avanti i suoi affari malvagi con il nome di Morganth.\n\nOra Morganth controlla lo Shadowhide Gnoll Clan, che esegue i suoi ordini. Come stabilisce la Law of Lakeshire, aiutare un criminale del regno si punisce con la morte.\n\nQuesti luridi gnoll vanno uccisi!\n\nConsegnami 10 Shadowhide Pendants e sarai ricompensato.", "Consegnami 10 Shadowhide Pendants e sarai <ricompensato/ricompensata>.", "La Court of Lakeshire riconosce il tuo impegno per la giustizia, {name}. Facendo rispettare le leggi del regno, hai contribuito a difendere la giustizia di queste terre.", 0x4cdcd468, 0x14f882a1, 0xdf5729ff, 0x236bce06, 0x10ddb922, "....." },
  [92] = { nil, "Chef Breanna di Lakeshire vuole 5 pezzi di Tough Condor Meat, 5 Great Goretusk Snouts e 5 porzioni di Crisp Spider Meat.", "Niente mi farebbe più piacere che prepararti un po' di Redridge Goulash. Ma c'è un piccolo problema. Durante la recente rivolta degli orchi ho sfamato l'intera brigata delle truppe di Stormwind. Ora la mia dispensa è vuota. Ma se mi procuri gli ingredienti, sarò felice di accontentarti.\n\nPortami solo 5 pezzi di Tough Condor Meat, 5 Great Goretusk Snouts e 5 porzioni di Crisp Spider Meat.", "Mi servono ancora 5 pezzi di Tough Condor Meat, 5 Great Goretusk Snouts e 5 porzioni di Crisp Spider Meat.", "Ben fatto, {name}. E che begli esemplari! Ed ecco la tua prelibatezza nota come Redridge Goulash!", nil, 0xa292ee13, 0x05480404, 0x61808eeb, 0xd0740ab9, "m...." },
  [93] = { nil, "Raccogli 6 Gooey Spider Legs e portale a Chef Grual, a Darkshire.", "Ti svelo un piccolo segreto: le Dusky \"Crab\" Cakes in realtà sono fatte con zampe di ragno! Lo so, è un po' disgustoso, ma le tortine hanno un bel sapore aspro e sono uno spuntino ottimo! Portami delle Gooey Spider Legs e te ne preparo qualcuna.\n\nHo sentito che i Venom Web Spiders sono una buona fonte: fanno il nido a nord, tra le colline e il fiume.", "Salute, {name}. Hai già preso quelle Gooey Spider Legs?", "Ah, sì, che bel mucchio di zampe! Lasciami solo condirle con le mie spezie segrete (non guardare!) e farle sfrigolare in padella per un po'...\n\nE anche se le Dusky Crab Cakes sono la mia specialità e la ricetta non la do a nessuno, ecco la ricetta di un piatto buono quasi quanto loro.", nil, 0x8efb36e6, 0x27a03112, 0x7c48a403, 0x83bd0d84, "m...." },
  [94] = { "Un occhio vigile", "Porta il Glyph of Azora alla Lion Statue vicino alla Tower of Ilgalar, a Redridge.", "Il mio rivale, Morganth, è un mago spietato e molto potente che vive nella Tower of Ilgalar, a Redridge. Ho escogitato un modo per spiarlo, l'Eye of Azora, e ora posso osservarlo da lontano.\n\nMa per studiare i suoi pensieri... mi serve altro aiuto.\n\nSe te la senti, porta il mio Glyph of Azora alla Tower of Ilgalar e posalo sulla Lion Statue vicino alla torre.\n\nFatto questo, il potere di Azora mi concederà visioni dei piani futuri di Morganth.", "Questa Lion Statue sta qui da decenni e veglia solitaria sulla famigerata Tower of Ilgalar.\n\nAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...", "Posi il Glyph of Azora sulla pietra. Aderisce da solo... e ne senti uscire la voce senza corpo di Theocritus:\n\nHai la mia gratitudine, giovane {name}. Ora potrai parlarmi attraverso questo glifo, e forse avrò altri compiti per te... dopo aver sondato i pensieri del mio rivale.", 0x4ce3e4cb, 0xae7ae989, 0x32080b45, 0x5d05e43a, 0x338c1c3b, "....." },
  [95] = { "La vendetta di Sven", "Vai alla Sven's Farm e trova cosa è stato sepolto dietro il vecchio ceppo.", "Lavoravo in una delle fattorie a sud-est... finché i Dark Riders del Deadwind Pass non piombarono sulla mia fattoria e massacrarono la mia famiglia mentre ero via!\n\nQuando tornai, vidi una figura nell'ombra che si aggirava furtiva vicino al mio fienile, a seppellire qualcosa. Fuggì prima che potessi prenderla, e io non potevo trattenermi perché ero alle calcagna dei Dark Riders. Così non scoprii mai cosa fosse nascosto.\n\nSe riesci a trovare cosa ha seppellito quella figura, te ne sarò grato. Il nascondiglio è dietro il vecchio ceppo vicino al mio fienile.", nil, "Qui c'è un mucchio di terra, ammassato in fretta, come se qualcuno avesse avuto bisogno di nascondere qualcosa... senza molto tempo per farlo.", 0x09c1ac2f, 0x7218d46f, 0x01da608e, nil, 0xacd152b2, "...m." },
  [96] = { "Il richiamo dell'acqua", "Porta lo Shard of Water a Islen Waterseer, nelle Barrens.", "Prendi frammento. Prendi frammento e dai vita.\n\nDai vita e capisci. Capisci acqua è vita... corruzione ferma vita.\n\nTu proteggi e dai vita con potere dell'acqua.", "Sei <tornato/tornata>. Splendido!\n\nCom'è andato il tuo viaggio a Silverpine? Ci hai messo molto?\n\nÈ difficile per me capire se hai avuto successo laggiù, perché gran parte della terra è diventata corrotta. Il suo fetore sovrasta qualsiasi bene tu abbia fatto. Ma i piccoli successi a volte sono importanti quanto quelli grandi. Purificare l'acqua laggiù è stato fondamentale per te e per tutti gli sciamani.", "Questa è la prova che ti ho chiesto. Hai fatto bene, {name}.\n\nSono lieta di essere la prima a congratularmi con te e a darti questo... il tuo totem dell'acqua.\n\nUsalo bene, e buona fortuna.\n\nLa tua prossima prova non arriverà per un po', quindi impara bene le tue lezioni. L'acqua pura non solo restituisce la vita a chi è ferito, ma può avere molti altri effetti. Ti suggerisco di cercare un istruttore degli sciamani quando ne avrai il tempo. Potrebbe avere altri incantesimi da insegnarti.", 0x1f0e11aa, 0xb068b278, 0x1bc4c72c, 0xb4ccba7c, 0x8edac29b, "....." },
  [97] = { "La leggenda di Stalvan", "Riferisci la notizia al Commander Ebonlocke.", "Fai sapere subito al Commander Ebonlocke che la calligrafia corrisponde, {name}! I suoi sospetti erano fondati!", "Sì, {name}?", "Lo sapevo! Ottimo lavoro, {name}.", 0xeb6571fb, 0xf668237f, 0x89f670d8, 0xabfc0333, 0xe1fbbf40, "....." },
  [98] = { "La leggenda di Stalvan", "Uccidi Stalvan Mistmantle e mostra a Madame Eva l'anello della sua famiglia.", "Stalvan Mistmantle ha condotto una vita di depravazione. Vittime innocenti sono morte per mano sua. Senza dubbio è colpevole di innumerevoli crimini. Ora quel folle minaccia Darkshire. Solo la Luce sa quali atti abietti stia tramando. Recati al suo cottage appena a nord della città, {class}, e giustizia Stalvan, una volta per tutte.\n\nQuando l'avrai fatto, va' da Madame Eva e mostrale l'anello della sua famiglia. Dopotutto è stata la sua premonizione a portare a questa macabra scoperta. Ma grazie a lei Darkshire è più sicura.", "Sì, {name}?", "Lo so, {name}: Stalvan è morto. Ho sentito un'ondata di speranza attraversare la foresta contaminata. Una volta per tutte, Duskwood è libera dalla sua sete di sangue. La mia gioia è offuscata dal pensiero di chi è caduto vittima di quell'orribile bestia. Comunque, sei {class} di grande coraggio e astuzia.", 0xeb6571fb, 0x6cc7a1f9, 0xf2779455, 0xabfc0333, 0x9b99fbec, "....." },
  [100] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [101] = { "Il Totem of Infliction", "Porta 10 Ghoul Fangs, 10 Skeleton Fingers e 5 Vials of Spider Venom a Madame Eva, a Darkshire.", "Mentre la corruzione mistica si insinua nella foresta, il bisogno di proteggersi è innegabile, {name}. I venti mi sussurrano e mi parlano di un grande pericolo che ti attende paziente nel prossimo futuro.\n\nSe vuoi proteggerti, nobile {class}, portami 10 Ghoul Fangs, 10 Skeleton Fingers e 5 fiale di veleno di ragno. Per te incanterò un Totem of Infliction che ferirà chi tenterà atti violenti contro di te.", "Portami 10 Ghoul Fangs, 10 Skeleton Fingers e 5 fiale di veleno di ragno. Per te incanterò un Totem of Infliction che ferirà chi tenterà atti violenti contro di te.", "Molto saggio da parte tua, {name}. Questo Totem of Infliction ti aiuterà a proteggerti dal male che si annida in tutta Azeroth e oltre. Quando ti senti in pericolo, stringi questo totem e trova conforto nella sua aura magica. Abbi coraggio, nobile {class}. Ti servirà tutto il coraggio che riesci a raccogliere, perché vedo molto spargimento di sangue nel tuo futuro.", 0x35b94d5e, 0xef7c0c6e, 0x1e1257d7, 0x90276681, 0xfa828321, "....." },
  [102] = { "Pattuglia a Westfall", "Porta 8 Gnoll Paws a Captain Danuvin, a Sentinel Hill.", "Stormwind ci ha abbandonati. Un vento malsano di depravazione soffia sulle pianure di Westfall. Questa era la mia terra, e non volterò le spalle ai cittadini che scelgono di restare. Noi, gli ex contadini, terremo duro.\n\nIl tuo compito, se decidi di accettarlo, è pattugliare le praterie di Westfall. Rintraccia e uccidi i luridi gnoll che sembrano lavorare d'accordo con i ladri delle Deadmines. Portami 8 Gnoll Paws e ricompenserò il tuo coraggio.", "Hai già raccolto 8 zampe da quei gnoll traditori?", "Ben fatto, {name}. Con avventurieri valorosi come te a combattere al fianco della People's Militia, Westfall potrebbe tornare a essere il granaio prospero di un tempo. Ti prego, accetta questo in riconoscimento dei tuoi sforzi instancabili.", 0xbdbd8c1d, 0xb285aa6c, 0x08d3c8d8, 0x34967c23, 0xe6d9e3f6, "....." },
  [103] = { "Custode della fiamma", "Porta 5 Flasks of Oil a Captain Grayson, al Westfall Lighthouse.", "La notte in cui morì la famiglia del guardiano del faro fu orribile. Guardai, impotente, mentre Old Murk-Eye guidava l'attacco. Ma ciò che è fatto è fatto, e ora mi preoccupo per la vita dei marinai del Great Sea, le cui navi si avvicinano agli scogli insidiosi della costa. Senza nessuno a vegliare sulla fiamma, la responsabilità è ricaduta su di me.\n\nAiutami a tenere accesa la torcia portandomi 5 Flasks of Oil dagli Harvest Monsters.", "La fiamma non brucerà a lungo senza olio, {name}.", "Che tu sia lodato, prode {class}. Grazie al tuo duro lavoro, gli scogli della Westfall Coast saranno illuminati. Molte vite saranno risparmiate finché la torcia resterà accesa.\n\nIo morii inutilmente su questa stessa riva. Il mio compito nell'aldilà è fare in modo che nessun altro segua il mio destino.", 0x3ef7ad7a, 0xadaf38bb, 0x2c40ca7a, 0xd537b66e, 0x38ec3914, "....." },
  [104] = { "La minaccia della costa", "Porta una scaglia di Old Murk-Eye a Captain Grayson, al Westfall Lighthouse.", "Quando la mia vita finì su quegli scogli, non avevo idea di cosa mi riservasse l'aldilà. Quella notte il Lighthouse era buio, perché Old Murk-Eye aveva fatto fuggire la famiglia del guardiano. Tornarono e riaccesero la fiamma, ma Old Murk-Eye costrinse i murloc più deboli di mente ad assaltare di nuovo il Lighthouse con lui. La seconda volta la famiglia non fu così fortunata, e morirono impotenti davanti ai miei occhi.\n\nUccidi Old Murk-Eye se lo vedi lungo la riva, portami una delle sue scaglie e ti ricompenserò.", "Hai già annientato la minaccia nota come Old Murk-Eye? È stato visto aggirarsi lungo la costa di Westfall.\n\nTorna da me quando quella lurida bestia sarà morta.", "Dunque il lurido pagano, Murk-Eye, è morto. Ben fatto, {name}. Per mano tua una vita è stata spenta, ma forse molte altre sono state salvate. Il Great Sea, pieno di pericoli com'è, stanotte sarà un pochino più sicuro grazie al tuo eroismo.", 0x2f06382c, 0x9bc7f6db, 0xa6201dcb, 0xd389c8ba, 0xf95015fd, "....." },
  [106] = { "Giovani innamorati", "Consegna la Maybell's Love Letter a Tommy Joe Stonefield.", "Oh, sono maledetta! Il mio cuore appartiene a Tommy Joe Stonefield, ma le nostre famiglie sono nemiche giurate. Così non posso vederlo, anche se i miei occhi bramano di guardare quel bel viso!\n\nTi prego, prendi questa lettera e dalla a Tommy Joe. Di solito è al fiume a ovest della Stonefield Farm, che si trova proprio a ovest di qui.", "Hai cosa?? Maybell è la luce della mia vita grigia. Presto, fammi vedere la sua lettera!", "Ah! Non sopporto di stare lontano da lei. Devo vederla!!", 0x39bb27e6, 0xaca204cb, 0x455a69fe, 0x8ed56116, 0xaef57c73, "....." },
  [107] = { "Un biglietto per William", "Porta la Gramma Stonefield's Note a William Pestle.", "Scommetto che William Pestle ha una pozione per unire i nostri due giovani innamorati!\n\nTieni, porta questo biglietto a William. Alloggia al Lion's Pride Inn, a Goldshire.", "Hai un biglietto da \"Gramma\" Stonefield, eh? Non vedo Mildred da anni! Chissà cosa ha da dire...", "Il mio cuore soffre per quelle due povere anime, Maybell e Tommy Joe. Ricordo cosa vuol dire essere giovani e innamorati, un tempo.\n\nCi dev'essere qualcosa che posso fare per aiutarli! Fammi pensare...", 0x94227104, 0x6cf2cbc4, 0x613551b1, 0x4d3b404b, 0xd5a99e73, "....." },
  [109] = { "Rapporto a Gryan Stoutmantle", "Parla con Gryan Stoutmantle. Di solito si trova nella torre di pietra di Sentinel Hill, appena fuori dalla strada, nel mezzo di Westfall.", "Mi pare che tu abbia visto parecchie battaglie, {class}. Se non l'hai già fatto, dovresti andare a fare rapporto a Gryan Stoutmantle. È a capo della People's Militia, che protegge i campi di Westfall. Scommetto che il tuo aiuto gli farebbe comodo. Di solito lo trovi nella torre di pietra di Sentinel Hill, appena fuori dalla strada, nel mezzo di Westfall.", nil, "Ah, quindi ti manda il mio amico? Che gentile.\n\nBe', la Stormwind Monarchy ha abbandonato la nostra causa. Ora tocca alla People's Militia tenere queste terre libere dalla corruzione. Se la nostra causa ti interessa, posso mettere a frutto le tue doti di combattimento in nome della libertà.", 0xc82e5075, 0x03f579cf, 0x50233a5c, nil, 0xb444ea08, "...m." },
  [111] = { "Parlare con Gramma", "Parla con Gramma Stonefield.", "Ti prego, {name}, parla con la mia Gramma. Se c'è qualcuno che può trovare il modo di farmi stare con Maybell, è lei.\n\nÈ in casa nostra, a est di qui.", "Non vedo l'ora di sapere come reagiranno i miei amici!\n\nNon se lo aspetteranno mai", "Finché le nostre famiglie sono in lite, Tommy Joe e Maybell non hanno un gran futuro, ma... forse possiamo farli stare insieme almeno per un po'.\n\nMmm, cosa possiamo fare...", 0x6b3f9d7c, 0xf51e0819, 0x90033b93, 0x96b93e46, 0x2fa7cabf, "....." },
  [112] = { "Raccolta di alghe", "Porta 4 Crystal Kelp Fronds a William Pestle, a Goldshire.", "Posso preparare per Maybell un Invisibility Liquor, così potrà sgattaiolare via dai Maclure Vineyards e raggiungere Tommy Joe. Ma per fare il liquore mi serve dell'alga cristallina.\n\nDi solito l'alga cresce nell'oceano... ma a volte i murloc la raccolgono. Vedi se i murloc vicino al Crystal Lake ne hanno. Il Crystal Lake è appena a est di Goldshire.", "Hai quell'alga cristallina? Di sicuro Maybell non vede l'ora di vedere il suo innamorato...", "Le hai prese. Ben fatto! Ora un momento solo, mentre preparo la pozione...", 0x2bebb48c, 0x3fc93ac6, 0x9e5c1b2e, 0x73f21124, 0xca7123ec, "....." },
  [114] = { "La fuga", "Porta l'Invisibility Liquor a Maybell Maclure.", "Porta questo Invisibility Liquor alla giovane Maybell. Dovrebbe durare abbastanza perché possa far visita a Tommy Joe.", "Hai consegnato la mia lettera a Tommy Joe? Cosa ha detto??", "Oh... cielo! Mi sento in colpa a ingannare la mia famiglia, ma ciò che provo per Tommy Joe è troppo forte per ignorarlo.\n\nGrazie, {name}. Berrò questo liquore appena potrò e sgattaiolerò via dal mio amore.\n\nE per te... ti prego, prendi questo.", 0x437cedda, 0x7b2f4392, 0x62549b36, 0x692ffc74, 0xe0cf61c2, "....." },
  [115] = { "Magia delle ombre", "Porta 3 Midnight Orbs a Marshal Marris, a Lakeshire.", "Gli orchi Blackrock hanno arruolato degli shadowcaster per aiutarli negli attacchi a Redridge, e hanno portato con sé strumenti di potere oscuro: le Midnight Orbs. Queste sfere hanno inferto colpi pesanti ai difensori di Redridge, ed è indispensabile togliere di mezzo questi oggetti contaminati dai demoni.\n\nTrova le Midnight Orbs sugli shadowcaster Blackrock uccisi e portamele. Poi le farò distruggere, perché questo mondo sarebbe un posto migliore senza di esse!", "Come va la lotta con gli shadowcaster? Hai trovato le Midnight Orbs?", "Grazie, {name}. Le manderò subito a distruggere.", 0x904fce2a, 0x60db0353, 0x5b872785, 0x92dca9d4, 0x6e8c3d71, "....." },
  [116] = { "Tempi di siccità", "A Barkeep Daniels di Lakeshire servono un barile di Thunderbrew Lager, una botticella di Merlot, una bottiglia di Moonshine e un otre di Sweet Rum.", "Mi trovo in un bel guaio, {name}. Le bottiglie sono quasi vuote. L'ultima spedizione di liquori è in ritardo da un pezzo. L'invasione degli orchi è stata un inferno.\n\nForse potresti lavorare per me?\n\nMi serve che tu vada a prendere un barile di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline di Westfall, una botticella di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli e farò in modo che tu sia <ricompensato/ricompensata>.", "Mi serve che tu vada a prendere un barile di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline di Westfall, una botticella di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli e farò in modo che tu sia <ricompensato/ricompensata>.", "Un lavoro ben fatto, {name}! Conosco bene le strade che hai dovuto percorrere per procurarti questa bella scelta di liquori. Ma i miei clienti torneranno felici!\n\nMia moglie è una sarta piuttosto brava. Ti prego, accetta questo mantello che ha fatto lei, in cambio dei tuoi servigi.", 0x1c0c7a25, 0x8d7bd5b0, 0xd5a46db2, 0x61956f46, 0xbe7fa4ea, "....." },
  [117] = { nil, "Porta 5 luppoli a Grimbooze Thunderbrew per completare la sua birra speciale.", "Presto, amico mio, sbrigati e corri\n\nSe vuoi una lager che non sappia d'orzo e porri\n\nChe sappia di birra e non di stufato,\n\nServe il luppolo per il nostro preparato.", "Presto, amico mio, sbrigati e corri\n\nSe vuoi una lager che non sappia d'orzo e porri\n\nChe sappia di birra e non di stufato,\n\nServe il luppolo per il nostro preparato.", "Luppolo e orzo, lievito e malto\n\nIl palato subisce un vero assalto,\n\nNon serve implorare, non serve pregare\n\nLa Thunderbrew Lager in barile la puoi trovare!", nil, 0xcca1a58d, 0xf52ffef7, 0xf52ffef7, 0xed1e1cbe, "m...." },
  [118] = { "Il prezzo dei ferri", "Porta la Verner's Note a Smith Argus, a Goldshire.", "Ho usato così tanto ferro per equipaggiare le Stormwind Guards che non me ne resta abbastanza per ferrare i cavalli della stalla!\n\nPorta questo biglietto a Blacksmith Argus, a Goldshire. Gli spiega il mio problema e gli chiede una spedizione di ferri di cavallo.", "Cos'è? Ti manda Verner, dici? Be', dammi il suo biglietto. E parla più forte!", "Eh, così il vecchio Verner ha bisogno di ferri, eh!?!", 0x0dd0b1f0, 0x58b93226, 0xff4bd583, 0xf790dafa, 0x3e4e8e76, "....." },
  [119] = { "Ritorno da Verner", "Torna da Verner Osgood a Redridge e consegnagli la Crate of Horseshoes.", "Va bene, gli darò i suoi 50 ferri di cavallo...\n\nEccoli qui, tutti inscatolati e pronti a partire! Di' a Verner che è stato un piacere fare affari con lui, e assicurati che legga il biglietto attaccato a questa cassa!", "Bene, sei <tornato/tornata>! Hai preso i ferri?", "Grazie, questo mi aiuta davvero.\n\nMa cos'è questo? Argus ha mandato un biglietto con la cassa... Cosa?? Argus vuole che sia io a pagarlo? Bah!\n\nBe', {name}, grazie per l'aiuto.", 0x1296097e, 0x49433401, 0xe1ab4783, 0xa467f765, 0x16236c6c, "....." },
  [120] = { "Un messaggero per Stormwind", "Magistrate Solomon ti ha dato un rapporto da consegnare al General Marcus Jonathan, a Stormwind. Il giudice vuole che tu torni da lui appena fatta la consegna.", "Sono tempi difficili, {class}. La municipalità è sotto assedio continuo. Senza rinforzi andremo sicuramente incontro alla sconfitta. Il messaggio che ora ti affido è della massima importanza. Porta subito questo rapporto al General Marcus Jonathan di Stormwind. Fatta la consegna, torna immediatamente da me con qualunque notizia, buona o cattiva.\n\nOra sbrigati!", "Cos'hai lì?", "Riposo, {class}.\n\nMagistrate Solomon è un capo nobile. Le sue parole hanno molto peso per me. Chiederò consiglio al re e gli spiegherò chiaramente la situazione. Assicura al buon giudice che ha il sostegno della Stormwind Army. I rinforzi saranno inviati appena Sua Maestà darà l'ordine.", 0x7fd00169, 0xf2be5934, 0x06176f7a, 0x19bf3607, 0x6d2fb894, "....." },
  [121] = { "Un messaggero per Stormwind", "Porta la lettera di risposta del General Marcus Jonathan al Magistrate Solomon, a Lakeshire.", "Mentre attendo una risposta dal re, voglio che porti questa lettera al Magistrate Solomon.\n\nPuoi andare, {class}!", "Il generale ha mandato notizie? I rinforzi sono in arrivo?", "Grazie per il tuo tempo, {class}. Per il tuo servizio a Lakeshire e a Stormwind ti ricompenso con queste monete.\n\nOra, se vuoi scusarmi, trovo questa corrispondenza piuttosto misteriosa. C'è qualcosa che non va nel nostro regno. Temo che questo sia l'inizio del conflitto, non la fine.", 0x7fd00169, 0xa53df32a, 0xf1bab4f4, 0xf8129079, 0x4d427db5, "....." },
  [122] = { "Scaglie del ventre", "Raccogli 6 Underbelly Whelp Scales dai Black Dragon Whelps e portale a Verner Osgood, a Redridge.", "Mi servono delle scaglie del ventre dei draghetti neri per pagare i ferri che Argus mi ha mandato da Goldshire. Se me ne porti 6, potrò pagare Argus con una parte... e avanzarne abbastanza per farti qualcosa.\n\nI draghetti neri volano spesso a sud di Lakeshire, ma amano spostarsi. Forse dovrai solo tenere gli occhi aperti e cacciarli quando li vedi.", "So che quell'avido di Argus manderà qualcuno a prendersi le scaglie se non gliele do presto. Hai già trovato quelle scaglie?", "Grazie! Con queste mi libero del debito con Argus...", 0x068001c9, 0xd4d12cd6, 0xcda5c273, 0xef1640b6, 0xf521558d, "....." },
  [123] = { nil, "Vai da Marshal Dughan a Goldshire e consegnagli The Collector's Schedule", "Questo foglio è un calendario con un elenco di giorni e orari in cui una persona, descritta solo come \"The Collector\", riceverà una spedizione d'oro dalle miniere della Elwynn Forest.\n\nDal calendario sembra che il Collector si nasconda vicino alla Brackwell Pumpkin Patch, nella parte orientale di Elwynn.\n\nSembra una cosa importante. Dovresti riferirla a Marshal Dughan, a Goldshire.", "Cosa?!? Sono mesi che non abbiamo gente al lavoro nelle miniere di Elwynn!\n\nFammi vedere quel biglietto che hai...", "Mmm... ho sentito parlare di questo \"Collector\", ma non so per chi lavori. Grazie per il calendario. Ci aiuterà a risolvere il mistero.", nil, 0x3b835957, 0x5a3d01e4, 0xb33d4341, 0x318a1e2f, "m...." },
  [124] = { "Gnoll che ululano", "Uccidi 10 Redridge Brutes e 8 Redridge Mystics, poi torna da Verner Osgood.", "Come se gli orchi all'attacco non bastassero! Ora ho anche bruti e mistici gnoll che si aggirano sulla cresta a nord della mia stalla e mi prendono i cavalli quando si allontanano...\n\nSe riesci a liberarti di quegli gnoll, io e i miei cavalli te ne saremo molto grati.", "I miei cavalli sono ancora nervosi, e la notte sento ancora quel maledetto ululato. Ti prego, {name}, fai qualcosa per quegli gnoll!", "Grazie per tutto il tuo aiuto, {name}.", 0xe85ed098, 0xa4d31ccd, 0xaddbfb20, 0x1ef3dbfd, 0xac71f116, "....." },
  [125] = { "Gli attrezzi perduti", "Foreman Oslow di Lakeshire vuole che tu recuperi la sua cassetta degli attrezzi dal fondo del Lake Everstill.", "Mi servirebbe proprio una mano, {name}. Con il paese sotto assedio è stato difficile ricevere rifornimenti. I miei attrezzi arrivavano da Goldshire su un carro, ma il ponte è saltato. Abbiamo messo gli attrezzi su una barca, ma gli orchi l'hanno colpita con una catapulta. Che sfortuna: la mia cassetta degli attrezzi è finita dritta sul fondo del lago.\n\nRecupera la mia cassetta, {name}, e ne varrà la pena.", "Sei <riuscito/riuscita> a trovare i miei attrezzi?", "Ottimo recupero, {name}! Non pensavo che avrei rivisto questi attrezzi.", 0xc690e293, 0xe17d01d0, 0x00f67f4e, 0xc0af6727, 0xa3088c9c, "....." },
  [126] = { "Ululati tra le colline", "Porta la Yowler's Paw a Verner Osgood, a Lakeshire.", "{name}, gli gnoll sono ancora là fuori. Sento i loro latrati mentre cacciano sulle colline sopra Lakeshire. E un grido è più forte degli altri: Yowler, il loro capo.\n\nUccidi Yowler e disperdi il suo branco! Portami la sua zampa come prova.\n\nE stai <attento/attenta>: se questo gnoll è il loro capo, c'è un motivo. Non è un Mongrel qualunque...", "Yowler è una creatura pericolosa, {name}. Se non sei <pronto/pronta> ad affrontarlo, lo capisco.", "Grazie ancora per l'aiuto. La Stormwind army è così occupata con gli orchi che non ha truppe per proteggere Redridge dalle minacce locali come gli gnoll.", 0x8dfeeed2, 0x12e4af10, 0x3fd1157a, 0x33d0330f, 0x3ba08361, "....." },
  [127] = { "Pesce in vendita", "Porta 10 Spotted Sunfish a Dockmaster Baren, a Lakeshire.", "Il Lake Everstill è famoso per i suoi Spotted Sunfish. C'è sempre richiesta... e io ne ho pochi!\n\nPortamene un carico di 10 e ti farò un buon prezzo. Se non sai pescare, allora... magari puoi prenderli ai murloc!", "Hai qualche sunfish per me, eh?", "Un piacere fare affari con te, compare!", 0x8959426d, 0x299dd9a7, 0x595008a9, 0x1c00230f, 0x0c2062ce, "....." },
  [128] = { "Taglia sui Blackrock", "Uccidi 15 Blackrock Champions e Guard Howe, a Lakeshire, ti ricompenserà.", "Il Blackrock Clan va distrutto. Il nemico ha invaso le nostre terre. Queste montagne sono sotto il diritto sovrano del re di Stormwind. Le nostre fonti dicono che i capi di ogni unità del clan sono chiamati Champions. Li troverai nel loro accampamento a nord, appena a ovest della strada per le Burning Steppes.\n\nMagistrate Solomon vuole questi luridi bruti morti. Uccidi 15 Blackrock Champions e torna da me.", "Torna quando avrai ucciso 15 Blackrock Champions.", "Vedo che hai combattuto con valore contro il Blackrock Clan, {class}. Il tuo servizio alla nostra municipalità è davvero grande.", 0xccdac34a, 0x3dc788d9, 0x3c6954d1, 0x465f09c0, 0x3ae1dc90, "....." },
  [129] = { "Un pranzo gratis", "Porta il pranzo di Parker a Guard Parker. Pattuglia la strada che porta a Darkshire.", "Mi faresti un favore? Ho preparato il pranzo per Guard Parker, ma è fuori di pattuglia... è una guardia di Stormwind grande e forte che sa difendersi, ma là fuori è troppo pericoloso per una paesana come me.\n\nQuindi, se gli porti il pranzo al posto mio, poi torna qui e ti darò un pranzo gratis! Parker pattuglia il tratto di strada che porta a Duskwood.", "Darcy mi ha mandato il pranzo, eh? Che cuore gentile che ha. Be'... dammelo!", "Grazie, un pasto mi ci voleva proprio. Difendere Lakeshire dagli orchi e dagli gnoll è un lavoro duro!", 0x88d7e35c, 0xaad7a98b, 0x9db66007, 0x3d1d5d66, 0xe1a276a1, "....." },
  [130] = { "Visita all'erborista", "Parla con l'erborista di Redridge, Martie Jainrose.", "Prima di tornare da Darcy, puoi portarle dei fiori da parte mia? Li trovi alla bottega dell'erborista a Lakeshire, in fondo al paese, a ovest.\n\nMa quando prendi i fiori... non dire all'erborista, Martie, da parte di chi sono né per chi sono...", nil, "Ti serve un mazzo di fiori? Non sei in paese da molto... hai già trovato qualcuno che ti piace?\n\nSo che non dovrei impicciarmi, ma è bello vedere che c'è amore nell'aria... soprattutto in tempi pericolosi come questi.", 0x71fe59f9, 0xa1ba4f91, 0x49da55c6, nil, 0x081a325e, "...m." },
  [131] = { "Consegna di narcisi", "Consegna a Darcy il Daffodil Bouquet.", "Ecco il tuo mazzo di fiori. Ti ho scelto dei narcisi. Sono i miei preferiti!", "Eccoti di nuovo, {name}. A Parker è piaciuto il pranzo che gli ho mandato?", "Oh, sono bellissimi! Non vedo l'ora di metterli nell'acqua!\n\nMa... questi sono i fiori preferiti di Martie. Parker non ti avrà mandato da quella gelosa di una volpe per questo mazzo, vero? Non le hai detto per chi erano, vero? Se l'hai fatto, non mi stupirebbe se li avesse avvelenati.\n\nOh, ma non è colpa tua. Grazie, ed ecco il tuo pasto.", 0xf4e8832d, 0x70089ffd, 0x81de289a, 0xa471da13, 0x046112fa, "....." },
  [132] = { "La Defias Brotherhood", "Porta la Wiley's Note a Gryan Stoutmantle, a Westfall.", "Ciò che sto per dirti potrebbe costarmi la vita. La banda dei Defias sta tramando qualcosa di grosso. L'ultima volta che ne ho sentito parlare, lavoravano insieme a vari gnoll, kobold e persino goblin.\n\nPorta questo biglietto a Stoutmantle. Spiega tutto ciò che so sull'argomento.", "Che bello rivederti, {name}. Cosa aveva da dire Wiley?", "Bah! Avrei dovuto lasciar marcire quel furfante quando ne ho avuto l'occasione. Ma questa informazione è fondamentale. Ottimo lavoro.", 0x2a2224c0, 0x790d2fad, 0xda37a6c4, 0xf10ad446, 0x494d4d81, "....." },
  [133] = { "Un'effigie per i ghoul", "Raccogli 7 Ghoul Ribs e portali ad Abercrombie, nella sua baracca.", "Vivo così lontano dalla protezione del paese che è un miracolo se i ghoul e i morti che camminano non mi hanno ancora mangiato! Proprio ieri un branco di Bone Chewers martellava sui muri di casa mia!\n\nVoglio fare un'effigie, una specie di \"spaventapasseri\" per i ghoul. Per farla mi servono dei Ghoul Ribs. Puoi prenderli da Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones e Plague Spreaders.\n\nProcurami le costole e ti ripagherò con qualche moneta.", "Mi sembra di sentire un branco di ghoul che si aggira sul retro della casa: meglio che metta su quell'effigie in fretta! Mi hai preso quei Ghoul Ribs?", "Ah, grazie. Queste andranno benissimo!", 0x47c35f07, 0x7edccc10, 0x24de59e7, 0xa7553706, 0x54d74c26, "....." },
  [134] = { "Ladri ogre", "Riporta l'Abercrombie's Crate ad Abercrombie.", "Qualche settimana fa stavo raccogliendo erbe lontano da casa, e una banda di ogre mi ha attaccato! Sono scappato, e ho dovuto abbandonare una cassa di preziosi attrezzi ed erbe.\n\nDopo avermi cacciato, gli ogre sono tornati spavaldi al tumulo degli ogre nel sud di Duskwood. Sono sicuro che la mia cassa è da qualche parte vicino al tumulo.\n\nTi prego, {name}, recupera questa cassa per me, perché mi manca moltissimo.", "Hai la mia cassa? Se è così, ti prego... dammela, presto!", "Ringrazio il Nec... be', ringrazio TE, {name}! Ti sei più che <guadagnato/guadagnata> la ricompensa.\n\nAha! Felici! Notti felici ci aspettano!!", 0xfbfe2bc3, 0x2e382dde, 0x04be4123, 0xb52cb521, 0x8cc08e89, "....." },
  [135] = { "La Defias Brotherhood", "Porta la Wiley's Note a Mathias Shaw, a Stormwind.", "Mi chiedo cosa intendesse Wiley quando ha parlato degli Stonemasons. Forse gli è scappato. Possibile che la banda dei Defias abbia a che fare con gli Stonemasons? Solo un uomo potrebbe saperlo con certezza: Mathias Shaw, capo dello SI:7. Mostragli la Wiley's Note e senti se ha qualcosa da aggiungere a questo mistero sempre più fitto. Se hai difficoltà a trovare Shaw, cerca nelle Barracks della Old Town.", "Che affari hai con me? Sono un uomo molto impegnato. . .", "La faccenda potrebbe essere più complicata di quanto Stoutmantle immagini.", 0x2a2224c0, 0x95f26f8f, 0x0882b814, 0x12eeb2a7, 0x48d02edd, "....." },
  [136] = { "Il tesoro nascosto di Captain Sander", "Trova il baule di Captain Sanders e frugaci dentro per il prossimo indizio.", "Se stai leggendo questo, vuol dire che il vecchio Captain Sanders riposa in una tomba d'acqua. Quindi il mio tesoro ora è tuo, devi solo seguire gli indizi.\n\nPrima devi trovare il mio baule. A quest'ora sarà mezzo sepolto nella sabbia, lungo la Western Coast di Westfall, vicino al relitto. Di relitti ce ne sono tanti, ma sulla costa c'è una sola ancora arrugginita. Trova l'ancora e troverai il mio baule! Guarda lì dentro per il prossimo indizio.", nil, "Il baule si apre lentamente, cigolando. Sembra contenere solo sabbia e acqua. Ma aspetta! Ne esce di corsa un granchietto con un indizio per il tesoro tra le chele!", 0x06bba426, 0x0a7c4cb3, 0xa2d6009c, nil, 0x386945df, "...m." },
  [138] = { "Il tesoro nascosto di Captain Sander", "Trova il vecchio barile vicino al camino in rovina e frugaci dentro per il prossimo indizio.", "L'indizio per il tesoro dice: Bel lavoro, compare! Ora devi andare dritto a est. A est su per le scogliere, a est fino alla strada. Cerca le rovine del vecchio camino al lato della strada. Lì troverai un vecchio barile con il prossimo indizio.", nil, "Bel lavoro, <cacciatore/cacciatrice> di tesori!", 0x06bba426, 0x1440041d, 0xf26acf24, nil, 0x7ca63b45, "...m." },
  [139] = { "Il tesoro nascosto di Captain Sander", "Fruga nella brocca vuota accanto al mulino per il prossimo indizio.", "Frugando nel barile scopri un altro pezzo di pergamena. Questo dice: Ora, da questo barile, girati verso nord. Dritto come vola il corvo, continua a camminare finché non vedi la brocca vuota accanto al mulino solitario sulle scogliere. Se frughi intorno a quella brocca, potresti trovare proprio quello che cerchi.", nil, "Sei sulla strada del bottino, <cercatore/cercatrice> di tesori!", 0x06bba426, 0x7ab5b5af, 0x0b996e82, nil, 0xd8473e97, "...m." },
  [140] = { "Il tesoro nascosto di Captain Sander", "Trova il forziere di Captain Sanders e aprilo per avere la tua ricompensa.", "Ed ecco che, in fondo alla Old Jug, c'è un altro indizio per il tesoro di Sander. In qualche punto l'inchiostro è colato e la carta sa di whisky, ma riesci a leggere parte del testo: Ora che hai trovato la mia vecchia brocca di whisky, sei quasi al tesoro! Girati verso ovest dalla bottiglia e scendi fino alla riva. Una volta in acqua, continua! Nuota dritto verso ovest finché non trovi l'isola con il mio forziere!", nil, "I cardini del vecchio forziere sono arrugginiti, ma funzionano ancora. Forzi il forziere e prendi il bottino.\n\nCongratulazioni!", 0x06bba426, 0x01f557fa, 0xc7539c95, nil, 0x6ef48c97, "...m." },
  [141] = { "La Defias Brotherhood", "Porta il rapporto di Shaw a Gryan Stoutmantle, a Westfall.", "La Stonemasons' Guild era guidata da un uomo di nome Edwin VanCleef. VanCleef fu responsabile della ricostruzione di Stormwind dopo che gli orchi la rasero al suolo nella First War. A quanto pare, VanCleef e i suoi uomini erano scontenti del trattamento ricevuto dal re una volta completata la ricostruzione. Questo potrebbe spiegare un paio di cose.\n\nHo scritto un resoconto più dettagliato per il tuo superiore a Westfall. Portaglielo subito!", "Il Master Shaw ha fatto un po' di luce sulla faccenda?", "Edwin VanCleef. . . conosco bene quel nome. Pensare che un uomo così operoso e talentuoso possa trasformarsi in un tale furfante mi inquieta. Mi serviranno altre prove prima di crederci.", 0x2a2224c0, 0x7a7f1227, 0x42f42474, 0xb9945de0, 0xe1668a3c, "....." },
  [142] = { "La Defias Brotherhood", "Rintraccia il Defias Messenger a Westfall e porta il suo messaggio a Stoutmantle.", "Dobbiamo scoprire dov'è il nascondiglio dei Defias. {name}, il mio esploratore riferisce che un Defias Messenger è stato visto sulle strade tra Moonbrook, la Gold Coast Quarry e la Jangolode Mine. Voglio che tu lo catturi. Se oppone resistenza, uccidilo e portami qualunque cosa abbia con sé.", "{name}, sei <riuscito/riuscita> a raccogliere qualche informazione? Hai trovato il messaggero?", "Questa è davvero la prova certa che a comandare è VanCleef. Ora ci resta solo da sapere dove si nasconde la banda dei Defias.\n\nMentre eri via abbiamo avuto un colpo di fortuna. Abbiamo catturato un ladro che cercava di rubare il carro di Saldean. Ha promesso di guidarci al nascondiglio in cambio della vita. Voglio che tu difenda il traditore, perché possa rivelarci il nascondiglio. Torna da me quando avrai scoperto dove si trova.", 0x2a2224c0, 0x243342aa, 0xf31363c7, 0x484fe496, 0xf9189f7b, "....." },
  [143] = { "Un messaggero per Westfall", "Il Magistrate Solomon vuole che tu porti la sua supplica scritta a Gryan Stoutmantle, a Westfall.", "C'è qualcosa di strano con l'esercito di Stormwind. Dovrebbe già essere qui in forze. Ma il tempo è un lusso che non abbiamo. Non resterò a guardare la gente di Lakeshire dare la vita senza cercare di procurarmi altro aiuto. Ho sentito dire che a Westfall si sta formando una milizia popolare.\n\nPorta questa supplica al loro capo, Gryan Stoutmantle. Forse gli uomini di Stoutmantle possono dare un po' di sostegno qui finché il re non manderà rinforzi.", "Salute, {class}. Che affari hai con The People's Militia?", "<Bravo/Brava> <messaggero/messaggera>, hai servito bene il tuo padrone.", 0xf6c85306, 0x57b20c17, 0xf7e36946, 0xd03393da, 0x8b9e2f77, "....." },
  [144] = { "Un messaggero per Westfall", "Torna da Magistrate Solomon con la risposta di Gryan Stoutmantle.", "Leggere il biglietto di Magistrate Solomon mi addolora. Ma è chiaro che non conosce la guerra che si combatte a Westfall, altrimenti saprebbe di non doversi aspettare aiuto dalla Militia. Se anche Stormwind non ci avesse abbandonati, non avremmo bisogno della Militia.\n\nPorta questa risposta al tuo padrone a Redridge, {class}. E digli che il mio cuore è pesante per la perdita di brava gente.", "Possiamo aspettarci presto la People's Militia? Le notizie di Lord Stoutmantle sono buone?", "Devo dire che non va affatto bene. Non sapevo che la situazione di Stoutmantle fosse così simile alla nostra qui a Lakeshire. Quale azione è così importante da allontanare la Stormwind Army dalla sua gente? Bah, non dovrei pensare ad alta voce.\n\nEcco, messaggero. Accetta queste monete in cambio del tuo servizio alla municipalità. Potrei avere ancora bisogno di te.", 0xf6c85306, 0x82d09720, 0x39c0aa3b, 0x16225e09, 0x7726c3a3, "....." },
  [145] = { "Un messaggero per Darkshire", "Magistrate Solomon vuole che tu porti una lettera a Lord Ebonlocke, a Darkshire.", "Ho di nuovo bisogno del tuo aiuto. Ho scritto a Lord Ebonlocke, chiedendogli di mandare le sue guardie addestrate, la Night Watch, ad aiutare a difendere Lakeshire. È indispensabile che questo messaggio gli arrivi in fretta. Devi essere estremamente prudente. Ebonlocke è il sindaco di Darkshire, nel cuore di Duskwood. Non lasciare le strade.", "Sembri venire da lontano, {class}. Che affari hai qui a Darkshire?", "Grazie per aver fatto il lungo viaggio fin qui. Sono davvero informazioni importanti.", 0x74e46a13, 0xbe30acba, 0x0448bdaa, 0x1745350a, 0x089c2d62, "....." },
  [146] = { "Un messaggero per Darkshire", "Torna da Magistrate Solomon con la lettera di risposta di Lord Ebonlocke.", "Se non conoscessi personalmente Magistrate Solomon, direi che è impazzito. Mandare la Night Watch a Lakeshire perché Stormwind rifiuta di aiutarli? La Night Watch è nata perché Stormwind ci ha abbandonati quando questa magia immonda è penetrata nella terra. Se mandassi la mia Night Watch, questo paese sarebbe travolto dal male prima ancora che le guardie raggiungessero il limitare della foresta.\n\nPorta questa lettera di risposta al tuo padrone, a Lakeshire.", "Ah, che bello rivederti, messaggero. Devo informare il maresciallo che la Night Watch sta arrivando da Darkshire?", "Per la Luce! La Stormwind Army si è ritirata da Westfall. E la Guard non protegge più Darkshire? C'è sotto un tradimento. Come può essere?\n\nOh, dimenticavo di ricompensare il tuo servizio, {class}. Ecco qualche moneta. Ora scusami. Qualcosa non va a Stormwind e devo andare a fondo della questione.", 0x74e46a13, 0x83daf12d, 0x98c1d172, 0x465827c6, 0x3452ae00, "....." },
  [147] = { "Caccia all'uomo", "Trova e uccidi \"the Collector\", poi torna da Marshal Dughan con The Collector's Ring.", "Se il \"Collector\" prende l'oro dalle nostre miniere, allora sta derubando il regno! Consegna il Collector alla giustizia e portami l'anello citato nel calendario dei ritiri che mi hai dato. Potrebbe dirci per chi lavora il Collector...\n\nSecondo quel Pickup Schedule, il Collector si nasconde alla Brackwell Pumpkin Patch. Dovresti cercarlo lì.", "Hai trovato il Collector? Hai scoperto per chi lavora?", "L'hai trovato? Ben fatto, {name}. Non \"collezionerà\" più niente dalle Elwynn Mines!\n\nE questo anello che hai trovato è interessante... è un anello di appartenenza alla vecchia Stonemason's Guild di Stormwind. Perché un ladruncolo dovrebbe avere l'anello di una gilda di artigiani, e perché i Defias Thieves raccolgono denaro dalle nostre miniere?\n\nDomande difficili. Spero che un giorno avremo delle risposte.", 0x3fd32b4a, 0xaffbf97d, 0xcaee2d0b, 0x03263e82, 0xe881e64e, "....." },
  [148] = { "Provviste da Darkshire", "Parla con Madame Eva.", "Oh, cosa deve fare un povero vecchio? Mi servono delle provviste da Darkshire, ma il villaggio è così lontano e io sono così vecchio e debole... non ce la farei mai.\n\nPuoi andare a Darkshire e riportarmi del Ghost Hair Thread? Lo trovi da Madame Eva, a casa sua sulla piazza di Darkshire.", nil, "Ah, ti serve del Ghost Hair Thread, eh? Temo di non averne, ma posso fartene un po'... se mi procuri i capelli di fantasma.", 0x3942c9e4, 0xe153bd5f, 0xf32e36c4, nil, 0xd45d9df9, "...m." },
  [149] = { nil, "Porta lo Spectral Comb a Blind Mary.", "C'è un povero spirito triste, Blind Mary, che infesta una vecchia fattoria sulle colline a sud di Darkshire.\n\nTieni, prendi questo Spectral Comb e chiedi a Blind Mary di pettinarsi i capelli. Poi riportami il pettine, e ne ricaverò il Ghost Hair che mi serve per il filo.\n\nE stai <attento/attenta>, perché ora vicino a quella casa si annidano cose oscure...", "<Singhiozza> Oh, ti prego, non guardarmi! Mi sono strappata questi occhi con le mie stesse mani, ma sento ancora il tuo sguardo!\n\nSono orribile! Orribile! Ti prego, guarda altrove!!", "Cos'è questo? Un pettine? È bellissimo! E scivola tra i miei capelli come se non fossero l'orrore rigido e stopposo che sono.\n\nOh, se solo avessi uno specchio...", nil, 0x528815c6, 0x616f9a53, 0xe0b4c1fb, 0x47317f65, "m...." },
  [150] = { "Murloc bracconieri", "Porta 8 Murloc Fins a Dockmaster Baren, a Lakeshire.", "I murloc stanno diventando un problema. Gruppi sempre più grandi di uomini-pesce gettano l'ancora lungo le rive del Lake Everstill e pescano a più non posso! Dobbiamo farli sparire prima che si mangino tutto il pesce del lago!\n\nDai la caccia ai murloc! Portami 8 delle loro pinne e forse avrò qualcosa per te...", "Hai quelle pinne? Presto, dobbiamo cacciare quei murloc dal lago!", "Ben fatto, {name}. Spero che quei murloc non ti abbiano dato troppi problemi.\n\nÈ strano vederli così lontano dal mare. Mi chiedo se siano qui perché stanno scappando da qualcosa...", 0x812e47f7, 0xbe5f0814, 0xc927bcbc, 0xabeb396e, 0x9a51f356, "....." },
  [151] = { "Povera Old Blanchy", "Verna Furlbrow, a Westfall, vuole che tu le porti 8 Handfuls of Oats.", "Povera Old Blanchy! È così stanca, dopo tutto il lavoro che le abbiamo fatto fare. Le ho dato da mangiare prima di lasciare la fattoria, ma non ci aspettavamo che il carro si rompesse. Se potessi portarle qualche manciata di avena dai campi, te ne sarei grata.\n\nScommetto che ne trovi intorno a tutte le fattorie di Westfall, se riesci a stare alla larga da quelle macchine orribili che le hanno occupate. Ci sono diverse fattorie a sud-ovest di qui.", "Old Blanchy è allo stremo. Per caso hai trovato dell'avena per lei?", "Grazie mille, {name}! La povera Old Blanchy sarà così felice!", 0x9bfac4dc, 0x7daa1244, 0x1fc2eef2, 0xfc0646d0, 0x51216ba8, "....." },
  [152] = { "La costa non è sgombra", "Uccidi 7 Tidehunters, 7 Warriors, 7 Oracles e 7 Coastrunners e torna da Captain Grayson al Westfall Lighthouse.", "Avrai notato tutti i relitti lungo la costa. Il Great Sea è davvero infido. La costa di Westfall va tenuta sgombra, perché i marinai che arrivano sulle nostre spiagge siano al sicuro. Però i murloc sono un problema.\n\nUccidi 7 Tidehunters, 7 Warriors, 7 Oracles e 7 Coastrunners e farò in modo che tu sia <ricompensato/ricompensata>.", "Uccidi 7 Tidehunters, 7 Warriors, 7 Oracles e 7 Coastrunners e farò in modo che tu sia <ricompensato/ricompensata>.", "Ben fatto, {name}. Hai un bel talento per il combattimento. Grazie a te la costa di Westfall è un posto più sicuro.", 0xcdad2308, 0x88ca96a9, 0xbc9bf3cb, 0xf2f2deb7, 0x27f90f2d, "....." },
  [153] = { nil, "Porta 15 Red Leather Bandanas a Scout Galiaan, a Sentinel Hill.", "Il fronte dei Defias si sposta di continuo. È da parecchio che seguo i loro movimenti. Tra l'altro, ho appurato che molti membri della banda si riconoscono dalle Red Leather Bandanas che portano.\n\nPortami 15 di queste bandane e farò in modo che tu sia <ricompensato/ricompensata>.", "Portami 15 Red Leather Bandanas e ti pagherò bene.", "Bel lavoro, {race}. Ti prego, accetta uno di questi oggetti come paga per tutto il tuo impegno.", nil, 0x15be8c76, 0xdc4ad0de, 0xca1a09c5, 0x9ab69279, "m...." },
  [154] = { "Restituire il pettine", "Riporta il Ghost Hair Comb a Madame Eva, a Darkshire.", "NO!!!!!\n\nPrendilo, porta via da me questo pettine!\n\nSono un mostro, e nessuno mi troverà mai più bella!", "Sento che hai visto Blind Mary. Hai il mio pettine...?", "Con questo posso fare un rocchetto di Ghost Hair Thread, e mi avanzerà qualche filo. Ecco qualche moneta per quei fili in più.", 0x67d027b2, 0x183f2e90, 0x78e5d132, 0x390dbc0c, 0x307b8fa2, "....." },
  [155] = { "La Defias Brotherhood", "Scorta il Defias Traitor fino al nascondiglio segreto della Defias Brotherhood. Quando il Defias Traitor ti avrà mostrato dove si nascondono VanCleef e i suoi uomini, torna da Gryan Stoutmantle con l'informazione.", "Così Stoutmantle manda te, {race} pelle e ossa, a proteggermi? Mi sa che dovrò accontentarmi. Meglio se porti anche qualche amico.\n\nConosci l'accordo, no? Tu mi copri le spalle e io ti porto al nascondiglio dei Defias. Ma faresti meglio a starmi vicino. La banda dei Defias ora vuole la mia testa. Se mi vedono con te, cercheranno di uccidermi.\n\nFammi sapere quando tu e gli amici che riesci a radunare siete pronti a partire.", "Che affari hai con me? Sono un uomo molto impegnato...", "Eccellente, {name}! Ora che sappiamo dove si nasconde, VanCleef è praticamente nostro.", 0x2a2224c0, 0x3c4fa4f6, 0xf3c6ce7f, 0xa49dc7ac, 0xd5d9b9c8, "....." },
  [156] = { "Raccogliere i Rot Blossoms", "Raccogli 8 Rot Blossoms e portali a Tavernkeep Smitts, a Darkshire.", "Se mi porti dei Rot Blossoms, posso prepararti una partita di Zombie Juice.\n\nI Rot Blossoms crescono in posti strani. In particolare, ho sentito che si trovano dentro i teschi degli Skeletal Horrors e degli Skeletal Fiends... non che io mi sia mai avvicinato abbastanza da guardare!\n\nIl Raven Hill Cemetery e i Tranquil Gardens pullulano di quegli scheletri. Già che cerchi i Rot Blossoms, tanto vale che te ne sbarazzi. Il paese di Darkshire te ne sarebbe grato.", "Ciao, {name}. Hai già quei Rot Blossoms per me?", "Bene, hai preso i Rot Blossoms. E dirò ad Althea Ebonlocke della Night Watch che hai ucciso degli scheletri.\n\nProteggere la gente di Darkshire è un fardello cupo per la Night Watch, e sapere che altri aiutano ad arginare l'ondata di mostri a Duskwood è davvero una bella notizia.", 0x4964f847, 0x04339e2b, 0x9f150c59, 0xd77731e5, 0x03dd4941, "....." },
  [157] = { "Consegnare il filo", "Porta il Ghost Hair Thread ad Abercrombie, nella sua baracca a nord del Raven Hill Cemetery.", "Ecco il tuo filo, {name}. Ha mille usi, dal legare gli spiriti malvagi al cucire la vita negli oggetti inanimati.", "Devo tendere il Ghost Hair Thread lungo la porta e le finestre per tenere lontani gli spiriti indesiderati. Me l'hai procurato?", "Delizioso! Andrà benissimo...\n\nTieni, buon {name}, prendi questo come compenso per la tua azione onorevole.", 0x80a7141b, 0x2aed716b, 0x68798fe6, 0x9910144d, 0xd4c4f3eb, "....." },
  [158] = { nil, "Parla con Tavernkeep Smitts.", "Mi serve una bottiglia di un certo liquore: lo Zombie Juice. Tavernkeep Smitts, alla Scarlet Raven Tavern di Darkshire, dovrebbe averne.\n\nE ti prego, sbrigati, {name}. Le notti si fanno fredde, e mi serve quella bevanda per rimettermi il fuoco nelle vene!", nil, "Ti serve dello Zombie Juice, eh? Mmm... è roba forte: di solito non me lo chiede nessuno.", nil, 0xefdb9d5e, 0xbb7de0a2, nil, 0xee62c9dd, "m..m." },
  [159] = { "Consegna a domicilio", "Porta lo Zombie Juice ad Abercrombie, nella sua baracca.", "Ecco il tuo Zombie Juice...\n\n...e attenzione con questa roba. È così forte da resuscitare i morti!", "Mi serve quello Zombie Juice per scaldarmi in queste notti fredde e buie. Me l'hai procurato?", "Mille grazie, {name}. Scaldi il cuore di un vecchio con la tua stupid... volevo dire... con la tua gentilezza!\n\nEcco a te, amico. Prendi questo come segno della mia gratitudine.", 0x820ab7e9, 0x7ac1d84f, 0xb9ae7652, 0xbae73c5a, 0xf27a5a51, "....." },
  [160] = { "Un biglietto per il sindaco", "Porta l'Abercrombie's Letter a Ello Ebonlocke, sindaco di Darkshire.", "Porta questo biglietto a Ello Ebonlocke, il sindaco di Darkshire.\n\nSiamo vecchi amici... e quando lo leggerà e scoprirà cosa hai fatto per me... sono sicuro che sarà felice quanto me! Ahahahah!", "Abercrombie...? Non conosco nessuno con quel nome. Dici di avere una lettera per me da questo tale Abercrombie?\n\nBe', allora dammela...", "<Ello guarda la lettera...>\n\nChe lingua è questa? Sembra antica... non riesco a leggerla.", 0xbf2ebcd6, 0x60a07e98, 0xf87484eb, 0xb6aabb3e, 0xa50301f2, "....." },
  [161] = { "Incombe una minaccia oscura", "Chief Engineer Hinderweir vuole che tu porti la polvere dall'odore strano ad Ashlan Stonesmirk, l'esperto di esplosivi di Dun Modr.", "Se i miei sospetti sono giusti, questa è una specie di polvere esplosiva. Va analizzata da un esperto di esplosivi, così sapremo con cosa abbiamo a che fare. Ashlan Stonesmirk è stato assegnato al reggimento che sorveglia Dun Modr e il Thandol Span. Ho bisogno che tu faccia un viaggio grave e pericoloso, {name}.\n\nPassa per l'Algaz Gate, segui la strada attraverso le Wetlands e cerca Stonesmirk a Dun Modr. Segui il mio consiglio: resta sulle strade e non fermarti per nessun motivo!", "Hai detto qualcosa, <ragazzo/ragazza>? Non sento un accidente a parte il fischio nelle orecchie. Ehi, cos'hai lì?", "Ah, be', il vecchio Hinderweir fa bene a preoccuparsi.", 0x285fa090, 0x10adbf1b, 0xc80198ee, 0xbcaa84da, 0xdf7a71cc, ".....", nil, nil, nil, 0x60a6efdd, nil },
  [163] = { nil, "Scopri cosa infesta Raven Hill.", "C'è qualcosa che non va a Raven Hill, {name}. Calor giura che qualcuno, o qualcosa, infesta gli edifici laggiù. Per due notti di fila ha visto le ombre muoversi, e la notte prima dice di aver visto una luce a una delle finestre.\n\nSe, come dici, ti sta a cuore la sicurezza di Duskwood, scopri quale mostro infesta Raven Hill.", nil, "No! Ti prego, non uccidermi! Sono solo io... Jitters!! Sono dappertutto... non riesco a sfuggirgli! Mostri a Raven Hill? N-n-n-no... non può essere. Solo l'innocuo Jitters.", nil, 0x22ae4d0b, 0x2349862f, nil, 0x6183fbd0, "m..m." },
  [164] = { "Consegne per Sven", "Consegna le provviste a Sven.", "Conosci Sven? Ecco un uomo che compie l'opera della Luce! Lui e i suoi seguaci hanno un accampamento al margine nord-occidentale di Duskwood.\n\nPurtroppo sono così pochi che non possono nemmeno mandare un uomo in paese a prendere le provviste. Gliele porteresti tu?", "Sembri un tipo robusto, {class}. Sei qui per unirti alla nostra lotta?", "Queste provviste saranno utilissime. L'aiuto della famiglia Carevin è sempre apprezzato. Ecco qualcosina per il disturbo.", 0x47ecd948, 0x353999cb, 0xebb9fbaa, 0xe4428de9, 0xa502323b, "....." },
  [165] = { "L'eremita", "Vai a vedere come sta il vecchio nella baracca vicino al cimitero di Raven Hill.", "C'era un vecchio che veniva in paese a comprare provviste piuttosto spesso, ma è da un bel po' che non lo vedo. Se ricordo bene, vive in una baracca che domina il cimitero di Raven Hill. Forse dovresti andare a vedere se c'è qualcosa che non va.", nil, "Elaine Carevin? Eh eh, oh sì... certo, i Carevin.\n\nNo, non c'è niente che non va, ma ora per me è difficile andare in paese. Le strade sono pericolose e non divento certo più giovane. Forse puoi fare qualche favore a un vecchio?", 0x424f8542, 0x6e8400ee, 0x94338923, nil, 0x8022318a, "...m." },
  [166] = { "La Defias Brotherhood", "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.", "Ti resta un ultimo compito. Edwin VanCleef deve essere assassinato. Anche se mi addolora condannare a morte un uomo, è per il bene della gente di Westfall che VanCleef venga messo a tacere una volta per tutte. Portami la testa del furfante quando avrai compiuto l'opera.", "Come va la caccia a Edwin VanCleef?", "{name}, il tuo coraggio è straordinario. La People's Militia ti ringrazia per il servizio reso alla gente di Westfall. Con la morte di VanCleef comincia la fine della Defias Brotherhood. Speriamo che presto la pace torni a benedire le pianure di questa bella terra.\n\nTi saluto, <Signore/Signora>!", 0x2a2224c0, 0xaf5696f5, 0xeeda81af, 0xb9d86261, 0x9f2be902, ".....", nil, nil, nil, nil, 0xf7825732 },
  [167] = { "Oh, fratello...", "Porta l'Explorers' League Badge del Foreman Thistlenettle a Wilder Thistlenettle, a Stormwind.", "Eravamo nel profondo di una vasta miniera a Westfall, nascosta sotto un fienile a Moonbrook. Non ho idea da dove siano sbucati quei luridi ladri. Comunque, la galleria della miniera ci è crollata addosso. Io sono uscito, ma gli altri... beh... degli altri non si è più saputo nulla.\n\nSembri avere più fortuna di me là dentro. Se potessi cercare mio fratello, te ne sarei grato. Portava sempre con sé il suo Explorers' League Badge. Se non riesci a trovarlo, quel distintivo mi darebbe almeno un po' di pace.", "Hai trovato qualche traccia di mio fratello? C'è ancora speranza dopo tutto questo tempo?", "I miei sospetti erano fondati. Il mio povero fratello.... Beh, grazie per aver dato una conclusione a questo mistero, anche se la conclusione è stata triste.", 0xc4d380c0, 0xe0579023, 0xa169aa0b, 0x9c2bb4b4, 0x9c87936b, "....." },
  [168] = { "Raccogliere ricordi", "Recupera 4 Miners' Union Cards e riportale a Wilder Thistlenettle, a Stormwind.", "Molti miei amici sono morti quel giorno orribile in cui la galleria della miniera è crollata. Se le tue avventure ti portano in quell'ala della miniera di Moonbrook, ti prego, cerca qualsiasi segno che possa identificarli. Se trovi qualcuna delle loro Miners' Union Cards, riportamele e farò in modo che le loro famiglie trovino un po' di pace dopo questo orribile incidente.", "Sei <riuscito/riuscita> a recuperare qualcuna delle Miners' Union Cards dei miei vecchi colleghi?", "Grazie per averle raccolte, {name}. I tuoi sforzi aiuteranno a dare pace ai morti dopo questa tragedia. Farò in modo che le famiglie vengano avvisate.", 0x2c56586a, 0xe0ab3ca6, 0x610a9b53, 0x358b3d1b, 0x320f3ed3, "....." },
  [169] = { "RICERCATO: Gath'Ilzogg", "Uccidi Gath'Ilzogg e porta la sua testa a Magistrate Solomon, a Lakeshire, per la ricompensa.", "Ricercato! Gath'Ilzogg, capo degli attacchi dei Blackrock alla Stonewatch Keep e delle incursioni contro la municipalità di Lakeshire.\n\nGath'Ilzogg è estremamente pericoloso. Si dice che sia asserragliato nella fortezza appena conquistata, a tramare nuovi crimini del clan Blackrock contro l'umanità. L'infestazione degli orchi va stroncata a ogni costo. Una generosa ricompensa sarà data a qualunque anima coraggiosa porti la testa di Gath'Ilzogg a Magistrate Solomon.", "Cos'hai lì, {race}?", "Lavoro fantastico, {name}! Gath'Ilzogg guidava quei bruti in battaglia e ha ucciso molti umani innocenti. Abbiamo avuto giustizia. È il primo passo per riconquistare la fortezza per il regno di Stormwind!", 0x1fa3cb70, 0xdb0eb6e4, 0x8a4b873e, 0x46dc827d, 0x5c3ce0be, "....." },
  [170] = { "Una nuova minaccia", "Balir Frosthammer vuole che tu uccida 6 Rockjaw Trogg e 6 Burly Rockjaw Trogg.", "Spero che tu sia qui per darci una mano, {class}. Dopo l'ultimo attacco dei trogg, ci serve tutto l'aiuto possibile.\n\nHo sentito che quei mascalzoni spuntano in tutte le terre, e pare che Coldridge Valley non faccia eccezione. Sono stati avvistati su tutte le colline a sud-est e vicino al lago ghiacciato.\n\nE non è tutto: solo poche notti fa hanno attaccato e travolto il nostro accampamento a ovest!\n\nQui siamo un po' a corto di uomini, <ragazzo/ragazza>, e ci servono braccia forti per ricacciare indietro i trogg.", "Tenaci quei mascalzoncelli, eh?", "Se i problemi che abbiamo avuto qui sono indicativi di ciò che accade altrove nelle nostre terre, per la barba di Magni, abbiamo dei guai davanti a noi! Posso solo sperare che il re e il senato stiano prendendo provvedimenti contro la minaccia dei trogg.", 0xea33a69d, 0x6b72f6c0, 0xa8fc7352, 0x37fa0bba, 0x09e25d88, ".....", nil, nil, 0x6c85e362, nil, nil },
  [171] = { "Un tutore dell'Alliance", "Riporta il tuo protetto all'orfanotrofio di Stormwind consegnando lo Human Orphan Whistle a Orphan Matron Nightingale, nel Cathedral District.", "Sei <stato/stata> così gentile con me, {name}. Non avrei mai sognato di divertirmi così tanto durante la Children's Week. Grazie. Non voglio essere triste per quello che mi è successo: i miei dicevano sempre di superare qualunque cosa brutta ti capiti. Sai, da grande voglio essere un eroe... proprio come te.\n\nMi dispiace dirlo, ma è ora che torni a casa. Torniamo indietro e dirò alla direttrice che persona fantastica sei!", "È un piacere rivederti, {name}. Hai svolto i compiti che ti sei <offerto/offerta> di fare durante la Children's Week?", "Che il cielo ti benedica, {name}. Hai fatto per Randis più di quanto la maggior parte della gente si sognerebbe mai di fare. Grazie: sei una stella splendente nei cieli dell'Alliance.\n\nTi prego, se hai tempo, torna a trovarci. So che a Randis farebbe piacere, e anche a me.\n\nRandis si è divertito tanto con te, {name}. Voleva darti uno dei suoi animaletti preferiti, perché ti ricordi di lui.", 0x7c77ad68, 0x83a21456, 0x0fb0bc39, 0xfd180aa5, 0xe231992f, "....." },
  [172] = { nil, nil, "Sei <disposto/disposta> ad aiutarci qui all'orfanotrofio? Che tu sia <benedetto/benedetta>, amico; il tuo aiuto durante la Children's Week sarà prezioso.\n\nPrendi questo fischietto. Potrai usarlo solo per poco tempo, di solito non oltre la Children's Week stessa. Quando lo usi, potrai parlare con il bambino di cui hai accettato di occuparti. Usandolo di nuovo, il bambino se ne andrà.\n\nForza, {name}, usa il fischietto e conosci il tuo protetto! Sono sicura che il bambino sarà ansiosissimo di conoscerti.", nil, nil, nil, nil, 0x427476d3, nil, nil, "mm.mm" },
  [173] = { "Worgen nei boschi", "Uccidi 6 worgen Nightbane Shadow Weaver per Calor, a Darkshire.", "L'oscurità sembra inesorabilmente attratta da Duskwood. La missione di Master Carevin è scacciare il male e l'eresia. Grazie ai nostri sforzi la gente di Darkshire è al sicuro.\n\nCredi di essere <degno/degna> di unirti a noi?\n\nUn tempo la pensavo come te. Deluso dall'indolenza della Watch, mi unii a Master Carevin. Se vuoi dimostrare il tuo valore, non sarà a parole.\n\nMetti alla prova le tue abilità contro i worgen Nightbane Shadow Weaver nella Brightwood Grove, \"brillante\", ah!, e nel Rotting Orchard.", "{name}, come va la caccia?", "Notevole, {name}. Sembra che tu sappia badare a te. Forse si potrebbe trovare una sfida più adatta a qualcuno con le tue capacità.\n\nÈ curioso, però... I worgen sembrano comparsi dal nulla. Ma con tutte le altre strane creature che hanno varcato i nostri confini, immagino sia solo una delle tante preoccupazioni.", 0x47dbaa77, 0xdbe54601, 0x0c5c5fbf, 0xc089edc0, 0x3d143d4d, "....." },
  [174] = { "Guardare le stelle", "Viktori Prism'Antras di Darkshire vuole che tu gli porti un tubo di bronzo.", "Il mio amico gnomesco, Cog, ha promesso di aiutarmi a costruire un congegno che mi permetterà di scrutare le stelle. Esiste una verità, al di là della magia, che può spiegare la strana trasformazione della foresta.\n\nPortami un tubo di bronzo fatto da un ingegnere esperto. Secondo il progetto di Cog, è il primo passo.", "Hai già trovato un ingegnere esperto che costruisca un tubo di bronzo?", "È perfetto, {name}. Il primo passo è fatto!", 0xb0b2f53c, 0x95b70dc4, 0x93fe2947, 0x7340ad08, 0xfdd8d8da, "....." },
  [175] = { "Guardare le stelle", "Trova Mary e convincila a cedere una superficie riflettente per il progetto di Viktori.", "Secondo il progetto di Cog, ora mi serve un modo per riflettere la luce. Ricordo una donna di nome Mary, diventata famosa da queste parti perché portava sempre con sé uno specchio. Forse puoi rintracciare Mary e vedere se ci presterebbe una superficie riflettente per questo progetto? Credo che un tempo vivesse nel sud di Duskwood. . .", nil, "Ma sì, un tempo avevo uno specchio.", 0xb0b2f53c, 0x5c290da2, 0xbbc7b806, nil, 0xf80d3335, "...m." },
  [176] = { "RICERCATO: \"Hogger\"", "Uccidi lo gnoll Hogger e porta il suo Huge Gnoll Claw a Marshal Dughan.", "Ricercato: Hogger\n\nUn enorme gnoll, Hogger, si aggira nei boschi della parte sud-occidentale di Elwynn. Ha avuto la meglio su tutti i tentativi di catturarlo.\n\nLa Stormwind Army ha messo una generosa taglia sullo gnoll. Per riscuotere la ricompensa, i cacciatori di taglie devono portare la prova della morte di Hogger a Marshal Dughan, a Goldshire.", "Sì, Hogger è stato una vera spina nel fianco per me e i miei uomini. Hai qualcosa da riferire su quella bestia?", "Ah! Ben fatto! Cominciavo a pensare che nessuno avrebbe abbattuto quel mostro!\n\nEcco a te, {name}. E grazie: quello gnoll mi stava facendo venire un mal di testa grande quanto la Blackrock Spire!", 0x9dcd29e7, 0x318a3a3b, 0xab83e5ae, 0xadee0c74, 0xc7de9815, "....." },
  [177] = { "Guardare le stelle", "Recupera il Blind Mary's Looking Glass dall'Insane Ghoul e consegnalo a Viktori, a Darkshire.", "Lo specchio era uno dei miei tesori più belli, finché. . . l'incidente. Dopo quello, lo gettai dietro il fienile. Là dietro si aggirava un Insane Ghoul. Forse l'ha raccolto lui. Si dice che quella bestia diabolica viva nel Tranquil Gardens Cemetery.", "Ho mostrato a Cog i primi passi della nostra macchina per osservare le stelle. Ne è rimasto colpito. Per caso hai trovato un congegno riflettente?", "Superbo! Funzionerà alla perfezione. Mille grazie!", 0xb0b2f53c, 0x7a6c1b09, 0xc5f77146, 0x22ff6d7e, 0x34eef752, "....." },
  [178] = { "Un recupero per Theocritus", "Porta il Faded Shadowhide Pendant a Theocritus the Mage.", "<Senti una voce senza corpo...>\n\nNon allarmarti. Sono Theocritus, High Mage della Tower Azora nella Elwynn Forest. Il ciondolo che tieni in mano è un mezzo di comunicazione tra gli Shadowhide Gnolls e il loro padrone, Morganth.\n\nDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi ciondoli. Se senti questo messaggio, il mio incantesimo è riuscito.\n\nPortami questo ciondolo e ti ricompenserò per il servizio.", "Ti ho parlato attraverso un ciondolo, dici? Mmm... dammelo, così posso studiarlo.", "Hai la mia gratitudine, {name}. Ho mandato quel messaggio agli Shadowhide Pendants settimane fa e lo credevo un fallimento. Ma sembra che l'incantesimo abbia raggiunto almeno alcuni ciondoli, con un notevole ritardo.\n\nCol tempo spero di imparare a lanciare un attacco attraverso i ciondoli, per immobilizzare gli Shadowhide Gnolls che li indossano.\n\nMa prima che sia possibile, temo servano molte altre ricerche.", 0xd1b6915b, 0xe9f541db, 0x7788c2a9, 0xdac36d0d, 0xd28bd097, "....." },
  [179] = { "Equipaggiamento nanico", "Sten Stoutarm vorrebbe 8 pezzi di Tough Wolf Meat.", "Che abbiamo qui? Sembri aver bisogno di qualcosa per tenere al caldo le mani, eh?\n\nTi dico io cosa ti servirebbe: un bel paio di guanti caldi. E, anima gentile quale sono, sarei felicissimo di fornirtene un paio adatto. Ho però una condizione.\n\nDevi andare a procurarmi un po' di carne di lupo. Bell'accordo, eh? Tu mi porti la carne di lupo e io mi assicuro che tu non perda nessun dito per il congelamento. Allora, che ne dici?", "I lupi ti danno un po' di filo da torcere? Faresti bene a evitare zanne, artigli e altre parti appuntite, no?", "Ah! Magnifico. La carne di lupo andrà benissimo. Oh, non preoccuparti, {name}, non dimenticherei la mia parte dell'accordo. Ecco, uno di questi dovrebbe andarti bene.", 0x26b28f66, 0x458fcb05, 0x26a8c43e, 0x4ab5a842, 0x3fbf9365, "....." },
  [180] = { "RICERCATO: Lieutenant Fangore", "Uccidi Lieutenant Fangore e torna da Magistrate Solomon, a Lakeshire, con la sua zampa.", "Ricercato: Lieutenant Fangore\n\nNoto capo dello Shadowhide Gnoll Clan, al servizio del nemico della municipalità e del regno, Morganth. Per ordine di Magistrate Solomon, questo lurido traditore di Stormwind è ricercato morto. Mostra la sua zampa al magistrato come prova della sua morte.", "Quali notizie porti davanti alla corte?", "Dunque il malvagio Lieutenant Fangore è morto? Bella liberazione da quella lurida creatura. Sei molto <coraggioso/coraggiosa>, {class}. La municipalità di Lakeshire ti ringrazia per l'aiuto.", 0x8dd050b7, 0xeaf3268f, 0xeb39ff35, 0xb6305447, 0x338741ad, "....." },
  [181] = { "Guardare le stelle", "Trova Zzarc'Vul nel tumulo degli ogre a sud di Duskwood e porta il suo monocolo a Viktori, a Darkshire.", "Ora serve solo un altro oggetto per completare il congegno. Il progetto di Cog richiede una specie di lente. L'unica lente che conosco abbastanza grande sarà molto difficile da ottenere.\n\nC'è un ogre di nome Zzarc'Vul che vive nel tumulo nel sud di Duskwood. Se ci riesci, portami il suo monocolo e lo useremo come lente!", "Sei <riuscito/riuscita> a convincere Zzarc'Vul a prestarci il suo monocolo per l'esperimento?", "Finalmente! Il congegno per osservare le stelle è completo! Grazie, {name}. Ora posso continuare le mie ricerche. . .", 0xb0b2f53c, 0x7425bc28, 0x1a69cde0, 0x9e98b22d, 0x548bc1fc, "....." },
  [182] = { "La grotta dei troll", "Grelin Whitebeard vorrebbe che tu uccidessi 14 Frostmane Troll Whelp.", "Mio fratello Senir e io siamo stati mandati in diverse parti di Dun Morogh a indagare sulla minaccia dei troll. Il senato ha già il suo daffare con i trogg, quindi non ha bisogno di altri fastidi.\n\nDa quel che ho visto, i troll non sono ben insediati qui a Coldridge Valley: soprattutto nella grotta a sud. Direi che l'esercito non sarà necessario. Qualche braccio forte dovrebbe bastare e avanzare.\n\nForse vorresti aiutare in questa impresa? Ho l'autorità di offrirti un compenso per il tuo aiuto.", "Da quel che ho appreso, questi troll vengono dal clan Frostmane. Temo di non sapere molto altro su di loro che possa esserti utile, {name}.", "Argh! Quei troll maledetti dalla Luce!\n\n<Fa qualche respiro e sembra calmarsi... un po'.>\n\nUn gruppo di loro è arrivato di notte e mi ha rubato il diario! Avrei dovuto saperlo che non bisognava fidarsi di quel buono a nulla di un appr...", 0xf6bcfb62, 0x0fe3fd39, 0x4d645eea, 0x76fb86d2, 0xfe9f5262, "....." },
  [183] = { "Il cacciatore di cinghiali", "Talin Keeneye vorrebbe che tu uccidessi 12 Small Crag Boar.", "Niente di meglio di una giornata di caccia al cinghiale, eh?\n\nAnche se qui a Coldridge Valley ci sono così tanti cinghiali che quasi non c'è più gusto. Non serve nemmeno provocarli: sono già tutti arrabbiati e pronti a caricare. Anzi, di recente ce ne sono stati così tanti in zona che è diventato pericoloso fare la mia caccia quotidiana.\n\nPer farla breve, se potessi aiutarmi a uccidere un po' di cinghiali, te ne sarei grato.", "Come va la caccia?", "Eccellente! Ora posso tornare alla mia... tranquilla... caccia. Grazie, {name}.", 0xd760ac9a, 0xd69ca3ad, 0xc4ab0b64, 0xe02b27bb, 0xc985f25a, "....." },
  [184] = { nil, "Porta il Furlbrow's Deed a Farmer Furlbrow.", "Questo è l'atto di proprietà di una distesa di terreni agricoli a Westfall. È firmato da un certo Theodore Furlbrow e controfirmato dalla moglie, Verna. E sul retro ci sono parole scarabocchiate in fretta:\n\n\"Abbiamo fatto pressione su Furlbrow e ci siamo presi il suo atto. Pensavo potesse servirti, se volessi falsificarne uno per un posto tutto tuo.\n\nI Furlbrow non ci daranno fastidio. L'ultima volta che li ho visti stavano lasciando Westfall, bloccati con un carro rotto.\"\n\nPensi che i Furlbrow potrebbero rivolere il loro atto...", "Hai l'atto della mia fattoria?? Che bella notizia! Dei furfanti me l'hanno rubato giorni fa... credevo di averlo perso per sempre!\n\nTi prego, dammelo. Stiamo lasciando Westfall e non torneremo tanto presto, ma se torneremo, ci serviranno quelle carte...", "Grazie infinite, {name}! Come dicevo, queste terre non sono più adatte alla gente onesta, ma se le cose miglioreranno, questo atto ci permetterà di riprenderci la nostra terra.\n\nNon ho molto da offrirti, ma ecco: prendi questo.", nil, 0x11feda88, 0x57a4e970, 0x5eec9a09, 0x4f2a8d57, "m...." },
  [199] = { "Incombe una minaccia oscura", "Torna da Chief Engineer Hinderweir e mostragli l'indizio che hai scoperto.", "Prendi un campione della polvere dall'odore strano.", "Per caso hai scoperto qualche indizio, {name}?", "Questa è una scoperta allarmante, a dir poco!", 0x285fa090, 0xf35c45fc, 0x6aeb4ed8, 0xf6db5556, 0x5a6f77c1, "....." },
  [212] = { "Un piatto da servire freddo", "Uccidi un Cold Eye Basilisk, prendi un Chilled Basilisk Haunch e riportalo ad Angus Stern, al Blue Recluse.\n\n<Per riuscire in questa missione non devi liberare il tuo spirito.>", "Uno dei miei piatti più famosi è il basilisco freddo in vinaigrette al lime. Ma il problema è... che la carne è impossibile da mantenere fresca, e stasera devo servire il piatto per il compleanno di un nobile!\n\nQuindi, se riesci a portarmi in fretta un Chilled Basilisk Haunch da un Cold Eye Basilisk appena ucciso, ti dovrò un banchetto da re!\n\nSi sa che i Cold Eye Basilisk si aggirano sulle dune della spiaggia nel nord-ovest di Stranglethorn, quindi hai molta strada da fare. E sii veloce!", "{name}! Hai quel cosciotto? Devo cominciare a prepararlo presto, o il banchetto sarà rovinato!", "Ah, questo andrà benissimo! Mille, mille grazie!\n\nOra, se vuoi scusarmi, devo tagliare, marinare e guarnire il cosciotto per il banchetto.", 0x0f466bd4, 0x755a6eb1, 0x48dfd0b9, 0x2003f762, 0x33a633d9, "....." },
  [214] = { nil, "Scout Riell, alla Sentinel Hill Tower, vuole che tu le porti 10 Red Silk Bandanas.", "Non è un segreto che il marchio della banda dei Defias siano le loro Red Bandanas. Ma abbiamo scoperto che il materiale di cui sono fatte indica il grado di chi le porta.\n\nDetto questo, voglio che tu elimini quanti più membri di alto grado dei Defias puoi. Quelli di grado più alto si trovano di sicuro nel nascondiglio segreto di VanCleef. Quando hai finito, portami 10 Red Silk Bandanas come prova della loro morte e ti ricompenserò. Buona fortuna, {name}.", "Hai riconquistato la nostra terra dalla banda dei Defias? Se è così, mostrami 10 Red Silk Bandanas come prova.", "Ben fatto, {name}! A nome della People's Militia ti rendo onore per i tuoi sforzi. Presto, con l'aiuto di anime coraggiose come te, restituiremo questa terra alla sua gente.", nil, 0x16e9af40, 0xca668909, 0x9de63344, 0xb8efc2a9, "m...." },
  [217] = { "In difesa delle terre del re", "Uccidi il capo dei trogg, Grawmug, e le sue due guardie, Gnasher e Brawler, poi torna a fare rapporto a Captain Rugelfuss nella torre di guardia meridionale.", "{name}, i nostri esploratori hanno individuato il capo di questa recente incursione dei trogg. Sembra che queste bestie di Loch Modan seguano gli ordini di un capotribù di nome Grawmug. Ma Grawmug è ben protetto. Due delle sue guardie migliori, Gnasher e Brawler, non lo lasciano mai.\n\nSe te la senti, {name}, voglio che guidi tu la missione per assassinare Grawmug e i suoi due scagnozzi. Con i capi dei trogg morti, potremmo avere una possibilità di ricacciare queste bestie sottoterra.", "Grawmug e le sue due guardie, Gnasher e Brawler, sono ancora vivi. La tua missione non è finita finché tutti e 3 non saranno morti. L'impero nanico conta su di te, {name}.", "Eccellente, {name}! Hai riportato la speranza a Loch Modan. Con Grawmug morto, abbiamo più possibilità di vedere i trogg eliminati da queste terre.", 0xc965c9da, 0xd0adb1a9, 0xd1d3aab4, 0x080d24f4, 0x996b47d7, "....." },
  [218] = { "Il diario rubato", "Grelin Whitebeard vuole che tu uccida Grik'nir the Cold e recuperi il suo diario.", "Il mio diario! L'hanno portato nella grotta. Quello che l'aveva... era un grosso bruto con strani segni sulla pelle e sul viso. Non sono riuscito a vederlo meglio di così.\n\nCon i troll hai avuto un po' di fortuna: forse potresti andare a riprendermelo?", "{name}! Fortuna?", "Magnifico, {name}! Mille grazie per aver recuperato il mio taccuino. Beh, sembra che la situazione dei troll qui a Coldridge Valley sia sotto controllo e non dia molti motivi di preoccupazione.\n\nDopo aver dato gli ultimi ritocchi al mio rapporto, avrò bisogno di qualcuno che lo porti a mio fratello Senir.", 0x5df25f99, 0x1dd2f28b, 0xfc2a9b7a, 0x224c9107, 0x3df5a70e, "....." },
  [219] = { "Disperso in azione", "Proteggi Corporal Keeshan durante il viaggio di ritorno a Redridge.", "Finalmente, amici dell'Alliance!\n\nAiuto... vi prego...\n\nL'ultima cosa che ricordo è che questi luridi orchi hanno sopraffatto il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Ho preso un forte colpo alla testa e poi è stato tutto buio. Ora sono prigioniero in questa caverna. Aiutatemi, sono ferito gravemente.\n\nMi servirà aiuto per tornare in paese... vi prego... siete la mia ultima speranza...", "Sì?", "Hai servito bene il regno, {class}. Grazie per aver aiutato Corporal Keeshan a fuggire da quei temibili Blackrock Orcs. Oggi sarai <ricompensato/ricompensata> per le tue azioni coraggiose.", 0xd4ba8881, 0x846a56f1, 0x9fe9b7bf, 0x0c07a888, 0x3364444e, "....." },
  [220] = { "Il richiamo dell'acqua", nil, nil, nil, nil, 0x1f0e11aa, nil, nil, nil, nil, ".mmmm" },
  [221] = { "Worgen nei boschi", "Uccidi 12 worgen Nightbane Dark Runner per Calor, a Darkshire.", "Avrai notato dei worgen più grossi che si aggirano nei boschi insieme agli Shadow Weavers? Da quanto ne sappiamo, questi Dark Runners sono il grosso dei worgen.\n\nNelle mie perlustrazioni ho anche visto che hanno invaso il Rotting Orchard, a sud-ovest del paese. Questi worgen sono un po' più duri di quelli che hai affrontato finora.\n\nStai in guardia.", "Già di ritorno, {name}? Spero che tu non sia <venuto/venuta> a dirmi che ti sei <arreso/arresa>.", "Te la sei <cavato/cavata> bene contro i Dark Runners, {name}. Ma sembra che il loro numero sia inesauribile. Ogni volta che facciamo progressi, ne spuntano altri a riempire le file.\n\nQual è il potere malvagio che li attira qui? Perché sono venuti a turbare il nostro infelice regno...\n\nRiporrò la mia fiducia in Master Carevin. Di sicuro andrà a fondo del problema.", 0x47dbaa77, 0x77e86e2a, 0xb1107ac6, 0x33d61b21, 0xc02e7176, "....." },
  [222] = { "Worgen nei boschi", "Uccidi 8 worgen Nightbane Vile Fang e 8 Nightbane Tainted One per Calor, a Darkshire.", "Le tue imprese passate mi hanno convinto che sei <pronto/pronta> ad affrontare i worgen più duri che infestano i boschi.\n\nTra i worgen che hanno fatto di questo posto la loro nuova casa, i Vile Fangs e i Tainted Ones si sono rivelati i più pericolosi. Si sono stabiliti vicino ad alcune caverne e nella miniera a sud.\n\nDa lontano si vede persino la luce dei loro falò...", "Bestie che mettono paura, vero? Ma non temere, {name}: chi sta dalla parte della Luce non cadrà mai!", "{name}, a dirti la verità, non credevo che saresti <arrivato/arrivata> fin qui, ma chiaramente sei {class} da non sottovalutare. Anzi, se vuoi unirti formalmente alla lotta di Master Carevin, ti scriverò volentieri una lettera di raccomandazione.", 0x47dbaa77, 0xd83d480e, 0x07eb6a76, 0x4a1b2c2d, 0x97850b04, "....." },
  [223] = { "Worgen nei boschi", "Porta il biglietto di Calor a Jonathan Carevin.", "Ecco a te, {name}. Porta questo messaggio a Master Carevin.\n\n<Tira fuori in fretta un pezzo di pergamena sbiadita e te lo porge.>\n\nAncora qualcuno come te, e saremo più numerosi della Night Watch! Forse allora potremmo completare l'opera che noi, in pochi, portiamo avanti oggi.", "Sì, cosa c'è? Fai in fretta, ho questioni urgenti di cui occuparmi.", "Perdona la mia accoglienza fredda, {name}, ma come avrai capito sono un uomo estremamente impegnato. Vedo che hai fatto colpo su Calor, e ti assicuro che non è poco, e che lui ti ha raccomandato.\n\nCi sono brutti tipi in giro, {name}, e ci serve l'aiuto di tutti quelli che hanno dato prova di sé. Combattiamo contro i demoni, i non morti e chi presta loro aiuto. Stai in guardia, sii prudente e non fidarti di chi non aiuterebbe la nostra causa.\n\nGloria sotto la Luce.", 0x47dbaa77, 0x7794d7d0, 0x5a6d3b68, 0x5d4aba8c, 0xa217e173, "....." },
  [224] = { "In difesa delle terre del re", "Mountaineer Cobbleflint, della torre di guardia meridionale, vuole che tu uccida 10 Stonesplinter Troggs e 10 Stonesplinter Scouts.", "Dobbiamo proteggere il Loch, {name}! Con tanti soldati del re che combattono valorosamente su campi di battaglia lontani, qui in patria siamo sopraffatti. I trogg sbucano scavando da ogni fessura! L'infestazione dei trogg è la minaccia più grande per Ironforge. Questi mutanti disgustosi vanno distrutti.\n\nAbbiamo bisogno di te, <coraggioso/coraggiosa> <avventuriero/avventuriera>: parti e annienta la minaccia dei trogg. Uccidi 10 Stonesplinter Troggs e 10 Stonesplinter Scouts e torna a fare rapporto.", "Loch Modan è sotto assedio, {name}! Ci serve ogni membro abile dell'Alliance. Hai già ucciso 10 Stonesplinter Troggs e 10 Stonesplinter Scouts?", "Ben fatto, {name}! Hai mostrato un coraggio straordinario sul campo di battaglia. La nostra guerra contro i trogg si vincerà con sforzi come il tuo. Hai servito bene King Magni.\n\nSe ti senti <portato/portata> per questo genere di avventure, ti consiglio di parlare con Mountaineer Gravelgaw. Il capitano lo ha assegnato a una pattuglia difficile, e di sicuro un aiuto gli farà comodo. Cerca Gravelgaw appena dentro la torre.", 0xc965c9da, 0x6d03495e, 0xc3723201, 0x75084503, 0xe35c303e, "....." },
  [225] = { "La tomba consumata", "Parla con Sirra Von'Indi, a Darkshire.", "La lapide consumata dice soltanto:\n\nMORGAN LADIMORE\n\n<Guardando meglio, noti che la terra sopra la tomba è stata smossa di recente, e che una buona parte sembra essere stata spostata...>", nil, "Morgan Ladimore?\n\nAh, sì, certo. La sua fu una storia lunga e triste. Lo conoscevo bene, prima che partisse per la guerra, ma quella fu l'ultima volta che lo vidi. Era un uomo nobile e buono, ma fece una brutta fine.\n\nEcco, dovrei avere qui qualcosa che racconta la storia meglio dei miei ricordi...", 0xc3ec23cc, 0x9f5ae082, 0xf3dd996f, nil, 0xe3b1dce6, "...m." },
  [226] = { "Lupi alle calcagna", "Uccidi 12 Starving Dire Wolves e 8 Rabid Dire Wolves, poi torna da Lars al Sven's Camp, sul confine occidentale di Duskwood.", "Io e Sven abbiamo giorni pericolosi davanti a noi, con il Necromancer a est e tutto il resto. E qui fuori, da soli come siamo, dobbiamo cacciare per procurarci il cibo. Sembra che ogni volta che torno all'accampamento con un po' di carne addosso, sbuchino dalla foresta dei dire wolf affamati o rabbiosi a volerne un morso. Inutile dirlo, vivere qui fuori è un lavoro pericoloso!\n\nMa se riesci a liberarci di un po' di quei lupi, la vita ci sarà più facile. Si aggirano soprattutto a nord e a est di qui, vicino al fiume.", "Stai ancora cacciando lupi...?", "Oh, bene. Hai sfoltito parecchio quel branco, e senza quei lupi alle calcagna possiamo concentrarci su Morbent Fel.\n\nTieni, prendi un po' di questi Flash Bundles. Li fanno in paese, e molti sono stati donati a Sven per aiutarlo nella sua causa.", 0xdeb794ec, 0xae5c308b, 0x0b5b5fe6, 0x3371447a, 0x489aecd3, "....." },
  [227] = { nil, "Parla con Commander Althea Ebonlocke, a Darkshire.", "<Fruga tra gli scaffali e tira fuori un libro rilegato in pelle.>\n\nSe vuoi saperne di più, potresti chiedere ad Althea: ultimamente è lei che si occupa del... problema... con lui.", nil, "Morgan Ladimore? Mai sentito...\n\nOh, intendi Mor'Ladim! Immagino che tu non abbia sentito la storia?\n\nBe', te la racconto in breve. Un non morto errante che si fa chiamare Mor'Ladim vaga per Duskwood. Da quello che abbiamo capito, sembra essere il corpo non morto di Morgan Ladimore, che a quanto pare conosci. Ci sta creando ogni sorta di problemi: attacca i Watchmen di pattuglia e uccide la gente.\n\n<Ti squadra.>\n\nSembri abbastanza in gamba, forse potresti dargli riposo.", nil, 0x1e643160, 0x6cb28bbc, nil, 0xd2e36039, "m..m." },
  [228] = { nil, "Uccidi Mor'Ladim, poi porta il suo teschio a Commander Althea Ebonlocke, a Darkshire.", "Da quello che mi dicono i miei esploratori, Mor'Ladim vaga per tutta Duskwood, seguendo uno strano percorso tortuoso attraverso il cimitero. Lo abbiamo sepolto oltre la casa sulla collina, sai dov'è?\n\nNon posso fare niente per aiutarti, ma ti auguro buona fortuna.", "Non ti biasimo se hai problemi con lui, {name}. Alcuni dei nostri Watchers più forti sono caduti per mano di Mor'Ladim.", "L'hai ucciso? Non è un'impresa da poco, {name}! A nome della gente di Darkshire e della Night Watch, ti ringrazio.\n\nAh... c'è però una piccola questione...", nil, 0x707df842, 0x40bc3cfa, 0xb35897e7, 0x9f6d1906, "m...." },
  [229] = { "La figlia sopravvissuta", "Parla con Watcher Sarah Ladimore, a Darkshire.", "Avrei dovuto dirtelo prima...\n\nCome posso dirlo...\n\nMorgan forse credeva che tutta la sua famiglia fosse morta, ma in realtà sua figlia, Sarah Ladimore, ora è una Watcher. Le... circostanze... della morte di suo padre l'hanno sempre tormentata. Forse potresti andare a darle la notizia.", nil, "Sì? Mio padre...\n\n<Abbassa lo sguardo.>\n\nVorrei... aver potuto fare qualcosa per lui... Se solo gli avessi parlato prima che...", 0x2a784eed, 0x8e6bd529, 0x42832c74, nil, 0x17c8873e, "...m." },
  [230] = { "L'accampamento di Sven", "Porta il Book from Sven's Farm a Sven.", "Scavando nel mucchio di terra, trovi un piccolo libro sporco di terra.\n\nIl libro non ha titolo, ma... contiene informazioni che Sven vorrebbe conoscere.", "Hai trovato cosa?? Ti prego, fammelo vedere...", "<Sven legge le pagine del libro, poi lo chiude di scatto.>\n\nQuella figura nell'ombra che ho visto è stata testimone della morte della mia famiglia! Ci sono domande che vorrei fare a quell'uomo... se solo sapessi chi è!", 0x03adfb1c, 0xb1da24c8, 0x4cc2761b, 0x9d6eaf1e, 0x4f4f7346, "....." },
  [231] = { "L'amore di una figlia", "Porta l'anello di Sarah Ladimore alla tomba di Morgan Ladimore.", "Tieni, prendi questo e posalo sulla sua tomba. Forse... in qualche modo, saprà che sto bene, e che nessuno di noi lo ritiene responsabile di quello che è successo.\n\n<Ora ha le lacrime agli occhi; si sfila un anello dalla mano destra e te lo preme tra le mani.>\n\nE... grazie, {name}.", "Lasciami in pace...", "<Una voce spettrale risuona nel vento...>\n\nQuesto è...? Sarah? Possibile che sia ancora viva? Il peso mi è tolto dalle spalle...\n\n{name}. Prendi la mia spada, Archeus. Ora che la mia anima trova pace, non mi serve più. È stata forgiata per fare il bene, e anche se io mi sono dimostrato indegno di impugnarla, forse tu porterai avanti la Luce attraverso di lei.\n\nLys, amore mio...", 0x78f5e66a, 0x84165d28, 0x70f44d6f, 0x2aff9400, 0x130e6acc, "....." },
  [233] = { "Posta per Coldridge Valley", "Consegna il pacco di lettere a Talin Keeneye.", "Mmm, immagino che non saresti <disposto/disposta> a farmi un favore, <ragazzo/ragazza>? Oggi è arrivato dal passo un pacco di lettere, ma non ho tempo di inoltrarle.\n\nSono tutte indirizzate a Talin Keeneye. Lo trovi a ovest, lungo la strada. Si è accampato accanto al lago ghiacciato.\n\nChe ne dici?", "Sì? Hai qualcosa per me?", "Grazie, aspettavo queste lettere da parecchio tempo...\n\nPurtroppo non sono tutte per me. Questa è indirizzata a Grelin Whitebeard. Non è troppo lontano, se vuoi consegnargliela.", 0xeea45c41, 0x43673bfd, 0x2f02ac16, 0xc599dffe, 0x2dbb1502, ".....", nil, nil, 0xce85efc5, nil, nil },
  [234] = { "Posta per Coldridge Valley", "Consegna la lettera a Grelin Whitebeard.", "Se ricordo bene, l'accampamento di Grelin è lungo la strada a sud-est. Di sicuro sarà ansioso di ricevere la sua posta.", "Posso aiutarti in qualcosa?", "Ahh, eccellente. Era da un po' che non ricevevo notizie da Ironforge. Ah, queste lettere della mia mamma mi scaldano il cuore. Tieni, non è giusto che tu non abbia niente da leggere. Prendi uno di questi manuali che abbiamo in giro.", 0xeea45c41, 0x9842e5d5, 0x570047d8, 0x931ded5d, 0xafa727e9, "....." },
  [237] = { "In difesa delle terre del re", "Mountaineer Gravelgaw, nella torre di guardia meridionale, vuole che tu uccida 10 Stonesplinter Skullthumpers e 10 Stonesplinter Seers e torni a fargli rapporto.", "Mountaineer Cobbleflint ha detto solo cose buone su di te, {race}. Per questo ti affiderò una missione della massima importanza. Dobbiamo tenere sotto pressione le forze dei trogg invasori finché i nostri fratelli nanici non tornano dal fronte dell'Alliance.\n\nParti per le colline meridionali e uccidi 10 Stonesplinter Skullthumpers e 10 Stonesplinter Seers. I tuoi attacchi ci faranno guadagnare tempo. Torna a fare rapporto quando avrai compiuto la missione.", "Ci serve più tempo, {race}. I tuoi ordini sono uccidere 10 Stonesplinter Skullthumpers e 10 Stonesplinter Seers. Tieni il nemico sotto pressione finché non ci concederanno rinforzi. Non è il momento di oziare.", "Hai portato a termine bene la tua missione, {race}. Il re in persona ne sarebbe fiero.\n\nMa i rinforzi che ci avevano promesso non sono mai arrivati. A quanto pare il fronte dell'Alliance è un mare cremisi del sangue dei nostri fratelli caduti. La notizia delle perdite lascia l'amaro in bocca. Ma non dobbiamo lasciare che la loro morte sia vana. Dobbiamo raccoglierci in questi tempi cupi e riportare gloria all'Alliance.\n\nParla con Mountaineer Wallbang per un nuovo incarico. Ora c'è bisogno di te più che mai.", 0xc965c9da, 0xecf18b12, 0xd0c449f5, 0x92de6ab6, 0x3ebcd8dc, "....." },
  [239] = { "La Westbrook Garrison chiede aiuto!", "Vai alla Westbrook Garrison e parla con Deputy Rainer.", "La guarnigione sul nostro confine occidentale ci avverte che gli gnoll e i ladri sono sempre più attivi. Chiedono che mandiamo altri soldati di Stormwind... ma non ne abbiamo da mandare!\n\nSe puoi aiutarci, ci farebbe comodo. Vai a parlare con Deputy Rainer alla Westbrook Garrison e senti di cosa ha bisogno.\n\nLa guarnigione è più avanti lungo la strada, a ovest. Dopo aver attraversato il ponte sul piccolo ruscello, la trovi sulla destra.", nil, "Ti manda Marshall Dughan, eh? Be', non fai parte dell'esercito, ma se ti manda Dughan per me va più che bene!\n\nLa nostra situazione è, a dir poco, tesa. Spero che tu possa darci una mano.", 0xdc5c2624, 0x2e02a498, 0x8d2938bf, nil, 0x3b449a23, "...m." },
  [240] = { "Ritorno da Jitters", "Torna da Jitters con le Dusky Crab Cakes.", "Ed eccole qui: \"Crab\" Cakes alla Grual!", "{name}, sei qui! Hai il mio cibo?!?", "Aha! Grazie, {name}. Ci volevano proprio!\n\nE tieni, lascia che te le paghi!", 0x1c60e6ea, 0xe6ff66e0, 0x74df57a6, 0x49ff2ae7, 0xb54be29c, "....." },
  [244] = { "Gnoll alle porte", "Fai rapporto a Deputy Feldon.", "Salute, {class}. Ho il compito di pattugliare questo tratto di strada. Anche se per ora la strada è sicura, ho visto accampamenti di gnoll a nord e a est di qui.\n\nLakeshire deve sapere che gli gnoll stanno radunando le forze! Vai da Deputy Feldon a Lakeshire e parlagli degli gnoll. Fallo, e di sicuro Feldon ti offrirà la paga di un esploratore.\n\nDi solito Feldon ispeziona la zona a sud del ponte per Lakeshire.", nil, "Ci sono Redridge gnolls così vicino a Elwynn?? Potrebbero essere pronti ad avanzare nella nostra terra. Presto quelli di Lakeshire potrebbero non essere gli unici umani sotto assedio!\n\nEcco la tua paga, anche se ci porti notizie terribili. E arrivano in un brutto momento, perché non siamo attrezzati per affrontarle.", 0x8c8be2e9, 0x7bc054fc, 0xae1593a2, nil, 0x3e80651e, "...m." },
  [245] = { "Minacce a otto zampe", "Uccidi 15 Pygmy Venom Web Spiders, poi torna a fare rapporto a Watcher Dodds, a Duskwood.", "Salute, {class}. Forse hai visto quei ragni che hanno invaso il confine occidentale? Quelle minacce a otto zampe sono troppe per noi, e il comandante non ha abbastanza uomini da mandare così lontano da Darkshire.\n\nMi dispiace chiedertelo, ma sembri in grado di occupartene. Non posso prometterti niente di gran valore, ma posso ricompensarti se mi aiuti a stanare quegli insetti schifosi.\n\nAh, e un consiglio: se puoi, evita il loro veleno.", "Faresti meglio a stare <attento/attenta> con i ragni: ho perso alcuni dei miei uomini per colpa loro, e credimi, non è un bello spettacolo vedere un uomo appeso a testa in giù nelle loro ragnatele dopo che il veleno ha cominciato a intenerirlo.\n\nNon vorrei vedere uno di quegli insetti farsi di te un pranzo.", "Ah! Sei <tornato/tornata>. E non troppo <malconcio/malconcia>, a quanto pare. Naturalmente, {name}, la Night Watch ti è grata per il tuo lavoro, e ti avevo promesso una ricompensa, quindi eccola.", 0xd491b1a7, 0x9eafc706, 0x22732e4f, 0xe12e0aee, 0x1c080d20, "....." },
  [246] = { "Valutare la minaccia", "Uccidi 10 Redridge Mongrels e 6 Redridge Poachers, poi torna a fare rapporto a Deputy Feldon a Lakeshire.", "Non abbiamo uomini da mandare, ma bisogna fare qualcosa per quegli gnoll che mi hai segnalato.\n\nEsplora la parte meridionale di Redridge in cerca di gnoll. Tormentali, uccidi quelli che puoi e torna a riferirmi quanti sono e quanto è grave la minaccia che rappresentano. Troverai gli gnoll accampati lungo tutta la strada meridionale di Redridge.\n\nFallo per la Stormwind Army, {name}, e sarai <ricompensato/ricompensata>.", "Scusami, {name}, ma qui abbiamo molto da fare. Se non hai niente da riferire, devo pensare ad altro.", "<Deputy Feldon ascolta il tuo rapporto...>\n\nLì è accampato un bel numero di gnoll, e da quello che mi dici sono dei duri. Non dev'essere stato facile raccogliere queste informazioni.\n\nEcco a te, {name}. Ti siamo grati per l'aiuto.\n\nE se non l'hai già fatto, parla con Marshal Marris e con Magistrate Solomon, a Lakeshire. La nostra situazione è sempre più disperata: di sicuro tutti e due avranno bisogno di te.", 0xcdd38f62, 0x1de28477, 0x75c1cdab, 0xfd431e78, 0x3a73678c, "....." },
  [248] = { "Guardare più lontano", "Sali sulla torre di guardia intatta accanto alla Stonewatch Keep.\n\nTrova un contenitore adatto in cui mettere il Glyph of Azora.", "Ho tenuto d'occhio la Tower of Ilgalar e percepisco che Morganth è in conflitto con gli orchi della Stonewatch Keep. Non conosco il motivo della loro contesa, ma puoi aiutarmi a svelare questo mistero.\n\nPrendi un altro Glyph of Azora, poi sali in cima alla torre di guardia intatta accanto alla Stonewatch Keep.\n\nTrova un oggetto adatto su cui posare il glifo. Un forziere o un vaso, un posto dove il glifo non venga notato, andrà bene per il mio scopo.", "Questo vaso un tempo conteneva un liquore maleodorante, ma ora giace vuoto e dimenticato su un paio di barili.", "È un recipiente adatto per il Glyph of Azora, e permetterà a Theocritus di scrutare le menti dentro la Stonewatch Keep.", 0x6310d65d, 0x375e6926, 0x7c764f66, 0x08216341, 0x02b3cbef, "....." },
  [249] = { nil, "Sconfiggi Morganth.\n\nPorta il suo Pendant of Shadow a Theocritus, alla Tower of Azora nella Elwynn Forest.", "Dopo lunghe osservazioni, ho scoperto i piani di Morganth.\n\nCerca la Scythe of Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains e il regno di Stormwind sentiranno la sua oscura potenza.\n\nNon sono pronto ad affrontare Morganth, ma temo che vada fermato subito. Perciò devi entrare nella Tower of Ilgalar e affrontarlo.\n\nSconfiggilo e portami il suo Pendant of Shadow. Fallo, e il regno ti sarà molto debitore.", "Presto, {name}, prima che il mio timore che Morganth estenda il suo potere si avveri!", "Hai fatto bene, {name}. Sconfiggendo lo stregone Morganth, hai salvato Stormwind da un grave pericolo.\n\nTi offro questa ricompensa con grande umiltà. E ti augurerei la pace, se questi fossero tempi di pace.\n\nInvece ti auguro fortuna nelle tue prove, e vittoria nei conflitti che verranno.", nil, 0x879964dd, 0x12522098, 0x0143479a, 0x425a6647, "m...." },
  [250] = { "Incombe una minaccia oscura", "Indaga nella zona vicino alla rampa orientale della diga e porta a Chief Engineer Hinderweir un indizio che possa rivelare cosa tramano i Dark Iron Dwarves.", "Grazie al cielo qualcuno si preoccupa della sicurezza della diga. Prima la distruzione del Thandol Span e poi il saccheggio di Dun Modr! Non ho dubbi che la diga sarà il bersaglio della prossima minaccia dei Dark Iron. Quasi tutto il servizio di sicurezza qui è stato riassegnato all'Alliance Front, compreso il mio miglior ispettore.\n\nPer questo ho bisogno di te, {name}. Ho visto alcuni Dark Iron Sappers aggirarsi intorno alla rampa orientale della diga. Indaga nella zona e riportami un indizio.", nil, "Il barile dall'aria sospetta contiene una polvere dall'odore strano.", 0x285fa090, 0xd58cd749, 0x3b5e1a8f, nil, 0xcbe807ee, "...m." },
  [251] = { "Tradurre il biglietto di Abercrombie", "Porta la Letter to Ello a Sirra Von'Indi.", "Porta il biglietto che mi hai dato a Sirra Von'Indi. È molto esperto di lingue e di arti antiche: se qui c'è qualcuno che può tradurre questo messaggio, è lui.", "Un biglietto dall'eremita Abercrombie, eh? Non lo conosco, ma se vive vicino al cimitero, allora so che gli è marcito il cervello!", "<Sirra comincia a tradurre il biglietto...>", 0x5d4115a2, 0x14115437, 0xcf076a63, 0x22e67061, 0xcc1a43e1, "....." },
  [252] = { "La traduzione per Ello", "Porta la Translated Letter a Lord Ello Ebonlocke", "Cielo! Se quello che c'è scritto in questo biglietto è vero, allora Abercrombie ha fatto qualcosa di... indicibile.\n\nFaresti meglio a riportare il biglietto tradotto a Ello.\n\nE fallo in fretta, perché temo che una sciagura stia già avanzando verso il nostro paese...", "Ah, il biglietto è tradotto? Ti prego, fammelo vedere...", "<Ello legge la lettera... e sbianca. Poi ti guarda...>\n\nAnche se l'aiuto che hai dato ad Abercrombie poteva nascere dalla gentilezza, le tue azioni hanno condannato il nostro paese.\n\n<Ello si perde nei suoi pensieri...>", 0xe1358fe4, 0x997dc93d, 0x30bdbc4f, 0x303a0cc2, 0xbf52b0c4, "....." },
  [253] = { "La sposa dell'imbalsamatore", "Trova la tomba di Eliza. Prendile l'Embalmer's Heart, poi torna da Ello Ebonlocke.", "The Embalmer è un nome che compare in una delle storie dei nostri bambini. Era un alchimista gentile, fatto impazzire dalla morte della moglie, Eliza. Per riportarla in vita, usò la magia oscura e mise il proprio cuore nel petto della sposa morta.\n\nQuesto fece rivivere Eliza... ma la maledisse con una fame di carne umana, costringendo l'Embalmer a tenerla sepolta.\n\nIl suo cuore è il suo potere. Trova la tomba di sua moglie, recupera il suo cuore e portamelo finché batte ancora. Fallo, e il suo potere sarà spezzato.", "Hai già trovato la tomba di Eliza? Hai il cuore dell'Embalmer?", "Ce l'hai fatta! La magia del suo cuore sarà una difesa contro il male dell'Embalmer, e un potente scudo sul paese di Darkshire.\n\nHai fatto una cosa grande per la nostra gente, {name}. Il tuo nome resterà per sempre nei nostri annali.", 0xe86145e0, 0x23727411, 0x572b08ce, 0xa3411c44, 0x7066ca1d, "....." },
  [254] = { "Scavare nella terra", nil, nil, nil, "Scavi nella terra smossa sopra la tomba... e trovi i resti di una bara.\n\nDentro la bara senti il raschiare vibrante di dita artigliate e il digrignare di denti marci...\n\nAprirai la bara per prendere il cuore dell'Embalmer?", 0x75e151d5, nil, nil, nil, 0x1f58c444, ".mmm." },
  [255] = { "Mercenari", "Magistrate Bluntnose di Thelsamar ti ha assunto per uccidere 4 Mo'grosh Ogres, 4 Mo'grosh Brutes e 4 Mo'grosh Enforcers.", "Due mesi solo per sentirci dire da Ironforge che ci concederanno una manciata di soldati per difenderci, e altri due mesi perché arrivino! È già grave che il nostro paese resti senza protezione, ma anche lo scavo e la diga, la diga!, sono esposti agli attacchi.\n\nA quanto pare non ho scelta, allora. Mi servono braccia a pagamento.\n\nChe ne dici tu? Sembri il tipo giusto, {class}. Un gruppo di ogre si è accampato a nord-est del lago. Forse potresti reclutare qualcun altro e aiutarci a eliminare la minaccia per il nostro paese?", "Hai avuto fortuna?", "Ah, questa è un'ottima notizia! I tuoi sforzi sono molto apprezzati da me e dalla gente di Thelsamar. Meglio ancora, se risolviamo il problema degli ogre, potremo concentrarci su quei trogg che la Luce li bruci.", 0x68e67e79, 0xd9633fd2, 0x6eaa85fa, 0x580fb5c3, 0x89841e1a, "....." },
  [256] = { "RICERCATO: Chok'sul", "Uccidi Chok'sul e porta la sua testa a Magistrate Bluntnose di Thelsamar.", "Per ordine del magistrato di Thelsamar:\n\nChok'sul, l'ogre ritenuto il capo e l'organizzatore degli attacchi contro il paese di Thelsamar, la Stonewrought Dam e il sito di scavo, è ricercato morto con qualunque mezzo necessario.\n\nUn compenso in denaro sarà corrisposto a chi porterà al magistrato la prova della morte di Chok'sul.\n\nChok'sul è stato visto l'ultima volta all'accampamento degli ogre, nella parte nord-orientale di Loch Modan.", "Sì? Posso fare qualcosa per te?", "Bleah! Cos'è quella cosa? E perché l'hai portata...\n\nMaledi...! È davvero? Be', che la Luce mi bruci, è la testa di quel dannato ogre? Questo sì che è un bel colpo! Ecco la tua ricompensa, e i ringraziamenti miei e della gente di Thelsamar.", 0xd76c7e39, 0xf939ce2f, 0x8fcfd75f, 0x74cd0668, 0x2b1ae6f2, "....." },
  [257] = { "La vanteria di un cacciatore", "Uccidi 6 Mountain Buzzards e torna da Daryl the Youngling alla Farstrider Lodge entro 15 minuti.", "Pensi di poterti misurare in astuzia con Daryl the Bold, eh? Non credo proprio! Naturalmente sei <liberissimo/liberissima> di provarci. Ecco una sfida che dovrebbe rivelarsi al di sopra delle tue capacità, quindi non prendertela troppo se non sei all'altezza.\n\nUno stormo di poiane ha fatto il nido qui a Loch Modan. Perché non provi ad abbattere qualcuna di quelle bestie? Facciamo così: se superi la mia sfida in 15 minuti, ti darò il mio arco o il mio fucile.\n\n<Ti squadra con aria sprezzante.>\n\nTanto, a quanto pare, non hai molto da perdere.", "Niente da fare? Non prendertela troppo, {name}...\n\nNon tutti possono essere come me.", "Cosa? Successo?\n\nAscolta me, {name}ama, non montarti la testa. Voglio dire, qualunque ragazzino imberbe con un arco avrebbe potuto uccidere esemplari così... piccoli. E spero che ammazzare le poiane non ti piaccia troppo, eh? Non vorremmo che si estinguessero.\n\nBe', ehm... Che non si dica mai che Daryl the Bold non mantiene la parola.", 0x0a7320b6, 0x5b163583, 0x5ce8605c, 0xe9d625da, 0x867e7877, "....." },
  [258] = { "La sfida di un cacciatore", "Uccidi 5 Elder Mountain Boars e torna da Daryl the Youngling alla Farstrider Lodge entro 12 minuti.", "{name}ath, giusto? Si vede che scoppi d'orgoglio per aver superato la prima prova, eh? Come ti ho detto, non è una grande impresa.\n\nDovresti provare a cacciare cinghiali. Fidati, questa non è una caccia al cinghiale nella Coldridge Valley, quindi faresti bene a stare <attento/attenta>. Stavolta ti do solo 12 minuti.\n\nNon prendertela se fallisci. Se ci riuscissi, ti darei la camicia che ho addosso!\n\nTi ho mai raccontato come mi sono fatto la mia famosa cicatrice? No? Era due anni fa...", "È naturale commiserarsi quando si viene battuti da qualcuno così nuovo a questo mondo. Non devi prendertela, {name}ah.\n\nMm? Ho sbagliato il tuo nome?", "Sembri un po' <malconcio/malconcia>. Di sicuro i cinghiali ti hanno dato qualche problema, eh? Niente paura, sarò discreto sulla tua fatica, immagino quanto sia già dura per te senza le accuse delle malelingue.\n\nOh! Sei <riuscito/riuscita> a uccidere i cinghiali? Io... be', cioè... cioè, non mi sorprende! Qualsiasi bambino avrebbe potuto... scommessa?\n\nQuale scommessa?", 0xc117168c, 0xf6f7aed2, 0x53a3b2ac, 0x73714f0b, 0x6757139d, "....." },
  [261] = { "Lungo il sentiero scarlatto", "Distruggi 30 Undead Ravager, poi torna dal Brother Anton, a Nijel's Point.", "Sarò franco. Siamo in guerra con la Scourge. È un male che corrompe la nostra gente e infetta la nostra terra. Deve essere fermato prima che ci sopraffaccia e trascini il nostro mondo nell'ombra. Noi della Scarlet Crusade abbiamo giurato di combattere la Scourge con il corpo e con l'anima.\n\nSe sei con noi, raccogli il tuo coraggio e dimostra la tua fedeltà: distruggi gli undead ravager di Desolace, nella Valley of Bones a sud.\n\nFallo, e la Crusade ti accoglierà.", "La Scourge cresce in potere ogni giorno che passa. Se vuoi davvero fermarne l'avanzata, dimostramelo.", "Hai dimostrato la tua risolutezza, e la Scarlet Crusade ti loda.\n\nSe non ti tiri indietro davanti a un giusto massacro, forse il tuo cammino è con noi...", 0xaeca3093, 0x5d043380, 0xdc7cbe13, 0x256387b8, 0x2d30e832, "....." },
  [262] = { "La figura nell'ombra", "Prendi il libro che hai trovato alla fattoria di Sven e mostralo agli abitanti di Darkshire.", "Devo sapere chi era quella figura furtiva nell'ombra che vidi la notte in cui fu uccisa la mia famiglia!\n\nTi prego, {name}, hai dimostrato di saperci fare. Ti prego, trova quella figura nell'ombra. Devo scoprire quali segreti nasconde!\n\nNon ho indizi che tu non conosca già, ma ecco: prendi il libro che hai trovato alla mia fattoria. Forse qualcuno in paese saprà collegare questo libro al suo proprietario.", "Se hai qualcosa che appartiene alla figura nell'ombra che cerchi, fammelo vedere. Forse riuscirò a intuire qualcosa sul suo proprietario.", "Mmm... Qualcuno ha maneggiato questo libro di recente, qualcuno spinto dalla vendetta. Ma le impronte lasciate, almeno quelle del proprietario originale, sono deboli.\n\nPosso dirti, però, che il proprietario originale di questo libro non è di Darkshire.", 0x314895c6, 0x43340f49, 0x13c0ea44, 0x383fb720, 0x6233a5dd, "....." },
  [263] = { "In difesa delle terre del re", "Mountaineer Wallbang, nella torre di guardia meridionale, vuole che tu uccida 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnappers.", "I Mountaineers mi dicono che hai molto coraggio e capacità, {name}. Ci serve qualcuno come te da queste parti, {race}. Il problema dei trogg non migliora. Le riserve sono state chiamate al fronte e qui fuori siamo soli. Ma ora che ci sei tu, {class} di esperienza, vediamo cosa sai fare.\n\nVai a uccidere 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnappers. Vediamo se sei all'altezza della tua fama, Trogg-Slayer.", "Già di ritorno? Nel caso non fossi stato chiaro, ci serve che uccidi 10 Stonesplinter Shaman e 10 Stonesplinter Bonesnappers, {name}. Ora vai a prenderli, Trogg-Slayer!", "Ho capito appena ti ho visto, {name}, che avresti reso fiera Ironforge. Hai servito bene King Magni. Ora che hai dimostrato di essere un aiuto così leale per il regno, forse dovresti parlare con il capitano per vedere se ti affiderà un incarico più importante.\n\nTi saluto, {name}.", 0xc965c9da, 0x4a79e4d2, 0x0a04bb9f, 0xe5f1b1fc, 0xfc0b08bb, "....." },
  [265] = { "La ricerca della figura nell'ombra continua", "Vedi se altri abitanti hanno indizi sulla figura nell'ombra.", "Ecco il tuo libro, {name}, e ti auguro fortuna nella tua ricerca. Se chiedi ad altri in paese, forse potranno darti altri indizi.\n\nEd eccone uno da parte mia: anche se l'autore di questo libro è un forestiero a Darkshire, il libro è stato comprato qui.", "A volte vendo libri bianchi a studiosi e maghi, o a chiunque voglia tenere un diario.\n\nRicordo bene tutti quelli a cui ho venduto un libro negli ultimi mesi...", "Ah, sì. Ho venduto questo libro un mese fa a un tipo losco. Non mi ha detto il suo nome, ma era un tizio nervoso e agitato, che si guardava sempre alle spalle.\n\nSpero che ti sia d'aiuto...", 0x15f6b643, 0xfc327109, 0xbf55c340, 0x1c3e5d22, 0x7f698a5e, "....." },
  [266] = { "Chiedere alla locanda", "Cerca nella locanda indizi sulla figura nell'ombra.", "Ecco il tuo libro, e buona fortuna con le tue indagini.\n\nForse dovresti estendere la ricerca alla locanda. Se la persona che cerchi ha passato del tempo in paese, è probabile che qualcuno l'abbia vista lì.", "Lo Scarlet Raven non fa più gli affari di una volta, ma qualche viaggiatore di passaggio lo vediamo ancora.\n\nSe riesci a descrivermi la persona che cerchi, forse me ne ricorderò.", "Ah, sì, mi ricordo di questo libro. Il suo proprietario ha preso una stanza per qualche giorno e passava le notti al bancone, a scrivere.\n\nSe n'è andato in fretta, borbottando che qualcosa gli dava la caccia. L'ultima volta che l'ho visto stava lasciando il paese verso ovest, in cerca di un nuovo nascondiglio.\n\nIl primo posto che troverebbe a ovest è Raven Hill...", 0x4736a4dc, 0xbe6a7054, 0x6d658e06, 0xe05a3817, 0x7f159659, "....." },
  [267] = { "La minaccia dei trogg", "Porta 8 Trogg Stone Teeth a Captain Rugelfuss, nella torre di guardia meridionale.", "{class}, forse sai o forse no della minaccia dei trogg che incombe sulle terre naniche. Con l'Ironforge Reserve chiamata sull'Alliance Front, ci resta solo una parte delle forze necessarie a tenere al sicuro queste terre. Il mio reggimento deve sorvegliare il Gate qui, e non possiamo lasciare il nostro posto per paura di un'invasione.\n\nMa bisogna fare pressione su quei maledetti trogg nascosti tra le colline. Se te la senti, lancia un assalto contro i trogg. Portami 8 Trogg Stone Teeth come prova.", "Hai 8 Trogg Stone Teeth da mostrarmi? Se no, c'è ancora lavoro da fare, {name}.", "Sono molto colpito, {name}. Hai reso un grande favore alla razza nanica difendendo le nostre terre. King Magni Bronzebeard in persona ne sarebbe fiero!", 0x5feba290, 0x14a4d831, 0xc4e3d0e9, 0xfb5e59d0, 0xe9c8efe3, "....." },
  [268] = { "Ritorno da Sven", "Torna da Sven con il diario completo di Jitters.", "Il libro che hai trovato era finito solo a metà. Ho dovuto lasciarlo alla fattoria di Sven quando sono scappato da lì...\n\nTieni. Porta il mio diario completo a Sven. Descrive meglio quello che è successo alla sua fattoria.\n\nAnche se questo diario è stato la mia unica compagnia nelle ultime settimane, se darlo via mi evita di dover affrontare Sven e la sua ira, lo faccio volentieri!", "Hai scoperto chi era la Shadowy Figure?", "Questo diario mi spiega molte cose e mi mette sulla strada contro i dark riders! Ho visto questi cavalieri a Duskwood, e li ho visti parlare con il mago Morbent Fel, alla Forlorn Rowe.", 0xb5e4d4a7, 0xddfbac78, 0xa746e876, 0x34bcef3e, 0x11d4dc98, "....." },
  [269] = { "In cerca di saggezza", "Consegna il Jitters' Completed Journal a Bishop Farthing, a Stormwind.", "Vai nella città di Stormwind e parla con Bishop Farthing, nella Cathedral of Light. Dagli il diario di Jitters e digli che intendi affrontare Morbent Fel.\n\nAnche se Stormwind ha abbandonato Darkshire, Farthing è un'anima gentile e molto saggia. Potrebbe aiutarti nella tua missione per salvarci.\n\nLa tua missione è pericolosa, ma sbrigati, {name}. Ogni ora che passa, le ombre di Duskwood si fanno più scure.", "Riposa, <fratello/sorella>. Vedo che hai viaggiato a lungo e porti un fardello pesante. Puoi dirmi cosa getta su di te quell'ombra scura?", "<Dopo aver letto il diario e ascoltato le tue intenzioni...>\n\nUna corruzione malvagia ha messo piede nella già tormentata Duskwood. Ringrazio la Luce di avere un eroe come te ad affrontarla.\n\nMa prima devi prepararti alla prova che ti attende... perché il Necromancer Morbent Fel è potentissimo, e si è circondato di oscuri incantesimi che lo proteggono dagli attacchi fisici. Se vuoi sconfiggerlo, ti servirà un'arma capace di vincere queste protezioni.", 0xa17403e8, 0xe615de8a, 0xc211aa79, 0x0ed6c310, 0xce1c3c43, ".....", nil, nil, nil, 0x36e5648e, nil },
  [270] = { "La flotta condannata", "Va' a Menethil Harbor, nelle Wetlands, e parla con Glorin Steelbrow.", "Anni fa, la Third Fleet di Kul'Tiras affondò lungo le coste delle Wetlands, una distesa paludosa a nord del regno nanico di Ironforge. A bordo di una nave c'era un carico di Lightforge Iron.\n\nQuesto metallo è prezioso per noi, perché gli oggetti forgiati con esso colpiscono con santa verità. Se devi affrontare Morbent Fel, ti servirà un'arma del genere.\n\nVa' a Menethil Harbor e parla con il mio collega nano Glorin Steelbrow. Se quel metallo perduto si può trovare, lui saprà dove cercare.", nil, "Il Lightforge Iron è un metallo prezioso, ma sembra che la tua missione sia disperata. Hai fatto molta strada, <fratello/sorella>. Con un po' di fortuna potresti trovare ciò che cerchi!\n\nE se riuscirai a procurarti il ferro, so chi può trasformarlo in un'arma contro questo negromante di Duskwood di cui parli.", 0xb30a2ab9, 0xb61b8cec, 0x14f1ea19, nil, 0xd5d90125, "...m.", nil, nil, nil, nil, 0x62417845 },
  [271] = { "La vendetta di Vyrin", "Uccidi Ol' Sooty, poi mostra il tuo lavoro a Daryl the Youngling, alla Farstrider Lodge.", "Non è che ti andrebbe di prenderti una piccola rivincita sul nostro audace amico? Daryl qualche abilità ce l'ha, mi duole ammetterlo.\n\nUn anno fa, alla Farstrider Lodge si dava la caccia a un grosso orso, ma nessuno dei cacciatori ebbe fortuna. Così Daryl pensò di provarci lui. Tutto quello che ne ricavò fu quella brutta cicatrice sull'occhio.\n\nUccidi l'orso, e sono sicuro che persino Daryl resterà senza parole, per una volta.\n\nL'orso, Ol' Sooty, si trova intorno alla sua tana sulle colline sopra Thelsamar.", "Ah, {name}! Già di ritorno? Di sicuro sei <tornato/tornata> a caccia, eh? Non preoccuparti se hai avuto qualche battuta d'arresto, alla lunga ti renderà migliore!\n\n...Tanto peggio di così non potresti fare...", "Ehm... cos'è questo? Una testa d'orso, a quanto pare.\n\n<Si passa un dito sulla cicatrice senza accorgersene.>\n\nBe', è una preda piuttosto interessante quella che hai lì. Non può essere l'orso di quella volta...\n\n<La voce gli si spegne e comincia a tremare visibilmente.>\n\nOh, portalo via, portalo via! Porta via di qui quella cosa raccapricciante!", 0xeb8bf51a, 0x9c0267f5, 0x0f0813b8, 0xce498672, 0x84cbe4fe, "....." },
  [272] = { "La prova del leone marino", "Trova l'Half Pendant of Aquatic Agility e l'Half Pendant of Aquatic Endurance. Parla con gli abitanti di Moonglade per avere indizi su dove possano trovarsi.\n\nForma il Pendant of the Sea Lion unendo le due metà. Per farlo devi trovarti nei pressi dello Shrine of Remulos.\n\nPorta il pendente completo a Dendrite Starblaze, nel villaggio di Nighthaven, a Moonglade.", "Per la seconda prova ti serviranno le due metà che formano il Pendant of the Sea Lion. Una metà trae potere dall'agilità dell'aspetto del leone marino, che scivola nell'acqua; l'altra trae potere dall'incredibile resistenza dell'aspetto del leone marino. I druidi attingono in egual misura a entrambe queste qualità per incarnare l'aspetto della loro forma acquatica.\n\nParla con gli abitanti di Moonglade per scoprire dove possano trovarsi le parti, e portale entrambe qui per unirle. Una volta formato, porta il pendente a Dendrite Starblaze.", "Hai formato il pendente da farmi esaminare, {name}? Se ti serve aiuto per trovare le parti, prova a chiedere informazioni agli abitanti. Non solo troverai ciò che cerchi, ma avrai anche un motivo per esplorare questa radura meravigliosa e sacra.", "Hai completato la Trial of the Sea Lion, {name}: congratulazioni.\n\nOgni compito per ottenere il pendente dimostra che agilità e resistenza sono entrambe necessarie per agire in armonia con ciò che desideri fare sott'acqua. Nessuna delle due può esistere senza l'altra, ed entrambe sono impossibili senza la tua volontà di abbracciare l'aspetto del leone marino.\n\nRicorda bene queste lezioni e contaci una volta ottenuta la tua forma acquatica.", 0x5cc8ed68, 0xdf177053, 0x23c219a5, 0x3520b13e, 0xb90d61f2, "....." },
  [273] = { "Rifornire lo scavo", "Parla con Huldar.", "Non è troppo tardi però, puoi andare a cercare Huldar. Non può essere andato molto lontano: forti come sono, Miran e Saean non possono muoversi troppo in fretta, carichi di quei barili.\n\nStanno facendo la solita strada per lo scavo: escono dal paese verso sud e seguono la curva del Loch.\n\nNon dovresti avere problemi a trovarli, a meno che non siano già arrivati.", nil, "Mph, ci vuole più di un'imboscata dei Dark Iron per fermare le consegne!\n\nMa Saean... non avrei mai sospettato che fosse uno dei loro simpatizzanti. Lavoriamo con lui da quasi un anno... forse non ho visto i segnali.\n\nBe', ci penserò più tardi.", 0xff211d45, 0x48ac2cba, 0xa385adaf, nil, 0xd8cf8be4, "...m." },
  [274] = { "Incombe una minaccia oscura", "Ashlan Stonesmirk vuole che tu torni dal Chief Engineer Hinderweir per informarlo della nuova scoperta.", "Questa non è una polvere esplosiva qualunque. Guarda i minuscoli cristalli argentati. E l'odore inconfondibile! È chiaro come il sole che questa è Seaforium Powder. Il Seaforium è abbastanza innocuo. Ma una volta bagnato potrebbe far saltare Ironforge fuori dalla montagna.\n\nLa reazione chimica può essere neutralizzata mescolando quattro componenti: veleno di lurker, cristallo di Mo'Grosh frantumato, una lacrima di crocolisk e questo colloide disinnescante. Ora avvisa Hinderweir prima che sia troppo tardi!", "Cos'è che porti da parte di Ashlan?", "Un colloide disinnescante? Per il Seaforium? Santo cielo!", 0x285fa090, 0xff4b9027, 0xae733e3d, 0x9e72d87b, 0x6bbfd674, "....." },
  [275] = { "Piaghe sulla terra", "Uccidi 12 Fen Creepers, poi torna da Rethiel the Greenwarden, nelle Wetlands.", "Non so perché, ma nelle Wetlands cresce una suppurazione. I Fen Creepers si sono sollevati. Sono piaghe malate e febbricitanti sulla terra, e perché la febbre passi vanno abbattuti e lasciati tornare a posarsi nelle paludi.\n\nI Fen Creepers si trascinano lungo i corsi d'acqua delle Wetlands.", "Le Wetlands piangono ancora, e i Fen Creepers infuriano ancora. Torna da me quando il tuo compito sarà compiuto.", "I tuoi sforzi danno sollievo a questa terra, e per questo ti concederò un dono.", 0x98ec1fa6, 0xa3687664, 0x588d9f5d, 0x987a7155, 0xd673054a, "....." },
  [276] = { "Zampe che calpestano", "Uccidi 15 Mosshide Gnolls e 10 Mosshide Mongrels, poi torna da Rethiel the Greenwarden, nelle Wetlands.", "I Mosshide Gnolls vivono in pace nelle Wetlands da molti anni, ma ora il loro numero cresce. I loro piedi schiacciano i cespugli e i fiori della palude, e le loro asce immonde tagliano troppa legna per alimentare i fuochi.\n\nNon sono più in equilibrio con la terra. Perché le Wetlands sopravvivano, gli gnoll vanno ridotti.\n\nUccidi 15 Mosshide Gnolls e 10 Mosshide Mongrels. Cacciali a sud, vicino al cancello nanico di Algaz. Fatto questo, torna da me.", "Il tuo compito ti attende ancora, giovane {class}.", "Riducendo il numero degli gnoll, ti sei <preso/presa> cura della salute delle Wetlands. Anche se in passato la mia fiducia nella tua gente è stata messa a dura prova, {race}, potrebbe ancora essere ripristinata.", 0xc2e1895b, 0xefe8bed1, 0x1e6b39f8, 0x5811b98d, 0xd1151a2d, "....." },
  [277] = { "Il tabù del fuoco", "Porta a Rethiel the Greenwarden 9 Crude Flints.", "I Mosshide tagliano gli alberi delle Wetlands e usano la loro carne per scaldarsi con il fuoco. Non sopporterò più questo dolore!\n\nTogli ai Mosshide le loro Crude Flints, gli strumenti con cui accendono il fuoco. Le portano tutti i Mosshide, tranne i più piccoli Mosshide gnolls e Mosshide mongrels.", "Hai gli strumenti per il fuoco degli gnoll?", "... grazie. Spezzerò queste pietre focaie e le getterò in mare, perché non vengano mai più usate per bruciare legno vivo.", 0xf9fd95dd, 0x98bf308d, 0x0d5db968, 0x4c8714a1, 0xf8f39043, "....." },
  [278] = { "Incombe una minaccia oscura", "Chief Engineer Hinderweir vuole che tu raccolga del Lurker Venom, un Mo'grosh Crystal e una Crocolisk Tear.", "Comincia subito a raccogliere i materiali per il disinnesco, {name}. Il Lurker Venom si trova sui ragni di Loch Modan. Anche le Crocolisk Tears si trovano qui nel Loch. Ma un Mo'Grosh Crystal sarà molto difficile da procurare. Gli ogre a nord-est li estraggono, ma i cristalli sono una merce molto rara.\n\nDobbiamo essere pronti a sventare un attacco dei Dark Iron! Torna da me quando avrai raccolto gli oggetti necessari e preparerò la miscela.", "Hai gli oggetti che servono? Il tempo stringe!!", "Appena in tempo, {name}!", 0x285fa090, 0x7dcc9e32, 0xda78b8d7, 0x6ba64689, 0x4c641a56, "....." },
  [279] = { "Artigli dagli abissi", "Uccidi 12 Bluegill Murlocs.\n\nUccidi Gobbler e prendi la sua testa.\n\nPorta la Gobbler's Head a Karl Boran, a Menethil Harbor.", "I murloc strisciano fuori dalle acque profonde e costruiscono i loro villaggi sulla costa. Molestano i nostri pescatori e mercanti e vanno fermati.\n\nUno di questi murloc, Gobbler, si aggira con altri Bluegill Murlocs e tormenta i mercanti lungo la strada, per poi ritirarsi sempre al sicuro nelle catapecchie dei murloc lì vicino. I nostri mercanti sono in pericolo, e pagheremo per proteggerli.\n\nGobbler si aggira nell'insenatura del fiume a nord di qui. Trovalo, uccidi i suoi simili e portami la sua testa.", "I nostri mercanti non saranno al sicuro finché non ci saremo liberati di Gobbler e di quei murloc.", "Ah, ben fatto {name}.\n\nAccetta questo come pagamento per aver adempiuto al tuo contratto con i Merchant Marines.", 0xb2853dd5, 0xf105a28f, 0x413ad26f, 0xf4549fd2, 0x3b289c36, "....." },
  [280] = { "Incombe una minaccia oscura", "Chief Engineer Hinderweir vuole che tu nuoti fino alla base della diga, trovi il barile di polvere e ci mescoli dentro la Disarming Mixture per evitare l'esplosione.", "Oggi ho visto alcuni Dark Iron Insurgents nuotare verso la diga con un grosso barile. Non c'erano Mountaineers a fermarli! Temo che abbiano piazzato il Seaforium alla base della diga, e potrebbe esplodere da un momento all'altro! Lasciami unire tutti questi ingredienti nella Disarming Mixture. Ecco fatto.\n\nOra ho bisogno che tu prenda questa miscela e la mescoli nel barile prima che sia troppo tardi! Presto!", "Il coperchio del barile si svita lentamente.", "Il barile sfrigola leggermente mentre la Disarming Mixture si deposita.", 0x285fa090, 0x49e1c755, 0xcabe6c09, 0x1bf6801c, 0x3e97c160, "....." },
  [281] = { "Recuperare la merce", "Fruga nelle casse e nei barili degli accampamenti dei murloc sulla costa.", "Non molto tempo fa una nave mercantile, la Blind Princess, è stata assaltata dai murloc. Anche se la nave si è salvata, gran parte del carico è stato trascinato fuori bordo da quelle creature, compresa una preziosissima statuetta di Terenas Menethil. Vogliamo recuperare quella statuetta.\n\nCerca nelle catapecchie dei murloc sulla costa casse, barili e altre tracce del carico perduto. Trova la Menethil Statuette e riportamela.", nil, "Questa cassa è coperta di graffi di artigli e di segni d'acqua. Aprendola trovi paglia fradicia e marcia, come se dentro fosse stato riposto qualcosa di valore. Frughi nella paglia...\n\n...e trovi una bracciata di bottiglie rosse.", 0x20e23136, 0x92703920, 0xae0acc9a, nil, 0x1db70c6a, "...m." },
  [282] = { "Le osservazioni di Senir", "Parla con il Mountaineer Thalos.", "Pensavo di mandare il mio apprendista da mio fratello Senir con il mio rapporto, ma mi sentirei molto meglio se fosse in mani più... affidabili. Sempre che non ti dispiaccia, s'intende.\n\nMmm... dovrai prendere la galleria per arrivare a Kharanos.\n\nParla con il Mountaineer Thalos prima di attraversare la galleria. Ormai è completamente infestata dai trogg.\n\nSegui la strada fino ad Anvilmar, poi continua verso est fino alla galleria: Thalos è di stanza lì vicino.", "Salute! Fa' attenzione, {name}: la galleria per Dun Morogh è infestata dai trogg e non è sicura da attraversare.\n\nSe non hai affari urgenti a Dun Morogh, dovrò chiederti di restare ad Anvilmar finché la galleria non sarà più sicura.", "Mm, beh, se Whitebeard ti manda a Dun Morogh per affari importanti, non posso certo fermarti, no?\n\nAlmeno lascia che ti dia qualche consiglio e qualche indicazione.", 0x034f6959, 0x04633807, 0xa94e25b2, 0xfbfd2fad, 0xe36152d6, "....." },
  [283] = { "Incombe una minaccia oscura", "La Disarming Mixture sembra aver fatto effetto. Torna da Chief Engineer Hinderweir a dargli la buona notizia.", "Il barile sfrigola leggermente.", nil, "Grazie mille, {name}!! Hai salvato la Stonewrought Dam! Senza il tuo aiuto, i terroristi Dark Iron avrebbero di sicuro distrutto questo possente monumento. Hai reso fieri il regno e l'Alliance, prode {class}.\n\nLa diga è di nuovo al sicuro. . . almeno per ora. . . .", 0x285fa090, 0x59adb22f, 0x5529aef7, nil, 0x6249196b, "...m." },
  [284] = { "La ricerca continua", "Cerca la Menethil Statuette.", "Perquisisci a fondo questo gruppo di catapecchie dei murloc, ma non trovi traccia della Menethil Statuette.\n\nForse una delle due catapecchie vicine, a nord e a nord-est, avrà altri indizi.", nil, "Questo barile è quasi intatto. Aprendolo...\n\n...ti investe l'odore pungente del formaggio. È un po' bagnato, ma ancora buono!", 0xf8a6514c, 0x2fa34187, 0xc6d42d7d, nil, 0xf8bf63bc, "...m." },
  [285] = { "Cercare in altre catapecchie", "Continua a cercare la Menethil Statuette nelle catapecchie dei murloc.", "Dopo un'ispezione accurata, questo gruppo di catapecchie dei murloc non rivela nulla.\n\n...ma sei <sicuro/sicura> che il prossimo indizio che troverai sarà quello buono.\n\nUna delle catapecchie a nord deve avere la Menethil Statuette!", nil, "Questo barile è mezzo sepolto tra il fango e l'erba...", 0x37a342ab, 0xe542c0b8, 0x164b5557, nil, 0xc166ecf6, "...m." },
  [286] = { "Restituire la statuetta", "Porta a Karl Boran la Menethil Statuette.", "Dopo aver liberato il barile dal fango e averlo aperto, trovi una statuina argentea avvolta in paglia fine. Raffigura un giovane paladino dai capelli lunghi con il martello alzato.\n\nDev'essere la Menethil Statuette! Ora devi riportarla a Karl Boran, a Menethil Harbor.", "Hai la statuetta?", "Il capitano della Blind Princess sarà sollevato di sapere che questo prezioso carico è stato recuperato. Ti sei ben <meritato/meritata> questo pagamento per i servigi resi.\n\nÈ bello vedere gente affidabile come te, soprattutto in tempi difficili come questi.", 0x6359787c, 0xe755db7e, 0x468c1b10, 0xc8e24594, 0xee837828, "....." },
  [287] = { nil, "Esplora Frostmane Hold e uccidi 5 Frostmane Headhunter per Senir Whitebeard, a Kharanos.", "Sono in ritardo con il mio rapporto e mi farebbe comodo il tuo aiuto, {name}. Sono appena riuscito a scoprire dove si sono rintanati i troll, ma ne ho visti così tanti che ho avuto paura di entrare.\n\nEcco cosa mi serve... Scendi nella grotta, curiosa un po' all'interno, uccidi qualche troll, poi torna qui.\n\nPrendi la strada che esce da Kharanos verso nord; quando arrivi al ponte, segui il fiume ghiacciato verso ovest fino all'Iceflow Lake. Troverai Brewnall Village sulla riva occidentale. La Hold è a sud-ovest del villaggio.", "Non riesci a trovarla? Le mie indicazioni erano chiarissime! Non abbiamo molto tempo, devi sbrigarti! Non tornare finché non avrai trovato la grotta.", "Ah, {name}! Non pensavo che avresti avuto molte difficoltà a trovare il posto: le mie indicazioni sono eccellenti, sai...\n\nLascia solo che finisca il mio rapporto, allora.\n\n<Tira fuori un po' di carta e ci scarabocchia sopra per un momento.>\n\nEcco! Beh, ahah, questa sì che è divertente... Immagino, {name}, che non ti dispiacerebbe farmi un ultimo favore?", nil, 0x7d5b3c3e, 0x6aadc3c6, 0x81548c58, 0x832ea7a7, "m...." },
  [288] = { "La Third Fleet", "Offri a First Mate Fitzsimmons un Flagon of Mead.", "Un tempo ero primo ufficiale sulla Wave Mistress, nave di linea della Kul Tiras Third Fleet. La Doomed Fleet. Condannata, perché nel suo ultimo viaggio la flotta fu attaccata dai draghi rossi. Draghi comandati dagli orchi!\n\nNon avevamo speranze contro quel fuoco di drago... e la nostra flotta fu bruciata e affondata proprio al largo di questa costa. Sono l'unico sopravvissuto di quelle povere navi...\n\n...Oh, la testa mi martella e mi rimbomba! Mi serve un altro bicchiere se voglio venire a capo di questa sbornia e continuare il mio racconto.", "Oh, ho una sete tremenda! Non offriresti da bere a questo povero, patetico sciocco?", "Ah! Ci voleva proprio, e scioglie la lingua. Grazie, compare!", 0xd344ba5e, 0x9f386e77, 0x4f64105d, 0x0916d95e, 0x77f68422, "....." },
  [289] = { "L'equipaggio maledetto", "Uccidi 13 Cursed Sailors, 5 Cursed Marines e First Mate Snellig. Porta la Snellig's Snuffbox a First Mate Fitzsimmons, a Menethil Harbor.", "<Rinfrancato, Fitzsimmons riprende il racconto...>\n\nSono l'unico sopravvissuto della sventurata Third Fleet di Kul Tiras, naufragata al largo della costa a nord. Ma anche se sono l'unico membro della flotta ancora vivo, non sono l'unico ancora in giro! Perché su una delle nostre navi era nascosto un grande e terribile tesoro, e il suo potere sinistro tiene le anime dei miei fratelli intrappolate negli scafi marci delle navi.\n\nMa se riesci a liberare alcuni dei miei fratelli, forse potrai spezzare la loro maledizione.", "In sogno a volte sento i lamenti dei miei fratelli condannati! Ti prego, <buon/buona> <signore/signora>, liberali dalle catene e placa le loro grida.", "Grazie, {name}. E hai anche la gratitudine dei miei fratelli maledetti.", 0x0118d790, 0x450465a8, 0x35bb2a47, 0x9a98af9c, 0xaaba9d50, ".....", nil, nil, nil, 0xa3fe69e6, nil },
  [290] = { "Spezzare la maledizione", "Prendi la Intrepid Strongbox Key a Captain Halyndor.\n\nUsa la chiave per aprire l'Intrepid's Locked Strongbox.", "Per spezzare la maledizione e liberare tutti i miei fratelli, quella... cosa... stivata sulla mia nave va recuperata e purificata! Non so cosa fosse, ma so che era custodita al sicuro nel forziere della nave, su cui vegliava Captain Halyndor.\n\nIl mio vecchio capitano mi compare ancora in sogno. So che si aggira sulla mia nave condannata, l'Intrepid. Prendigli la chiave e usala per aprire il forziere dell'Intrepid.\n\nPoi, quando avrai quella cosa maledetta, portala al sacerdote Glorin Steelbrow, in paese.", "Questo forziere è chiuso a chiave saldamente.", "La chiave è arrugginita, ma entra perfettamente nella serratura.", 0x67d85feb, 0x99644b95, 0x74e1986b, 0x24ee971a, 0xfcdb2cc9, "....." },
  [291] = { "I rapporti", "Consegna il rapporto di Senir al Senator Barin Redstone, a Ironforge.", "Eccellente! Porta il mio rapporto al Senator Barin Redstone. È un tipo scorbutico, quindi non lasciarti abbattere dal suo carattere tutt'altro che solare. Si trova a Ironforge, nella sala in cui King Magni tiene udienza.\n\nNon conosci la strada per Ironforge? Prendi la strada che esce da Kharanos verso nord, attraversa il ponte, poi segui la strada verso est, fiancheggiata da grandi stendardi, su per il fianco della montagna.\n\nA proposito, potresti evitare di dire che mi hai aiutato? Non posso lasciar credere che qui fuori non lavori sodo, capisci?", "Mmm... pare che le mie guardie stiano diventando meno selettive con i postulanti. Beh, che cosa vuoi? Fa' in fretta.", "<Scorre rapidamente il rapporto.>\n\nPer autorità del re!? Magni ha perso del tutto il senno? E quel dannato Whitebeard... Ha preso in mano la situazione, eh? Al senato non farà piacere sentirlo, neanche un po'.\n\nCosa, sei ancora qui? Va', prima che chiami le guardie!", 0xdad7b810, 0xaeae0022, 0x237d8c9e, 0x1abc830a, 0xe6cf8786, "....." },
  [292] = { "L'Eye of Paleth", "Porta il Cursed Eye of Paleth a Glorin Steelbrow.", "Aprendo il forziere trovi una sfera annerita che pulsa di una luce sinistra. È il tesoro di cui parlava Fitzsimmons: un Cursed Eye of Paleth.\n\nPorta il Cursed Eye of Paleth al sacerdote nanico Glorin Steelbrow, a Menethil Harbor. Chiedigli come togliere la maledizione dall'Eye.", "Ti manda quell'ubriacone di Fitzsimmons? Be', puoi dirgli che non ho birra in più. Dovrà scroccare da qualcun altro!", "Un Eye of Paleth? Incredibile! Mmm... questo ha qualcosa che non va. L'hai trovato su uno di quei relitti? Be', questo spiega tutto! Ma... non sapevo che ci fosse un Eye del genere nella Third Fleet...\n\nNon c'è da stupirsi che Fitzsimmons fosse così spaventato. Un Cursed Eye of Paleth non è cosa da ridere.", 0xc0c774ae, 0x82ab47a4, 0x610cc5e1, 0xd79890d9, 0x4fe3c3df, "....." },
  [293] = { "Purificare l'Eye", "Porta ad Archbishop Benedictus il Cursed Eye of Paleth. Benedictus si trova nella Cathedral of Light, nella città di Stormwind.", "Non riesco a togliere la maledizione dall'Eye of Paleth. Gli Eyes furono creati da sacerdoti umani, quindi dovrai andare a Stormwind per trovare qualcuno che possa aiutarti. Parla con Archbishop Benedictus. È a capo della Cathedral of Light di Stormwind. Lui può aiutarti.\n\nLo spero, per il tuo bene.", "Cos'è quella sfera che hai? Sembra... contaminata.", "Un Eye of Paleth. Ma questo ha visto molto dolore... dev'essere stato testimone di una tragedia terribile, terribile.\n\nLascia che lo purifichi, perché gli Eyes sono stati creati per risplendere, e i loro poteri possono essere piuttosto pericolosi se contaminati come questo.", 0x2f74c1ea, 0xbdcdebd1, 0x6e4ad21f, 0xed3db153, 0x32563e90, "....." },
  [294] = { "La vendetta di Ormer", "Ormer Ironbraid, al Whelgar Excavation Site, vuole che tu uccida 10 Mottled Screechers e 10 Mottled Raptors.", "La situazione è grave, questo è certo. Quando abbiamo portato alla luce queste ossa, abbiamo attirato i raptor. Quelle bestie schifose hanno ucciso i miei fratelli e hanno intrappolato quassù me, Merrin e il povero Prospector.\n\nAiutaci a liberare le Wetlands da questi raptor, {name}. I Mottled Raptors e i Mottled Screechers sono appena a ovest della scogliera laggiù. Uccidine 10 di ciascuno, se puoi.\n\nSarà un buon inizio per la vendetta che ho in serbo per loro.", "Uccidi 10 Mottled Raptors e 10 Mottled Screechers, {name}. I miei compagni di lavoro non meritavano la sorte che è toccata loro. È ora di pareggiare i conti.", "Uccidere è un lavoro sporco, ma hai fatto bene il tuo, {name}. Se non fossi obbligato a restare con il Prospector e Merrin, sarei laggiù a versare sangue al tuo fianco.", 0x9f3d027d, 0x635d743b, 0x5fa2aa4a, 0x3737f909, 0x4931c25a, "....." },
  [295] = { "La vendetta di Ormer", "Ormer Ironbraid vuole che tu uccida 10 raptor Mottled Scytheclaw e 10 raptor Mottled Razormaw, poi torni da lui al Whelgar Excavation Site.", "Ora è il momento di far pentire davvero quei temibili raptor della loro sete di sangue. Proprio qui sotto ci sono decine di Mottled Scytheclaws e Mottled Razormaws. Fai pagare quelle creature marce uccidendone 10 di ciascuno!", "Voglio far pagare a quei Mottled Scytheclaws e Mottled Razormaws quello che hanno fatto. Ne hai già uccisi 10 di ciascuno?", "Hai fatto un lavoro coi fiocchi a ripulire la zona da quei raptor, {name}!", 0x9f3d027d, 0xcc43a4ca, 0xe2f5b517, 0xedd86ff7, 0x8ba1a22c, "....." },
  [296] = { "La vendetta di Ormer", "Ormer Ironbraid, al Whelgar Excavation Site, vuole che tu uccida Sarltooth e torni da lui con uno dei suoi artigli a compito eseguito.", "Mentre eri laggiù, ho notato che una di quelle bestie spiccava sulle altre. Era più grossa e più minacciosa. Scommetto che è lei ad aver guidato le altre qui a devastare il sito di scavo.\n\nTi chiedo un ultimo compito, {name}. Fai in modo che Sarltooth sia consegnato alla giustizia. E vista la gravità dei suoi crimini, in questo caso giustizia vuol dire morte! Portami uno dei suoi artigli come prova della sua morte.", "Sarltooth è morto? Hai riscattato la memoria dei caduti?", "Grazie, {name}. I tuoi sforzi qui non saranno dimenticati. Molti nani innocenti sono morti in questo sito, mentre facevano semplicemente il loro lavoro. La vendetta che hai portato a quelle creature malvagie dovrebbe farle pensare due volte prima di attaccare di nuovo i sudditi di King Magni.", 0x9f3d027d, 0x55a6e9a9, 0xb18d561a, 0xa3d83fdb, 0xdef3baa5, "....." },
  [297] = { "Raccogliere gli idoli", "Porta a Magmar Fellhew 8 Carved Stone Idols.", "Di recente, poco prima che i trogg sbucassero nel sito, avevamo portato alla luce un gran numero di strani idoli scolpiti. Ma non abbiamo avuto modo di studiarli, perché subito dopo la scoperta i trogg ci hanno cacciati dalle rovine! E quegli idoli hanno uno strano effetto sui trogg: li fanno impazzire!\n\nPortami 8 idoli: voglio studiarli, e li voglio fuori dalle mani dei trogg! Trovi gli idoli sui trogg che infestano il sito.", "Hai quegli idoli? Dobbiamo studiarli e riferire le nostre scoperte a Ironforge!", "Li hai presi! Ben fatto, {name}!\n\nE non sembri troppo <malconcio/malconcia>, nonostante quei trogg impazziti in giro. Ti terrò d'occhio... promette bene.", 0x34178260, 0x0eaf668c, 0xf3ba4390, 0x2fd4cc59, 0xd1d1aa18, "....." },
  [298] = { "Rapporto sui progressi dello scavo", "Porta l'Ironband's Progress Report a Jern Hornhelm, a Thelsamar.", "Mi serve che un rapporto sui progressi arrivi a Thelsamar: un rapporto, e una nuova richiesta di altra blastpowder! Ecco il rapporto. Portalo a Jern Hornhelm. È il nostro contatto a Thelsamar.\n\nNon è un compito difficile, ma va fatto.", "Oh, un rapporto sui progressi dal sito? Molto bene!", "Bah! Ironband ha problemi con i trogg. Mi chiedo se voglia quella blastpowder per scavare o per combattere quelle bestie...\n\nBe', in ogni caso è polvere ben spesa!\n\nMa la cosa strana è che gli ho mandato blastpowder in abbondanza settimane fa. Chissà dove è finita...", 0xc9016865, 0x22803ca7, 0x4dd4de52, 0xe37dea91, 0x509d05e4, "....." },
  [299] = { "Svelare il passato", "Prospector Whelgar vuole che tu perlustri il sito di scavo in cerca dei 4 frammenti di tavoletta mancanti: Ados, Modr, Golm e Neru.", "Poco prima dell'invasione avevo portato alla luce una grande tavoletta chiamata Goaz Stone. Il testo tradotto si interrompe in 4 punti. Il testo parla di un \"piano divino\" e di una \"profezia di sventura\".\n\nTemo che il tempo stia per scadere. Sono troppo vecchio per scendere ad affrontare quelle bestie. Ma tu sei forte.\n\nPerlustra il sito di scavo e porta alla luce i 4 frammenti di tavoletta mancanti: Ados, Modr, Golm e Neru. Cercali tra i manufatti antichi o dove la terra è smossa. Portameli, così potrò cominciare a svelare il mistero!", "Hai già portato alla luce i quattro frammenti, {name}? Ados, Modr, Golm e Neru...", "Ah, la Goaz Stone è completa! Ottimo lavoro, {name}. Davvero ottimo. Ora posso continuare la delicata traduzione di questa scrittura dei Titan. Riesco già a distinguere parole nuove! Mmm. . . qui dice: \"Old Gods. . . incatenati sotto la terra.\" È l'inizio di qualcosa di epico.", 0xd591b8f3, 0x9774ad41, 0xdce1b81f, 0x1bd68c28, 0x5c615bf5, "....." },
  [301] = { "Rapporto a Ironforge", "Porta l'Ironband's Progress Report a Prospector Stormpike.", "Ci servirà un'approvazione per dare a Ironband altra blastpowder. Dovrai portare il suo rapporto al quartier generale dell'Explorers' League, a Ironforge.\n\nEcco il rapporto. Consegnalo a Prospector Stormpike, e non dimenticare di abbassarti dopo averlo consegnato. Stormpike è una testa calda, e non sarà contento di sapere dei lenti progressi di Ironband allo scavo.\n\nTroverai Stormpike nell'Assembly of Explorers.", "A noi Stormpike non piace essere disturbati per sciocchezze, {class}. Spero che tu porti notizie degne della mia preziosa attenzione.", "Maledetto Ironband! Gli ho mandato un carico di blastpowder settimane fa, ma in questo rapporto non ne parla.\n\nAllora... dov'è finita la blastpowder?!?", 0x7f3b765a, 0x08c53212, 0xdc3ccebc, 0xd762c5af, 0x79fbe892, "....." },
  [303] = { "La guerra dei Dark Iron", "Motley Garmason, a Dun Modr, vuole che tu uccida 15 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs e 5 Dark Iron Demolitionists.", "La guerra infuria in patria e all'estero. Mentre i possenti soldati nanici danno la vita in territori lontani in nome dell'Alliance, le nostre stesse terre cadono preda delle azioni malvagie dei Dark Iron Dwarves. Hanno devastato il Thandol Span. Dun Modr è caduta subito dopo.\n\nCi serve che tu raduni le forze e respinga il fronte. Se riesci a uccidere 15 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs e 5 Demolitionists, la riserva potrebbe arrivare in tempo per completare l'offensiva.\n\nOra sbrigati!", "Roggo non è riuscito a mettersi in contatto con le forze di riserva. Ci serve una pressione offensiva su quell'accampamento dei Dark Iron, {class}. Ora torna là fuori e fai il tuo dovere verso King Magni!", "Hai eseguito bene i tuoi ordini, {class}. Hai dimostrato di essere un soldato valoroso e un servitore leale di King Magni, e per questo ti saluto! Con la pressione che hai esercitato sull'accampamento dei Dark Iron, ora abbiamo una possibilità di cacciarli dalle nostre terre per sempre. . . se solo quella maledetta riserva si facesse vedere. . . .", 0xb421cac2, 0xfb9fbc0f, 0x6d3dee8c, 0xbeddfaae, 0xf0eb01de, "....." },
  [304] = { "Un compito cupo", "Uccidi Balgaras the Foul e porta il suo orecchio a Longbraid the Grim, fuori da Dun Modr.", "Molti dei miei soldati sono morti nella battaglia di Dun Modr. Mio fratello è perito quando il West Bridge sul Thandol Span è stato distrutto. Sì, i nani Dark Iron sono una razza diabolica. Da quello che Roggo è riuscito a scoprire, il capo di questa banda di delinquenti nelle Wetlands è uno stregone di nome Balgaras the Foul. Ma è un gran codardo. Manda i suoi soldati a eseguire i suoi ordini mentre lui resta sfuggente, lontano dal pericolo.\n\nSe riesci a trovare quella feccia senza spina dorsale, uccidila e portami il suo orecchio. Ti ricompenserò, {class}.", "Sei <riuscito/riuscita> a trovare Balgaras the Foul, {class}? Ci sfugge da parecchio tempo.", "Balgaras the Foul è finalmente morto. La sua morte non riporterà in vita i tanti nani innocenti morti inutilmente per mano sua, ma aiuterà a restituire la pace a chi è sopravvissuto. Con Balgaras morto, la feccia dei Dark Iron rimasta dovrebbe essere abbastanza facile da gestire. Ora dobbiamo spazzarli via prima che mandino un nuovo capo da queste parti.\n\nHai fatto bene, {class}.", 0x0abbedc6, 0x9ddb772b, 0x57aeb2ff, 0xe02c98c7, 0x8ca97064, "....." },
  [305] = { "In cerca della squadra di scavo", "Tarrel Rockweaver vuole che tu vada all'Excavation Site e contatti Merrin Rockweaver.", "Non puoi immaginare quanto sia stato in pensiero.\n\nMia moglie, Merrin, mi ha mandato lettere ogni settimana per tutto l'ultimo mese. Fa parte della squadra del Whelgar Excavation. Ma sono quasi due settimane che non ricevo sue notizie. Di sicuro c'è qualcosa che non va!\n\nLongbraid ha detto che avrebbe mandato un esploratore a controllare se non avessimo avuto presto notizie della squadra. Immagino che quell'esploratore sia tu, {name}. Trova Merrin al sito di scavo, a est!", nil, "Oh, grazie al cielo sei qui!", 0x1719a646, 0x2d2e1e26, 0x39755cdf, nil, 0xe6062395, "...m." },
  [306] = { "In cerca della squadra di scavo", "Torna da Tarrel Rockweaver con il biglietto di Merrin.", "È stato orribile! Stavamo portando alla luce manufatti rari e abbiamo cominciato a scoprire queste grandi ossa.\n\nPrima che capissimo cosa stava succedendo, questi Mottled Raptors hanno travolto il sito di scavo. Abbiamo perso molte vite.\n\nOrmer, qui, così coraggioso, ha salvato il Prospector e me. Ci ha difesi mentre correvamo al riparo. Ora siamo intrappolati. E il nostro duro lavoro è in rovina.\n\nTieni, porta questo biglietto al mio dolce Tarrel. Gli spiegherà la situazione.", "Sei <riuscito/riuscita> a trovare Merrin? Ti ha dato un messaggio?", "Che notizie orribili! Almeno 3 di loro sono sopravvissuti. Ma quando finirà questa strage? Desidero il giorno in cui i sudditi di King Magni potranno vivere senza paura.", 0x1719a646, 0x8401118b, 0x88a97402, 0x78ff4985, 0x07626a00, "....." },
  [307] = { "Zampe sudicie", "Vai alla Silver Stream Mine e raccogli 4 carichi di Miners' Gear.\n\nTorna da Mountaineer Stormpike.", "La Silver Stream Mine, a est, si è esaurita da un pezzo. La Miners' League l'ha trasformata in un deposito, ma ora ci si sono trasferiti i kobold, che mettono le loro zampe sudicie su ottimi attrezzi nanici!\n\nStaneremo quei parassiti abbastanza presto, ma la League vuole che qualcuno porti fuori la sua attrezzatura dalla miniera prima che noi guerrieri ci entriamo a rompere tutto. Sarà una discesa dura: forse ti conviene avere dei compagni al fianco.\n\nL'attrezzatura è riposta nelle Miners' League Crates sparse per la miniera. Buona fortuna.", "Hai quella Miners' Gear, {name}?", "Hai visto molti kobold là dentro? Non vedo l'ora che arrivi l'ordine di cacciarli dalla miniera. Al pensiero delle loro mani luride che frugano nella nostra miniera mi si rivolta lo stomaco!", 0xe6dfbab1, 0x6239462b, 0x8b70f766, 0x83e3d7a0, 0x6be768cd, "....." },
  [308] = { "Distrarre Jarven", nil, nil, "Uff! Qui sotto c'è tutto questo alcol, ma ho ordini severi di non toccarlo. Se solo potessi assaggiare un po' della nostra Thunder Ale... mi schiarirebbe le idee, non mento!", "Per me? Sei <un/una> <vero/vera> <eroe/eroina>, {name}!", 0xef7d7727, nil, nil, 0xd7c692ec, 0xe0ee940d, ".mm.." },
  [309] = { "Proteggere il carico", "Assicurati che Miran e il carico arrivino al sito dello scavo, poi avvisa Prospector Ironband.", "<Pronto/Pronta> a partire, {name}?\n\nPrima di tutto dobbiamo portare questa polvere a Ironband. Sarà parecchio da portare per me, e queste zone possono diventare pericolose... e chissà cos'altro i Dark Iron potrebbero avere in serbo per me.\n\nMi sentirò molto meglio se vieni con me.", "Dov'è la mia polvere, {name}? Ogni giorno che passa ne ho più disperatamente bisogno.", "Oh, grazie alla Luce la polvere è qui. Ma porti anche notizie preoccupanti. Pensare che i Dark Iron abbiano simpatizzanti capaci di procurare questo genere di materiale per i loro piani infami.\n\nÈ una questione che dovrà considerare qualcun altro, un'altra volta. Devo mettere a buon uso questa polvere.", 0x086b0483, 0xbcb09af3, 0xaf7d4d4e, 0xcad7bca5, 0x0c439c60, "....." },
  [310] = { "Rivali acerrimi", "Nel seminterrato della Thunderbrew Distillery di Kharanos, sostituisci un barile di Thunder Ale con un Barrel of Barleybrew Scalder.", "Devo ammetterlo, quei Thunderbrew fanno delle buone bevande. Ma devono imparare che la loro non è l'unica birra decente! Forse puoi aiutarmi a dar loro questa lezione...\n\nEcco, prendi questo barile di Barleybrew Scalder. Intrufolati nel seminterrato della Thunderbrew Distillery di Kharanos e scambialo con uno dei loro barili di Thunder Ale. Poi vedremo se i loro clienti preferiranno la mia birra alla loro!\n\nE se i barili sono sorvegliati, potresti dover distrarre la guardia...", "La data su questo barile indica che presto verrà spillato.", "Metti rapidamente il barile di Barleybrew Scalder di Marleth tra i barili dei Thunderbrew.", 0xf6727a81, 0x0eee3138, 0x4aba5129, 0x1e29e7f1, 0x61e614ef, "....." },
  [311] = { "Ritorno da Marleth", "Porta il barile di Thunder Ale a Marleth Barleybrew, a Brewnall Village.", "Dopo aver messo un barile di Marleth's Scalder nella cantina della Kharanos Distillery, afferri un barile di Thunder Ale come prova dell'impresa...", "Hai fatto lo scambio?", "Niente male, {name}! Hai avuto difficoltà a superare la loro guardia?\n\nNon importa: mille grazie, e se mai ti servisse una stout che dà la carica, non dimenticare i Barleybrew!", 0x3a28c9e8, 0xf80b297f, 0x6e9701ee, 0x31a1b899, 0x1b072cf7, "....." },
  [312] = { "La scorta rubata di Tundra MacGrann", "Recupera la carne essiccata di Tundra MacGrann dalla dispensa rubata nella grotta di Old Icebeard.", "Avevo un mese di carne essiccata salata e messa sotto chiave per la stagione fredda. La tenevo chiusa perché gli orsi non la prendessero! Ma mentre ero a caccia di cervi, quella bestia, Old Icebeard, si è portato via la dispensa. Non riuscirà a sfondare quel Thorium, però. Ma io morirò di fame se non riavrò la mia carne.\n\nSembri un po' più <furtivo/furtiva> di me. Forse puoi recuperare la mia scorta? Con questa gamba malandata non riuscirei mai a entrare e uscire da quella grotta abbastanza in fretta.", "Sei <riuscito/riuscita> a entrare nella mia dispensa, {name}?", "Che anima gentile sei, {name}! Grazie al tuo coraggio non morirò di fame quando arriveranno le bufere della stagione fredda.", 0x992959f9, 0x5b0707e1, 0xa3f43510, 0x754c3b09, 0xd5b6ac1e, "....." },
  [313] = { "La tana del grizzly", "Raccogli 8 Wendigo Manes e portale al Pilot Stonegear.", "Guidare un Siege Engine non è per tutti. Ci vogliono una presa di ferro e nervi d'acciaio... per fortuna ho entrambi! E tu? Che tempra hai? Vuoi dimostrarmelo?\n\nBeh... vorrei rendere il mio mezzo, Trollplow, un po' più accogliente. Che ne dici di procurarmi un mucchio di Wendigo Manes dalla Grizzled Den, a ovest di Kharanos? Quelle criniere sarebbero un ottimo tappeto per il ponte interno di Trollplow!", "Ehi, {name}. Sei già <stato/stata> alla Grizzled Den? Quei wendigo sanno essere feroci.", "Ah sì, queste criniere andranno benissimo! Hai molto fegato, {class}: scommetto che vedremo grandi cose da te.", 0x9d1372af, 0xa90aa758, 0xac88ca21, 0xb2b8b4b1, 0x6f400b46, "....." },
  [314] = { "Proteggere la mandria", "Rudra Amberstill vuole che tu uccida Vagash e le porti la sua zanna al ranch degli arieti.", "Abbiamo sentito le grida nel cuore della notte. Poi stamattina, com'era prevedibile, alla mandria mancavano due arieti. Quella bestia infame nota come Vagash fa strage del nostro sostentamento. Con gran parte dell'esercito di King Magni in terre lontane a combattere con l'Alliance, non c'è nessuno a tenere lontano Vagash.\n\nForse sei abbastanza <coraggioso/coraggiosa> da cercare la bestia e ucciderla. Portami una delle sue zanne e ti ricompenserò. Vagash si aggira appena sopra il ranch, ma <attento/attenta>: è letale.", "Vagash terrorizza ancora la mandria! Ti prego, aiutaci uccidendo quella bestia infame.", "Davvero ben fatto! Veron sarà felicissimo di sentire la buona notizia. Uccidere Vagash non è impresa da poco. Immagino che un giorno combatterai al fianco degli uomini di King Magni sull'Alliance Front.", 0xefa031f4, 0x2475a572, 0x9f0339dd, 0xf712a472, 0x3bc82f3e, "....." },
  [315] = { "La stout perfetta", "Porta 6 Shimmerweed a Rejold Barleybrew, a Brewnall Village.", "Sono in missione, la missione di creare la stout perfetta. So di potercela fare: la birra ce l'ho nel sangue. Devo solo trovare la ricetta giusta...\n\nI troll Frostmane coltivano una pianta, la shimmerweed, in alto sulle colline a est. La usano nei loro strani rituali tribali. Noi nani non ne abbiamo trovato molti usi, ma ha un sapore unico... e voglio sperimentarla nelle mie birre!\n\nProcurami un po' di shimmerweed dai veggenti Frostmane, oppure sottraila dai cesti di shimmerweed dei troll.", "Hai quella shimmerweed? Ho quasi pronta una partita di stout da fermentare e voglio provare ad aggiungere l'erba a questa miscela.", "Ottimo! Non vedo l'ora di usarle in qualcuna delle mie ricette. Ce n'è una in particolare in cui credo che funzioneranno benissimo...", 0xadc5e20f, 0xfc736db3, 0x4c0b4974, 0xc1da3265, 0x068f94a8, "....." },
  [317] = { "Rifornimenti per Jetsteam", "Raccogli 4 Chunks of Boar Meat e 2 Thick Bear Furs e consegnali al Pilot Bellowfiz, allo Steelgrill's Depot.", "Mi preparo a partire per una missione per la Siege Brigade. È lunga, e devo rifornire Jetsteam di provviste per un mese. Quindi, mentre Steelgrill lavora al mio carro, puoi andare a caccia per me?\n\nMi serviranno pellicce per il giaciglio e carne di cinghiale come cibo. Puoi prendere la carne dai cinghiali e la pelliccia dagli orsi... li trovi entrambi nelle distese innevate a sud della Grizzled Den.", "I preparativi procedono bene. Come va la tua caccia?", "Per la barba di Magni, ne hai fatta di caccia!! Grazie, {name}.", 0x9298abb1, 0x763455c2, 0x6304c52d, 0xf79f8e14, 0xf15f9d6d, "....." },
  [318] = { nil, "Prendi un barilotto di Evershine da Rejold Barleybrew, a Brewnall Village.", "Rejold Barleybrew fa esperimenti con le sue birre. Alcune sono buone, altre cattive, e alcune... beh, alcune stenderebbero chiunque tranne il nano più robusto.\n\nVive a Brewnall Village, a ovest di Kharanos, e una delle sue bevande, l'Evershine, è quella che voglio. Mi aiuterà a stare al caldo sulla strada gelida.\n\nE... quella roba benedetta brucia così forte che posso buttarla nella fornace di Jetsteam per una scarica di potenza! Quel trucchetto mi ha tirato fuori da più di una situazione difficile.", nil, "A Bellowfiz serve un po' del mio Evershine? Mm... va bene.", nil, 0xcb9ca884, 0x9b9623a7, nil, 0x0bdd12f0, "m..m." },
  [319] = { "Un favore per l'Evershine", "Uccidi 6 Ice Claw Bear, 8 Elder Crag Boar e 8 Snow Leopard, poi torna da Rejold Barleybrew, a Brewnall Village.", "Ho un barilotto di Evershine a portata di mano, ma... puoi farmi un favore? A Brewnall Village servirebbe una mano contro gli animali selvatici che vagano per le nevi qui intorno. A volte si avvicinano troppo.\n\nNon abbiamo paura di questi orsi, felini e cinghiali (nessun nano che si rispetti ne avrebbe), ma se puoi occuparti di quegli animali per noi, avremmo più tempo per il nostro lavoro e le nostre birre.", "Ti sei <occupato/occupata> di quegli animali selvatici?", "Grazie, {name}. Sarà bello dedicarci al nostro lavoro senza sentire tanti ringhi e grugniti fuori dal villaggio.", 0x46ebb913, 0xe3630b84, 0xe551b5b9, 0x8630896b, 0x1e4bad26, "....." },
  [320] = { "Ritorno da Bellowfiz", "Dai il barilotto di Evershine al Pilot Bellowfiz, allo Steelgrill's Depot.", "Ecco il tuo barilotto di Evershine, {name}. E grazie ancora per la caccia di prima.", "Hai preso quell'Evershine?", "Sì, questo andrà benissimo. Credo che aprirò subito una bottiglia per assaggiarlo...", 0xb3dbad35, 0x289b7cd5, 0x0fbc74dc, 0x8ef21aef, 0xf157f980, "....." },
  [321] = { nil, "Fruga nel relitto della Flying Osprey, nelle Wetlands.", "I relitti al largo di questa costa sono la sventurata Third Fleet di Kul'Tiras, bruciata e affondata dai draghi rossi durante l'ultima grande guerra.\n\nLa flotta veniva da Lordaeron, ma con lei c'era una nave, un cacciatorpediniere elfico: la Flying Osprey. Trasportava un carico di Lightforge Iron e si era unita alla Third Fleet per avere protezione. Ironia della sorte, è affondata per mano degli stessi draghi...\n\nBasta con la storia. Il relitto della Flying Osprey è a sud di Menethil Harbor. Se lì trovi il Lightforge Iron, portamelo.", nil, "Questo forziere è fradicio, con le pareti rotte. Molti segni di artigli lo rovinano dentro e fuori... come se i murloc ci avessero frugato dentro e ne avessero rubato il tesoro.\n\nMa infilato in fondo al forziere c'è un solo Lightforge Ingot. Purtroppo ne serviranno molti di più per avere abbastanza metallo da forgiare un'arma.", nil, 0x90913df9, 0x4f73f4fe, nil, 0x43d7effb, "m..m." },
  [322] = { "Un'arma benedetta", "Porta la Crate of Lightforge Ingots a Grimand Elmore, a Stormwind.", "C'è un fabbro d'armi nanico, nel Dwarven District di Stormwind, che sa lavorare il lightforge iron. Si chiama Grimand Elmore.\n\nHo messo in una cassa il ferro che hai trovato. Portala a Grimand e raccontagli la tua storia. Sono sicuro che vorrà aiutare qualcuno impegnato in un'impresa come la tua, e ti forgerà un'arma: un'arma che preoccuperebbe persino Morbent Fel!", "Come posso mettere la mia arte al tuo servizio, {class}?", "Hai proprio una bella storia. E lightforge iron! Sono anni che non lavoro un metallo simile. Sarà un onore lavorarlo di nuovo. E dovrai tornare da me più tardi a raccontarmi della tua battaglia contro il negromante.\n\nMa andiamo troppo in fretta. Prima, la tua arma contro Morbent Fel...", 0xc00e26ec, 0xfe21b562, 0x8155f944, 0xbc274cdc, 0xcdab21ec, "....." },
  [323] = { "Dimostrare il proprio valore", "Uccidi 15 Skeletal Raiders, 3 Skeletal Healers e 3 Skeletal Warders, poi torna da Sven.", "Morbent Fel è un negromante, alleato dei dark riders. Ti metterei contro il potere di Morbent Fel, ma non ti manderò contro quell'immondo demonio senza conoscere prima la tua forza.\n\nMi hai già dimostrato il tuo coraggio, ma se vuoi davvero affrontare il negromante, ora devi dimostrare la tua abilità contro i suoi servitori.", "Combatti con forza, {name}. E non disperare, perché la disperazione è l'arma più grande del male.", "La tua abilità in combattimento, {name}, non si può mettere in dubbio. La tua determinazione potrebbe ancora portarci fino alla fine di Morbent Fel!", 0x2b69e0a3, 0xe93db108, 0xa4fe1361, 0x3028a831, 0x850f6fbf, "....." },
  [324] = { "I lingotti perduti", "Raccogli 5 Lightforge Ingots, poi torna da Glorin Steelbrow, nelle Wetlands.", "Preso l'unico Lightforge Ingot dal forziere fradicio, è chiaro che il resto l'hanno rubato i murloc. Dai la caccia ai murloc raider vicino al relitto della Flying Osprey per recuperare il lightforge iron perduto.", "Hai trovato il lightforge iron che ti serve?", "Ah, li hai trovati! Ora battiamo questo lightforge iron e facciamone qualcosa di utile, eh?", 0xbad55a3a, 0x3e3da78f, 0x3c29b98a, 0x0a6e75bf, 0x67c1cb55, "....." },
  [325] = { "Armato e pronto", "Porta il Morbent's Bane a Sven, a Duskwood.", "Ecco l'arma contro il demonio di cui parlavi. Sei <pronto/pronta>, {name}. Buona fortuna, e non vedo l'ora di sentire il racconto della tua gloria!", "Salve, {name}. Non sei <stato/stata> via così a lungo, ma vedo nei tuoi occhi un fuoco che prima non c'era.", "Ah, questo sarà la difesa contro il demonio Morbent Fel! Ben fatto!\n\nSei <pronto/pronta>. Morbent Fel cadrà.", 0x87f2ec41, 0xcc976788, 0xd24c2a78, 0xc11cc698, 0xad511684, "....." },
  [332] = { "Pubblicità dell'enoteca", "Va' alla Gallina Winery e porta a Suzetta Gallina il Wine Ticket per una bottiglia di vino gratis.", "Se parli di vino con chiunque, sai che noi Gallina vendiamo il miglior vino di Stormwind. E non siamo lontani: siamo sempre nel Trade District, lungo i graziosi canali della città.\n\nEcco, prendi questo volantino. Portalo a mia sorella Suzetta, nel nostro negozio, per una bottiglia omaggio del nostro famoso pinot nero. Non te ne pentirai!", "Salute e <benvenuto/benvenuta>, <signore/signora>. Hai già provato uno dei nostri ottimi vini?", "Ah, quindi hai visto Renato? Bene, ecco a te, <signore/signora>. Una bottiglia del nostro speciale pinot nero. Non ne troverai uno uguale in tutta Azeroth!", 0xbef51e47, 0xa087845e, 0x1a55a490, 0x057eda77, 0xb3727db1, ".....", nil, nil, nil, 0x894606fa, 0xbccda04d },
  [333] = { "Harlan ha bisogno di rifornimenti", "Va' al Canal Tailor Shop e porta a Rema Schneider la Cloth Request di Harlan Bagley.", "Ultimamente facciamo molti affari. Sembra che tutti comprino armature e vestiti robusti. Quasi come se si aspettassero una stagione fredda e dura...\n\nMa queste sono preoccupazioni future. La mia preoccupazione di oggi è che sto finendo gli abiti di maglia da vendere. Mi serve un altro carico dal nostro fornitore.\n\nSe puoi portare questa richiesta a Rema Schneider, al Canal Tailor and Fit Shop, te ne sarei molto grato.", "Porti notizie dal signor Bagley?", "Qui dice che gli affari di Harlan vanno a gonfie vele. È una buona notizia, ma mi chiedo perché la gente abbia bisogno di tutta quell'armatura. Non ho sentito parlare di guerra aperta... c'è qualcosa che i nobili non ci dicono?\n\nBeh, grazie per avermi portato la richiesta. Ecco il tuo pagamento, e farò in modo che Harlan riceva i suoi rifornimenti.", 0xb45daef4, 0xe2e2a078, 0x90d86eed, 0xacbdeec7, 0x6c92f110, "....." },
  [334] = { "Un pacco per Thurman", "Va' alla Larson Clothiers, nel Mage Quarter di Stormwind, e dai a Thurman Schneider il suo Sewing Kit.", "Mio figlio Thurman è apprendista alla Larson Clothiers, nel Mage's Quarter. Oggi andava di fretta e ha dimenticato forbici e aghi. So che qualcuno di valore come te, {class}, deve avere compiti importanti da svolgere, ma senza i suoi attrezzi Thurman non può fare il suo lavoro di apprendista!\n\nTi prego, {name}. Puoi portare a mio figlio il suo kit da cucito? La Larson Clothiers è una delle due sartorie del Mage's Quarter: è quella più all'interno, vicino alla Mage's Tower.", "Sei qui per comprare vestiti?", "Oh, accidenti! Pensavo che dimenticare il kit mi avrebbe liberato dal lavoro. Ora immagino che dovrò aiutare i Larson con il cucito...\n\nOh, beh. Il divertimento arriverà dopo, immagino.", 0x2f63edc3, 0x271cf18d, 0xdd0e9c55, 0x50590106, 0x82df6d32, "....." },
  [335] = { "Una birra nobile", "Zardeth the Black Claw vuole che tu gli porti una Tear of Tilloa da Darkshire e una Musquash Root dalle Wetlands.", "Lord Wishock sta creando un bel trambusto nella House of Nobles. È venuto a sapere del nostro piccolo \"locale\" quaggiù e fa pressioni per un'indagine completa. Ho un piano per tenere Wishock \"occupato\", ma mi servirà il tuo aiuto.\n\nNel Garden of Stalvan, alla periferia di Darkshire, cresce un fiore. Questo piccolo fiore bianco è noto come Tear of Tilloa. Mi servirà anche una Musquash Root, che si trova solo ai piedi delle cascate, molto sotto lo Stonewrought Dam nelle Wetlands.", "Wishock otterrà presto abbastanza appoggi da causarci molti guai. Sei <riuscito/riuscita> a procurarti la Tear of Tilloa o la Musquash Root?", "Eccellente! Sono davvero ottimi campioni!", 0xb74eb85e, 0x62942fae, 0xe7ffff8f, 0xcd7a22de, 0x7e0ff13b, "....." },
  [336] = { "Una birra nobile", "Porta la Black Claw Stout a Lord Wishock, nella Hall of Petitioners.", "Lord Wishock, come tutti gli uomini, ha le sue debolezze. La sua è la passione per i liquori. L'ipocrisia è sbalorditiva. Quello sciocco banale passa le giornate a cercare di far chiudere la nostra piccola \"taverna\", mentre passa le notti al piano di sopra, accumulando un conto che non paga mai. Beh, vediamo come piacerà a Wishock questa birra speciale che ho preparato per lui: la Black Claw stout. Ha un bel carattere, {name}.\n\nPortagliela e vedi se gli piace. Molto probabilmente quel vecchio sciocco gironzola per la Hall of Petitioners.", "Non vedi che sono occupato? Le mie parole devono essere ascoltate! Sono molto importante per il futuro di questo regno!\n\nOh... cos'hai lì? Ma sembra una bevanda rinfrescante...", "Ah, grazie per avermi portato questa stout dall'aspetto pregiato, <servitore/serva>. Ecco una moneta di rame per te. Ora sparisci e lasciami godere la mia bevanda!", 0xb74eb85e, 0x53f90ba6, 0xda7b4013, 0x1b629e3f, 0x43acc741, "....." },
  [337] = { nil, "Restituisci il libro The History of Stormwind alla Stormwind Library.", "Anche se la copertina di questo libro è rovinata da graffi e incrostata di fango, sul dorso si leggono ancora le parole \"The History of Stormwind\". Aprendo il libro, sulla prima pagina è chiaramente impresso il sigillo della Stormwind Library.\n\nSembra che qualcuno abbia preso in prestito questo libro e non l'abbia mai restituito...", "Oh! Cos'è quel vecchio libro che hai lì? Posso vederlo??", "Oh, cielo! Questo libro non stava su questi scaffali da prima della ricostruzione di Stormwind, anni fa. Andrà restaurato, naturalmente, è in cattive condizioni, ma sarei onorato di inserirlo nella nostra collezione di libri rari.\n\nGrazie, <signore/signora>. Accetta questo come compenso per aver restituito il libro!", nil, 0x1883e731, 0x53cae2d4, 0xf9cb11cb, 0x48ec99b2, "m....", nil, nil, nil, nil, 0x26f2965a },
  [343] = { "Parlando di forza d'animo", "Va' alla Royal Library nello Stormwind Keep e parla con Milton Sheaf. Può trovarti il libro di metallurgia che serve al Brother Kristoff per il suo discorso.", "Terrò un discorso sulla forza d'animo dello spirito e vorrei citare passi di un particolare libro di metallurgia, \"The Stresses of Iron\". Una copia di questo libro dovrebbe trovarsi nella Royal Library, nello Stormwind Keep. Puoi recuperarla per me? Se sì, che le benedizioni della Luce siano con te!\n\nLa Royal Library è molto grande, ma il bibliotecario capo, Milton Sheaf, conosce ogni scaffale come fosse suo figlio. Parla con lui, ti recupererà il libro.", nil, "Metallurgia? Ah sì, abbiamo molti libri sull'argomento e siamo felici di aiutare il Brother Kristoff con il suo discorso! Allora... quale libro in particolare serviva al buon fratello?", 0x2aad28e2, 0x5b41f90b, 0xdb30b559, nil, 0xcfbcf25b, "...m." },
  [344] = { nil, "Parla con il Brother Paxton, alla Northshire Abbey.", "The Stresses of Iron? Sì, conosco il libro. Un'ottima opera, scritta dal minatore nanico Margulf Blaggon qualche decennio fa. Passò la maggior parte del tempo nel profondo delle montagne di Khaz Modan, a scavare minerali. Un tipo intelligente!\n\nMa dov'ero rimasto? Ah sì, The Stresses of Iron! Temo che il libro sia stato portato alla Northshire Abbey. Il custode della biblioteca dell'abbazia, il Brother Paxton, voleva farne una copia per i suoi scaffali.\n\nMa è stato mesi fa. Mi chiedo perché ci stia mettendo così tanto...", nil, "Il signor Sheaf si chiede dove sia il suo libro? Beh, è un tantino imbarazzante. Ho il libro, ma sto ancora facendo la mia copia e non sono del tutto pronto a restituire l'originale!", nil, 0xed902b3e, 0x5c81c1f5, nil, 0x65a09975, "m..m." },
  [345] = { "Scorte d'inchiostro", "Parla con Foreman Oslow a Lakeshire e chiedigli del Rethban Iron Ore.", "Volevo finire la mia copia di The Stresses of Iron, ma...\n\nVedi, faccio da me l'inchiostro per i libri che copio. È una mia ricetta: non cola, non sbava e asciuga in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi di copiare, e non ho avuto occasione di farne dell'altro!\n\nPer farne altro mi serve del Rethban Iron Ore dalle Redridge Mountains. Di solito me lo fornisce Foreman Oslow, a Lakeshire.", nil, "Ti serve cosa?? Forse non te ne sei <accorto/accorta>, ma siamo impegnati a rafforzare le difese di Lakeshire e a riparare i danni dei recenti attacchi degli orchi. Se ti serve del Rethban Iron Ore, dovrai procurartelo da <solo/sola>!", 0x6436fa89, 0x9f82018f, 0xf8e115c5, nil, 0x6eaa5bf6, "...m." },
  [346] = { "Ritorno da Kristoff", "Torna da Brother Kristoff nella Cathedral Square e consegnagli il libro The Stresses of Iron.", "Ora che ho finito di copiare il libro, ecco l'originale di Stresses of Iron. Grazie per la pazienza, e se vedi Milton, digli che mi dispiace per il lungo ritardo.", "Sei <riuscito/riuscita> a trovare il libro?", "È proprio quello! Grazie, {name}. Che la Luce risplenda sul tuo corpo e sul tuo spirito!", 0x7914bcc7, 0xaffc7d2d, 0xa9d0a831, 0xf44efc87, 0xcfcb4f09, "....." },
  [347] = { nil, "Raccogli 5 carichi di Rethban Ore e portali a Brother Paxton, nella Northshire Library.", "La Rethban Ore prende il nome dall'uomo che la trovò per primo, Bart Rethban. Una volta fusa non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che alcuni scribi usano per le loro tinture. Si trova nelle Rethban Caverns, a nord di qui.\n\nDi solito ne abbiamo un po' in magazzino, ma siamo troppo presi a prepararci agli attacchi degli orchi per raccoglierne. E poi... ora nelle Rethban Caverns vivono i Redridge Gnolls, e i loro Drudgers il minerale se lo raccolgono da soli.\n\nQuindi, se te ne serve, dovrai procurartelo da <solo/sola>.", "Hai la Rethban Ore?", "Oh, splendido! Posso usare questo minerale per la mia tintura, e poi finire di copiare The Stresses of Iron.\n\nGrazie, {name}!", nil, 0x66b7c48d, 0xcc491e42, 0xd2e294d7, 0x1dd5b437, "m...." },
  [350] = { "Rivolgersi a un vecchio amico", "Parla con Elling Trias, a Stormwind.", "Che Marzon contattasse un membro dei Defias e avesse legami con Lescovar...\n\nAvendo ucciso VanCleef e Thredd, sarà difficile vedere Lescovar consegnato alla giustizia, perché le tue prove non valgono nulla senza le loro testimonianze. E questo senza considerare che Lescovar è un nobile con molte conoscenze. Di fatto è al di sopra della legge.\n\nTi servirà altro aiuto. Detesto farlo, ma conosco qualcuno che ci aiuterà. Troverai Trias nel Trade District della città.", nil, "Stai scherzando? Shaw vuole di nuovo il mio aiuto? Che faccia tosta...\n\nLa Defias Brotherhood, dici? Beh, sei proprio <portatore/portatrice> di splendide notizie, eh? La prossima cosa che mi dirai è che Deathwing è ancora vivo e sta attaccando la città.\n\nVa bene, raccontami tutto dall'inizio. E non tralasciare nulla, anche se pensi che non sia importante. Devo sapere tutto.", 0x0a6b7a91, 0x3f1c2d43, 0x75a8e91d, nil, 0x89bbcf8d, "...m." },
  [353] = { "La consegna di Stormpike", "Consegna il Package for Stormpike al Mountaineer Stormpike, a Loch Modan.", "Gli Stormpike sono un clan nanico rispettato, noto per i suoi gusti raffinati ed esigenti. Non c'è quindi da stupirsi che Gringer Stormpike, un Mountaineer di Ironforge, mi abbia commissionato un'arma.\n\nL'arma è pronta, ma... il Mountaineer Stormpike è lontano, nella remota Loch Modan. Se hai in programma di viaggiare a nord, puoi consegnargli questo pacco?\n\nNel suo ultimo messaggio il Mountaineer Stormpike diceva di essere di stanza alla torre di guardia settentrionale di Loch Modan.", "Vieni fin da Stormwind? Ho sentito che laggiù, nelle terre degli umani, la situazione si fa rischiosa, con briganti e orchi in giro. Il posto perfetto per dimostrare il proprio valore, {class}!", "Aha! Quindi Grimand ha finalmente finito la mia ascia! Non vedo l'ora di provarla contro qualche trogg e qualche kobold!\n\nMille grazie, {name}. Era un lungo viaggio per questa consegna. Ecco qualche moneta per i tuoi sforzi.", 0x8e577b92, 0xd5f60077, 0xab2b7ebb, 0xae7f0689, 0x2aedd325, "....." },
  [361] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [373] = { "La lettera mai spedita", "Consegna la Letter to the City Architect a Baros Alexston, a Stormwind.", "Perquisendo Edwin VanCleef scopri, tra le altre cose, una lettera mai spedita. È indirizzata a Baros Alexston, City Architect di Stormwind, City Hall, Cathedral Square.\n\nSembra scritta e sigillata di recente.", "Sì? Posso aiutarti in qualcosa?", "Edwin VanCleef, dici? Mi aspetterei piuttosto una lettera dalla mia nonna morta... Quindi l'hai ucciso? Scusa se te lo dico, ma sono piuttosto sorpreso. In gioventù era un combattente senza pari. Vediamo cosa sente il bisogno di scrivermi dopo tanti anni.\n\n<Baros scorre la lettera.>\n\nEdwin... vedo che gli anni non ti hanno cambiato affatto, idealista come sempre, e romantico. Non gli importa chi ferisce, {name}. La vendetta lo ha consumato. Ma d'altronde non sono sicuro di potergliene fare una colpa.", 0xaf33b2fe, 0xb7077b54, 0x4d9722a9, 0x5bf43657, 0x5b678cae, "....." },
  [377] = { "Delitto e castigo", "Councilman Millstipe di Darkshire vuole che tu gli porti la mano di Dextren Ward.", "Come se l'abbandono degli abitanti di Duskwood non bastasse, ora la House of Nobles sputa in faccia al Darkshire Council con la decisione di imprigionare Dextren Ward a Stormwind invece di decapitare il furfante come da sentenza di Lord Ebonlocke.\n\nWard è stato sorpreso a vendere a Morbent Fel i corpi del cimitero, un crimine punibile con la morte. Eppure Stormwind reclama Ward come suo prigioniero.\n\nAssassina Ward nella Stormwind Stockade, portami la sua mano, e ti ricompenserò.", "Finché un profanatore di morti come Dextren Ward viene lasciato in vita, la giustizia è tradita. Torna da me quando la sentenza di morte di Lord Ebonlocke sarà eseguita su quel profanatore, Ward. Daremo alle famiglie dei morti la pace che meritano e, meglio ancora, manderemo un messaggio chiaro alla House of Nobles di Stormwind.", "Così Dextren Ward ha finalmente pagato per i suoi crimini contro l'umanità? Bella liberazione da quella feccia, dico io. E alla tua salute, amico mio! Non solo hai dato alle famiglie dei morti la pace che meritano, ma hai mandato un messaggio eloquente a quei burocrati corrotti della House of Nobles. Stormwind deve rispondere ai bisogni della gente di Duskwood, o ci libereremo della sua tirannia.", 0xd8baf022, 0x6846295b, 0x8a0de614, 0xc306418b, 0x3d4fa9be, "....." },
  [378] = { "Una furia profonda", "Motley Garmason vuole che gli porti la testa di Kam Deepfury, a Dun Modr.", "Hai dimostrato la tua lealtà a King Magni, {class}. E il tuo odio per quella feccia dei Dark Iron è grande quanto il mio.\n\nC'è un compito che vorrei portare a termine io stesso, ma l'onore mi obbliga a restare con Longbraid. Roggo però ha raccolto informazioni che provano che Kam Deepfury ha partecipato al complotto dell'attacco al Thandol Span. È per un piano di Deepfury che Longbraid ha perso la sua famiglia.\n\nDeepfury è trattenuto per ragioni politiche nella Stormwind Stockade. Lo voglio morto, {name}. Per Longbraid! Portami la sua testa!", "Non lascerò che la stupida burocrazia umana interferisca con le faccende naniche, {name}. Kam Deepfury ha di sicuro partecipato al complotto dell'attacco al Thandol Span. La brava gente di King Magni ha perso la vita per l'inganno di Deepfury. Gli umani si accontenteranno di lasciar marcire Deepfury nella Stockade, ma io non dormirò sonni tranquilli finché Deepfury non sarà morto.", "Così Kam Deepfury ha finalmente provato cosa vuol dire trovarsi faccia a faccia con la morte? Bene. Se l'è meritato, quel codardo della feccia Dark Iron. Hai fatto bene, {class}. Le vittime dell'attacco al Thandol Span erano solo vittime in un mondo lacerato dalla guerra e dai disordini. Le loro famiglie avranno la pace di sapere che Deepfury ha avuto la punizione che meritava. La morte del fratello di Longbraid è stata vendicata.", 0x1158c5af, 0x54c0df47, 0xcec43aea, 0xfee1b4d9, 0x53eb2770, "....." },
  [384] = { nil, "Ragnar Thunderbrew, a Kharanos, vuole 6 Crag Boar Ribs e un boccale di Rhapsody Malt.", "Niente piace di più ai clienti della mia taverna delle Beer Basted Boar Ribs! L'unico problema è che il cacciatore di pellicce della zona che mi portava le provviste si è arruolato nell'esercito del re per aiutare nella guerra sul fronte dell'Alliance.\n\nForse puoi aiutarmi tu? Se mi porti sei costine di crag boar e una Rhapsody Malt dalla taverna qui, ti darò la ricetta di famiglia delle mie famose Beer Basted Boar Ribs, per non parlare di un assaggio gratis! Il segreto è nella Malt!", "Mi serviranno sei costine di crag boar e un boccale di Rhapsody Malt, {name}.", "La Malt è pronta, i cinghiali sono andati\n\nE prima che tutto sia detto e pure mangiati\n\nCi sarà da lottare per avere il primo boccone\n\nDi queste Beer Basted Boar Ribs, che passione!", nil, 0x848a85be, 0xacc6d110, 0xe5dfc379, 0x3d02ca9a, "m...." },
  [385] = { "Caccia ai crocolisk", "Procura 5 pezzi di Crocolisk Meat e 6 Crocolisk Skins per Marek Ironheart, alla Farstrider Lodge.", "Molti cacciatori vengono a Loch Modan per cacciare i nostri famosi coccodrilli. Ci sono sempre mercanti in cerca di Crocolisk Skins per abiti o armature, e c'è anche chi apprezza il sapore della loro carne.\n\nNe facciamo un po' di commercio, ma non molto, perché i crocolisk sono feroci e si sono trincerati sulle isole del Loch. Ma non lasciarti scoraggiare: lottare con le mascelle di quelle bestie è un'esperienza.\n\nPensa che una volta...", "Ti ho raccontato di quando ho quasi perso la mano per colpa di uno dei coccodrilli? Una bestiaccia, con denti come coltelli. Ma sono stato fortunato... Gli ho bloccato le fauci con il mio coltello. Ce l'ho ancora qui da qualche parte, quel coltello...", "Be', questi che hai raccolto sono ottimi esemplari, {name}. Bei soldi per materiali di alta qualità, questo è certo.", 0x08c77bcd, 0x39f97603, 0x43d56489, 0x6cc0be27, 0x469a4235, "....." },
  [386] = { "Chi la fa l'aspetti...", "Porta la testa di Targorr the Dread a Guard Berton, a Lakeshire.", "Targorr the Dread era il boia supremo al servizio di Gath'Ilzogg. I suoi metodi erano spietati, persino per gli standard di quei luridi orchi. Uomini che avevano combattuto con coraggio per difendere il regno venivano torturati a suo capriccio. Ora è rinchiuso nella Stormwind Stockade, condannato a morte. Eppure qualcosa non torna. Uno dei nobili della burocrazia ha sospeso la sua esecuzione. Sono certo che c'è sotto qualcosa di losco.\n\nMetti fine a Targorr the Dread, {name}. Vai alla Stockade e decapitalo prima che l'inganno abbia la meglio.", "Sei già <stato/stata> a Stormwind, alla Stockade? Temo che l'inganno che ha tenuto in vita Targorr the Dread così a lungo finirà per ridargli la libertà. È stato condannato a morte, {name}, non a fare da pedina politica per il capriccio di un nobile.", "Targorr the Dread ha finalmente incontrato il suo destino. Io, per primo, sono contento di sapere che quella bestia ora sa cosa vuol dire trovarsi nella morsa spietata della morte. Hai fatto bene, {name}. A volte la giustizia più vera si trova solo fuori dall'aula di tribunale, oltre la vista annebbiata della politica.", 0x985b5c1d, 0x0bd13fa2, 0x9d18b187, 0x4b424f22, 0x4701141d, "....." },
  [387] = { "Sedare la rivolta", "Il Warden Thelwater di Stormwind vuole che tu uccida 10 Defias Prisoner, 8 Defias Convict e 8 Defias Insurgent nello Stockade.", "La rivolta deve essere sedata! Ho bisogno del tuo aiuto. Se si sparge la voce che la prigione è stata presa d'assalto, perderò il lavoro! Se mai ho visto un caso di sabotaggio, è questo. Ma ora l'importante è costringere questi prigionieri alla resa per la sicurezza di Stormwind.\n\nLa pena per l'insurrezione è la morte. Uccidi un po' di questi delinquenti! Così le cose dovrebbero tornare sotto controllo.", "Lo Stockade è ancora in mano ai rivoltosi! Bisogna mostrare a questi Defias Rats che le loro azioni non saranno tollerate. Ora torna laggiù e mostra un po' di forza!", "I tuoi sforzi nello Stockade sono stati valorosi, {name}. È evidente che questo problema è più grande di entrambi. Ma hai agito bene e per questo ti sono grato.", 0x577b3efe, 0x537853f9, 0xb27b21dc, 0x07128f06, 0x7f65d9bb, "....." },
  [388] = { "Il colore del sangue", "Nikova Raskol di Stormwind vuole che tu raccolga 10 Red Wool Bandanas.", "L'amarezza mi scorre nelle vene come un fiume gelido. Mio nipote, Mac, era un così bravo ragazzo. Aveva appena 14 anni. Quando l'esercito fu mandato al fronte, Mac prese le armi per difendere la città. Era una guardia dello Stockade, dove è rinchiusa la banda dei Defias. Mac rimproverò alcuni prigionieri perché strappavano le loro coperte di lana per farne sciarpe, simbolo della loro banda. Per questo Mac fu pugnalato alla schiena.\n\nVoglio vendetta. Portami 10 delle loro preziose Wool Bandanas. Sono del colore del sangue.", "Vedo che sei <tornato/tornata>, {class}. Hai già raccolto 10 Red Wool Bandanas da quei Defias Scum nello Stockade?", "Quindi queste bandane, luridi simboli di corruzione, sono ciò per cui il mio Mac è dovuto morire? Che spreco. Che tragico sacrificio.\n\nMa ahimè, non posso tornare al passato. Sappi solo, {name}, che con le tue azioni hai reso giustizia alla mia famiglia.", 0x309b5224, 0x731de4a6, 0x75502eb1, 0x94db022c, 0x3ca7de8a, "....." },
  [389] = { nil, "Parla con il Warden Thelwater, nello Stockade.", "VanCleef e io eravamo membri della Stonemasons Guild. Il nostro progetto principale era ricostruire Stormwind dopo la guerra.\n\nQuando terminammo il nostro lavoro, fummo truffati. I nobili si rifiutarono di pagarci. Ad alcuni degli scalpellini più anziani furono offerti incarichi governativi, ma VanCleef rifiutò per lealtà verso tutti gli scalpellini. Guidò una rivolta e lasciò la città, giurando vendetta.\n\nIl suo luogotenente, Bazil Thredd, potrebbe sapere di più sui piani di VanCleef. È tenuto prigioniero nello Stockade.", nil, "Per la Luce, che cosa vuoi? Non vedi che qui abbiamo una crisi?\n\nBazil Thredd?! Perché mai vorresti parlare con quel bastardo? Come faccio a sapere che non fai parte dei suoi tirapiedi, qui ad aiutarlo con la sua maledetta rivolta? Se tutte quelle dannate celle non fossero aperte, ti ci butterei dentro per un po'!", nil, 0x9f1dfef8, 0xcad99174, nil, 0x275f421d, "m..m." },
  [391] = { "Le rivolte dello Stockade", "Uccidi Bazil Thredd e porta la sua testa al Warden Thelwater, allo Stockade.", "Mettiamo in chiaro una cosa, {name}: non mi fido di te. Ma, con la situazione così com'è, probabilmente non farai alcuna differenza.\n\nQuindi ecco come andrà: scendi laggiù e fai la tua chiacchierata con Thredd. Se sei davvero dalla nostra parte, uccidilo e portami la sua testa a lavoro finito. E se si scopre che sei dalla sua parte e non esci... quando ti troveremo, morirai insieme al resto di quei vermi.", "O mi porti la testa di Thredd, o prendo la tua, capito, {name}?", "Senza Thredd a guidarli, speriamo che le rivolte siano più controllabili. Vedremo.\n\nDevo dire che dopo mezz'ora non mi aspettavo proprio che saresti <uscito/uscita>, ma a quanto pare ti ho <giudicato/giudicata> male.\n\nImmagino quindi che tu non abbia ricavato molte informazioni utili da lui? Ma io so un paio di cose sulle attività di Thredd che potrebbero interessarti.", 0x8d19e31c, 0x1cb86e24, 0xa2b8b189, 0xb08a569e, 0x6178e7e9, "....." },
  [392] = { "Il visitatore curioso", "Porta la Sealed Description of Thredd's Visitor a Baros Alexston, a Stormwind.", "Nei primi anni di prigionia di Thredd, non ha mai ricevuto visite. Ho pensato che non fosse più utile alla Brotherhood, e che l'avessero abbandonato.\n\nComunque, qualche mese fa è cambiato tutto: ha cominciato a ricevere visite regolari... una, forse due volte a settimana. Era un uomo strano, il tipo silenzioso. Avevo i miei sospetti, ma i suoi documenti erano tutti in regola.\n\nSecondo i suoi documenti si chiamava Maelik; ecco la sua descrizione. Non credo che verrà più a trovare Thredd.", "Sì, {name}? Cosa hai trovato?", "Mmm. Maelik? No, il nome non mi dice nulla, e nemmeno questa descrizione. Ma potrebbe essere chiunque! Un ex scalpellino, uno della Defias Brotherhood... Però, se ha tante conoscenze come suggerisce Thelwater, forse qualcun altro potrebbe riconoscerlo. Fammi pensare.", 0x35a2f6f1, 0xdb51b853, 0x0cbcac0d, 0x2a96cc90, 0x473d9a09, "....." },
  [393] = { "L'ombra del passato", "Porta la Sealed Description of Thredd's Visitor al Master Mathias Shaw, a Stormwind.", "Non ne ho davvero idea, {name}. C'è qualcun altro che potrebbe aiutarti, e guarda caso mi deve un favore per... beh, lasciamo perdere. Il Master Mathias Shaw dello SI:7 si trova nelle caserme di Old Town. Shaw tiene d'occhio la maggior parte dei traffici loschi e sottobanco della città.\n\nSe qualcuno lo sa, è lui.", "Salute. Come posso esserti utile, {class}?", "Cosa? Cos'è questo? Sì, credo di sapere chi sia quest'uomo, ma il suo nome non è Maelik. Gli assassini portano molti nomi e molte maschere, e li abbandonano quando non servono più. Un altro alias noto di quest'uomo è Marzon; anche se di sicuro nemmeno questo è il suo vero nome.\n\nIn ogni caso, è un assassino e so molto su di lui.\n\nMarzon è attualmente al servizio di Lord Gregor Lescovar, un lord di dubbia reputazione, persino considerando la corruzione della nobiltà di Stormwind.", 0x57046a0a, 0x20fa1c0c, 0x29c82d75, 0x3a5dbaf1, 0x224c7373, "....." },
  [394] = { "La testa della bestia", "Parla con Mathias Shaw, a Stormwind.", "Trova Shaw a Old Town. Fagli sapere che la minaccia di Lescovar è stata eliminata e raccontagli del tuo coinvolgimento nei complotti del lord contro la città. Sono sicuro che sarà fiero di avere un'altra figura eroica tra i cittadini di Stormwind.\n\nCon ogni probabilità ti manderà a incontrare il principe o qualche altro nobile. Non montarti la testa, {name}. I nobili possono credere di governare la città quanto vogliono, ma alcune cose restano fuori dalla loro portata.", nil, "Quindi è morto? La tua giustizia è stata rapida, {name}. Prego la Luce di non diventare mai la tua preda!\n\n<Ride e ti dà una pacca sulla spalla.>\n\nNon intendo criticarti, {name}. Come potrei, io che sono il maestro di tutti gli assassini? Ma in verità hai reso un grande servizio alla gente di Stormwind, e per questo ti ringrazio.", 0xe4545c03, 0xad70b6fb, 0x578303cb, nil, 0x2ab8dabc, "...m." },
  [395] = { "La fine della Brotherhood", "Parla con Baros Alexston, a Stormwind.", "Ah, quasi dimenticavo. Alexston è venuto mentre eri via, voleva parlarti. Senza dubbio vuole riferire ai nobili le attività della Defias Brotherhood.\n\nUn consiglio, {name}: se qualcuno dovesse chiederlo, darei tutti i dettagli tranne il fatto che è stata la tua mano a uccidere Lescovar. Fidati. Ho una certa... familiarità... con questo genere di cose.\n\nE quanto a Trias, beh, non parlarne con nessuno... mai... se puoi evitarlo.", nil, "Che piacere vederti, {name}. Ho sentito che Lord Gregor Lescovar è stato trovato morto non molto tempo fa.\n\nSembra che la tua missione abbia avuto successo. Hai la mia gratitudine per aver salvato me, e molti altri, dalla vendetta di VanCleef.", 0x321120ba, 0xe768ecd1, 0x6cface0d, nil, 0xf4847567, "...m." },
  [396] = { "Udienza dal re", "Consegna il rapporto di Baros Alexston sulla Defias Brotherhood a King Varian Wrynn, nello Stormwind Keep.", "Ho preparato un rapporto per il re. Credo che dovresti essere tu a consegnarglielo, insieme a un resoconto di ciò che hai scoperto. Non preoccuparti, non c'è dubbio che ti loderà per aver fatto il tuo dovere verso la gente di Stormwind.\n\nLa tua udienza è fissata a breve, quindi faresti meglio a sbrigarti: lo Stormwind Keep è un po' distante.", "{name}, giusto? Baros Alexston mi ha informato che saresti <venuto/venuta>. Devo dire che sono molto interessato a ciò che hai da dire.", "Meriti un encomio per il servizio che hai reso a Stormwind, {name}. Se VanCleef fosse riuscito nelle sue macchinazioni, avrebbe senza dubbio causato gravi danni al regno, cosa che ovviamente dobbiamo evitare.\n\nPrendi questo, {class}, come segno dell'apprezzamento del re. Mi dispiace solo che non possa consegnartelo di persona, ma è via per una missione diplomatica e non tornerà per un po' di tempo.", 0x6971d0c2, 0xfe7b374c, 0x8cfc5b31, 0x2434fd41, 0xb23a1117, "....." },
  [397] = { "Ci hai serviti bene", "Parla con Zggi, il servitore di Zardeth the Blackclaw, per ritirare la tua ricompensa.", "Ho sentito che a Lord Wishock è piaciuta la sua bevanda.\n\nCi hai serviti bene, {name}. Grazie a te gli stregoni di Stormwind potranno praticare le nostre arti senza disturbo. Per i tuoi sforzi ti ho preparato un dono speciale. Parla con il mio servitore, Zggi, e ritira la tua ricompensa.", nil, "Il padrone dice dare regalo a {name}. Zggi vuole tenere bel regalo ma Zggi sa che non deve tradire il padrone.", 0xeaaf884a, 0x441331ba, 0x5147d5ea, nil, 0xa9142260, "...m." },
  [398] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [399] = { "Umili inizi", "Va' alla casa di Baros Alexston a Westfall e cerca la sua bussola, poi riportagliela nella Cathedral Square di Stormwind.", "Sembra passata un'eternità da quando ero un ragazzo che lavorava nella fattoria di Westfall. Si dice che non si può mai tornare indietro, ed è vero. Doppiamente vero nel mio caso: la casa della mia famiglia è stata bruciata e occupata dai ladri.\n\nHo parlato con mio padre della sorte di alcuni miei oggetti, tra cui la mia prima bussola. Non è riuscito a salvarli. Però dice anche che dovrebbero essere nascosti nella fattoria.\n\nTroverai l'Alexston Farmstead a ovest di Sentinel Hill. Forse potresti andare a recuperarla per me?", "{name}! Hai avuto fortuna?", "Oh, grazie, {name}! Non mi è di alcuna utilità pratica, ma il valore affettivo... Inutile dirlo, grazie per avermela portata... a scapito del tuo benessere, per non parlare del tempo per andare fino a Westfall. Hai la mia gratitudine, e prendi questo come segno del mio ringraziamento.", 0xe3c50bf4, 0xf6990729, 0x3d3b2003, 0x92e1e141, 0x3dfe9061, "....." },
  [400] = { "Attrezzi per Steelgrill", "Consegna gli Steelgrill's Tools a Beldin Steelgrill.", "Beldin Steelgrill gestisce l'officina meccanica della zona ed è il miglior tecnico di macchine d'assedio che ci sia! Ma con i suoi attrezzi non ha pietà. Giuro che rompe più chiavi arclight di quante riusciamo a fornirgliene!\n\nAbbiamo appena evaso il suo ultimo ordine di attrezzi. Se glielo consegni, sono sicuro che ne varrà la pena.\n\nLa sua officina, lo Steelgrill's Depot, è appena a nord-est di Kharanos. Ed è un ritrovo per i piloti veterani di macchine d'assedio, quindi tieni le orecchie aperte per qualche opportunità mentre sei lì.", "Mm? Sembri un po' giovane per pilotare una macchina d'assedio. Ma non importa... hai qualcosa da far riparare?\n\nBeh, prendi il numero e mettiti <comodo/comoda>. Sto lavorando a un paio di mezzi in questo momento e non avrò tempo per un altro lavoro per almeno qualche giorno.\n\nOppure eri qui per qualcos'altro...?", "Hai i miei attrezzi? Ben fatto, <ragazzo/ragazza>, ben fatto! Ho rotto il mio ultimo cricchetto a zanna un'ora fa e me ne serve uno per finire le riparazioni della macchina d'assedio del Pilot Stonegear. Hai fatto una buona cosa a trascinare qui quegli attrezzi, {name}.\n\nTieni, prendi queste monete per il tuo aiuto.", 0x872f52ba, 0xc5e776cd, 0x841b2028, 0x849bd1d2, 0xfbff9b36, ".....", nil, nil, nil, nil, 0x7de665ab },
  [401] = { "Aspettare che Sirra finisca", "Aspetta un momento, poi parla di nuovo con Sirra Von'Indi.", "Ho quasi finito di tradurre quel biglietto. Se torni tra qualche momento dovrei aver finito.", nil, "Ecco fatto. È tradotto...\n\n<L'aria si fa pesante, come se un drappo nero e fitto calasse sulla terra...>", 0xec04092d, 0xa17cff08, 0x5bacacc5, nil, 0x16c781dc, "...m." },
  [403] = { "Il barile sorvegliato dei Thunderbrew", nil, nil, nil, "Questo barile di birra è sorvegliato da Jarven Thunderbrew. Finché lui è nel seminterrato, nessun barile può essere toccato.", 0xdf09604e, nil, nil, nil, 0x33af4f29, ".mmm." },
  [412] = { "Operazione ricombobulazione", "Porta a Razzle Sprysprocket, a Kharanos, 8 Restabilization Cogs e 8 Gyromechanic Gears.", "Da un'analisi più approfondita della situazione di Gnomeregan, sembrerebbe che non solo non siamo riusciti a sterminare i trogg, ma abbiamo anche trasformato gran parte della razza gnomesca in orribili gnomi lebbrosi, malvagi e senza cervello.\n\nOzzie e io intendiamo invertire l'orribile effetto della lebbra con la nostra ultima invenzione: il Recombobulator. La macchina è quasi completa, ma abbiamo un disperato bisogno di Restabilization Cogs e Gyromechanic Gears. Recuperane un po' dagli gnomi lebbrosi davanti a Gnomeregan per noi.", "Il Recombobulator sarà in funzione non appena avremo abbastanza Restabilization Cogs e Gyromechanic Gears.", "Questi Gyromechanic Gears e Restabilization Cogs sono perfettamente conformi agli schemi di Ozzie per il Recombobulation Device. Una volta aggiunto un po' di idrolubrificante ai pistoni a combustione interna, regolato il cricco-manovella e aumentata la viscosità del gel elettrogommoso, la razza gnomesca tornerà come nuova.", 0xeb51823c, 0x9967013a, 0x65cd1925, 0x5da233c7, 0xc3725696, "....." },
  [413] = { nil, "Porta il Barrel of Shimmer Stout al Mountaineer Barleybrew.", "Vorrei che mio fratello Wellart assaggiasse la mia nuova Shimmer Stout. È un Mountaineer di stanza nella torre di guardia meridionale, una delle due torri al confine con Loch Modan.\n\nNon sarà un mastro birraio come il resto di noi Barleybrew, ma ama bere e so che questa gli piacerà.\n\nPuoi portargli questo Barrel of Shimmer Stout da parte mia?", "Salve, {class}! E quale faccenda ti porta fin quassù?\n\nQualcosa di emozionante, spero. Sono giorni che non faccio una bella zuffa, e questo barile di birra è quasi asciutto...", "<Il Mountaineer Barleybrew assaggia la Shimmer Stout...>\n\nOh. Accidenti! Questa roba ti fa proprio brillare gli occhi. Mi sembra di vedere al buio!", nil, 0x8e29116f, 0xc2c58cab, 0xb59d2e44, 0xe387b846, "m...." },
  [414] = { "Stout per Kadrell", "Porta il Cask of Shimmer Stout al Mountaineer Kadrell.", "Ho bevuto ancora di quella Shimmer Stout che ha fatto mio fratello: è roba ottima! Voglio che la assaggi un altro Mountaineer. Si chiama Kadrell e di solito pattuglia la strada che attraversa Thelsamar, a Loch Modan.\n\nPer arrivare a Thelsamar, va' a sud-est attraverso la galleria, poi gira a nord-est quando il sentiero si biforca in una strada. Segui quella strada dritto fino a Thelsamar.\n\nDai al Mountaineer Kadrell questo barilotto di Shimmer Stout e senti cosa ne pensa!", "Salute, {class}, e <benvenuto/benvenuta> a Thelsamar!", "Ora fammi assaggiare...\n\nPer la barba di Magni! Questa roba ti fa girare la testa! E alleggerisce anche le membra.\n\nMi sembra di poter volare!", 0xd20ea02e, 0xeed35031, 0x40ac0d91, 0xffeabd23, 0x91b650e9, "....." },
  [415] = { "La nuova birra di Rejold", "Parla con Rejold Barleybrew.", "Rejold Barleybrew, a Brewnall Village, ha chiesto di te.\n\nVuole parlarti di una nuova bevanda che sta preparando... ha detto qualcosa sul fatto che lo aiuterai tu. Forse dovresti tornare a Brewnall Village a sentire cosa ha da dire.\n\nPotrebbe scapparci qualcosa da bere gratis per te...", nil, "{name}! Hai presente la shimmerweed che mi hai portato? Beh, l'ho usata in qualche ricetta a cui stavo lavorando, e una è venuta benissimo!\n\nEcco, assaggiala e dimmi cosa ne pensi...", 0xe805c4ca, 0x2b9ce38c, 0x1d773d33, nil, 0xb5fafd9a, "...m." },
  [416] = { "Caccia ai ratti", "Porta 12 Tunnel Rat Ears al Mountaineer Kadrell, a Thelsamar.", "A ovest abbiamo una vera infestazione. I kobold tunnel rat si sono trasferiti sulle colline, costruendo tane e insozzando la nostra terra con la loro sporcizia!\n\nVogliamo che siano eliminati. Dagli la caccia, portami le loro orecchie e incassa la taglia.\n\nTroverai i kobold tunnel rat e le loro tane a ovest di Thelsamar, sparsi lungo il fianco della montagna.", "Salute, {name}. Come procede la caccia ai ratti?", "Bleah! Quando ho chiesto quelle orecchie non immaginavo che puzzassero così tanto!\n\nEcco la tua ricompensa, {name}. Ben fatto.", 0x63070b4c, 0x45c146d7, 0x5b4e949e, 0x46cea726, 0x1e9a33db, "....." },
  [417] = { "La vendetta di un pilota", "Uccidi Mangeclaw.\n\nPorta il suo Mangy Claw e l'Hildelve's Journal al Pilot Hammerfoot.", "Hildelve ha scritto nel suo diario di essere stato attaccato da Mangeclaw, un \"enorme Ice Claw Bear\". Ha scacciato la bestia, ma non prima che lo dilaniasse ferocemente.\n\nA giudicare dallo stato del corpo di Hildelve, Mangeclaw dev'essere tornato più tardi e averlo ucciso.\n\nTuttavia Hildelve ha scritto nel suo diario il suo unico, ultimo desiderio:\n\nVendetta contro Mangeclaw.", "Salve, {name}. Hai notizie del mio amico Hildelve?", "Sono brutte notizie, perché Hildelve era un buon amico. E vorrei essere stato lì con te quando hai trovato quella bestia, Mangeclaw!\n\nGrazie, {name}. La tua impresa sarà ricordata dai piloti della Ironforge Siege Brigade.", 0xc8a157ff, 0xfc8ba3ba, 0x36d8afa5, 0x86e8914d, 0x2e3d6b6c, "....." },
  [418] = { nil, "Porta 3 pezzi di Bear Meat, 3 Boar Intestines e 3 Spider Ichor a Vidra Hearthstove, a Thelsamar.", "Qui a Thelsamar le pance vuote non mancano mai: bambini che entrano ed escono, operai dello scavo che arrivano dopo una dura giornata di lavoro. Siamo famosi per i nostri sanguinacci, non li hai mai assaggiati, vero?\n\nNo? Be', da queste parti i pasti bisogna guadagnarseli, e non credere di fare eccezione solo perché sei <un/una> {class} di gran classe.\n\nMi servono Bear Meat, Boar Intestines per i budelli e Spider Ichor come spezia. Procurameli e lascia la cucina a Vidra!", "Sono pronta a cominciare a cucinare: hai gli ingredienti per me?", "Fidati, sembra molto più difficile di quanto sia, ma...\n\nOh, non ho mai visto nessuno interessarsi tanto alla preparazione delle salsicce, ma ti do la ricetta, non si sa mai. Eccola, e mi raccomando, mangiale fresche!", nil, 0x3da74c62, 0x0fbff557, 0x6090d9ed, 0x9a0355ae, "m...." },
  [419] = { "Il pilota disperso", "Trova il Pilot Hildelve.", "Il mio amico e collega pilota di Siege Engine, Mori Hildelve, si è perso sulle colline. Cercavamo un minerale raro necessario per una polvere esplosiva di alta qualità, e durante la ricerca ha guidato il suo mezzo su per una collina ripida e l'ha distrutto!\n\nAncora convinto che il minerale fosse in queste montagne, Hildelve mi ha incaricato di sorvegliare i nostri mezzi mentre lui proseguiva a piedi a cercarlo.\n\nSono passati giorni, e di notte ho sentito dei ringhi bestiali sulle colline. Mori è duro come la roccia, ma sono preoccupato.\n\nTi prego, {name}. Trovalo.", nil, "Ecco il cadavere di un nano: dilaniato, congelato e spolpato dagli spazzini di montagna. Stretto in mano c'è un libro con gli appunti scarabocchiati alla buona di Mori Hildelve. E indosso, ancora in ottime condizioni, c'è un Brigadier's Vest.\n\nQuesta scena raccapricciante dev'essere il luogo dove il pilota di Siege Engine ha trovato la morte.", 0x7f8b701c, 0x19886134, 0x7506a7ac, nil, 0x78eadffd, "...m." },
  [420] = { "Le osservazioni di Senir", "Consegna il rapporto di Grelin a Senir Whitebeard, a Kharanos.", "I trogg nella galleria sono estremamente ostili e non hanno mostrato esitazione ad attaccare chi la attraversa. Comunque sembri abbastanza <robusto/robusta>, quindi dovresti essere al sicuro.\n\nIndicazioni? Se vai a parlare con Senir, lo troverai a Kharanos.\n\nAttraversa la galleria e, una volta <uscito/uscita> dall'altra parte, continua a seguire la strada: ti porterà dritto a Kharanos.", "Come stai? Ti va di bere qualcosa con me, magari? Al freddo non c'è molto altro da fare.", "Cos'è questo? Ah, il rapporto di mio fratello. Mmm...\n\nGli avevo detto di non abusare del nome del re, ma non mi ha ascoltato. Nessun danno, suppongo, anche se di sicuro farà storcere qualche naso al senato. Non che non fossero nasi da far storcere! Ah!\n\nAd ogni modo, credo che significhi che dovrei mandare anch'io il mio rapporto a Ironforge, ma devo ammettere di essere un po' indietro. Maledetto freddo.\n\nDovrei avere del lavoro per te più tardi, se ti interessa.", 0x034f6959, 0xd1c8fc65, 0x507d5ef4, 0xd802ec21, 0xf5afd554, "....." },
  [432] = { "Quei maledetti trogg!", "Uccidi 6 Rockjaw Skullthumper per il Foreman Stonebrow, alla cava di Gol'Bolar.", "Quei trogg maledetti dalla Luce, che riducono il mio cantiere a un disastro! Guarda là, ecco che salta un altro barile di polvere!\n\nOhhh, vorrei poter scendere laggiù e tirare il collo a ognuno di quei mingherlini! Voglio ucciderli tutti!\n\nTutto questo stress e questa rabbia non possono far bene alla mia salute... Cosa mi hanno lasciato? Niente!\n\nLi ucciderei io stesso, ma non ho più la mira di una volta! Va' tu nella cava e uccidi un po' di quei luridi mascalzoni! Ti pagherò! Basta che li fai soffrire, che li uccidi!", "Mi fa arrabbiare tantissimo! Grrr...", "Beh, questo mi fa sentire un po' meglio...\n\nMa non sarò contento finché non saranno tutti morti! Tutti quanti!", 0xa38a8583, 0x68645f8e, 0xd7fa5983, 0xcd9b49ca, 0xda5abbb8, "....." },
  [433] = { "Il servitore pubblico", "Uccidi 10 Rockjaw Bonesnapper per il Senator Mehr Stonehallow, alla cava di Gol'Bolar.", "Come membro del senato e dell'Explorers' League, mi sono fatto carico di occuparmi di questa parte dell'infestazione di trogg che ha colpito le nostre terre.\n\nDi certo hanno ridotto la cava di Gol'Bolar a un disastro, e senza motivo. Mentre scavavamo in profondità nella terra, si sono riversati fuori, distruggendo le nostre attrezzature e cacciando i minatori. Non ci resta altro che sterminarli tutti, ricostruire e tornare al lavoro.\n\nSe mi aiuti con i trogg, sarò lieto di ricompensarti per il tuo tempo.", "Se riusciamo a cacciare i trogg dalla cava di Gol'Bolar, sarà il primo di molti passi che dovremo compiere per liberarci di questa minaccia.", "È un inizio. Speriamo di poterne approfittare e far entrare qualche Mountaineer per mettere in sicurezza la zona. Poi potremo cominciare a ripristinare le nostre strutture e rimettere al lavoro i minatori.\n\nGrazie per il tuo aiuto, {name}.", 0x23152624, 0x8332d369, 0xdd9ed5fb, 0xf528dd76, 0xc92f32fa, "....." },
  [434] = { "L'attacco!", "Resta nel giardino finché Lord Gregor Lescovar e Marzon the Silent Blade non avranno finito di parlare. Poi uccidili entrambi prima di tornare da Elling Trias, a Stormwind.", "Dopo che avrò messo il travestimento a Spybot, entrerà a parlare con Lescovar. Le guardie dovrebbero lasciarlo passare senza problemi.\n\nMentre tu mi procuravi i materiali, mi sono occupato di informare Marzon che era ora che lui e Lescovar si incontrassero di nuovo. Gli ho anche passato qualche informazione falsa.\n\nLescovar congederà le guardie e aspetterà Marzon qui fuori in giardino. Quando sentirai parlare dei Defias, entra in azione. Devi ucciderli entrambi prima che le guardie tornino! Quando hai finito, parla con Trias.", "Sì, {name}? Le cose vanno bene con Tyrion? Mi ha messo al corrente della situazione e l'ho aiutato a ingannare Marzon perché andasse al castello.\n\nMarzon è stato una spina nel fianco di molte persone a Stormwind, molte delle quali sono miei cari amici. Nessuno tocca i miei amici... non se ci tiene alla salute.\n\nPeccato solo che nel frattempo stia facendo indirettamente un favore a Shaw e allo SI:7. Pazienza, non tutti i piani sono perfetti.", "Quindi è fatta? Bene. Grazie infinite per la tua discrezione, {name}. Hai dimostrato il tuo valore sotto più di un aspetto. Terrò d'occhio te e i tuoi progressi all'interno dell'Alliance.\n\nE cerca di rigare dritto.", 0xdc0ceea9, 0x91a3233e, 0x71af2a8a, 0x065d5a10, 0xeeafb6f9, "....." },
  [436] = { "L'Ironband's Excavation", "Parla con Explorer Fellhew.", "Prospector Ironband dirige uno scavo di rovine antiche a est del lago. Ultimamente i suoi progressi sono stati lenti, soprattutto considerando tutte le provviste che gli abbiamo mandato.\n\nIronband è un nano robusto e onesto che bada ai risultati, e questo mi fa temere che ci siano forze che lavorano contro di lui.\n\nVai all'Ironband's Excavation e parla con Magmar Fellhew. Si occupa dei dettagli del sito e saprà perché c'è un rallentamento.\n\nPer arrivare al sito di scavo, aggira la punta meridionale del lago, poi vai verso est.", nil, "Jern vuole sapere perché c'è un rallentamento, eh?\n\nIronband sta preparando il suo ultimo rapporto con tutti i dettagli, ma posso dirti questo:\n\nSono i trogg!!", 0x2c4f5a39, 0x18791172, 0x721d5d65, nil, 0x7334fe2a, "...m." },
  [453] = { "Trovare la figura nell'ombra", "Trova la figura nell'ombra. I tuoi indizi:\n\nNon è di Darkshire.\n\nÈ una persona nervosa e agitata.\n\nHa lasciato Darkshire ed è andato verso ovest.", "Buona fortuna, {name}. Spero che tu trovi quel tipo, e spero che tu lo trovi vivo.\n\nSe ha lasciato la sicurezza di Darkshire, potrebbe finire preda delle bestie selvatiche.", "Chi sei?? Lasciami in pace!", "<Jitters sospira...>\n\nSì, sono io l'autore di quel libro. Alla fine mi hai trovato, eh?\n\nBe', se hai letto quel diario... allora ne conosci solo la metà!", 0x2ae0c829, 0xd39bd401, 0x2c24a350, 0x9d47818e, 0x344ae3ba, "....." },
  [454] = { "Dopo l'imboscata", "Parla con Miran.", "Prima di questa... faccenda, portavamo avanti e indietro i barili di polvere con diversi viaggi. Ora dobbiamo dividerci il lavoro: Miran porta i barili e io sorveglio gli altri.\n\nNon mi sento tranquillo a lasciare che Miran trasporti da solo il resto del carico. Quando è pronto a partire, forse potresti scortarlo nel suo prossimo viaggio?", nil, "Salve, {class}.\n\nMi scorterai al sito di scavo? Mi fa piacere... Dopo Saean e i suoi compari, chissà cos'altro hanno in serbo i Dark Iron?\n\nComunque, lasciami fare gli ultimi controlli. Parlami di nuovo quando sei <pronto/pronta> a partire.", 0x2d57ae65, 0xb4a1fd8d, 0x4806532e, nil, 0x7d1ab5fb, "...m." },
  [455] = { "La sfida di Algaz", "Attraversa Dun Algaz.\n\nUccidi 8 Dragonmaw Scouts e 6 Dragonmaw Grunts.\n\nFai rapporto a Valstag Ironjaw, a Menethil Harbor.", "Gli orchi del clan Dragonmaw hanno un rifugio nelle Wetlands. E ora si sono allargati fino a Dun Algaz! Non possiamo lasciare che mettano radici qui, o Loch Modan sarà tagliata fuori da Menethil Harbor, il nostro porto e la nostra roccaforte nelle Wetlands.\n\nApriti un varco attraverso Dun Algaz fino alle Wetlands e uccidi qualche orco, già che ci sei! Fai rapporto a Valstag Ironjaw, a Menethil Harbor.\n\nMenethil si raggiunge attraverso Dun Algaz, poi a nord lungo la strada, poi a ovest al bivio.\n\nContiamo su di te, {name}. Non deluderci.", "Vieni da Loch Modan? Com'è la situazione degli orchi all'Algaz Gate?", "Il tuo rapporto è pieno di brutte notizie!\n\nVedo che i Dragonmaw stanno avanzando in forze ad Algaz. Di solito i Dragonmaw se ne stanno nascosti sulle colline. Cosa li abbia spinti a riversarsi ad Algaz è ancora un mistero...\n\nGrazie, {name}. E probabilmente ci servirà il tuo aiuto per occuparci di questi orchi.", 0x3a6441ba, 0x8925dac0, 0x2bd879fc, 0xadb75063, 0xcd00a06e, "....." },
  [456] = { "L'equilibrio della natura", "Uccidi 7 Young Nightsabers e 4 Young Thistle Boars e torna da Conservator Ilthalaine.", "Salute, {name}. Sono Conservator Ilthalaine. Il mio compito a Shadowglen è assicurarmi che l'equilibrio della natura sia mantenuto.\n\nQuest'anno le piogge di primavera sono state particolarmente abbondanti, e alcune bestie della foresta sono prosperate mentre altre hanno sofferto.\n\nPurtroppo i nightsaber e i thistle boar sono diventati troppo numerosi. Shadowglen può produrre solo una certa quantità di cibo per le bestie. Parti, giovane {class}, e sfoltisci i cinghiali e i nightsaber, perché l'armonia della natura sia preservata.", "C'è ancora lavoro da fare, {name}. Torna da me quando avrai sfoltito i nightsaber e i thistle boar.", "Hai svolto bene i tuoi doveri, {name}.", 0x2cefa7e3, 0x57f2ad93, 0x2ca7f2af, 0x1bb3c7c9, 0xb4a95be9, "....." },
  [457] = { "L'equilibrio della natura", "Conservator Ilthalaine ha bisogno che tu uccida 7 Mangy Nightsabers e 7 Thistle Boars.", "Sfoltire le creature più giovani qui a Shadowglen è stato un buon inizio, {name}, ma c'è ancora lavoro da fare.\n\nLe risorse della foresta si esauriranno troppo in fretta se il problema non viene affrontato. Uccidere le bestie della natura è un male necessario per il bene di tutti quelli che condividono questa terra. Addentrati nella foresta e uccidi i mangy nightsaber e i thistle boar in nome dell'equilibrio.", "Il tuo compito non è ancora finito, {name}. Torna da me quando avrai ucciso 8 mangy nightsaber e 8 thistle boar.", "Hai dimostrato bene la tua dedizione alla natura, {name}. Davanti a te, giovane {class}, c'è un futuro promettente.", 0x2cefa7e3, 0xc9b080bf, 0x37d9d1de, 0xe2130366, 0x943085ad, "....." },
  [458] = { "La protettrice dei boschi", "Cerca la driade chiamata Tarindrella.", "Grazie al cielo sei qui, {class}. Strane notizie mi sono giunte attraverso i sussurri degli spiriti della foresta.\n\nLa misteriosa protettrice dei boschi, Tarindrella, è tornata a Shadowglen. La presenza della driade non si avverte nelle foreste di Kalimdor da anni. Se è tornata in questa terra, di sicuro c'è qualcosa che non va.\n\nCerca Tarindrella e scopri di cosa si occupa nel nostro bosco. Una delle Sentinels ha riferito di averla vista a sud-ovest di Aldrassil.", nil, "Vedo che mi hai trovata, giovane {race}. Melithar è un druido saggio ad averti mandato qui. Ma hai ancora molto da imparare. So che quelli come te amano i libri. Ti prego, prendine uno per continuare la tua istruzione.", 0x89f0da3a, 0x7d2d6e81, 0xa893a5da, nil, 0x8298799d, "...m." },
  [459] = { "La protettrice dei boschi", "Raccogli 8 Fel Moss e portali a Tarindrella.", "Qualcosa di malvagio si sta preparando nelle foreste di Teldrassil. Guarda lungo le colline, dove vivevano i pacifici furbolg. Hanno abbandonato le loro case e si stanno radunando sotto il nome di tribù Gnarlpine.\n\nSolo la corruzione del malvagio Fel Moss potrebbe causare una trasformazione simile. I grell e i grellkin hanno infestato la zona e minacciano gli abitanti di Shadowglen.\n\nAffronta questi grell e grellkin, {name}, e scopri se sono davvero sotto l'incantesimo del malvagio Fel Moss.", "Togli ogni dubbio ai miei sospetti, {name}. Portami 8 Fel Moss.", "Il tuo servizio alle creature di Shadowglen merita una ricompensa, {name}.\n\nPerò hai confermato i miei timori. Se i grell sono stati contaminati dal Fel Moss, si può solo immaginare cosa ne sia stato della tribù di furbolg Gnarlpine che un tempo viveva qui.\n\nSe ti trovi a Dolanaar, abile {class}, cerca il sapiente druido Athridas Bearmantle. Condivide la nostra preoccupazione per il benessere della foresta.", 0x89f0da3a, 0x26033e95, 0xd7bf71e4, 0x048ee8f1, 0x503e2cc2, "....." },
  [463] = { "Il Greenwarden", "Trova il Greenwarden.", "Hai sentito parlare del Greenwarden? Non lo starai cercando, vero? Be', io dico che sei <matto/matta> se lo fai, ma chi sono io per impedire a uno sciocco di andare incontro alla morte?\n\nSe cerchi quella bestia, ho sentito che è nella palude, a est della strada dove si dirama verso Dun Modr. Si nasconde lì tra i coccodrilli... e di peggio!\n\nE lascia qui i tuoi soldi. Dove vai non ti serviranno... e non vorrai mica scheggiare un dente al vecchio Greenie con il tuo oro quando ti morderà a metà, no?", nil, "Le radici e le felci parlano bene di te, piccolo essere. Anche se ho molti nomi, rispondo solo ad alcuni. Ma tu puoi chiamarmi Rethiel.\n\nE devi ascoltare... perché queste terre piangono per ferite infette, e io ti chiederei di guarirle.", 0xfb7098bf, 0xbe0cd27c, 0x6f613338, nil, 0xf9cd436c, "...m.", nil, nil, 0x65c7375f, nil, nil },
  [464] = { "Stendardi di guerra", "Porta 8 Dragonmaw War Banners a Captain Stoutfist.", "Il clan di orchi Dragonmaw fu quasi distrutto alla fine della Second War, quando perse il controllo dei suoi draghi rossi addomesticati. I draghi non erano molto contenti dei loro vecchi padroni, e diedero una caccia feroce ai Dragonmaw. I pochi rimasti fuggirono da Grim Batol sulle montagne a est del Whelgar's Excavation.\n\nOra hanno ripreso forza, e hanno un accampamento a nord-est di Menethil.\n\nVogliamo che tu attacchi quell'accampamento. Raccogli i loro stendardi di guerra e portameli come prova.", "Hai attaccato l'accampamento dei Dragonmaw?", "Ben combattuto, {name}. I Dragonmaw non sono più la minaccia di quando avevano i draghi, ma restano avversari feroci.\n\nI Dragonmaw sono guidati da Nek'rosh, figlio di Nekros, che anni fa era il capo dei Dragonmaw. Nekros usava una magia potente per domare i draghi rossi, ma quando quella magia lo tradì... i draghi non ne furono contenti.\n\nNekros fu ucciso, e suo figlio ha giurato vendetta contro i draghi che gli uccisero il padre.", 0x342e9831, 0xfebb6d1b, 0x31e6e5db, 0x6eddf078, 0xb005d6c1, "....." },
  [465] = { "La mossa di Nek'rosh", "Distruggi le catapulte dei Dragonmaw.", "I Dragonmaw sono più vicini di quanto pensassimo a mettere in atto i loro piani d'attacco.\n\nNek'rosh ha costruito delle catapulte e vuole assediare Menethil! E con i combattimenti a Dun Algaz, siamo di fatto tagliati fuori dai rinforzi!\n\nDevi distruggere quelle catapulte. Sono nell'accampamento dei Dragonmaw.\n\nTieni, prendi questa esca. Fatti strada combattendo fino alle catapulte e dagli fuoco con l'esca.\n\nE dopo, trova e uccidi Nek'rosh. Dobbiamo tagliare la testa a questa bestia dei Dragonmaw... proprio al collo.", "La prima catapulta è davanti a te. Le darai fuoco?", "Metti un po' di esca sulla catapulta, poi ci fai cadere sopra una scintilla.\n\nLe fiamme divampano e si propagano in fretta!", 0xe486ecaa, 0x3078639a, 0xb379dcba, 0xec1a628f, 0x33e28a1a, "....." },
  [466] = { "In cerca di incendicite", "Porta 6 carichi di Incendicite Ore al Pilot Stonegear, a Dun Morogh.", "Ho sentito che un minerale raro, l'incendicite, è stato trovato nelle Wetlands, in una grotta a nord-ovest dell'Algaz Gate. L'incendicite è roba instabile e difficile da usare senza saltare in aria, ma sono sicuro che, fusa nel modo giusto, potrebbe dare proiettili da cannone con una potenza formidabile!\n\nProcurami del minerale di incendicite e troverò qualcuno abbastanza coraggioso da sperimentarlo.\n\nAh, e per estrarre quel minerale da un filone ti servirà l'abilità di estrazione mineraria. Se non ce l'hai, allora... porta in quella grotta un amico che ce l'abbia!", "Dov'è quel minerale, {name}?!", "Hai il minerale! Ben fatto, {name}! Lo farò lavorare subito da qualcuno. Speriamo che non salti in aria!", 0x469ffcbc, 0x3c97991b, 0x5e710ce5, 0x46a9e54f, 0x6a8505d0, "....." },
  [467] = { "La ricerca di Stonegear", "Parla con il Pilot Stonegear.", "Il Pilot Stonegear ama la sua macchina d'assedio, come ogni pilota dovrebbe! Ed è sempre ansioso di trovare nuovi modi per aumentare la potenza di fuoco del suo carro!\n\nHa sentito voci su un minerale raro e cerca qualcuno che glielo trovi. Se hai voglia di metterti in cammino, cerca Stonegear allo Steelgrill's Depot, a Dun Morogh, e senti cosa vuole.", nil, "Salve, {name}. Sei qui per il compito che ho, eh? Fa piacere vedere qualcuno di giovane della razza {race} a cui ribolle il sangue all'idea dell'avventura!", 0xbf72506c, 0x71b54a38, 0x914d3b00, nil, 0x768a05c1, "...m." },
  [468] = { "Rapporto al Mountaineer Rockgar", "Parla con il Mountaineer Rockgar.", "Il Mountaineer Rockgar cerca volontari per una missione attraverso Dun Algaz fino alle Wetlands.\n\nSe vuoi bagnarti gli stivali in quella contea fradicia a nord, parla con Rockgar a Dun Algaz. Dun Algaz è a nord lungo la strada, oltre la torre di guardia.", nil, "Salve, {class}! Sei qui per la missione di ricognizione, vero? Molto bene!\n\nSpero che il tuo equipaggiamento sia in buone condizioni, perché questa missione di \"ricognizione\" si è trasformata in qualcosa di più complicato...", 0xaca33545, 0x25296a5b, 0x8f51853a, nil, 0xf66d3152, "...m." },
  [469] = { "La consegna di ogni giorno", "Consegna il Bundle of Crocolisk Skins a James Halloran, il conciatore, a Menethil Harbor.", "Salute, viaggiatore!\n\nPer caso vai in direzione di Menethil? Se no, ti consiglio di fermarti lì: è un buon posto per comprare merci e anche per bere una pinta e rilassarsi.\n\nOra, se per caso vai proprio da quella parte, ti dispiacerebbe portare questo fagotto di pelli di crocolisk a James Halloran, il conciatore?\n\nLo farei io, ma mia moglie ultimamente è proprio di cattivo umore, e vorrei rimandare il più possibile il momento di affrontarla.", "Salve, {class}. Posso interessarti con un paio di stivali? Magari qualche pelle appena conciata?", "Mmm, questo è di Einar, giusto? È quasi una settimana che non mi consegna le pelli di persona. Di sicuro ci sono di mezzo screzi con la moglie!\n\nForse un giorno manderò mia moglie a parlare con Sida...", 0x4ccc1397, 0x32b2e18d, 0xd17d7bf3, 0x65e51f86, 0xbde24237, "....." },
  [470] = { "Frugare nella melma", "Una delle melme dell'Ironbeard's Tomb ha la borsa di Sida: recuperala e riportagliela a Menethil Harbor.", "Durante la mia visita settimanale all'Ironbeard's Tomb sono stata attaccata da melme orribili e gocciolanti! Naturalmente sono andata nel panico.\n\nHo tirato la mia borsa contro una di loro, ma non è servito a niente! La melma l'ha risucchiata e basta... Per fortuna mi ha dato abbastanza tempo per scappare.\n\nLa brutta notizia è che ho davvero bisogno di quello che c'è nella borsa!\n\nNon so contro quale melma ho tirato la borsa: sembravano tutte uguali! L'Ironbeard's Tomb è a nord-est di qui, vicino a Dun Modr. Grazie mille!", "Hai trovato la mia borsa?", "Oh, grazie, {name}! Temevo di averla persa per sempre!\n\n<Svuota in fretta per terra il contenuto della borsa coperta di melma, prima di raccoglierlo.>\n\nMmm, questo non mi serve più a molto, ma se lo lavi sono sicura che potrai usarlo.", 0x775c3dbd, 0xca612179, 0xa1442cd7, 0xffefe4fa, 0xf927327c, "....." },
  [471] = { "I doveri dell'apprendista", "Raccogli 6 Giant Crocolisk Skins e portale a James Halloran, a Menethil Harbor.", "Ho mandato il mio apprendista nelle paludi a scuoiare qualcuno dei nostri famosi crocolisk giganti delle Wetlands. Quando non è tornato, sono andato a cercarlo... Diciamo che non è stato un bello spettacolo.\n\nLa levatrice dice che potrebbe cavarsela, ma nel frattempo mi servono comunque le pelli!\n\n...Se ti va di uccidere qualcuno di quei bruti in più, non mi opporrei, dopo quello che hanno fatto. Trovi i coccodrilli a nord lungo la costa, oltre le catapecchie dei murloc.", "Il mio apprendista è come un figlio per me. Sarà dura per lui vivere con una gamba sola.\n\nAh, {name}, come va? Hai le mie pelli?", "Mmm... Non è che ti interesserebbe diventare <mio/mia> apprendista, vero?\n\nAh! No, sto scherzando. Innanzitutto sei troppo <vecchio/vecchia>. E poi, a guardarti, sembra che tu abbia altre ambizioni nella vita. Comunque, sono ottime pelli quelle che hai procurato, e saprò farne buon uso.", 0x574671c8, 0xeda0e52b, 0xb121762e, 0xfe757fb5, 0x2c27a8df, "....." },
  [472] = { "La caduta di Dun Modr", "Cerca Longbraid vicino al paese di Dun Modr.", "Dun Modr è caduta in mano ai Dark Iron Dwarves!\n\nLe mie ferite sono gravi, {class}. Quasi tutto il reggimento è stato ucciso! Quei delinquenti dei Dark Iron ci hanno attaccati prima che potessimo riorganizzarci dopo l'imboscata al Thandol Span.\n\nIl nostro capo, Longbraid, ha suonato il corno della ritirata. Mentre lasciavamo il paese, un'ascia vagante mi ha colpito alla schiena. Poi è stato tutto buio.\n\nMi sono svegliato qui a Menethil, ma temo per i miei compagni. La speranza arde ancora in me. Forse Longbraid è ancora vivo! Vedi se riesci a trovarlo vicino a Dun Modr, {race}!", nil, "Quale prode {class} manda notizie da Menethil? Ah, {name}, ti chiamano.\n\nPorti speranza in una situazione disperata. È davvero una bella notizia che il giovane Harlo sia sopravvissuto. Durante la fuga è stato ferito gravemente. Abbiamo avuto pochissimo tempo per mandarlo via in groppa all'unico destriero rimasto al reggimento.\n\nMa ora siamo in una situazione pericolosa. Dun Modr è caduta e siamo solo l'ombra del grande reggimento che eravamo.", 0x2480801e, 0x9ccb757d, 0xd17a7577, nil, 0x4bca7f5e, "...m." },
  [473] = { "Rapporto a Captain Stoutfist", "Parla con Captain Stoutfist.", "{name}. Il clan di orchi Dragonmaw mostra la sua forza non solo ad Algaz.\n\nCaptain Stoutfist ha chiesto di parlare con chi è disposto ad aiutare contro questi orchi. È dentro la fortezza, nella sala di guerra.", nil, "{name}. Valstag mi ha informato dei tuoi successi passati contro i Dragonmaw Orcs a Dun Algaz. Hai del valore, {race}.\n\nE ho un compito per te.", 0x738d103f, 0x4a1d9b30, 0x08a06865, nil, 0x4b813de0, "...m." },
  [474] = { "Sconfiggere Nek'rosh", "Uccidi Chieftain Nek'rosh.\n\nPorta la Nek'rosh's Head a Captain Stoutfist.", "Ora che le catapulte sono bruciate, trova e uccidi Chieftain Nek'rosh.", "Hai ucciso Nek'rosh?", "Ottimo lavoro, {name}. Hai inferto un colpo pesante al clan di orchi Dragonmaw. Potrebbero non riprendersi mai più. E la distruzione di quelle catapulte ha messo al sicuro Menethil Harbor.\n\nHai dei meriti, {race}, e il regno di Ironforge ricompensa chi lo serve bene.", 0x3c477488, 0xef5f3349, 0xd9531c6b, 0x94b6673f, 0xe065ceac, "....." },
  [475] = { "Una brezza inquietante", "Cerca Gaerolas Talvethren, a Starbreeze Village.", "Una brezza inquietante soffia nella foresta.\n\nGaerolas Talvethren è il Great Warden dei Druids of the Talon in letargo nel Ban'ethil Barrow Den. Il suo dovere di protettore scelto dei dormienti è garantire la loro sicurezza, perché il loro patto con Ysera resti rispettato.\n\nMa le notizie di Gaerolas tardano, e comincio a preoccuparmi. Vai a est, a Starbreeze Village, e riportami un rapporto di Gaerolas, così potrò mettere a tacere le mie paure, sapendo che i miei fratelli sognanti dormono al sicuro.", nil, "Siano ringraziati gli spiriti della foresta, sei qui! Sapevo che Athridas avrebbe sentito il pericolo e mandato aiuto.", 0x42437c5a, 0x464394e4, 0xaf4e302f, nil, 0x78e5478b, "...m." },
  [476] = { "La corruzione dei Gnarlpine", "Torna da Athridas Bearmantle, a Dolanaar.", "La tribù Gnarlpine è stata corrotta!\n\nI furbolg, un tempo pacifici, si sono rivoltati contro i protettori della foresta. Mi hanno teso un'imboscata mentre partivo per il Ban'ethil Barrow Den e poi hanno saccheggiato Starbreeze Village. Ursal the Mauler, il loro capotribù, usa i poteri malvagi del Fel Moss per farli impazzire.\n\nSono troppo ferito per tornare da Athridas a portargli questa grave notizia. Il compito spetta a te, giovane {class}. Possiamo solo sperare che i Gnarlpine impazziti non siano ancora arrivati al Ban'ethil!", nil, "Per le stelle! Questo è davvero molto inquietante!", 0x333dcbf7, 0xc82e6f6a, 0xda446a65, nil, 0x5e5ae3c1, "...m." },
  [483] = { "Le reliquie del risveglio", "Recupera le Relics of Wakening e portale ad Athridas Bearmantle, a Dolanaar.", "Sono stati visti invasori Gnarlpine devastare il Ban'ethil Barrow Den, a ovest.\n\nI druidi dormienti resteranno intrappolati nell'Emerald Dream per l'eternità, ignari della loro sorte, se non li aiutiamo. Il delicato rituale del letargo non può essere interrotto senza le Relics of Wakening.\n\nVai al Den e recupera il Raven Claw Talisman, la Black Feather Quill, il Sapphire of Sky e la Rune of Nesting. I druidi li custodiscono in forzieri sacri. Riportameli e preparerò il rituale del risveglio.", "{name}, i Druids of the Talon rapiti resteranno intrappolati per sempre nell'Emerald Dream se non recuperiamo le Relics of Wakening dal Ban'ethil Barrow Den, a ovest.\n\nOgni minuto di ritardo avvicina di un passo la loro sorte alla rovina eterna.", "Ci sei <riuscito/riuscita>, giovane {class}! Ben fatto. E appena in tempo, direi.", 0x269464e3, 0x956f3a24, 0x3fcb2591, 0xa4a2f2fb, 0x69323857, "....." },
  [484] = { nil, "Procura $N1 Young Crocolisk Skins per James Halloran, a Menethil Harbor.", "Sono James Halloran, il conciatore. Le mie pelli di crocolisk conciate sono ricercate ovunque, e i carichi partono in nave per porti di tutto il mondo.\n\nHai conosciuto Einar? È uno dei cacciatori che mi portano le pelli di crocolisk.\n\nSono un po' a corto delle pelli più morbide, quelle dei crocolisk giovani.\n\nVisto che ne ho poche, ti pagherò profumatamente per una pila di pelli. Trovi i coccodrilli giovani nelle acque appena fuori dal paese.", "{name}, giusto? Hai le mie pelli?", "Bel lavoro, {name}. La qualità di queste pelli è superba. Dovrò metterle a conciare il prima possibile. Oh, ma prima di farlo, c'è un altro lavoro da fare di cui credo potresti occuparti tu.", nil, 0x2f1b74bf, 0xe4e1e7f0, 0x268e2dce, 0x1944bc7f, "m...." },
  [486] = { nil, "Uccidi Ursal the Mauler e torna da Athridas Bearmantle, a Dolanaar.", "Ora è giunto il momento di salvare i Druids of the Talon. Se falliamo adesso, {name}, resteranno persi nel sonno per sempre.\n\nPreparerò le Relics of Wakening ed eseguirò il rituale. Perché il mio lavoro abbia effetto, la bestia maledetta responsabile di questa orribile situazione deve essere uccisa. Solo allora il rituale sarà completo.\n\nÈ stato Ursal the Mauler a interferire con la chiamata dei nostri fratelli, ed è Ursal the Mauler che ora deve pagare perché siano liberati. Vai alla Gnarlpine Hold, a sud-ovest, e uccidilo.", "I nostri fratelli non possono essere risvegliati finché Ursal the Mauler non sarà ucciso, {name}.", "{name}, hai dimostrato di essere {class} di grande valore e capacità. Chi segue la via dell'onore con la tua stessa sicurezza troverà di certo grande gloria in questo mondo, {race}.\n\nChe gli spiriti della foresta ti proteggano ovunque ti portino i tuoi viaggi.", nil, 0xa1727d4c, 0x3474dc51, 0xd8fc3fa7, 0x6273f6f3, "m...." },
  [487] = { "La strada per Darnassus", "Uccidi 6 Gnarlpine Ambushers e torna da Sentinel Amara Nightwalker, fuori Dolanaar.", "La strada per Darnassus deve restare sicura. I viaggiatori diretti da Dolanaar a Darnassus riferiscono di attacchi spietati da parte dei furbolg corrotti della tribù Gnarlpine.\n\nOgni giorno notizie importanti e merci viaggiano da e per Darnassus lungo questa strada. Non possiamo permettere che una banda di pagani fuorilegge terrorizzi la gente.\n\nPrendi le armi in nome della foresta sacra, {class}. La loro tana è da qualche parte sotto questo punto d'osservazione. Uccidi 6 di questi Gnarlpine ambushers e torna a riferirmi.", "La strada non è ancora sicura, {class}. Vai, uccidi 6 Gnarlpine Ambushers e torna da me.", "Hai servito bene la brava gente di Dolanaar e di Darnassus, prode {class}. Come membro delle Sentinel di Teldrassil, rendo onore ai tuoi sforzi.", 0x02e02bee, 0x82c785f5, 0x0083a597, 0x0910083a, 0x48dc3b9e, "....." },
  [488] = { "Gli ordini di Zenn", "Porta a Zenn Foulhoof, fuori Dolanaar, 3 Nightsaber Fangs, 3 Strigid Owl Feathers e 3 pezzi di Webwood Spider Silk.", "<Ansioso/Ansiosa> di lavorare, vedo. Per tua fortuna non passa giorno senza che io desideri avere {class} alle prime armi che esegua i miei ordini.\n\nVedi, {name}, posso renderti molto felice e darti cose che non hai mai sognato di avere. Ma perché succeda, devi portarmi certi oggetti.\n\nI miei affari nella foresta richiedono spesso certi. . . reagenti. Procurami 3 Nightsaber Fangs, 3 Strigid Owl Feathers e 3 pezzi di Webwood Spider Silk.\n\nChe resti il nostro piccolo segreto, {race}.", "Hai lavorato come un'ape operosa, {name}? Ti stavo aspettando con quello che mi serve.", "Ah ah! Ben fatto davvero.\n\nChi l'avrebbe mai detto che io, Zenn Foulhoof, avrei avuto {race} ai miei ordini? Non io, di certo! Ma così va il mondo... questo nostro amato mondo è pieno di sorprese.\n\nTre urrà per gli ingenui e i creduloni!", 0x3c90fdc2, 0x717fc8a2, 0xccae3948, 0xb7e65c4d, 0x8c124f4e, "....." },
  [489] = { "Cerca la redenzione!", "Raccogli 3 Fel Cones e consegnali a Zenn Foulhoof, fuori Dolanaar.", "Il Council of the Forest ha saputo che hai aiutato Zenn Foulhoof. Il satiro è un nemico della foresta. Da {race} quale sei, dovresti sapere che non si profana la foresta uccidendo le creature della natura.\n\nDevi riscattarti agli occhi del Council se vuoi restare <amico/amica> di Teldrassil.\n\nDai una lezione a Foulhoof e sarai <redento/redenta>. Le Fel Cones sono semi corrotti che cadono dagli alberi. Emanano un fumo verde.\n\nDagliene qualcuno. Penserà che gli hai portato uno spuntino innocuo.", "Cos'hai per me, {name}? Uno spuntino delizioso, immagino?", "Ah, che dolcezza di {race}! Sapevo che mi saresti <tornato/tornata> utile!", 0x713743b3, 0x0ce5bdd5, 0x26b28abb, 0x2249cbce, 0x33294b57, "....." },
  [493] = { nil, nil, nil, "Hai qualcosa per me?", nil, nil, nil, nil, 0xa03be4c2, nil, "mmm.m" },
  [500] = { "Taglia sui Crushridge", "Raccogli 9 Dirty Knucklebones dagli ogre Crushridge delle Alterac Mountains. Portali al Marshal Redpath, a Southshore.", "Gli ogre Crushridge hanno scavato un tumulo nelle Alterac Mountains, vicino alla città in rovina di Alterac. E i miei esploratori mi dicono che hanno occupato anche quelle rovine.\n\nNon possiamo lasciare che si mettano comodi lassù; se si sentono al sicuro dove sono, il loro prossimo passo sarà scendere sulle colline, e ce li ritroveremo davanti alla porta!\n\nVa' a nord, nelle Alterac Mountains, e dai la caccia agli ogre. Portami i Dirty Knucklebones che hanno addosso e guadagnerai una bella taglia.", "{name}, stai ancora dando la caccia agli ogre? Hai le nocche che ti ho chiesto di raccogliere?", "Molto bene, {name}. Devi aver fatto a pezzi un bel mucchio di ogre per avere tutte queste nocche.\n\nQuesto dovrebbe tenerli lontani da noi. Almeno per un po'.", 0xd5997ddd, 0x11f570e0, 0x38ecbe34, 0x43214dd1, 0x3fa88dba, "....." },
  [504] = { "I guerrafondai Crushridge", "Uccidi 15 Crushridge Warmonger, poi torna dal Marshal Redpath, a Southshore.", "Ora che hai assaggiato gli ogre Crushridge, voglio che tu gliele dia di santa ragione...\n\nEntra nelle Ruins of Alterac e cerca i Crushridge Warmonger. Voglio che tu ne abbatta un buon numero: è l'unico modo perché quei bruti imparino a stare lontani dal territorio dell'Alliance.", "Hai altri Warmonger da uccidere, {name}. Dovresti essere su quelle montagne a svolgere il tuo compito, non quaggiù con l'arma riposta.", "Molto bene. Ecco la tua ricompensa.\n\nE mentre davi la caccia a quei Warmonger, com'era la città di Alterac? In pessime condizioni, immagino. Gli ogre non sono noti per la loro pulizia.\n\nPer fortuna i tuoi sforzi aiuteranno a tenerli lontani da Southshore.", 0x9f73d70b, 0x78abd8ad, 0xc39d2e2e, 0xb352d2cf, 0x9c185a7e, "....." },
  [505] = { "Gli assassini del Syndicate", "Uccidi 12 Syndicate Footpad e 8 Syndicate Thieves, poi torna dal Magistrate Henry Maleb, a Southshore.", "Sono il nuovo magistrato di Southshore, nominato di recente dopo l'assassinio del magistrato precedente. Gli assassini non sono mai stati trovati, ma dalle nostre indagini siamo quasi certi che siano stati assoldati dal Syndicate, una banda di ladri guidata da nobili malvagi del regno ormai caduto di Alterac.\n\nIl Syndicate ha un accampamento a nord di Tarren Mill, occupata dall'Horde, e i nostri ultimi indizi portavano a quell'accampamento. Uccidi i membri del Syndicate che trovi lì.", "Hai ucciso quei delinquenti del Syndicate, spero?", "Grazie, {name}. Anche se potrebbero ancora aggirarsi da queste parti, speriamo che alcuni dei ladri e dei tagliaborse che hai ucciso fossero responsabili della morte dell'ultimo magistrato. Ma anche se non lo fossero, il Syndicate è una piaga per questa terra e una macchia per la razza umana.\n\nLa loro morte è gradita a Southshore.", 0xbf89c9ca, 0xd1477bb0, 0xc4b88ed5, 0x7a6d6e71, 0xe4e50f44, "....." },
  [512] = { "Morti nobili", "Porta 7 Alterac Signet Rings al Magistrate Maleb, a Southshore.", "Temo che i capi del Syndicate vogliano la rovina di Southshore. Dobbiamo colpire duramente questi capi prima che i loro piani si realizzino.\n\nEntra nelle rovine di Strahnbrad, nelle Alterac Mountains a nord. Pensiamo che il Syndicate usi la zona come quartier generale.\n\nSappiamo che questa banda di tagliagole è guidata da ex nobili di Alterac. Potrebbero nascondersi tra i normali agenti del Syndicate, ma saprai di aver ucciso un nobile dall'anello con sigillo che porta.\n\nPortami quegli anelli con sigillo.", "Hai dato la caccia al Syndicate? Hai quegli anelli?", "Privare il Syndicate dei suoi nobili gli toglierà la capacità di agire in modo deciso e lo ridurrà a nient'altro che una banda di delinquenti.\n\nServi bene la tua Alliance, {name}.", 0x6efdc3b1, 0xc5b7714b, 0x5eabc548, 0x18c6efdc, 0x8a695cc5, "....." },
  [514] = { "Lettera per Stormpike", "Porta la Cleverly Encrypted Letter al Prospector Stormpike, a Ironforge.", "Ho un collega a Ironforge che potrebbe aiutare a decifrare questa lettera. Va' alla biblioteca nella Hall of Explorers di Ironforge e parla con il Prospector Stormpike. Digli che ti mando io e mostragli la lettera. Se c'è qualcuno a nord di Blackrock Spire capace di leggerla, è lui.", "Ti ha mandato Dibbs da Southshore, eh? Come se la passa quel vecchio topo di biblioteca?", "Ah, crittografia! Una mia specialità. Vediamo un po'...", 0x3a29aa39, 0x51d81fad, 0x84ef8753, 0x713c5edf, 0x43030dbb, "....." },
  [522] = { nil, "Porta l'Assassin's Contract al Magistrate Maleb, a Southshore.", "È un contratto per l'assassinio del Magistrate Henry Maleb. È stato sigillato e timbrato con ceralacca rossa, usando un anello con sigillo caratteristico.", "Sembri senza fiato! Hai qualcosa da riferire?", "<Maleb esamina il contratto.>\n\nQuesto spiega l'ultimo attacco a Southshore. Il Syndicate deve volere me, proprio come voleva l'ultimo magistrato!", nil, 0xd38982ba, 0x39e886c2, 0xd3e3d94d, 0xba35e005, "m...." },
  [523] = { "La fine del barone", "Porta l'Head of Baron Vardus al Magistrate Maleb, a Southshore.", "Il contratto che hai recuperato è firmato dal Baron Vardus, un nobile dell'ex regno di Alterac, noto per il suo cuore freddo e i suoi metodi brutali. Non mi stupisce che dietro ci fosse uno come il barone.\n\nTrova quest'uomo. Trovalo e consegnalo alla giustizia. Dev'essere tra i covi del Syndicate: forse tra le rovine di Strahnbrad, o forse nella valle a nord di esse.", "Il Baron Vardus non può credere che Southshore gli permetta di mandarci contro i suoi delinquenti impunemente. Voglio la sua testa!", "Grazie, {name}. La mia testa riposa un po' più tranquilla sapendo che quel furfante ha perso la sua.", 0xd825af65, 0x58cdb439, 0x25dbeae9, 0xbce9488d, 0xd03bb650, "....." },
  [526] = { nil, "Raccogli 5 Lightforge Ingots, poi torna da Glorin Steelbrow, nelle Wetlands.", "Forse in quel forziere avrai trovato un Lightforge Ingot, ma non basta per forgiare niente di decente!\n\nDovresti tornare là e cercarne altri. Forse i murloc intorno a quel relitto hanno dei Lightforge Ingots addosso.", "Hai trovato il lightforge iron che ti serve?", "Ah, li hai trovati! Ora battiamo questo lightforge iron e facciamone qualcosa di utile, eh?", nil, 0x2c181b7a, 0xa9406e02, 0x0a6e75bf, 0x67c1cb55, "m...." },
  [531] = { "La vendetta di Vyrin", "Porta la testa di Ol' Sooty a Vyrin Swiftwind, alla Farstrider Lodge.", "Luce! Non portare cose del genere nella Lodge... è antigienico, indicibile, in... in... antigienico!\n\nPortalo via di qui, vuoi? Nessuno vuole vedere il tuo piccolo trofeo insanguinato, davvero!", "Ottimo lavoro, {name}! Gliel'abbiamo fatta vedere! Ecco, dammi la testa e me ne occupo io.", "Grazie per avermi aiutato con il mio piccolo piano, {name}. Erano mesi che non vedevo l'ora di vendicarmi di quel ragazzino presuntuoso e pieno di sé, e direi che abbiamo fatto un buon lavoro! Tieni, prendi questo, te lo sei <guadagnato/guadagnata>.", 0xeb8bf51a, 0xcafffbbe, 0x90fd33a0, 0x31f709f1, 0x2e24ea10, "....." },
  [536] = { "Giù lungo la costa", "Uccidi 10 Torn Fin Tidehunter e 10 Torn Fin Oracle per il Lieutenant Farren Orinelle, a Southshore.", "Trasferito dalla guardia cittadina di Stormwind a Southshore, una città che a vederla andrebbe abbandonata... Puzza di porto giorno e notte.\n\nPer non parlare del vecchio Redpath... Vuole che mi occupi dei murloc. Ah!\n\nRiesco a malapena a trovare la voglia di andare in qualcuna delle sacche di quei pesci troppo cresciuti giù lungo il Western Strand. Se andassi tu al posto mio a occupartene, te ne sarei grato.", "Un'altra birra, per favore, l'ultima sembra proprio sparita!\n\nPer la Luce, quanto ancora dovrò restare bloccato qui?\n\nOh, sei tu, {name}. Hai già ucciso quei murloc?", "Spero che basti a convincere Redpath che ho... ah!... eseguito i suoi ordini e liberato Southshore dalla terribile e orribile minaccia dei temuti murloc! Perché non potrebbe esserci male più grande delle devastazioni di pesci troppo cresciuti!", 0x89675618, 0x07796c70, 0x0ee219d7, 0x9449d897, 0x06ffe0e5, "....." },
  [537] = { "Il consiglio oscuro", "Uccidi 4 Argus Shadow Mage.\n\nPorta l'Head of Nagaz al Magistrate Maleb, a Southshore.", "La lettera che mi hai portato è stata scritta da un essere che si fa chiamare Nagaz, membro dell'Argus Wake. Non so cosa sia questo Argus Wake, ma se sono alleati del Syndicate devono essere una minaccia.\n\nVoglio che tu trovi Nagaz e gli Argus Shadow Mage menzionati in quella lettera. Voglio che tu li trovi e li uccida.\n\nCerca negli Uplands, dove il Syndicate è più forte. Si trovano a nord di Strahnbrad.\n\nCon un po' di fortuna troverai lì questi emissari dell'Argus Wake.", "Hai trovato gli emissari di The Argus Wake?", "Ben fatto, {name}. L'Argus Wake non sembra un gruppo che vogliamo a capo del Syndicate.\n\nE anche se qui hai distrutto il loro capo, Nagaz era solo il servitore di un altro. L'Argus Wake potrebbe avere radici profonde in tutto il continente di Azeroth.\n\nO persino nel mondo intero.", 0xa17f6b61, 0xbe485ded, 0x8e5ad737, 0x79bde192, 0xbb1f9d27, "....." },
  [538] = { nil, "Parla con il Loremaster Dibbs, a Southshore.", "{name}. Se un lungo viaggio non ti spaventa, ho un compito per te, per aiutare ancora Stormwind ad arricchire la sua biblioteca.\n\nL'antico regno di Alterac cadde dopo la grande guerra, e possedeva una vasta collezione di libri. È una tragedia che la città sia in rovina, ma ancora più tragico è che tutto il suo sapere sia andato perduto! Dobbiamo recuperare ciò che possiamo.\n\nSouthshore è la città più vicina alle Ruins of Alterac. Va' lì e parla con il Loremaster Dibbs. Può indicarti le rovine e i libri che vi si possono trovare.", nil, "Ah sì, mi ricordo di Milton. Un topo di biblioteca, senza dubbio. Che caro.\n\nE ha ragione. Le Ruins of Alterac custodiscono ancora riserve di sapere che rischiano di andare perdute!\n\nOra ad Alterac vivono gli ogre, e non tengono molto all'istruzione superiore.", nil, 0x7e3967fe, 0x3b3b331d, nil, 0xb82f44b2, "m..m." },
  [540] = { "Preservare il sapere", "Porta 5 Recovered Tomes e il Worn Leather Book che contiene The Arm of Gri'lek al Loremaster Dibbs, a Southshore.", "Quegli ogre bestiali ora vivono tra le rovine di Alterac, e rabbrividisco al pensiero di cosa stiano facendo con i preziosi libri ancora lì. Devi recuperare ciò che puoi!\n\nEntra nelle Ruins of Alterac e cerca i tomi saccheggiati dagli ogre. Prendi tutto ciò che trovi e portamelo, ma cerca anche un libro in particolare: The Arm of Gri'lek. Contiene un antico sapere troll che devo imparare, e le Ruins of Alterac sono l'ultimo luogo noto in cui si trovava una copia integra di questo libro.", "Vorrei poter perlustrare anch'io le rovine, ma temo che queste ossa non reggerebbero alla salita su per le montagne. Comunque, come procede la tua caccia al sapere, {name}?", "Oh, li hai presi! Splendido! Devo cominciare subito a studiare l'Arm of Gri'lek!", 0x6bc8fd3c, 0x308d0cb3, 0xeffbce9e, 0xba406758, 0xfc6765c2, "....." },
  [542] = { "Ritorno da Milton", "Porta i Tomes of Alterac a Milton Sheaf, a Stormwind.", "Devo dedicare un po' di tempo allo studio del libro Arm of Gri'lek che mi hai portato, anche se sono sicuro che Milton non veda l'ora di aggiungere gli altri libri recuperati alla collezione di Stormwind.\n\nEcco i libri che hai raccolto nelle Ruins of Alterac, imballati e catalogati. Riportali a Milton Sheaf, a Stormwind, e sono sicuro che te ne sarà grato.", "{name}, sei <tornato/tornata>! Com'è andata la tua incursione ad Alterac? Hai riportato qualcosa?", "Oh, oh! Guarda qui! Non posso credere che siano sopravvissuti alla rovina di Alterac. E a tutti quegli ogre!\n\nGrazie, {name}. Grazie infinite! Hai aiutato a preservare il sapere umano e accresci lo splendore della Royal Library di Stormwind.", 0x8059ffd0, 0x62528f2b, 0xd177e73f, 0x5c8f0d76, 0x5e9286a2, "....." },
  [543] = { "La Perenolde Tiara", "Porta la Perenolde Tiara a Remington Ridgewell, a Stormwind.", "La Perenolde Tiara è un antico cimelio dei \"nobili\" Perenolde, la famiglia regnante di Alterac prima che quel regno cadesse in rovina. Si dice che sia stata realizzata da maestri gioiellieri di Ironforge e incastonata con i più bei smeraldi.\n\nQuando Alterac fu distrutta, la tiara andò perduta, ma si dice che un Ogre Mage, Grel'borg the Miser, l'abbia trovata e ora vaghi per le Ruins of Alterac in cerca di altri tesori.\n\nVorremmo che tu recuperassi la tiara per noi.", "Saluti, {name}. Cerca di non calpestarmi gli orli dei pantaloni. Questo abito è stato appena confezionato.", "Ah, splendido. Andrà pulita, naturalmente, ma ti sei davvero <superato/superata>, {name}. Farò preparare la tiara da qualcuno e la farò inserire nella nostra collezione immediatamente.\n\nCome sono sicuro converrai, la nostra gratitudine è grande quanto la nostra collezione.", 0xf44affa1, 0x291669a4, 0x03800364, 0x83074589, 0x1b1f74bf, "....." },
  [551] = { "L'Ensorcelled Parchment", "Porta l'Ensorcelled Parchment al Loremaster Dibbs, a Southshore.", "Questa pergamena è incantata con un sortilegio che la rende indecifrabile. Ma una parola in cima al foglio si riesce a leggere:\n\nNagaz", "Oh. Hai qualcosa che vorresti farmi vedere? Qualche frammento di sapere raccolto lassù sulle montagne, spero...", "Altre note cifrate?\n\nVorrei avere il talento per decifrare tutti gli strani frammenti di scrittura che arrivano da Alterac. Ma temo di non avere le conoscenze.", 0x531d0156, 0x50b9c1c2, 0xa92d237b, 0xd1eeba76, 0x14f969f5, "....." },
  [554] = { "La decifrazione di Stormpike", "Porta l'Ensorcelled Parchment al Prospector Stormpike, a Ironforge.", "Il Prospector Stormpike è un maestro della decrittazione e della decifrazione. Se gli porti la pergamena che hai trovato, con un po' di fortuna riuscirà a capirla. Stormpike al momento studia nel quartier generale dei Prospector, a Ironforge.\n\nE quando lo vedi, digli che hai parlato con me: ultimamente gli sto mandando parecchio lavoro.", "Altre interruzioni?\n\nAh, questa pergamena è ricoperta da un incantesimo molto intricato e finemente intessuto. Posso scioglierlo, certo, ma ci vorrà tempo. E il tempo per me è molto prezioso...\n\nForse te la compro e basta?", "Una saggia decisione. Non credo che ci sia altro studioso oltre a me con le capacità di tradurre questa pergamena. E se il suo contenuto si rivelerà interessante, non temere. Ti manderò a chiamare.", 0xa276f0c0, 0x1b2f4bfd, 0x3cd91bcf, 0x12b5e1b2, 0x2ec976df, "....." },
  [555] = { nil, "Porta 10 pezzi di Turtle Meat e un po' di Soothing Spices allo Chef Jessen, a Southshore.", "Se c'è una cosa che imparerai di Southshore, è che abbiamo alcune delle migliori cucine a nord di Stormwind!\n\nPrendi la mia ricetta segreta della Turtle Bisque, per esempio. Ho conosciuto gente venuta persino da Darkshire solo per gustarne una ciotola. A proposito, ultimamente non sono riuscito a prepararne. Un tempo salivo io stesso oltre Dalaran fino al Lake Lordamere a cacciare Snapjaw, ma ora è troppo pericoloso. Se mi porti un po' di Turtle Meat dagli Snapjaw a nord e delle Soothing Spices, te ne preparo un po'!", "Fortuna con gli ingredienti? Te lo dico io, questo territorio non è più il luogo pacifico di un tempo. Ah, se solo questi disordini non fossero mai accaduti. . .", "Saranno tutti felicissimi: la Soothing Turtle Bisque dello Chef Jessen torna in tavola!", nil, 0xd9437495, 0x8281c5e6, 0xf16cfe59, 0xe0721028, "m...." },
  [559] = { "La prova di Farren", "Raccogli 10 Murloc Heads dai murloc del Western Strand per il Lieutenant Farren Orinelle, a Southshore.", "Ci crederesti, {name}? Redpath non è soddisfatto di tutti i murloc che abbiamo ucciso (oh, non fare tanto il modesto, ci hai messo mano anche tu). Ora vuole che gli porti la prova dei morti, tagliando fredde e viscide teste di murloc da sottoporre alla sua approvazione.", "Mi hai preso quelle teste, {name}?", "Oh, per l'amore della Luce... sgocciolano per terra.\n\nIo non sopporto toccare quelle cose. I pesci vanno benissimo, ma quando gli spuntano le gambe e cominciano a camminare... Non mangio pesce da settimane, te lo dico io, e a Southshore questo significa non mangiare granché.", 0x45ee0c0c, 0x24ec62a0, 0xeee029fe, 0xa398efff, 0x06f12d58, "....." },
  [560] = { "La prova di Farren", "Consegna il sacco di teste di murloc al Marshall Redpath, a Southshore.", "Sai, {name}, preferirei davvero non portare queste teste... Visto che ormai ci hai preso la mano, ti dispiacerebbe consegnarle a Redpath al posto mio?", "Salute. Sei qui per contribuire a mantenere la sicurezza di Southshore?", "Fai le commissioni per Farren, vero, <ragazzo/ragazza>?\n\nSe hai aiutato Farren a procurare queste teste, allora grazie. Southshore ha bisogno di gente che lavori sodo e di impegno per restare protetta.", 0x45ee0c0c, 0x03a74911, 0xd2edee81, 0xe440eb18, 0x24ca6f34, ".....", nil, nil, nil, nil, 0xd82c0a9f },
  [561] = { "La prova di Farren", "Parla con il Lieutenant Farren Orinelle, a Southshore.", "Ti prego, informa il Lieutenant Orinelle che vorrei che concentrasse di nuovo i suoi sforzi sui naga che infestano l'Eastern Strand. Quando avrà dei risultati, digli di venire a farmi rapporto di persona.", nil, "I naga, eh? Redpath deve aver appena ricevuto le mie stesse informazioni... Ah! Non otterrà una promozione grazie alle mie fatiche. Lascia che ti spieghi.", 0x45ee0c0c, 0x6ecedb91, 0xdd4ac0b9, nil, 0x377b18a1, "...m." },
  [562] = { "Verso Stormwind!", "Uccidi 10 Daggerspine Shorehunter e 10 Daggerspine Siren per il Lieutenant Farren Orinelle, a Southshore.", "Il mio ex mentore nella guardia cittadina di Stormwind mi ha mandato a dire che l'Alliance High Command comincia a preoccuparsi della minaccia dei naga. Da quel che ha sentito, ci sono buone possibilità di promozione, o almeno di trasferimento, per chi si dimostra utile in questo campo.\n\nC'è solo un piccolo problema... Non sono in grado di affrontare i naga, {name}. Oh, certo, potrei sedare una rissa tra ubriachi in taverna, o portar via un mendicante molesto, ma i naga sono troppo per me. Devi aiutarmi, {name}!", "Ho una lettera pronta da mandare al Major Samuelson, a Stormwind. Mi servono solo i risultati.", "Con i naga sconfitti a Southshore, il mio trasferimento è assicurato. Rivedrò Stormwind... lontano da questo porto abbandonato dalla Luce.", 0x2c3969ea, 0x95d8c908, 0xcf1a959e, 0x0faabf4d, 0x6f8fff5d, "....." },
  [563] = { "Trasferimento", "Consegna il rapporto di Farren al Major Samuelson, nello Stormwind Keep.", "Non dovrebbe essere un problema far vedere il mio rapporto. Il nuovo capitano della guardia, il Major Samuelson, è stato il mio mentore quando ero di stanza a Stormwind. Dovrebbe dargli una scusa più che sufficiente per farmi trasferire di nuovo in città. Però ho bisogno che tu gli porti il mio rapporto... non vorrei che il vecchio Redpath se ne accorgesse.", "Salute. La guardia cittadina di Stormwind può esserti d'aiuto?", "Cos'è questo? Ah... quindi il mio diligente allievo si è dedicato al problema dei naga a Southshore. Grazie per avermelo portato, ne terrò certamente conto quando rivedrò le assegnazioni del personale il mese prossimo.", 0x90f1f63b, 0x0b3f5dd6, 0x78c69450, 0xa222ff6a, 0xfb5790a8, "....." },
  [564] = { "Una minaccia costosa", "Darren Malvew di Southshore vuole che tu uccida 8 Mountain Lion e 10 Hulking Mountain Lion.", "Non c'è niente che mi irriti di più che perdere questi splendidi cavalli. E credimi, ne abbiamo persi parecchi tra quei maledetti non morti, quella dannata banda del Syndicate e tutti gli altri farabutti buoni a nulla che ficcano il naso da queste parti.\n\nMa giuro sulla tomba del mio vecchio nonno che non c'è minaccia più grande per i nostri cavalli di quei Mountain Lion lassù ad Alterac. Scendono sempre dalle colline e mi rendono la vita difficile!\n\nTi credi <un/una> <eroe/eroina>? Allora va' a fare qualcosa!", "I Mountain Lion ci ammazzano i cavalli a destra e a manca, e tu sei qui a voler chiacchierare del tempo e di chissà cos'altro.\n\nDovrei andarmi a cercare un vero eroe. Più ammazzare e meno chiacchierare.", "Che bella notizia! Avrei dovuto trovarmi <un/una> <vero/vera> <eroe/eroina> di guerra fin dal primo giorno per occuparmi di quelle bestie. Avresti reso fiero il tuo papà, {name}.", 0xb2ece6a4, 0x33273d5d, 0x03e26472, 0xd480338a, 0x5d61201c, "....." },
  [565] = { nil, "Porta a Bartolo Ginsetti di Southshore una Bolt of Wool, un Hillman's Cloak, del Fine Thread e 10 ciuffi di Yeti Fur.", "Io, il grande Bartolo, creerò per te il mantello di pelliccia di yeti famoso in tutto il mondo e celebre in tutta l'Alliance!\n\nGira il pianeta e trovati un mantello migliore, ti sfido. Oh, aspetta, cosa dici, piccolo membro della razza {race}? \"Bartolo, non esiste mantello più bello!\" Sì, sì! Questo l'ho già sentito.\n\nBartolo ha bisogno di una Bolt of Wool, di un Hillman's Cloak fatto da un abile conciatore, di Fine Thread e, naturalmente, di Yeti Fur! Portami questi oggetti e sarai un cliente felice!", "Allora sei <tornato/tornata> dal grande Bartolo. Forse hai finito di raccogliere i materiali per il tuo Yeti Fur Cloak? O forse ti piace soltanto crogiolarti nella grandezza di me, Bartolo!", "Ora è il momento che il grande Bartolo faccia la sua magia! Non mi serve il bastone di un mago, né la verga di un incantatore. Perché io, il grande Bartolo, faccio magie con un semplice ago e filo!", nil, 0x733020fd, 0x67d80369, 0x82f1db22, 0x9ffce924, "m...." },
  [567] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [579] = { "La biblioteca di Stormwind", nil, nil, "King Anduin ha dato grande importanza all'istruzione e ha quindi stanziato fondi per mettere a disposizione del pubblico copie di vari tomi e scritti. È molto semplice. Mi porti un buono della biblioteca e io posso darti una copia di uno dei libri disponibili.", "Qualcuno di questi titoli ti interessa, {name}?", 0x308ed743, nil, nil, 0xccf61e18, 0x71324ab5, ".mm.." },
  [631] = { "Il Thandol Span", "Rhag Garmason vuole che tu trovi Ol' Rustlocke.", "Un'esplosione tremenda ha rimbombato tra le colline. È stato orribile, te lo dico io!\n\nBravi soldati sono morti difendendo il Thandol Span. Longbraid dice che ci vendicheremo dei Dark Iron prima che sia finita.\n\nMa siamo messi male, e di rinforzi non se ne vedono. Longbraid ha mandato Ol' Rustlocke a esplorare il ponte orientale per vedere se potevamo metterlo al sicuro.\n\nSono passati giorni. Con Dun Modr sotto assedio non abbiamo uomini per cercarlo.\n\nForse tu puoi trovarlo...", nil, "Esamini il piccolo cadavere nanico. Inciso sull'elmo leggi chiaramente: Ebenezer Rustlocke.", 0x3e71d80d, 0x65e8a88f, 0xe1ea688d, nil, 0xbdd11f16, "...m." },
  [632] = { "Il Thandol Span", nil, nil, nil, nil, 0x3e71d80d, nil, nil, nil, nil, ".mmmm" },
  [633] = { "Il Thandol Span", "Distruggi il deposito di esplosivi.", "Cielo, no! Povero Rustlocke. È proprio una tragedia.\n\nNon dobbiamo lasciare che la sua morte sia vana. Questa pergamena che hai trovato indica che Kam Deepfury, la mente dietro l'attacco originale, ha fatto nascondere un deposito di esplosivi appena oltre il Thandol Span, negli Arathi Highlands.\n\nSe quegli esplosivi arrivano al ponte, la nostra principale via di rifornimento verso nord sarà tagliata! Il deposito va distrutto, {name}! Torna da me quando avrai compiuto la missione.\n\nSei la nostra unica speranza.", "Il deposito di esplosivi va distrutto!", "Il ponte rimasto è salvo! Hai reso un grande servizio a King Magni e alla gente di Khaz Modan.\n\nOra, se solo riuscissimo a resistere abbastanza a lungo perché arrivino i rinforzi...", 0x3e71d80d, 0xb3f61268, 0xc3ede072, 0x51d8635c, 0x8b545d8f, "....." },
  [634] = { "Appello all'Alliance", "Cerca Captain Nials a Refuge Pointe.", "Ti chiedo un altro piccolo favore, {class}. Aspettiamo le riserve di Ironforge. Ma Roggo sa di un accampamento dell'Alliance a nord, negli Arathi Highlands, a Refuge Pointe.\n\nVai là e cerca Captain Nials. Chiedi al buon capitano se l'Alliance può concederci qualche soldato per aiutarci a riconquistare Dun Modr e il Thandol Span.", nil, "Le mie condoglianze a Longbraid e ai suoi coraggiosi soldati. La notizia della tragedia del Thandol Span e della caduta di Dun Modr mi pesa sul cuore.\n\nMa Stromgarde è caduta! Per questo siamo qui a Refuge Pointe. Dobbiamo riconquistare la nostra grande città.\n\nL'onore e il dovere ci impongono di non lasciare gli Highlands finché Stromgarde non alzerà di nuovo il possente stendardo del re. Manderò a dire a Longbraid che dovrà cavarsela da solo...", 0xad9b0160, 0xb6fee4d4, 0x8240441f, nil, 0xa65d819b, "...m." },
  [647] = { nil, "Porta il MacKreel's Moonshine a Brewmeister Bilger, a Southshore.", "Ieri sera ho bevuto parecchio del vecchio Moonshine! Longbraid mi farebbe la pelle se sapesse che sono svenuto durante il mio turno di guardia.\n\nLa zucca mi fa un male cane. Sembrava che una brigata intera di macchine d'assedio mi passasse sopra, con tutto quel rombo.\n\nOh, cielo, guarda che ora è! Ho promesso a Brewmeister Bilger, a Southshore, che avrei saldato il mio debito mandandogli del Moonshine.\n\nMa mancano solo 15 minuti prima che sia in ritardo! Gli porteresti questa partita, per favore? E sbrigati!", "Che si dice, {race}?", "Ah, niente come il Moonshine di Foggy MacKreel per scaldarti in una giornata fredda! E io che pensavo che quel briccone sarebbe stato di nuovo in ritardo con i conti. Grazie, amico! Grazie davvero!", nil, 0x674a14d5, 0x270bf03c, 0x35f07d1b, 0x31b8acb8, "m...." },
  [657] = { "Indizi di una nuova piaga?", nil, nil, nil, nil, 0xf6153188, nil, nil, nil, nil, ".mmmm" },
  [658] = { "Indizi di una nuova piaga?", nil, nil, nil, nil, 0xf6153188, nil, nil, nil, nil, ".mmmm" },
  [659] = { "Indizi di una nuova piaga?", "Trova Quae e Kinelory vicino alla Go'Shek Farm, nelle Arathi Highlands.", "Salute, e ben <trovato/trovata>, {name}. Guido un gruppo di avventurieri che indaga su strani avvenimenti in questa zona.\n\nMio cugino a Hillsbrad ha da poco dovuto sopprimere il suo cane Stanley, perché l'animale era misteriosamente cresciuto fino a dimensioni enormi e aggrediva ferocemente chiunque gli si avvicinasse.\n\nCredo che ci siano di mezzo i non morti, e cerchiamo segni che lo dimostrino.\n\nDue miei compagni, Quae e Kinelory, sono andati alla Go'Shek Farm nelle Arathi Highlands e non si fanno sentire da giorni. Li troveresti per me? Comincio a preoccuparmi.", nil, "Cerca di fare meno rumore possibile, <viaggiatore/viaggiatrice>.\n\nAgli orchi non piace essere spiati, e in questa fattoria c'è più di quanto sembri.", 0xf6153188, 0x43c42cf9, 0x9c68d408, nil, 0x99c14d17, "...m." },
  [660] = { "Indizi di una nuova piaga?", nil, nil, nil, nil, 0xf6153188, nil, nil, nil, nil, ".mmmm" },
  [661] = { "Indizi di una nuova piaga?", nil, nil, nil, nil, 0xf6153188, nil, nil, nil, nil, ".mmmm" },
  [690] = { "La richiesta di Malin", "Trova Skuerto a Refuge Pointe, nelle Arathi Highlands.", "Salute, {name}. Hai l'aria di chi cerca avventure, e io ho un compito da sbrigare.\n\nL'Archmage Trelane, il mio primo maestro, è fuggito da Stromgarde, nelle Arathi Highlands, non molto tempo fa, e mi ha chiesto di aiutarlo a recuperare alcuni degli oggetti che ha lasciato là.\n\nLa città è stata assediata, e lui ha cercato di difendere la Tower of Arathor, ma invano. Ho già degli agenti nelle Highlands, ma mi hanno chiesto di mandare altri aiuti. Ti interessa?", nil, "Allora ti ha mandato Malin? Non m'importa se Muradin fosse risorto dai morti e ti avesse portato qui su un drago. Sono occupato! Parla con Kryten se ti serve qualcosa.", 0x278d4eda, 0xc5c70302, 0x6378bf3d, nil, 0x49a0c989, "...m." },
  [697] = { "La richiesta di Malin", nil, nil, nil, nil, 0x278d4eda, nil, nil, nil, nil, ".mmmm" },
  [704] = { "La sorte di Agmond", "Porta 4 Carved Stone Urns a Prospector Ironband, a Loch Modan.", "L'ultimo rapporto che ho ricevuto da Agmond è preoccupante, e ancora di più ora che è morto! Diceva che i suoi scavatori avevano portato alla luce delle \"urne antiche\" nel sito di scavo fuori Uldaman. Temo che le urne trovate in quel sito abbiano aizzato i trogg, proprio come gli idoli che ho trovato qui.\n\nMi servono quelle urne per i nostri studi. Vai al sito di Uldaman, raccogli le urne e torna da me.", "Hai trovato quelle urne, {name}? Dobbiamo trovare il legame tra loro e i trogg!", "Ben fatto! Con fortuna e diligenza troveremo il legame che c'è tra i trogg e questi antichi manufatti.\n\nHai reso un grande servizio ai Prospectors, {name}. I tuoi sforzi non saranno dimenticati. E nemmeno Agmond.", 0x489c165c, 0xf3b9cc5e, 0x3e07aaf7, 0x50776b5d, 0xd3e7f943, "....." },
  [722] = { "L'amuleto dei segreti", "Trova l'Hammertoe's Amulet e riportaglielo a Uldaman.", "Hai fegato... <coff>... a venire a Uldaman per me, {class}.\n\nSe sei davvero qui per aiutare... il vecchio Hammertoe, allora... <coff>... dovrai trovare... il mio amuleto.\n\nCe l'ha Deepshadow... Magregan Deepshadow. È qui intorno... nelle rovine, di sicuro. Quell'amuleto li porterà... <coff>... dritti ai rotoli, se nessuno lo ferma. Dipende da te, {name}. Ti prego... prendi quell'amuleto.\n\nI rotoli aiuteranno di sicuro i Dark Iron a creare golem ancora più potenti. Lo so e basta. Me lo sento nelle ossa.", "Lo Shadowforge clan... <coff> è pericoloso. Stai <attento/attenta>. <coff> Devi trovare l'amuleto.", "Ah! <coff coff>\n\nLo sapevo che avresti trovato il mio amuleto, {name}.\n\n<ansima> Davvero ben fatto, {name}. <coff>", 0xe652e713, 0x071be869, 0x1fdf43a5, 0xb97feb8b, 0xd73cb9e2, "....." },
  [723] = { "Una prospettiva di fede", "Porta l'Hammertoe's Amulet a Prospector Ryedol, nelle Badlands.", "<Hammertoe si tiene le ferite e si prende un momento per ricomporsi prima di parlare di nuovo.>\n\nTrova Ryedol, {name}. Portagli il mio amuleto. <coff coff> Lui... <coff> capirà cosa fare. Sa che cercavo le origini del nostro popolo, e... <coff>... sa che la mia missione era anche fermare lo Shadowforge clan. Non devono trovare i rotoli... <coff>", "Direi che è stata una brutta giornata, ma queste sono le Badlands: ogni giornata è brutta.", "L'amuleto di Hammertoe? Credo di essere stato più su di morale quando pensavo che fosse morto. Saperlo per certo rende il dolore solo più forte. Questo amuleto era l'opera della sua vita. Non posso lasciare che la sua morte sia stata vana.", 0x49c004dd, 0xec3e3ec3, 0x421a43e5, 0x0dc62f1d, 0x2202d187, "....." },
  [724] = { "Una prospettiva di fede", nil, nil, nil, nil, 0x49c004dd, nil, nil, nil, nil, ".mmmm" },
  [729] = { "Il cercatore distratto", "Va' a sud a controllare il Prospector Remtravel.", "Che onore è stato quando il Master Greywhisker mi ha assegnata a lavorare sotto la guida del grande Prospector Remtravel. All'accademia di Ironforge tutti conoscevano le grandi scoperte di Remtravel.\n\nMa il prospector è piuttosto... ehm... distratto... riguardo a ciò che lo circonda.\n\nAvevamo scoperto le prove di una grande civiltà. Orribili golem sono sbucati dal terreno e hanno invaso il sito. Remtravel non sembrava nemmeno accorgersene. Sono corsa ad Auberdine a cercare aiuto.\n\nTi prego, va' a sud e vedi se il prospector sta bene!", nil, "Hollee, sei tu? Mi serve aiuto a cesellare questa pietra. Passami la mia spazzola di pietra, credo di vedere qualcosa.\n\nEhi, tu non sei Hollee! Non è che hai visto la mia spazzola di pietra?\n\nLascia perdere! Ho promesso alla League che avrei mandato il fossile misterioso che ho trovato. Dov'è andata Hollee?\n\nC'è così tanto lavoro da fare! Ora, dov'è quel fossile misterioso... e la mia spazzola... e Hollee...\n\nE tu chi sei... non importa, purché tu sia qui ad aiutare.\n\nFammi sapere quando sei <pronto/pronta> a cominciare a cercare.", 0xb9653d3d, 0xfae33a52, 0x15681a9a, nil, 0x1419b23f, "...m." },
  [730] = { "Guai a Darkshore?", "Vai ad Auberdine e cerca tracce della squadra di scavo nanica.", "Che bello vedere {class} che si interessa alle grandi meraviglie archeologiche del nostro mondo.\n\nSpesso i nostri amici dell'Alliance liquidano il nostro lavoro come un semplice passatempo. Ma molti non capiscono che le recenti scoperte a Khaz Modan hanno dimostrato che una forza grande e potente minaccia tutta Azeroth, da Lordaeron a Kalimdor.\n\nSono molto preoccupato per la squadra che ho mandato a Darkshore. Sono settimane che non dà notizie.\n\nVai ad Auberdine e cerca un indizio su dove si trovino.", nil, "Sono così felice che il Chief Archeologist Greywhisker ci abbia mandati a chiamare....", 0x267580f4, 0x8039f2c6, 0xcf3329d9, nil, 0xa8b5955b, "...m." },
  [731] = { "Il cercatore distratto", "Proteggi il Prospector Remtravel mentre cerca il fossile misterioso, poi torna dall'Archaeologist Hollee, ad Auberdine.", "Allora, Hollee... ah già, tu non sei Hollee. Dov'è Hollee?\n\nBah, non è questo il punto. Dobbiamo trovare quella spazzola di pietra... cioè, il fossile misterioso! Dobbiamo trovare quel fossile. L'Explorers' League di Darnassus vorrà qualche indicazione su ciò che ho fatto.\n\nFammi sapere quando sei <pronto/pronta> e andremo a caccia di quella spazzola.... cioè, di quel fossile! Troveremo qualcosa di scritto per soddisfare la League.\n\nAllora, sei <pronto/pronta>?", "Il prospector è vivo?", "Grazie al cielo il Prospector Remtravel è salvo! Te l'avevo detto che era distratto. Non posso credere che abbia insistito per restare lì con tutte quelle orribili creature in giro.", 0xb9653d3d, 0x700580fd, 0xf5e66d39, 0x7c063599, 0x6e9a29da, "....." },
  [738] = { "Trovare Agmond", "Trova Agmond.", "Prospector Agmond era responsabile dei nostri siti di scavo nelle Badlands, a sud-ovest. Dico \"era\" perché... be', sono settimane che non ho sue notizie. Ho bisogno che tu trovi Agmond, così potrò avere il suo rapporto.\n\nL'ultima volta che ho saputo qualcosa, Agmond era al sito di scavo più a sud delle Badlands, una piccola attività oltre l'Angor Fortress. Comincerei a cercarlo da lì.", nil, "Questo scheletro devono essere gli sfortunati resti di Agmond. Il suo corpo è rotto e martoriato, e le sue ossa ripulite.", 0xb8f48aab, 0xa522f785, 0x2dd9d0d7, nil, 0xd6cd386b, "...m." },
  [741] = { "Il cercatore distratto", "Porta il fossile misterioso al Chief Archaeologist Greywhisker, a Darnassus.", "Quindi il prospector vuole mandare il fossile misterioso all'Explorers' League di Darnassus? Non mi sento di lasciare Darkshore senza di lui.\n\nEcco, {name}, consegna il fossile misterioso al Chief Archaeologist Greywhisker, a Darnassus.", "Cosa posso fare per te, {race}?", "Oh, cielo! Solo il Prospector Remtravel poteva fare una scoperta del genere!", 0xb9653d3d, 0x4673c264, 0x9261fce9, 0x99c037c7, 0x5249d78d, "....." },
  [783] = { "Una minaccia interna", "Parla con Marshal McBride.", "Spero che tu abbia stretto bene la cintura, giovane {class}, perché qui a Northshire c'è del lavoro da fare.\n\nE non parlo di lavorare i campi.\n\nLe guardie di Stormwind faticano a mantenere la pace, con tanti di noi in terre lontane e tante minacce sempre più vicine. Per questo arruoliamo chiunque sia disposto a difendere la propria casa. E la propria alleanza.\n\nSe sei qui per rispondere alla chiamata, parla con il mio superiore, Marshal McBride. È dentro l'abbazia, alle mie spalle.", nil, "Ah, bene. Un'altra recluta. Di questi tempi ne arrivano tante.\n\nSpero che basti.\n\nLe terre degli umani sono minacciate dall'esterno, e molte delle nostre forze sono state mandate lontano. Questo, a sua volta, lascia spazio a gruppi corrotti e fuorilegge che prosperano entro i nostri confini.\n\nCombattiamo una battaglia su molti fronti, {name}. Preparati a una lunga campagna.", 0x5dfca6f5, 0x4ec936be, 0x0ab5d4f4, nil, 0x031c7505, "...m." },
  [819] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [858] = { "Accensione", "Prendi l'Ignition Key e portala a Wizzlecrank.", "Immagino che non ti abbia mandato Sputtervalve? Sono nei guai. Sono saltato dentro senza rendermi conto che serve una chiave per sbloccare la colonna di movimento dello shredder. Uno degli altri operatori di shredder mi ha chiesto se andava tutto bene e sono andato nel panico! Invece di dirgli che mi mancava la chiave, gli ho detto che c'era una specie di problema meccanico.\n\nDobbiamo andarcene da qui alla svelta! Sali nella sala di controllo in cima alla torre di trivellazione: il supervisore dovrebbe avere una chiave per questo shredder.\n\nAiutami!", "Presto, dobbiamo andarcene da qui prima che qualcuno sospetti qualcosa!", "Sì, questa sembra la chiave giusta. Lasciami solo controllare di sapere come far funzionare questo coso...\n\nMmm... controllo della rotazione... Questo regola velocità e stabilità... controllo fine del movimento del braccio. Guarda qua! Non posso credere che la Venture Company abbia progettato qualcosa di così migliore del nostro. Devo riportarlo a Ratchet!", 0x18e364df, 0xfd656f2e, 0xc1e7e3e9, 0xb25128ee, 0xa8725124, "....." },
  [863] = { "La fuga", "Proteggi Wizzlecrank e lo shredder goblin rubato lungo la strada fino a Sputtervalve, a Ratchet.", "Immagino che imparerò strada facendo... Non può essere troppo difficile. Solo qualche pulsante qui, una leva o due... Allora, sei <pronto/pronta> a partire?", "Posso aiutarti?", "Speriamo di poter ricavare qualcosa di valore dal prototipo di shredder distrutto... il mio tempo sta per scadere! Manderò subito una squadra di recupero dove si trova Wizzlecrank.\n\nOh, lascia che ti dia qualcosa anche per il disturbo.", 0x437cedda, 0x71ada0fe, 0x646e9b5d, 0xf30770a2, 0x6d0bbb0f, "....." },
  [865] = { "Corna di raptor", "Raccogli 5 Intact Raptor Horns dai Sunscale Scytheclaw e portali a Mebok Mizzyrix, a Ratchet.", "I raptor delle Barrens sono più intelligenti dei raptor di altre terre. E credo che tutta quell'intelligenza si nasconda nelle loro corna! Se è così, potrei macinarle in polvere e usarla per fare \"bevande intelligenti\". Potrei venderle a peso d'oro!!!\n\nE tu puoi aiutarmi. Trovami delle corna intatte di sunscale scytheclaw. Si aggirano nelle Barrens meridionali e nelle Barrens settentrionali, vicino al confine con l'Ashenvale Forest.", "Hai preso le corna, {name}? Quelle cose mi faranno fare una fortuna!", "Ottimo, le hai prese! Ora devo solo macinarle e mescolarle con un po' di vino, e...", 0x1c567a17, 0x3fc5f7ab, 0x7d0b4af6, 0x849a25eb, 0xa8f3ad03, "....." },
  [866] = { "Campioni di radici", "Porta 8 Root Samples a Mebok Mizzyrix, a Ratchet.", "Le erbe delle Barrens non sono proprio come le erbe di altre terre. Le loro proprietà sono quasi le stesse, ma l'acqua delle oasi qui altera le piante: sono appena un po' diverse.\n\nVoglio studiare quelle differenze... per vedere se si possono sfruttare!\n\nSe sei <esperto/esperta> in erboristeria, raccogli campioni di radici dalle erbe che trovi nelle Barrens. Riportami questi campioni, così potrò confrontarli con erbe di altre regioni.", "Salve, {name}. Hai preso quei campioni di radici?", "Sì sì, sono molto belli! Coltiverò degli esemplari da queste radici e li studierò. Spero di scoprirne nuove proprietà. Proprietà nascoste e preziose...!\n\nE non preoccuparti: se ci riuscirò, sarai la prima persona a saperlo. Perché mi servirà qualcuno che ne raccolga altri!", 0x70eb75ac, 0x4cbd0479, 0x8786eff9, 0x068cbe55, 0xf9891d3a, "....." },
  [873] = { nil, "Porta l'Heart of Isha Awak a Mahren Skyseer.", "Il grande Isha Awak è il signore di queste acque. Grande è la sua forza, e solenne il suo orgoglio. Gli umani della costa lo temono, perché ne ha divorati molti.\n\nMa io non lo temo. Sono grato che sia qui. È una sfida degna, una preda onorevole.\n\nSe sei <pronto/pronta>, allora nuota al largo e cerca Isha Awak, il Deep Doom.\n\nIl suo spirito dimora nel suo cuore, e sentirne il battito significa conoscere il proprio destino.", "Non temere le acque, {race}.", "Ora sei tutt'uno con Isha Awak, {name}. Il suo spirito è con te. Si annida nei tuoi occhi...\n\nOcchi che, un giorno, impareranno a vedere.", nil, 0x9e928276, 0xd7808914, 0x038b0db1, 0xac941e2b, "m...." },
  [887] = { nil, "Uccidi 12 Southsea Brigand e 6 Southsea Cannoneer per Gazlowe, a Ratchet.", "Vorrei proprio che il Vice Admiral Grezzlik facesse un lavoro migliore nel tenere i mari sicuri per le nostre navi mercantili. Con tutto l'oro che i principi mercanti hanno riversato nelle Trade Fleets, mi fa infuriare vedere così tanti pirati scorrazzare liberamente, assaltando le mie navi e rubando la mia merce!\n\nHo sentito che i Southsea Freebooters hanno allestito un accampamento appena a sud di qui. Sono stati una vera spina nel fianco, e se Grezzlik non se ne occupa, beh, forse puoi aiutarmi tu a sbarazzarmene.", "Non voglio nemmeno pensare ai profitti che ho perso per le razzie dei pirati, e ora si sono accampati davanti alla mia porta? La situazione sta sfuggendo di mano, Undermine deve fare qualcosa.", "Hai fatto un buon lavoro, <ragazzo/ragazza>. Ancora un po' di lavoro così e sarà una preoccupazione in meno per me. Speriamo che si convincano a spostare le loro attività altrove.\n\nNel frattempo c'è la piccola questione di riprendere la merce che mi hanno rubato!", nil, 0x69ce9e05, 0x7623fe2d, 0xd3e5fc1b, 0x9a1f5c52, "m...." },
  [888] = { "Bottino rubato", "Recupera la Shipment of Boots e la Telescopic Lens per Gazlowe, a Ratchet.", "Vorrei recuperare tutta la mia merce, ma sono sicuro che non sia possibile. Comunque, ci sono alcune cose che devo assolutamente avere!\n\nCome vedi, il mio osservatorio è pronto, ma gli serve la più piccola delle due lenti. La prima è arrivata in carovana da Durotar, ma la seconda viaggiava per nave e non è mai arrivata. E non ho nemmeno ricevuto la mia spedizione di stivali da Drizzlik, a Booty Bay!\n\nScendi all'accampamento dei pirati e vedi se riesci a trovarli.", "Hai trovato le mie cose, {name}?", "È un sollievo riavere tutta questa roba, quindi grazie per l'aiuto, {name}. Sai, mi farebbe comodo qualcuno della razza {race} come te per aiutarmi con i miei affari qui. Se mai cercassi lavoro, non dimenticare quanto bene paga Gazlowe!", 0x64d599c7, 0x739fc2b0, 0x0b53afc7, 0x23319024, 0xe9cacd44, "....." },
  [890] = { "La spedizione scomparsa", "Porta il Gazlowe's Ledger al Wharfmaster Dizzywig.", "Aspetto da un'eternità la mia ultima spedizione di merce da Booty Bay! Sono quasi sicuro che l'abbiano rubata i Freebooters, ma giusto per sicurezza, puoi scendere al molo a chiedere a Dizzywig se la mia merce è già stata messa nel mio magazzino a mia insaputa?\n\nEcco, porta il mio libro mastro a Dizzywig e fagli confrontare i miei registri d'inventario con i suoi.", "Merci da spedire con la prossima nave, {name}?", "Ah, ti ha mandato Gazlowe, eh? Un momento, lasciami dare un'occhiata ai miei registri per assicurarmi di non aver mandato la spedizione di Gazlowe nel posto sbagliato.\n\nScommetto che aspetta quegli stivali da Drizzlek...", 0x6e986c05, 0xb6778f93, 0x3b8b55c6, 0x0751d23b, 0x749eab9a, "....." },
  [892] = { "La spedizione scomparsa", "Riporta il Gazlowe's Ledger a Gazlowe, a Ratchet.", "Dai miei registri sembra tutto in ordine, {name}. Torna pure a dire a Gazlowe che non ha fortuna. Non mi stupirei se fossero stati i pirati ad arraffare la sua roba.\n\nNon posso fare altro per lui. Oh... però potresti dirgli che ho alcune cose da Undermine per lui, quando avrà tempo di venire a prenderle.", "Allora, cosa ha detto Dizzywig?", "Niente da fare, eh? Allora devono essere stati i Freebooters... Dizzywig è onesto, sono sicuro che non mi imbroglierebbe così. Dopotutto è sul mio libro paga.\n\nSembra che io abbia della merce da recuperare, {name}. Che ne dici?", 0x6e986c05, 0xccb10e11, 0xd2dbc272, 0xf6aa07eb, 0xfba18b3c, "....." },
  [894] = { nil, "Accedi alla console di controllo del sito di ricerca della Venture Company.", "La Venture Company ha allestito un piccolo centro di ricerca molto a nord di qui, a sud-ovest della Sludge Fen. Non so molto di ciò che fanno, ma sono riuscito a scoprire che stanno sperimentando qualcosa chiamato \"samophlange\".\n\nE che diavolo è un samophlange? Beh, qualunque cosa sia, voglio esaminarlo, quindi mi serve qualcuno che vada a prenderlo.\n\nMi sono procurato una copia del manuale operativo del loro sistema di controllo: dovresti riuscire a capire come sganciare il samophlange.", nil, "Una varietà di pulsanti, leve e luci lampeggianti è disposta in modo piuttosto caotico sul pannello della console di controllo. Un piccolo indicatore mostra che l'apparato funziona attualmente a livelli ottimali e che le valvole di controllo dalla uno alla tre sono aperte. Nella parte inferiore destra del pannello c'è una piccola serratura.", nil, 0x4672c678, 0x2862ca26, nil, 0x663259ed, "m..m." },
  [895] = { "RICERCATO: Baron Longshore", "Porta la testa del Baron Longshore a Gazlowe, a Ratchet.", "RICERCATO!\n\nBaron Longshore, capitano dell'Heedless\n\nIl capitano Longshore di Gilneas guida navi dei Southsea Freebooters ed è ricercato con l'accusa di pirateria. I resti devono essere riconoscibili!\n\n-- Gazlowe", "Che succede? Posso aiutarti in qualcosa? Merci da spedire, magari un lavoro di ingegneria?", "Ahhhh! Quel genere di affari. Sai, una volta ho visto l'Heedless in mare aperto. Una nave temibile, o era una barca... quei marinai sono così pignoli!\n\nComunque, vederla scivolare sull'acqua era proprio uno spettacolo. Sono felice che il suo famigerato capitano non darà più fastidio alle mie navi.", 0x491ae825, 0xd4870698, 0xa3d7e5a0, 0x053eeee1, 0x55a4e1a1, "....." },
  [896] = { "La fortuna del minatore", "Recupera il Cats Eye Emerald da uno dei Venture Co. Overseer o Enforcer per il Wharfmaster Dizzywig, a Ratchet.", "Come Wharfmaster di un porto trafficato come Ratchet, tengo il polso delle informazioni. So tutto degli scambi di merci e denaro tra qui e Booty Bay.\n\nL'ultima notizia che ho sentito riguarda la miniera Boulder Lode della Venture Company, a nord-est della Sludge Fen. Uno dei minatori ha scoperto uno smeraldo grande quanto un pugno. Conosco alcuni compratori che sarebbero interessati a mettere le mani su una cosa del genere, e sarei disposto a fare a metà sulla vendita.", "Se solo sapessimo quale dei minatori ha trovato lo smeraldo, sarebbe una passeggiata...", "Guarda che dimensioni, {name}! Diventeremo ricchi! Vediamo, secondo le tariffe che ho visto per le gemme dirette a Undermine, dovrei riuscire a calcolare la tua parte: il cinquanta per cento, non preoccuparti!\n\nDunque, vediamo... credo che questo dovrebbe andar bene. È un piacere fare affari con te, {name}.", 0xf0a4978e, 0xb7148907, 0x65b6bf5c, 0x6508ab66, 0x517d57ef, "....." },
  [898] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [900] = { nil, "Chiudi la Fuel Control Valve, la Regulator Valve e la Main Control Valve, poi usa di nuovo la console di controllo.", "Le tre valvole di controllo sono attualmente aperte. Le varie letture sul pannello di controllo ti fanno supporre che debbano essere chiuse prima di poter spegnere l'apparato.", "Le luci lampeggianti sulla console di controllo indicano che le valvole di controllo principali non sono state chiuse.", "Le luci che indicano le tre valvole di controllo si attenuano mentre vengono chiuse. Le luci verdi sfumano lentamente in gialle, e l'interruttore che controlla l'apparato ora si può muovere: con le valvole chiuse, l'apparato può essere spento.", nil, 0xc702a51e, 0x84fa6910, 0x016095ec, 0xd54462d9, "m...." },
  [901] = { nil, "Prendi la Console Key dal Tinkerer Sniggles per usarla sulla console di controllo.", "Con l'apparato disattivato, il pannello di controllo può essere aperto e il samophlange estratto dalla console. Con tutto il resto a posto, non resta che procurarsi la chiave per sbloccare la console.", "Le luci della console sono attenuate e indicatori e quadranti segnano tutti zero: tutto è al minimo.", "Girando la chiave nella serratura, la console di controllo si sblocca. Una luce rossa in cima alla console si spegne e il terminale perde tutta l'energia.", nil, 0x3bc295f6, 0xdda2316f, 0x90e09488, 0xec181a95, "m...." },
  [902] = { nil, "Riporta il Samophlange a Sputtervalve, a Ratchet.", "Aprendo il pannello frontale della console di controllo, scopri un groviglio fitto di cavi, tubi e altri strani oggetti meccanici, la maggior parte dei quali sembra non avere alcuno scopo pratico. Scostandoli e frugando più a fondo nella console, trovi il samophlange. Con uno strattone lo estrai dal suo alloggiamento.", "Oh, sei <tornato/tornata>, {name}! Hai il samophlange?", "Questo è... ehm... interessante... sì. Lo farò mandare alla sede della Tinkers' Union a Undermine. Sono sicuro che dopo un'attenta dissezione e qualche ricerca riusciranno a capirci qualcosa.\n\nMa forse prima gli darò un'occhiatina io stesso...", nil, 0xc6a03d7b, 0x6dc9a2ce, 0x2213d644, 0x020e9774, "m...." },
  [916] = { "Il veleno dei Webwood", "Porta 10 Webwood Venom Sacs a Gilshalan Windwalker, ad Aldrassil.", "Sono venuto a Shadowglen per osservare i ragni Webwood che vivono nella Shadowthread Cave. Sono cugini di una specie di ragno molto più piccola; credo che l'albero del mondo abbia avuto un effetto profondo su di loro, e vorrei degli esemplari da studiare per confermarlo.\n\nPrima di tutto vorrei un po' del loro veleno. Raccogli le Webwood Venom Sacs dai ragni dentro e intorno alla Shadowthread Cave, a nord. Poi potrò esaminarle per vedere le somiglianze con il veleno dei loro cugini più piccoli.", "Hai raccolto le sacche di veleno, {name}?", "Grazie, {name}. Quando tornerò a Darnassus confronterò il veleno di queste sacche con quello di altri ragni. Credo che avrà proprietà legate alla recente crescita del nostro nuovo albero del mondo.", 0x5ef3699f, 0xcd2d6c5d, 0x328f2ab5, 0x0d16764a, 0x93e71cf8, "....." },
  [917] = { nil, "Porta un Webwood Egg a Gilshalan, ad Aldrassil.", "Ora che ho il veleno dei ragni, vorrei degli esemplari vivi da studiare. Purtroppo catturare un ragno gigante vivo è più di quanto possa chiederti, giovane {class}. E un ragno gigante sarebbe troppo anche per me!\n\nMa se riesci a trovare un uovo non ancora schiuso, portare gli esemplari sarà molto più facile, e potrò far custodire i ragni non ancora nati.\n\nDev'esserci un nido in fondo alla Shadowthread Cave. Ti prego, cerca un uovo nel nido e riportamelo.", "Sei <stato/stata> nella Shadowthread Cave, {name}? Hai trovato un uovo di ragno?", "Ah, molto bene. Farò trasportare questo uovo e il veleno a Darnassus, poi ci tornerò quando avrò finito i miei studi qui. Mi aspetto di scoprire molto da questi esemplari, {name}. Mi sei <stato/stata> di grande aiuto.", nil, 0xe3b29d22, 0x81a464b0, 0x04406a66, 0x2017b57d, "m...." },
  [918] = { nil, "Porta 8 Timberling Seeds a Denelan, al Lake Al'Ameth.", "I timberling di Teldrassil sono elementali della natura. In un certo senso riflettono l'ordine naturale di piante e animali sul nostro grande albero.\n\nPer questo è preoccupante vedere quanto si siano arrabbiati i timberling.\n\nCredo che c'entri il terreno. Sto lavorando a diversi metodi per nutrire le piante e vorrei provarli sui semi dei timberling. Ti prego, puoi raccogliere semi dai timberling intorno al Lake Al'Ameth e portarmeli?", "Hai i semi? Non vedo l'ora di piantarli.", "Li hai presi. Bene!\n\nPianterò questi semi in un terreno speciale che ho preparato. Credo che ne nasceranno timberling molto più docili. Forse più avanti potrai vedere i risultati!", nil, 0x25b24cca, 0x6bd8e4d3, 0x0e19807b, 0xe481e8bb, "m...." },
  [919] = { nil, "Porta 12 Timberling Sprouts a Denalan, al Lake Al'Ameth.", "Piccoli timberling stanno spuntando intorno alle acque del Lake Al'Ameth. Temo che questi germogli non si possano più salvare: dovremmo cercare di toglierli di mezzo prima che crescano abbastanza da creare problemi.\n\nQuando giri intorno al lago, se vedi dei Timberling Sprouts, ti prego, prendili. Aiutaci a tenere pulita la nostra terra!", "Salve, {name}. Hai trovato dei germogli vicino all'acqua?", "Sono tantissimi! Temo che si stiano diffondendo a un ritmo pericoloso. Spero di riuscire a risolvere l'enigma di cosa li contamini.\n\nGrazie per l'aiuto, {name}. Grazie ai tuoi sforzi la terra è più pulita.", nil, 0x6fa3313a, 0x3ae4085a, 0xe4c0ddfe, 0xf442a65d, "m...." },
  [920] = { "La convocazione di Tenaron", "Parla con Tenaron Stormgrip, in cima ad Aldrassil, a Shadowglen.", "{name}, giusto? Ho sentito che Tenaron ha chiesto di te. Lo trovi nella stanza più alta, in cima ad Aldrassil.\n\nViviamo vite lunghe, ma è meglio non farlo aspettare troppo.", nil, "Ah, {name}. Speravo che rispondessi prontamente alla mia convocazione. Ho un compito importante che vorrei affidarti.", 0xde22b969, 0x7548d88d, 0x92b7f833, nil, 0x7330b9e5, "...m." },
  [921] = { "La corona della terra", "Riempi la Crystal Phial e riportala a Tenaron Stormgrip, in cima ad Aldrassil.", "È ora che tu parta in cerca del tuo destino, {name}. Ma prima di essere <pronto/pronta> ad avventurarti nel mondo oltre le nostre foreste incantate, c'è molto che devi imparare sulla nostra storia recente.\n\nMolto è cambiato per il nostro popolo dalla battaglia del Mount Hyjal. Nordrassil è un pallido riflesso di ciò che era un tempo: il suo potere è stato usato per sconfiggere Archimonde e respingere la Burning Legion...\n\nC'è un compito che devi svolgere. Vai al pozzo lunare a nord di Aldrassil e riportami una fiala della sua acqua.", "I pozzi lunari contengono le acque del Well of Eternity, l'antica fonte di magia che ha portato tanti orrori nel nostro mondo.\n\nI druidi ne sfruttano le proprietà e le Sentinels venerano i pozzi come santuari di Elune, ma la stregoneria è proibita a tutti.", "Dunque hai sentito la prima parte di ciò che accadde dopo la battaglia del Mount Hyjal. C'è molto altro da raccontare, e il compito che hai cominciato qui continuerà per tutto il resto del tuo viaggio attraverso Teldrassil e fino a Darnassus.", 0x6a9c354f, 0x6f20ec86, 0x63729cf0, 0x92295015, 0x4972e13e, "....." },
  [922] = { nil, "Porta un Timberling Seed a Rellian Greenspyre, a Darnassus.", "{name}, puoi portare uno dei semi che mi hai procurato al mio amico Rellian Greenspyre? È un druido di Darnassus, e l'ultima volta che ci siamo parlati si è mostrato interessato al mio lavoro con i timberling. Aveva qualche idea anche lui, e apprezzerà un seme da studiare.\n\nGrazie, {name}. Mi sei <stato/stata> di grande aiuto. Spero che un giorno vedrai il frutto del mio lavoro.\n\nDi solito trovi Rellian lungo i sentieri del Cenarion Enclave, a Darnassus.", "Salve...\n\nE come posso aiutarti?", "Ah, un Timberling Seed? Volevo provare a farne crescere uno per aiutare Denalan nei suoi studi.\n\nMa temo di aver scoperto che in molti timberling è cresciuta una corruzione, e i semi di quelle creature portano la contaminazione dei genitori. Ripararli va oltre le mie capacità.\n\nDenalan è molto abile con le cose che crescono. Forse troverà una cura per i timberling futuri. Potrebbe essere la loro unica speranza.", nil, 0x0cd55696, 0x31859f95, 0x36a1f94a, 0x61b8489f, "m...." },
  [923] = { "Tumori", "Porta 5 Mossy Tumors a Rellian Greenspyre, a Darnassus.", "Nei timberling sta crescendo una malevolenza. Stiamo cercando di trovarne la fonte, ma finché non ci riusciamo... per mantenere al sicuro Teldrassil dobbiamo abbattere i timberling che non si possono più salvare. Quelli che si aggirano intorno al Wellspring Lake, nel nord di Teldrassil, sono i più contaminati. Vanno eliminati!\n\nDistruggi i timberling che trovi lì e raccogli i Mossy Tumors che crescono su di loro. Portami i tumori, così potremo bruciarli.", "Sei <stato/stata> al Wellspring Lake, {name}? Hai dato la caccia ai timberling che ci sono?", "Ben fatto! Questi tumori sono il sintomo della malattia dei timberling. Sono pieni di un veleno che dobbiamo eliminare dalla nostra nuova terra.\n\nMi sbarazzerò di questi tumori. Grazie, {name}.", 0x9be57a52, 0xd33dba21, 0x8c75928f, 0x75561cf5, 0xab86b70c, "....." },
  [926] = { nil, nil, nil, nil, "Queste pietre sono infuse di energia magica, ma volutamente difettose. Sono molto instabili e, una volta tolte dal tavolo, si consumeranno rapidamente.", nil, nil, nil, nil, 0x79072959, "mmmm." },
  [927] = { "Il Moss-twined Heart", "Porta il Moss-twined Heart a Denalan, al Lake Al'Ameth.", "Il cuore di Blackmoss the Fetid è coperto da un muschio scuro e oleoso. Anzi, l'unico modo per capire che è un cuore è il suo battito lento e ritmico... Un battito che continua ancora adesso.\n\nForse Denalan vorrà vedere questo cuore.", "{name}! Hai qualcosa per me?", "...Cos'è questo? Il cuore di un timberling?? È coperto da un muschio immondo!\n\nGrazie per avermelo portato, {name}. Esaminerò il cuore e, se la fortuna ci assiste, scoprirò la natura del muschio che lo ricopre.", 0x8ab57346, 0x174962f9, 0x3bdb0906, 0xdfd947e9, 0x5c540383, "....." },
  [928] = { "La corona della terra", "Porta il Partially Filled Vessel a Corithras Moonrage, a Dolanaar.", "Potrei raccontarti ancora molto dei pozzi lunari e di Teldrassil, ma devo lasciarti andare. Corithras Moonrage ti aspetta. Ho versato la fiala d'acqua che mi hai portato in questo recipiente, da portare a lui.\n\nCerca Corithras. Lo troverai al pozzo lunare di Dolanaar. Segui la strada verso sud da Aldrassil fino a uscire da Shadowglen, e continua a seguire l'acciottolato quando la strada gira a ovest.\n\nMa bada a restare sulla strada, {name}. Ultimamente nelle foreste ci sono bestie pericolose.", "Salute, {class}. A cosa devo il piacere di questo incontro?", "Ah, capisco. Ti manda Tenaron. Be', allora sembra che abbiamo molto di cui parlare, molto da fare e poco tempo per farlo.\n\nCredo che sia meglio cominciare.", 0x6a9c354f, 0x519e561b, 0x69be4dda, 0xa03c786d, 0xd5848e6f, "....." },
  [929] = { "La corona della terra", "Riempi la Jade Phial e riportala a Corithras Moonrage, a Dolanaar.", "Prima di tutto, lascia che ti dica di più del compito che devi portare a termine. I druidi di Darnassus usano l'acqua dei pozzi lunari di Teldrassil, e il loro pozzo va rifornito di tanto in tanto. Con queste fiale fatte apposta puoi raccogliere l'acqua dei pozzi lunari.\n\nPorta questo recipiente al pozzo lunare fuori da Starbreeze Village, a est, riempilo con un po' della sua acqua e torna da me. Quando avrai finito, riprenderò la storia da dove l'ha lasciata Tenaron...", "Eccoti di nuovo, {name}. Hai portato a termine il tuo compito?", "Dopo la battaglia del Mount Hyjal eravamo senza una guida. Nordrassil fumava per il fuoco che aveva scatenato, e la nostra immortalità, l'essenza stessa del nostro essere!, era perduta.\n\nFu in quel momento difficile che il Betrayer fu liberato dalla sua prigione, e Shan'do Stormrage scomparve. Un periodo buio per tutti.", 0x6a9c354f, 0x188ad811, 0x725fcab1, 0xd7878828, 0x95ab8c86, "....." },
  [930] = { "La Glowing Fruit", "Porta il frutto luminoso a Denalan, al Lake Al'Ameth.", "Sotto le fronde di questa pianta luminosa pende un grosso frutto rotondo.\n\nDenalan vorrà di sicuro studiare questo frutto.", "{name}, sembri avere qualcosa da dirmi. Hai notizie sui timberling?", "L'hai trovato su Teldrassil? Interessante... questo frutto è esotico. Forse i suoi semi sono stati portati qui da lontano. Forse addirittura da Azeroth! E c'è qualcosa in questo frutto... sembra aver reagito in modo molto strano con il terreno di Teldrassil.\n\nGrazie, {name}. Ora, se vuoi scusarmi, devo studiarlo meglio...", 0xa2834fd5, 0x29dd07f4, 0x84397c8e, 0x2532fbc0, 0x2ea98bd6, "....." },
  [931] = { "La Shimmering Frond", "Porta una Shimmering Frond a Denalan, al Lake Al'Ameth", "Le fronde di questa pianta scintillano nella luce della foresta, dandole un'aura che si contorce e pulsa.\n\nCredi che Denalan ne vorrebbe un esemplare.", "Hai qualcosa per me?", "Dove l'hai preso? Non vedevo una pianta del genere da un viaggio che feci nella Swamp of Sorrows... decenni fa! È incredibile che un esemplare sia arrivato fino a Teldrassil. Ed è cresciuto così tanto!\n\nGrazie, {name}. Perdona la mia brevità, ma c'è un esperimento che vorrei fare su questa fronda...", 0x3dda56af, 0xe2d17f64, 0xd3966077, 0xa03be4c2, 0xa5f2249f, "....." },
  [932] = { "Odio contorto", "Uccidi Lord Melenas e porta la sua testa a Tallonkai Swiftroot, a Dolanaar.", "Devo avvertirti, {name}: questa faccenda deve restare tra noi. I satiri sono già abbastanza una vergogna per noi, e questo è fin troppo vicino a casa.\n\nSi chiama Lord Melenas. Vive nella vicina caverna di Fel Rock, dove ha radunato un grosso gruppo di guerrieri grell. Il suo cuore è nero come la notte, e trama qualcosa di molto immondo.\n\nDevi trovarlo nella sua caverna, appena a nord di qui, e portarmi la sua testa.", "Hai già ucciso Lord Melenas? È fondamentale che ce ne occupiamo in fretta e in silenzio, {name}. Finché esiste è una vergogna per tutti noi.", "Con Lord Melenas messo a riposo posso finalmente passare ad altro. Grazie, {name}.", 0x10738b8e, 0xa49ba15f, 0xbc655ff9, 0x7bab7e42, 0x4a8d372b, "....." },
  [933] = { "La corona della terra", "Riempi la Tourmaline Phial e riportala a Corithras Moonrage, a Dolanaar.", "C'è un altro pozzo lunare a sud-est dell'ingresso di Darnassus, sulle rive delle Pools of Arlithrien. Le Sentinels hanno difficoltà a pattugliare la zona per via degli attacchi e del malumore crescente dei furbolg Gnarlpine.\n\nStai in guardia mentre cerchi il pozzo, e tieni le armi a portata di mano.", "All'inizio le notizie di attacchi di furbolg impazziti non furono prese sul serio. Chi avrebbe pensato che i pacifici uomini-orso sarebbero caduti in una rabbia cieca? Un altro dei problemi che ci affliggono qui nella nostra nuova casa.", "Shan'do Stormrage non tornò mai, i druidi erano allo sbando, e ancora oggi non sappiamo che ne sia stato di lui. Con Malfurion scomparso, Arch Druid Fandral Staghelm prese la guida dei druidi e convinse il Circle of Ancients di Darkshore che era tempo che il nostro popolo ricostruisse, e che riconquistasse l'immortalità.\n\nCon l'approvazione del Circle, Staghelm e i druidi più potenti fecero crescere Teldrassil, il nuovo albero del mondo.", 0x6a9c354f, 0x3d0857d5, 0x4d68f2e0, 0x531af2f0, 0x63415c4c, "....." },
  [934] = { "La corona della terra", "Riempi l'Amethyst Phial e riportala a Corithras Moonrage, a Dolanaar.", "Ma non tutto andava bene con Teldrassil. I piani accurati di Staghelm per il nuovo albero del mondo avevano dato i frutti che sperava, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nMa di questo non parlerò ancora. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nell'Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e il più potente dei nostri pozzi. Prendi una fiala della sua acqua e torna da me.", "Insieme ai druidi, l'Oracle Tree e l'arcidruido hanno seguito con attenzione la crescita di Teldrassil. Ma anche se abbiamo una nuova casa, le nostre vite immortali non ci sono state restituite.", "Essere al cospetto dell'Oracle Tree... è quasi sentire la saggezza prendere forma. Lascia che continui il racconto...\n\nCresciuto Teldrassil, l'arcidruido chiese ai draghi la loro benedizione, come quella che i draghi avevano dato a Nordrassil nei tempi antichi. Ma Nozdormu, signore del tempo, rifiutò la sua benedizione e rimproverò il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm, e senza la sua benedizione la crescita di Teldrassil è stata imperfetta e imprevedibile...", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [935] = { "La corona della terra", "Porta il Filled Vessel ad Arch Druid Fandral Staghelm, a Darnassus.", "Senza le benedizioni di Alexstrasza the Life-Binder e di Nozdormu the Timeless, la crescita di Teldrassil non è stata priva di difetti. Si dice che strane bestie spuntino dal terreno stesso dell'albero, e furbolg impazziti attaccano i viaggiatori di passaggio.\n\nPosso solo sperare che la soluzione che l'arcidruido cerca venga trovata presto. Verserò tutte le fiale che mi hai portato in questo recipiente, perché tu lo consegni a Darnassus.\n\nPortalo a Fandral Staghelm: lo troverai nel bosco dei druidi.", "So di non averti convocato, quindi non posso fare a meno di chiedermi perché sei <venuto/venuta> a parlarmi.\n\nQualunque cosa sia, ti prego, fai in fretta.", "Ah sì, l'acqua che avevo chiesto. Tenaron e Corithras se la sono presa comoda a farmela consegnare... forse non hanno scelto i messaggeri più affidabili... mmm.\n\nComunque, finalmente posso tornare al mio lavoro. Il peso dei problemi di Teldrassil grava sulle mie spalle. Un giogo di cui vorrei liberarmi presto.\n\nPrendi questo, potrebbe esserti utile.", 0x6a9c354f, 0x1325e4e5, 0x54cda088, 0xaf4b925e, 0xf477d1e8, "....." },
  [937] = { "La radura incantata", "Procura 6 Bloodfeather Belts e portale a Sentinel Arynia Cloudsbreak, nell'Oracle Glade.", "Sono stata mandata qui con un piccolo gruppo di Sentinels a proteggere l'Oracle Tree dalle arpie che hanno fatto il nido tutto intorno alla radura. Poco a poco stiamo cercando di respingerle.\n\nQuando l'Oracle Tree ha cercato di mandare un messaggero a Darnassus con un rapporto, il messaggero è stato attaccato e ucciso da un gruppo di arpie.\n\nSe te la senti, vai ai loro nidi, uccidile e portami le loro cinture come prova delle tue azioni.", "I loro artigli taglienti e i loro becchi aguzzi potrebbero mettere alla prova le tue capacità, {name}, ma ho fiducia che non fallirai in questo compito.", "Sono colpita da ciò che hai fatto qui in così poco tempo, {name}. Vorrei poterti chiedere di restare ad aiutarmi nei miei doveri... ma in cuor mio so che ti attendono compiti più grandi.\n\nHo notato che l'Oracle Tree ha appena perso un pezzo di corteccia. Senza dubbio ha un compito che vuole vedere portato a termine. Dovresti parlargli.", 0xc112d404, 0x3f1ffacf, 0x6aee024a, 0x465cb007, 0x5c5a347c, "....." },
  [938] = { nil, "Scorta Mist da Sentinel Arynia Cloudsbreak, al pozzo lunare vicino all'Oracle Tree.", "La pelliccia della sciabolatigre è di un grigio caratteristico, che si confonde con la foresta intorno. Mentre giace lì, noti che è gravemente ferita, con profondi squarci sulla schiena e sul ventre.\n\nAlza la testa e ti guarda, con un'intelligenza viva che brilla negli occhi azzurri. Sembra voler venire con te.", "Mist... È stata colpa mia! Le streghe mi hanno colta di sorpresa... Non avrei dovuto lasciare che ti prendessero...", "Oh, grazie, {name}! Temevo che non avrei mai più rivisto Mist, con nel cuore solo il pensiero della sua morte, senza più potermi ricongiungere alla mia fedele compagna. Ti devo più di quanto tu possa immaginare, e hai la mia eterna gratitudine.", nil, 0x87fed568, 0x72d756dc, 0xeca87270, 0x849d34d3, "m...." },
  [940] = { nil, "Consegna l'Inscribed Bark ad Arch Druid Fandral Staghelm, a Darnassus.", "La foresta sussurra delle tue imprese valorose, {name}. Quando ho sentito le arpie cacciate dai loro nidi, una calma più grande si è diffusa nella foresta, e le sue creature si sono sentite di nuovo al sicuro. Avevo paura di mandare un altro messaggero all'arcidruido, ma so che tu porterai il mio messaggio fino a lui senza intoppi.\n\nConsegnaglielo, e sappi che la foresta ti accompagnerà al sicuro lungo i suoi sentieri fino alla foresta di pietra.", "Mmm... Porti con te lo spirito della foresta, forte dentro di te, {class}. Che affari hai con l'arcidruido dei Kaldorei?", "Mi chiedevo perché l'Oracle Tree non comunicasse con me da tanto tempo... Sembra che alcuni problemi si attenuino mentre altri diventano preoccupazioni più grandi.\n\nTemo che il mio lavoro su Teldrassil non sarà mai completato, e che la nostra immortalità non sarà mai restituita.\n\nComunque, hai svolto bene il compito dell'Oracle Tree, e meriti una ricompensa per la tua diligenza.", nil, 0x3d134466, 0xd95bd925, 0xba14a37c, 0x4699ba60, "m...." },
  [941] = { "Piantare il cuore", "Pianta il Tainted Heart nel Denalan's Planter.", "Ho tolto quel muschio immondo dal cuore, ma resta contaminato...\n\nProva a mettere il cuore nel mio vaso. È pieno di un terriccio nutriente che potrebbe purificare e guarire il cuore.", "Questo vaso è pieno di terriccio, preparato appositamente da Denalan.", "Metti il cuore nel vaso, e quello si infila subito nella terra!\n\nPochi secondi dopo esce di nuovo dimenandosi, purificato. Pulsa appena... come se ti invitasse a prenderlo.", 0x65f8fb52, 0xe00d7701, 0x54612342, 0xda090df6, 0x4660d6c8, "....." },
  [942] = { "Il cercatore distratto", "Porta il fossile misterioso all'Archaeologist Flagongut, a Menethil Harbor.", "Questo fossile somiglia in modo impressionante a uno che vidi una volta a Ironforge. Un archeologo di nome Flagongut lo portò al nostro convegno annuale dell'Explorers' League. Credeva che il fossile avesse un potere che in qualche modo si poteva sbloccare.\n\nL'ultima volta che ne ho sentito parlare, Flagongut si era rintanato nella Deepwater Tavern di Menethil Harbor, in attesa di una scorta per il Whelgar Excavation Site. Cercalo e mostragli il fossile di Remtravel. Forse potrà svelare i segreti del passato.\n\nLa nave per Menethil parte da Auberdine.", "Cos'hai lì, amico?", "Oh, cielo! Dici che viene dalle terre lontane di Kalimdor?\n\nStraordinario! Semplicemente straordinario!", 0xb9653d3d, 0xfc29c252, 0x961f86d3, 0x8fb7e5ca, 0xd1acd945, "....." },
  [943] = { "Il cercatore distratto", "Archaeologist Flagongut, a Menethil Harbor, vuole che tu gli porti la Stone of Relu e il Flagongut's Fossil.", "Prospector Whelgar ora custodisce il fossile originale nel suo sito nelle Wetlands. Quando scoprii la Stone of Relu, pensai che fosse la chiave per svelare il mistero del fossile.\n\nMentre ero in viaggio per incontrare Whelgar, fui attaccato dai raptor e il reperto andò perduto. Non so quale di quelle bestie maculate abbia inghiottito il reperto, ma se riesci a recuperarlo, potrò liberare il potere di questi manufatti.\n\nPortami sia la Stone of Relu sia il fossile originale che custodisce lui.", "Con la Stone of Relu potrò liberare i segreti nascosti del mio fossile e anche di quello di Remtravel, da Darkshore, {name}.", "Eccellente, {name}!\n\nOra vediamo se riesco a usare la pietra per decifrare i poteri dei fossili.", 0xb9653d3d, 0x2f21bebd, 0x53989e47, 0x7833064e, 0xa4671511, "....." },
  [944] = { "Il Master's Glaive", "Raccogli informazioni, poi usa la Phial of Scrying per creare una Scrying Bowl. Usa la ciotola per parlare con Onu.", "È strano che i naga siano qui, a Darkshore. Ma ancora più strano... è il Twilight's Hammer. Quel culto venera gli antichi, antichissimi signori della terra. Signori sconfitti tanto tempo fa.\n\nIl Master's Glaive, a sud, è un luogo dove cadde uno di questi antichi signori.\n\nVai lì e cerca altri cultisti del Twilight's Hammer.\n\nPrendi questa fiala divinatoria. Usala per creare una ciotola divinatoria dopo aver perlustrato il Master's Glaive. Poi parlami attraverso la ciotola.", "Il Master's Glaive, {name}.\n\nVacci, poi torna a parlare con me.", "Il Twilight's Hammer è al Master's Glaive?\n\nSfortunato.\n\nL'antico signore impalato dalla lama è morto da tempo, ma ciò non significa che non ne restino ancora frammenti di potere.\n\nIl Twilight's Hammer deve essere in cerca di questo potere.", 0xabfa3b4e, 0x950cae03, 0x671bb4a4, 0x27463bf7, 0xdb98b446, "....." },
  [945] = { "La fuga di Therylune", "Aiuta Therylune a fuggire, poi di' a Therysil, allo Shrine of Aessina, che sua sorella è al sicuro.", "Aiuto!\n\nGironzolavo intorno al Master's Glaive, e questi sudici cultisti mi hanno circondata. Per fortuna sono brava a nascondermi!!\n\nPuoi aiutarmi a uscire di qui? E devo far sapere a mia sorella Therysil che sto bene. È ad Ashenvale, a sud, allo Shrine of Aessina.", nil, "Mia sorella era dove?? A Therylune non dispiace sporcarsi, ma comunque! È un bel tratto da percorrere, e il Master's Glaive è un luogo malsano...\n\nBeh, grazie, {name}. È stato molto gentile da parte tua farmi sapere che sta bene.", 0x108df69c, 0x3b1c1761, 0xed177776, nil, 0x2b7ac90f, "...m." },
  [947] = { "Funghi delle caverne", "Porta 5 Scaber Stalks e 1 Death Cap a Barithras Moonshade, ad Auberdine.", "Sto preparando una pozione che richiede funghi rari, funghi che crescono solo in una certa caverna. La caverna si trova dietro le Cliffspring Falls, a est e un po' a nord lungo le montagne.\n\nCi andrei io, ma il Grove of the Ancients mi ha consigliato di stare lontano da quel posto. I nostri venerabili alleati sentono che la caverna è il nascondiglio di un nuovo male a Darkshore.\n\nTi prego, {name}, raccogli i funghi per me. E già che ci sei, esplora la caverna per confermare i timori degli Ancients.", "Hai i miei funghi, {name}? Sei stato nella grotta?", "Mille grazie, {name}. Questi funghi sono ottimi esemplari!\n\nE quando eri alle Cliffspring Falls, hai trovato qualcosa che confermasse gli avvertimenti degli Ancients?\n\nGli Ancients sono saggi, ma speravo che, questa volta, si sbagliassero.", 0xe674f448, 0xe01d023c, 0x2758e8e4, 0xcf4d0564, 0x4ed87853, "....." },
  [948] = { nil, "Parla con Onu, al Grove of the Ancients.", "Onu, un Ancient of Lore del Grove of the Ancients, sa del tuo viaggio alle Cliffwater Falls e vuole parlarti. Il bosco si trova a sud, annidato vicino alle montagne.\n\nGli Ancients sono pazienti e saggi, {name}. Ma se Onu chiede il tuo parere su ciò che hai visto alle cascate, temo che sia urgente.", nil, "{name}. Sei qui.\n\nBene.\n\nAbbiamo delle questioni... da discutere. Tu e io.", nil, 0xed0d7f6a, 0xf32fed85, nil, 0x8d028ef5, "m..m." },
  [949] = { "L'accampamento del crepuscolo", "Trova un indizio nell'accampamento del Twilight's Hammer, al Master's Glaive.", "Lo scopo del Twilight's Hammer al Master's Glaive non è noto. Ma dev'essere oscuro.\n\nPerlustra il loro accampamento al Glaive... Cerca qualcosa che possa rivelarci le loro intenzioni.\n\nPerché dobbiamo conoscere le loro intenzioni prima di fare un piano.", nil, "Questo libro è scritto a mano in una lingua antica e illustrato da un maestro artista.", 0x08317362, 0x27ef0e95, 0x330bad56, nil, 0x76b4c2ab, "...m." },
  [950] = { "Ritorno da Onu", "Porta a Onu gli Insane Scribbles recuperati.", "Scrutare nel Twilight Tome fa impazzire. Dopo un solo sguardo il testo comincia a nuotare e a danzare, e quelli che erano bei fregi si contorcono in forme grottesche.\n\nRiesci solo a strappare una pagina di scarabocchi folli prima che uno svenimento ti colga.", "{name}. Sei <tornato/tornata>.", "Una magia caotica e primordiale avvolge questa pergamena di scarabocchi. Vi percepisco l'opera degli antichi.\n\nSperiamo che riveli lo scopo del Twilight's Hammer a Darkshore...", 0xcaaab2e6, 0xf6b0f093, 0x4cbe9339, 0x6065f49a, 0x508596c3, "....." },
  [951] = { nil, "Porta 6 Mathystra Relics a Onu, al Grove of the Ancients.", "La pergamena che hai trovato al Master's Glaive è una pagina di un testo antico... scritto dagli elfi! È pesantemente maledetta e contaminata dalla corruzione del Twilight's Hammer, ma sembra che il culto usi un'antica magia elfica per riportare nel nostro mondo i suoi antichi padroni.\n\nVai alle rovine di Mathystra, a nord-est, e cerca reliquie antiche tra l'erba e le pietre spezzate. Studiandole potremmo intuire come il Twilight's Hammer intenda sfruttare la magia degli elfi.", "{name}. Frugare tra le Ruins of Mathystra ha dato i suoi frutti?", "Grazie. Queste reliquie risalgono a un tempo in cui Mathystra splendeva. Quel bastione un tempo grande degli elfi è decaduto, ma ne restano frammenti di magia. Speriamo di svelare i segreti di quel luogo prima dei nostri nemici...\n\nResta vigile, {name}.", nil, 0x1bae28a2, 0x8ad041ac, 0xf6dded2e, 0xdf4141bd, "m...." },
  [952] = { "Il Grove of the Ancients", "Consegna il messaggio di Fandral a Onu, nel Grove of the Ancients a Darkshore, a sud di Auberdine.", "Se hai avuto abbastanza tempo per fare da messaggero all'Oracle Tree, di sicuro posso arruolarti per consegnare un messaggio al Grove of the Ancients, a Darkshore, proprio a sud di Auberdine.\n\nMolto probabilmente dovrai procurarti un passaggio in ippogrifo, ma ho abbastanza fiducia in te da credere che ce la farai. Porta questo a Onu, l'Ancient of Lore. Aspetta notizie da me, così come io aspettavo notizie dall'Oracle Glade.", "Ah. {class}. In cosa può aiutarti Onu?", "Ah. Grazie, {name}. È strano, però. L'arcidruido sembra sempre così di fretta. La foresta sa che tutto accadrà al momento stabilito. Shan'do Stormrage lo capiva.", 0x44207422, 0x8512a341, 0x323a6b71, 0xee3400fd, 0xe747f116, "....." },
  [953] = { "La caduta di Ameth'Aran", "Studia le tavolette che raccontano di Ameth'Aran e della sua caduta, poi torna da Sentinel Tysha Moonblade, a Darkshore.", "A est troverai le rovine di Ameth'Aran. Ora sono abitate dagli spiriti inquieti degli Highborne che un tempo vivevano tra le sue mura, ma un tempo era un luogo dove i servitori di Azshara praticavano liberamente le loro potenti magie.\n\nFui mandata a esplorare le rovine e trovai due grandi tavolette, incise con le storie di Ameth'Aran e della sua caduta. Mentre leggevo le rune fui assalita dagli spiriti e fuggii.\n\nTi prego, se puoi, vai alle rovine e decifra le tavolette al posto mio.", "Quando avrai studiato le tavolette e appreso della caduta di Ameth'Aran, porterò queste conoscenze ad Auberdine e informerò il Circle of Ancients.", "Abbiamo poche testimonianze del periodo intorno alla War of the Ancients, specialmente vicino alla distruzione del Well of Eternity. Dati gli sconvolgimenti e gli eventi catastrofici che stavano accadendo, non è una grande sorpresa.\n\nGrazie, {name}. Con il tuo aiuto il mio lavoro qui è concluso e potrò consegnare un rapporto completo al Circle.", 0x6ea45cc6, 0x4162f8d3, 0x979f8038, 0x149e3567, 0xdcc1007d, "....." },
  [954] = { nil, "Trova la fonte dello strano alone blu tra le rovine di Bashal'Aran.", "Le rovine di Bashal'Aran, a est, sono invase da servitori demoniaci. I folletti e i satiri che si sono stabiliti nella zona si nutrono delle energie magiche del luogo, e i loro poteri crescono con l'esposizione continua.\n\nEppure ho notato che c'è un santuario a cui non si avvicinano. Sul lato occidentale delle rovine, in cima a una piccola altura, si diffonde uno strano alone blu... Dev'esserci una spiegazione alla riluttanza dei demoni.\n\nVorrei che indagassi.", nil, "Ahh... A cosa mai devo lo straordinario onore della compagnia di qualcuno della razza {race}? Dice davvero molto dei miei attuali compagni, senza offesa per i miei ospiti, i nobili grell e satiri, che la tua presenza possa essere considerata un miglioramento.\n\nMa ti prego, non lasciare che la mia lingua sgarbata ti allontani da qui. Sono passati davvero molti anni, persino decenni, dall'ultima volta che ho avuto una compagnia civile.", nil, 0x3c376bcf, 0xaff407b3, nil, 0xb1c6dbd5, "m..m." },
  [955] = { nil, "Procura 8 Grell Earrings per Asterion, a Bashal'Aran.", "Se dovessi raccontarti la storia della mia vita, non ho dubbi che metterei a dura prova la tua pazienza. Diciamo che la mia è stata una vita lunga e dolorosa, e questa forma spettrale è forse il tormento peggiore di tutti.\n\nSono trattenuto qui con la magia. Anche se le mie parole possono sembrare poco sincere, ti assicuro che ti sarei grato oltre ogni dire se mi aiutassi a trovare il mezzo della mia prigionia. Mi lega un sigillo, ed esaminando gli orecchini dei folletti e dei grell potrei trovarne una traccia.", "Una volta avuti gli orecchini, lancerò l'incantesimo per scoprire dove si trova il sigillo che mi vincola. Per secoli ho pensato alla libertà che la distruzione del sigillo mi porterebbe... Forse quei secoli hanno messo a dura prova la mia mente, tanto che potrei non riprendermi mai...", "In effetti... I grell di Bashal'Aran non possiedono ciò che sto cercando... ma di recente vi sono venuti in contatto. Di recente... per i tuoi tempi, direi, non per i miei. Il recente, per me, si estende nel velo del passato, quasi un'altra era...", nil, 0xb1b08f05, 0x302949d5, 0xd4d00e5b, 0x1c6e13cb, "m...." },
  [956] = { nil, "Ottieni l'Ancient Moonstone Seal e portalo ad Asterion, a Bashal'Aran.", "Se i grell sono venuti a stretto contatto con il sigillo che lega la mia prigione eterna, credo di conoscerne la causa. Senza dubbio il sigillo è finito nelle mani dei satiri che li guidano.\n\nSento con forza che dev'essere così, {name}. Uno dei satiri deve averlo di sicuro. Se riesci a ottenerlo, mi porteresti così vicino a varcare le sbarre della mia prigione che mi verrebbero le lacrime agli occhi.", "I pilastri di questo santuario sono per me come le sbarre di una prigione, {name}. Nessuna forza che ancora possiedo potrebbe spezzarli, e nessuna magia che padroneggio potrebbe distruggerli...\n\nPer oltre mille anni li ho fissati, chiedendomi se, sopravvivendo infine persino alla pietra, sarei stato libero. Oppure sarebbero state sbarre invisibili a trattenermi...", "È... è difficile persino credere che ciò che ora stringo sia quel che mi ha imprigionato così a lungo. Non perdiamo tempo, {name}. Quando il sigillo sarà distrutto, potrò di nuovo camminare liberamente per le foreste del mondo.", nil, 0xfb2c025d, 0x0c0b89e8, 0x0eba01db, 0xc00d95ea, "m...." },
  [957] = { nil, "Distruggi l'Ancient Moonstone Seal nella fiamma antica di Ameth'Aran, poi torna da Asterion a Bashal'Aran.", "Fu l'arte di uno dei più potenti tra gli Highborne a creare il sigillo che formò la mia prigione. Ad Ameth'Aran, le rovine a sud gemelle di queste, arde ancora oggi una fiamma antica, di colore blu. In quella fiamma il sigillo potrebbe essere distrutto.\n\nStai in guardia tra le rovine, {name}...", "A dire il vero, {name}, ho paura... Paura che il tuo arrivo, tutto questo, sia soltanto il frutto di una mente squilibrata. Puoi immaginare che tortura sia? Io... Ti prego, devi andare in fretta.", "Sono libero, {name}! Ora posso vedere con i miei occhi i cambiamenti avvenuti nel nostro mondo... Ne ho conosciuto solo frammenti. Pensare che l'ultima volta che camminavo libero il Well esisteva ancora e gli Highborne tenevano corte con Azshara, la nostra amata regina.\n\nSento che il mio carceriere, il mio antico padrone, Athrikus, è ancora vivo... Già il mio senso di disperazione lascia il posto a pensieri di vendetta.", nil, 0x77a1d7fa, 0x7a4ea159, 0xfa5255d4, 0x0a963c92, "m...." },
  [958] = { "Gli strumenti degli Highborne", "Recupera 7 Highborne Relics per Thundris Windweaver, ad Auberdine.", "{class}. Avrei un compito da chiederti.\n\nHai visto le rovine di Ameth'Aran? Se no, le troverai sul lato orientale della strada principale, un po' più a sud. Un tempo erano la casa di molti potenti Highborne, ora sono la testimonianza della distruzione prodotta dai loro esperimenti.\n\nLe Sentinels mi hanno detto che gli spiriti degli Highborne persistono, e che impugnano i loro antichi strumenti magici. Quelle reliquie vanno sottratte, perché possiamo distruggerle.", "Se solo gli strumenti della loro rovina fossero stati distrutti nel cataclisma che distrusse il nostro mondo... Ad ogni modo, dobbiamo fare il possibile perché gli orrori del nostro passato non si ripetano in futuro.", "Anche se è certo frutto della mia immaginazione, mi sembra quasi di percepire su di esse la contaminazione dell'immonda magia degli Highborne. Le farò distruggere, perché il loro male a lungo sopito non venga mai più liberato.", 0xf1c555fe, 0x1bf755d6, 0xc1d7eb43, 0xc63c0c84, 0x53b1da4b, "....." },
  [959] = { "Guai al molo", "Il Crane Operator Bigglefuzz, a Ratchet, vuole che tu recuperi la bottiglia di 99-Year-Old Port da Mad Magglish, che si nasconde nelle Wailing Caverns.", "Ops!\n\nHo avuto un piccolo incidente, come vedi! Il carico del mattino da Booty Bay era enorme. Enorme, ti dico! Mai viste così tante casse. Beh, cercavo di sbrigarmi e ho cominciato a scaricare un po' più di quanto riuscissi a gestire. È lì che è crollato tutto.\n\nPrima che capissi cosa stava succedendo, ho visto quella peste, Mad Magglish, scappare via con una bottiglia di porto di 99 anni. L'ho inseguito fino alle Wailing Caverns. Non sarei mai entrato lì dentro.\n\nForse tu sei abbastanza <coraggioso/coraggiosa> da trovarlo?", "Il capo del molo mi sta addosso da quando Mad Magglish se l'è svignata con quel porto di 99 anni. A quanto pare quella bottiglia era destinata in dono a Gazlowe da parte nientemeno che del Baron Revilgaz in persona.\n\nSe sei abbastanza <coraggioso/coraggiosa> e paziente da cercare Mad Magglish e riprendere quel porto, farò in modo che tu riceva una bella ricompensa.", "Superbo! E proprio mentre stavo per perdere il lavoro! Farò in modo che Gazlowe riceva subito questo regalo.\n\nGrazie, {name}. Ben fatto, davvero!", 0x6013131a, 0x90fc1932, 0x0388702e, 0x5b209d4d, 0x2b9e98ad, "....." },
  [960] = { "Onu sta meditando", nil, nil, nil, "Sto meditando sul tuo compito, {name}. Medito sui motivi per cui il Twilight's Hammer e i naga si trovano qui.\n\nQuando sarai <pronto/pronta>, usa la fiala di divinazione per creare una coppa di divinazione. Poi contattami attraverso la coppa.\n\nSe hai perso la tua fiala di divinazione, eccone un'altra.", 0x0ff81326, nil, nil, nil, 0xbfcb1ba3, ".mmm." },
  [961] = { "Onu sta meditando", nil, nil, nil, "La scoperta dei cultisti del Twilight's Hammer è inquietante. Devo meditare sulle loro intenzioni...\n\nQuando avrai altre informazioni, parlami attraverso una coppa di divinazione. Se ti serve una fiala di divinazione per creare una coppa, allora... eccone un'altra.", 0x0ff81326, nil, nil, nil, 0x10632bc8, ".mmm." },
  [963] = { "Per un amore eterno", "Libera lo spirito di Anaya Dawnrunner e riporta il suo ciondolo a Cerellean Whiteclaw, ad Auberdine.", "Dopo le battaglie al Well of Eternity, seppi che Ameth'Aran era stata distrutta e la sua gente uccisa, compreso il mio amore, Anaya.\n\nNon avrei mai pensato che, migliaia di anni dopo, il ricordo di Anaya avrebbe ancora tormentato i miei sogni. Vagando come in trance per i boschi di Darkshore, mi ritrovai tra le rovine di Ameth'Aran... dove vidi lo spirito tormentato della mia amata.\n\nVa liberata, ma non ho il coraggio di farlo. Il suo spirito va distrutto.", "Con grande dolore nel cuore seguii lo Shan'do Stormrage nel letargo e portai il mio dolore nei sogni, dormendo per migliaia di anni.", "Grazie, {name}. Forse sarebbe stato meglio... se l'avessi fatto io stesso. Ma anche dopo migliaia di anni non ho potuto sopportare di alzare la mano contro la mia amata.\n\nTi prego, vorrei restare solo con il mio dolore...", 0xeea4b9a0, 0x229907e1, 0x038cd4bb, 0x18987e92, 0x1a264e3b, "....." },
  [965] = { "La Tower of Althalaxx", "Trova Balthule Shadowstrike vicino alla Tower of Althalaxx, a Darkshore.", "Salute, giovane {race}. Sono Elissa Starbreeze, e il mio compito è proteggere Auberdine dal male.\n\nPer questo ho mandato Balthule Shadowstrike a osservare gli strani avvenimenti intorno alla Tower of Althalaxx, a nord-est.\n\nSarebbe dovuto tornare da un pezzo. Temo che abbia incontrato qualche pericolo imprevisto nella foresta. Ti sarei molto grata se lo trovassi e controllassi che stia bene.", nil, "Ti ha mandato Elissa? Allora porti buone notizie. Ho notizie preoccupanti da riferirle e non avevo modo di fargliele avere.", 0x6dbe45ec, 0xdb947d32, 0xf74bdde2, nil, 0x7808df32, "...m." },
  [966] = { "La Tower of Althalaxx", "Raccogli 4 Worn Parchments per Balthule Shadowstrike, vicino alla Tower of Althalaxx.", "Un gruppo di stregoni si è stabilito intorno alla torre e dentro di essa. Sarei tornato prima ad Auberdine a fare rapporto a Elissa, ma temevo di perdermi qualcosa mentre ero via.\n\nDelgren sospettava che una simile compagnia potesse radunarsi alla torre, ma non sapeva perché.\n\nMi sono capitati tra le mani alcuni brandelli di pergamena che gli stregoni portano con sé, ma me ne servono altri per completare il quadro. Ti avverto però di non entrare nella torre: gli stregoni lì dentro sono molto più potenti!", "Hai trovato altre delle loro pergamene? Se riesci a trovarle, dovrei poter ricostruire un quadro più ampio del culto.", "Mille grazie, {name}. Questo dovrebbe fare un po' di luce su questo raduno di stregoni...\n\nMmm... il Cult of the Dark Strand... Non ho mai sentito parlare di questo gruppo. Senza conoscerne la storia, è quasi impossibile dire quali siano i loro piani.\n\nNon c'è più tempo da perdere. L'avvertimento deve essere consegnato subito a Delgren.", 0x6dbe45ec, 0x50a2d0dd, 0x43621fad, 0xc078402c, 0xc22bb9fd, "....." },
  [967] = { "La Tower of Althalaxx", "Consegna la lettera di Balthule a Delgren the Purifier, nella Ashenvale Forest.", "Il mio maestro, Delgren the Purifier, è un paladino che ha gentilmente offerto il suo aiuto per difendere le nostre foreste dalle forze dei demoni e dei non morti. Mi ha insegnato molto sulla Holy Light e sull'arte della battaglia.\n\nDelgren deve sapere subito delle attività del culto.\n\nLo troverai molto a sud di qui, al Maestra's Post, nella Ashenvale Forest. Sii <rapido/rapida>: temo che la minaccia del Dark Strand cresca di ora in ora.", "Hai qualche faccenda da sbrigare con me, {class}?", "Se permetti, mi sembri un po' troppo ben <equipaggiato/equipaggiata> per un messaggero, eh? Immagino che Balthule volesse essere sicuro che la sua lettera arrivasse nelle mie mani. Vediamo cosa ha da dire...\n\nSono notizie inquietanti. Quando si trovano forze non morte o demoniache, aiuto le Sentinels a distruggerle.\n\nAll'inizio non ero abituato ai modi degli elfi della notte, ma ho imparato a rispettarli molto come alleati.", 0x6dbe45ec, 0x6d6be3b8, 0xa0f446d1, 0xba59c4d3, 0xec7f73c4, "....." },
  [970] = { "La Tower of Althalaxx", "Raccogli una Glowing Soul Gem e riportala a Delgren the Purifier, al Maestra's Post.", "La lettera di Balthule è allarmante. Questo Cult of the Dark Strand è una spina nel fianco che va eliminata. Ho avuto a che fare con un po' di quella feccia del Dark Strand a nord-est di qui, a Ordil'Aran. Uno di loro possiede una gemma dell'anima che credo custodisca il segreto del potere del culto.\n\nPortamela e riuscirò a decifrare i segreti che contiene.", "Hai preso quella gemma dell'anima?", "Mmm, una magia oscura incanta questa pietra dell'anima. Vediamo cosa c'è intrappolato dentro, che ne dici?", 0x6dbe45ec, 0xdf5dcec0, 0xf639e0e6, 0x74cacd19, 0x0a139b17, "....." },
  [972] = { nil, nil, nil, nil, "Prendi la water sapta e trova la pozza d'acqua corrotta a Silverpine, {name}. Ho grande fiducia nelle tue capacità.", nil, nil, nil, nil, 0x5beca969, "mmmm." },
  [973] = { "La Tower of Althalaxx", "Porta l'Ilkrud Magthrull's Tome a Delgren the Purifier, al Maestra's Post.", "Ilkrud Magthrull. Sì, lo conosco. È un potente stregone orco che risiede al Fire Scar Shrine, un luogo di grande malvagità nel sud-ovest di Ashenvale.\n\nFinora era stato poco più di un fastidio e non me ne ero occupato, ma sembra che il suo momento sia giunto.", "Sembri un po' <scosso/scossa>, {name}. Stai bene?", "Oggi hai fatto una grande cosa, {name}. Dovresti essere molto <fiero/fiera> di te per aver affrontato uno stregone così potente.\n\nOra vediamo cosa possiamo imparare dagli scritti di Ilkrud.", 0x6dbe45ec, 0xbec21fbf, 0xa5e7b8bb, 0x3e2447c6, 0xca5719ec, "....." },
  [976] = { "Rifornimenti per Auberdine", "Parla con Delgren the Purifier al Maestra's Post dopo aver scortato Feero sano e salvo attraverso l'Ashenvale Forest.", "Delgren mi ha chiesto di consegnare messaggi e rifornimenti alla Sentinel Starbreeze, ad Auberdine, ma sono restio a partire da solo. Nella foresta agiscono nemici pericolosi, e non voglio rischiare che questi rifornimenti e queste informazioni finiscano nelle mani sbagliate.\n\nSe tu e altri poteste farmi da scorta, potrei partire subito. Con la vostra protezione non ho dubbi che riusciremo a portare questa merce sana e salva ad Auberdine.", "Le Sentinels hanno un gran bisogno di rifornimenti per rafforzarsi a Darkshore.", "Oggi hai fatto bene, {class}. I rifornimenti che abbiamo mandato in aiuto ad Auberdine saranno subito utili per affrontare le oscure minacce che infestano la foresta.\n\nPrendi questi con i miei più sentiti ringraziamenti.", 0xcbd0f669, 0x33bf359a, 0x88ce1007, 0x30b8fa32, 0xde942b67, "....." },
  [978] = { "Wildkin toccati dalla luna", "Raccogli 10 Moontouched Feathers a Winterspring, poi torna da Erelas Ambersky, a Rut'theran Village.", "Le piume dei wildkin degli Hinterlands sembrano contenere tracce di qualità magiche. Questi poteri... non sembrano usati dalle creature: è più come se fossero innati nella specie, parte della loro stessa essenza.\n\nDurante i miei studi ho sentito che una grande popolazione di wildkin abita le terre innevate di Winterspring. Possibile che queste creature abbiano gli stessi poteri? Ti prego, aiutami a trovare una risposta, {name}. Vai a Winterspring e raccogli le piume cadute a terra, poi torna da me.", "Da dove possono venire questi poteri? Credo che siamo sulla strada giusta per trovare la risposta, {name}.", "Ora posso confrontare le piume... Vediamo...", 0x93346eb5, 0xab75d9b5, 0x4fe449ae, 0x1f50ef1c, 0x23f29c32, "....." },
  [979] = { "Trovare Ranshalla", "Trova Ranshalla nella parte orientale di Winterspring.", "Sì, sì, queste piume sembrano avere lo stesso incantesimo magico che avevo notato prima... Non so bene cosa potremmo trovare, ma ti esorto a continuare a cercare risposte, {name}.\n\nUna mia collega è andata di recente a Winterspring per osservare i wildkin nel loro habitat. Perché non la raggiungi e vedi cosa ha scoperto?", nil, "Ciao! Ti manda Erelas? Ottimo, mi stavo proprio preparando a salire alle caverne, e un po' di compagnia non mi dispiacerebbe.", 0x71e9e89f, 0x355d3f50, 0x3382ee83, nil, 0x40a10506, "...m." },
  [981] = { "La Tower of Althalaxx", "Parla con Delgren the Purifier, al Maestra's Post.", "Per tutto il lavoro che hai fatto, meriti una bella ricompensa. Torna da Delgren e digli che Athrikus Narassin giace morto per mano tua, e che il Cult of the Dark Strand è sconfitto e disperso.", nil, "Sapevo che saresti <stato/stata> all'altezza, {name}.\n\nPercepisco grandi imprese davanti a te, e che rimedierai a molti dei torti che affliggono le nostre terre. Porta con te le mie benedizioni, {name}, e anche questo dono.", 0x6dbe45ec, 0x01697167, 0xd28e1f05, nil, 0xda5abf55, "...m." },
  [982] = { "Oceano profondo, mare sconfinato", "Recupera la Silver Dawning's Lockbox e la Mist Veil's Lockbox per Gorbold Steelhand, ad Auberdine. Dovresti trovarle entrambe a bordo dei relitti delle navi a nord del villaggio.", "Al largo della costa di Darkshore, a nord, ci sono due navi naufragate: la Silver Dawning e la Mist Veil. Tempo fa, entrambe le navi si scontrarono con quei maledetti murloc mentre attraversavano il vasto mare diretti ad Auberdine. Ora giacciono sul fondo dell'oceano come trofei di quei demoni.\n\nNessuno dei due capitani ne uscì vivo quella notte, e i loro diari di bordo e gli altri effetti personali sono ancora laggiù, in cassette chiuse. Vorrei che li recuperassi per noi; significherebbe molto per i membri degli equipaggi ancora da queste parti.", "I capitani di quelle navi erano bravi elfi della notte e meritavano una sorte migliore di quella che hanno avuto. Forse prendersi cura dei loro effetti personali sarà il modo migliore per dare pace ai loro spiriti.", "Hai reso un grande servizio a noi di Auberdine, <ragazzo/ragazza>. Faremo in modo che i loro effetti personali siano trattati come si deve.\n\nQuanto a te, prendi questo. È il minimo che possa fare per chi ha avuto il coraggio di rimettere le cose a posto.", 0x7355073d, 0xcfdd6269, 0x145f3c4e, 0x2b87f83b, 0x1cb94298, ".....", nil, nil, nil, nil, 0xbe9c2983 },
  [983] = { nil, "Raccogli 6 Crawler Legs e mettile nel Buzzbox 827.", "Ehi! Aiutami con la mia ultima invenzione, il buzzbox. Puoi parlare con gente lontana!\n\nForse li hai già visti: sono scatole con delle leve sopra. L'unico problema è che hanno bisogno di manutenzione continua.\n\nOgnuno ha un problema diverso, ma ho preso una decisione davvero furba. Li ho messi tutti vicino a creature che hanno i pezzi giusti per riparare quella particolare macchina. In questo momento il Buzzbox 827 fa le bizze. È appena a sud di Auberdine, vicinissimo. Per ripararlo servono 6 Crawler Legs. Ti pagherò...", "Buzzbox 827 se ne sta in un silenzio inquietante. Una sola luce lampeggiante indica che bisogna mettere 6 Crawler Legs nel suo contenitore.", "Mentre metti le Crawler Legs nella macchina, senti degli ingranaggi cominciare a stridere. A giudicare dai colpi che provengono dal Buzzbox, pensi che le Crawler Legs vengano sistemate al loro posto. Presto la macchina comincia a ronzare e senti una vocina chiamare dall'interno.\n\n\"Pronto? Ehm... Pronto! L'hai riparato! Comunque sono Wizbang! Grazie mille... Ehi, non è che ne ripareresti un altro?\"", nil, 0xe5d8e072, 0xe3959d90, 0xd3d4bf05, 0xb8705f2d, "m...." },
  [984] = { "Quanto è grave la minaccia?", "Trova un accampamento di furbolg corrotti a Darkshore e torna da Terenthis, ad Auberdine.", "Alcuni dei miei fratelli sono stati salvati da un furbolg corrotto a Teldrassil, e ho giurato di fermare altre atrocità prima che altri della nostra gente vengano feriti... o peggio.\n\nHo già visto un paio di indizi di corruzione a Darkshore, ma non ho ancora trovato segni diffusi. Credo che sarebbe logico proseguire l'indagine con i furbolg. Troveresti uno dei loro accampamenti e torneresti da me se vedi segni di corruzione?", "Come procede la tua ricerca, {name}?", "Sono davvero notizie terribili, {name}.\n\nCon i furbolg così vicini ad Auberdine, dovremo prepararci all'inevitabile.\n\nGrazie, {name}.", 0xbceca2f9, 0xdbec2402, 0xe0cddc5b, 0xb0630bc5, 0x6c96ba7c, "....." },
  [985] = { "Quanto è grave la minaccia?", "Uccidi 8 Blackwood Pathfinders e 5 Windtalkers e torna da Terenthis, ad Auberdine.", "Hai già dimostrato di essere abile nell'esplorare il territorio nemico, {name}. Hai anche la stoffa per combatterli?\n\nNon tutti gli avventurieri preferiscono il combattimento diretto all'arte della furtività e dell'evasione.\n\nSe pensi di essere all'altezza del compito, l'accampamento dei furbolg a sud di Auberdine è al momento la minaccia più grande per la nostra gente. Lì troverai alcuni della tribù Blackwood. Uccidi 8 pathfinder e 5 windtalker e torna qui da me.", "Non trattenere la mano da ciò che va fatto, figlio mio. So quanto sia ripugnante l'idea di uccidere le creature della foresta, ma in questo caso è necessario. Non è stata scoperta alcuna cura per la corruzione scatenata sulla foresta, e dobbiamo fare il possibile per fermarne l'avanzata finché non se ne troverà una.", "Lava il sangue dalle tue vesti, {name}, e non piangere per ciò che hai dovuto fare. Rendi grazie, piuttosto. Hai ridotto la minaccia per la nostra gente qui ad Auberdine, anche se Darkshore è ancora in pericolo a causa del muschio vile.", 0xbceca2f9, 0x5ededd64, 0x44114385, 0xe43d21de, 0x467213bb, "....." },
  [986] = { "Un padrone perduto", "Trova 5 Fine Moonstalker Pelts e portali a Terenthis, ad Auberdine.", "{name}, le tue abilità mi hanno già aiutato nella mia impresa. Posso approfittare di nuovo di te per aiutare Grimclaw e il suo padrone Volcor? In più, posso confezionarti un mantello magico che ti permetterà di muoverti <indisturbato/indisturbata> tra le creature di Darkshore mentre lo cerchi.\n\nPer creare il mantello mi servono 5 Fine Moonstalker Pelts da un moonstalker sire o da una matriarch, per avere abbastanza materiale. I felini si trovano vicino al Wildbend River, a sud, o ancora più a sud, vicino ad Ashenvale.", "In coscienza non posso permetterti di cercare Volcor finché non avrò confezionato quel mantello per te.", "Andranno benissimo, {name}. Mi metterò subito al lavoro sul mantello.\n\nDammi qualche istante, poi torna da me.\n\nOh, un'ultima cosa: dopo aver usato l'incantamento del mantello, le tue interazioni con gli altri saranno limitate. Se puoi, limitati a parlare con gli altri. Qualcosa di più potrebbe dissolvere l'illusione.", 0x9437ffb8, 0xca85525c, 0x7310ed86, 0x249ed804, 0xbdb74a95, "....." },
  [990] = { "In viaggio verso Ashenvale", "Trova Raene Wolfrunner, ad Ashenvale.", "{name}, la mia signora, Raene Wolfrunner, ti aspetta nella città di Astranaar, ad Ashenvale. Con il tuo aiuto, forse potremo almeno alleviare un po' la corruzione che vi ha attecchito.\n\nVai a sud da qui e resta vicino alla strada: seguendo queste indicazioni ci arriverai senza problemi.", nil, "Ah, {class} da Darkshore. Selarin ha fatto bene a mandarti qui così in fretta, {name}. Vorrei che il tuo viaggio non fosse avvenuto in circostanze così gravi. Forse con il tuo aiuto potremo migliorare le cose.\n\nComincerei la visita parlando con gli altri abitanti di Astranaar. Di sicuro ad alcuni farebbe comodo il tuo aiuto.", 0x2a43ad8f, 0x98ade4fe, 0x4a28ff7a, nil, 0x275f06e9, "...m." },
  [991] = { "La purificazione di Raene", "Trova Teronis ad Ashenvale.", "{name}, anche un mio vecchio amico aiuta le Sentinels qui ad Ashenvale, ma non è ancora tornato.\n\nAveva delle piste per trovare un oggetto che secondo lui avrebbe potuto rallentare gli attacchi dei furbolg contro la nostra gente: una verga creata da un malvagio stregone ormai morto.\n\nPrima di partire ha detto che avrebbe cercato una gemma per la verga.\n\nHa accennato al fatto che la gemma potesse essere nascosta nel santuario del Lake Falathim, ai piedi della montagna a ovest. La gemma era custodita lì prima che il luogo venisse invaso.\n\nTrova il mio amico, {name}, ti prego.", nil, "Il corpo di Teronis giace spezzato in cima all'isola. Per qualche motivo sconosciuto, i murloc l'hanno lasciato stare.\n\nI profondi squarci sul cadavere vengono chiaramente dalle armi e dagli artigli dei murloc.", 0x30e3be54, 0xc6c80ccb, 0x536c2270, nil, 0xe5bfb046, "...m." },
  [993] = { "Un padrone perduto", "Trova Volcor a Darkshore e dagli l'Enchanted Moonstalker Cloak.", "Il mantello è pronto, {name}. È giunto il momento di trovare Volcor. Posso solo sperare che siamo in tempo.\n\nLa magia del mantello, una volta invocata, non dura a lungo; forse cinque minuti. Starà a te capire quando usarlo: ti consiglierei di aspettare di aver trovato Grimclaw.\n\nSe quello che mi ha detto è vero, troverai il suo padrone in una caverna a sud di qui. Grimclaw ti aspetterà lungo la strada. Fagli un cenno con la mano quando lo vedi, e ti indicherà la strada verso il suo padrone.", nil, "Meraviglioso! Terenthis ha trovato qualcuno che mi aiuti.\n\nE guarda, un mantello di moonstalker... <tossisce> Oh... fa male. Grazie, {name}.\n\nI furbolg mi hanno ferito prima che riuscissi a sfuggirgli. Dammi un momento e dovrei riuscire a parlare ancora.", 0x9437ffb8, 0x900ee79d, 0x246b1676, nil, 0x47b3ad53, "...m." },
  [994] = { "Fuga con la forza", "Proteggi Volcor finché non raggiungete la strada, poi parla con Terenthis ad Auberdine.", "Va bene, {name}, allora con la forza. Usciamo di qui appena sei <pronto/pronta>. Ci apriremo la strada combattendo fino alla strada: Grimclaw dovrebbe essere ancora lì. Una volta lì, potremo separarci.\n\nTerenthis vorrà sentire subito la tua versione della storia, quindi vai ad Auberdine dopo che saremo usciti di qui.", nil, "{name}! Sono lieto di vedere che sei <tornato/tornata> con successo. Il tuo aiuto a Volcor mi ha dato fiducia che possiamo superare le sfide che ci attendono qui a Darkshore e oltre.", 0x2fba7967, 0x3c185ef0, 0x1806fdc3, nil, 0xcbf7190d, "...m." },
  [995] = { "Fuga furtiva", "Fuggi dalla caverna dei furbolg e raggiungi Terenthis ad Auberdine.", "Va bene allora... se ne sei <sicuro/sicura>, usciremo di qui di soppiatto. Partiamo quando sei <pronto/pronta>.\n\nRicorda, dopo essere <fuggito/fuggita>, raggiungi Terenthis ad Auberdine. Io ci andrò per conto mio, visto che probabilmente sarò più veloce di te.", "Sì, {name}?", "{name}! Sono lieto di vedere che sei <tornato/tornata> con successo. Il tuo aiuto a Volcor mi ha dato fiducia che possiamo superare le sfide che ci attendono qui a Darkshore e oltre.", 0xad883aaf, 0x9dd2b11a, 0x65c47290, 0xabfc0333, 0xcbf7190d, "....." },
  [997] = { "La terra di Denalan", "Porta il pacchetto di Rare Earth a Denalan, al Lake Al'Ameth.", "Vai verso sud? Al Lake Al'Ameth? Se è così, avrei un compito da chiederti...\n\nIl mio collega Denalan ha un accampamento sulla sponda orientale del lago, dove studia e fa esperimenti sulle piante di Teldrassil. Aveva chiesto un pacchetto di terre rare da Darnassus, che è arrivato in ritardo, solo di recente, qui a Dolanaar.\n\nPuoi portargli il pacchetto?", "Hai qualcosa per me?", "Ah, è arrivata! Aspettavo questa terra rara da parecchio tempo. Spero che sia ancora fresca...\n\nGrazie per avermela portata, {name}. Sei <generoso/generosa> del tuo tempo, {race}.", 0xa42c6191, 0x11448aaa, 0xcc1b2d88, 0xa03be4c2, 0x1cee6b9e, ".....", nil, nil, nil, nil, 0x8a75adc2 },
})
